#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>

typedef struct NetworkInterfaceConfig {
    int InterfaceID;
    char IPAddress[16];
    char SubnetMask[16];
    int NetworkStatus;
} NetworkInterfaceConfig;

NetworkInterfaceConfig* initializeNetworkInterfaces(int numInterfaces) {
    srand(time(NULL));
    NetworkInterfaceConfig *configs = malloc(numInterfaces * sizeof(NetworkInterfaceConfig));
    for (int i = 0; i < numInterfaces; i++) {
        configs[i].InterfaceID = i + 1;
        char ipAddress[16];
        char subnetMask[16];
        sprintf(ipAddress, "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        sprintf(subnetMask, "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        configs[i].IPAddress = ipAddress;
        configs[i].SubnetMask = subnetMask;
        configs[i].NetworkStatus = (rand() % 2) ? ACTIVE : INACTIVE;
    }
    return configs;
}
