    int key;
} Record;

// Define a function to allocate and initialize memory for the arrays
void init_arrays(int *offset, int *key, int num_records) {
    // Allocate memory for the offset array
    offset = (int *)malloc(num_records * sizeof(int));
    if (!offset) {
        printf("Error: Failed to allocate memory for offset array\n");
        return;
    }

    // Initialize the offset array with random values within a given range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offset[i] = rand() % 1000 + 1;
    }

    // Allocate memory for the key array
    key = (int *)malloc(num_records * sizeof(int));
    if (!key) {
        printf("Error: Failed to allocate memory for key array\n");
        free(offset);
        return;
    }

    // Initialize the key array with random values within a given range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        key[i] = rand() % 1000 + 1;
    }
}

// Define a function to merge the offset and key arrays into a single sorted array
void merge_arrays(int *offset, int *key, int num_records) {
    // Allocate memory for the merged array
    Record *merged = (Record *)malloc(num_records * sizeof(Record));
    if (!merged) {
        printf("Error: Failed to allocate memory for merged array\n");
        free(offset);
        free(key);
        return;
    }

    // Merge the offset and key arrays into a single sorted array based on the keys
    int i = 0, j = 0, k = 0;
    while (i < num_records && j < num_records) {
        if (offset[i] <= key[j]) {
            merged[k++] = (Record){ offset[i++] };
        } else {
            merged[k++] = (Record){ key[j++] };
        }
    }

    // If the merged array size exceeds a predefined threshold, trigger a system log warning
    if (k > 1000) {
        printf("Warning: Merged array size exceeds predefined threshold\n");
    }

    // Release resources properly when the function exits
    free(offset);
    free(key);
    free(merged);
}

// Define a function to handle potential errors gracefully and release resources properly
void cleanup() {
    printf("Cleaning up...\n");
}

int main() {
    // Initialize the arrays with random values within a given range
    int *offset = NULL, *key = NULL;
    init_arrays(offset, key, 10);

    // Merge the offset and key arrays into a single sorted array based on the keys
    merge_arrays(offset, key, 10);

    // Release resources properly when the function exits
    cleanup();

    return 0;
}
