// Function to read a list of integers from standard input, ensuring the input size does not exceed 10,000 elements
int* read_integers(int* num_ints) {
    // Initialize an array to store the integers
    int* arr = malloc(10000 * sizeof(int));
    if (arr == NULL) {
        printf("Error: unable to allocate memory for integer array\n");
        return NULL;
    }

    // Read each integer from standard input and store it in the array
    int i = 0;
    while (i < 10000 && scanf("%d", &arr[i]) == 1) {
        i++;
    }

    // If the input stream is interrupted before all integers are read, gracefully terminate
    if (i == 0) {
        printf("No integers provided\n");
        free(arr);
        return NULL;
    }

    // Update the number of integers in the array and return the array
    *num_ints = i;
    return arr;
}

// Function to find and print the largest integer in an array of integers
void print_largest(int* arr, int num_ints) {
    if (num_ints == 0) {
        printf("No integers provided\n");
        return;
    }

    // Initialize the largest integer to the first element in the array
    int largest = arr[0];

    // Iterate over the remaining elements in the array and find the largest integer
    for (int i = 1; i < num_ints; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }

    // Print the largest integer
    printf("Largest integer: %d\n", largest);
}
```
