    return true;
}

bool encrypt_decrypt(const char* data, const EVP_CIPHER* cipher, bool decrypt) {
    int len = strlen(data);
    unsigned char* encrypted = (unsigned char*)malloc(len + 16);
    memset(encrypted, 0, len + 16);

    // Initialize the DES cipher mode
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return false;
    }

    int ret = EVP_EncryptInit(ctx, cipher, NULL, NULL);
    if (ret != 1) {
        EVP_CIPHER_CTX_free(ctx);
        free(encrypted);
        return false;
    }

    // Encrypt/decrypt the data
    int outlen = len + 16;
    ret = EVP_EncryptUpdate(ctx, encrypted, &outlen, (unsigned char*)data, len);
    if (ret != 1) {
        EVP_CIPHER_CTX_free(ctx);
        free(encrypted);
        return false;
    }

    // Handle the last block
    outlen = 0;
    ret = EVP_EncryptFinal(ctx, encrypted + len, &outlen);
    if (ret != 1) {
        EVP_CIPHER_CTX_free(ctx);
        free(encrypted);
        return false;
    }

    // Clean up
    EVP_CIPHER_CTX_free(ctx);
    free(encrypted);

    return true;
}

bool encrypt_decrypt_oauth2_token(const char* token, const EVP_CIPHER* cipher, bool decrypt) {
    if (!verify_oauth2_token(token)) {
        return false;
    }

    // Encrypt/decrypt the access token
    if (!encrypt_decrypt(token, cipher, decrypt)) {
        return false;
    }

    return true;
}
