public class PokemonReport {
    public static String generateReport(Pokemon pokemon) {
        // Retrieve the Pokemon's type using a specified library function
        String type = retrieveType(pokemon);

        // Handle any potential exceptions that may occur during this process
        try {
            // Use a switch statement to determine the weaknesses and resistances based on the Pokemon's type
            List<String> weaknesses = new ArrayList<>();
            List<String> resistances = new ArrayList<>();
            switch (type) {
                case "Fire":
                    weaknesses.add("Water");
                    resistances.add("Ground");
