                    resistances.add("Fighting");
                    break;
                case "Bug":
                    weaknesses.add("Fire", "Flying");
                    resistances.add("Poison");
                    break;
                case "Dark":
                    weaknesses.add("Psychic", "Fairy");
                    resistances.add("Ghost");
                    break;
                case "Ghost":
                    weaknesses.add("Normal", "Psychic");
                    resistances.add("Dark");
                    break;
                case "Steel":
                    weaknesses.add("Fire", "Water", "Electric");
                    resistances.add("Fighting", "Dragon");
                    break;
                case "Normal":
                    weaknesses.add("Fighting");
                    resistances.add("Ghost");
                    break;
