                    weaknesses.add("Poison", "Steel");
                    resistances.add("Dragon");
                    break;
                case "Dragon":
                    weaknesses.add("Fighting", "Ground");
                    resistances.add("Bug", "Steel");
                    break;
            }

            // Utilize another library function to retrieve this data efficiently
            List<String> allTypes = retrieveAllTypes();

            // Include the Pokemon's name and type in the HTML report, formatted appropriately for display
            String htmlReport = "<h2>" + pokemon.getName() + " (" + type + ")</h2>";
            htmlReport += "<p>Weaknesses: ";
            for (String weakness : weaknesses) {
                htmlReport += "<span class=\"weakness\">" + weakness + "</span>, ";
            }
            htmlReport = htmlReport.substring(0, htmlReport.length() - 2);
            htmlReport += "</p>";
            htmlReport += "<p>Resistances: ";
            for (String resistance : resistances) {
                htmlReport += "<span class=\"resistance\">" + resistance + "</span>, ";
            }
            htmlReport = htmlReport.substring(0, htmlReport.length() - 2);
            htmlReport += "</p>";
            htmlReport += "<p>All Types: ";
            for (String allType : allTypes) {
                htmlReport += "<span class=\"all-type\">" + allType + "</span>, ";
            }
            htmlReport = htmlReport.substring(0, htmlReport.length() - 2);
            htmlReport += "</p>";

            // Optimize the function for performance, ensuring it can handle a large number of Pokemon objects within a reasonable time frame
            return htmlReport;
        } catch (Exception e) {
            // Handle any potential exceptions that may occur during this process
            System.out.println("Error generating report: " + e.getMessage());
            return "";
        }
    }

    private static String retrieveType(Pokemon pokemon) {
        // Retrieve the Pokemon's type using a specified library function
        try {
            return pokemon.getType();
        } catch (Exception e) {
            throw new RuntimeException("Error retrieving type: " + e.getMessage());
        }
    }

    private static List<String> retrieveAllTypes() {
        // Utilize another library function to retrieve this data efficiently
        try {
            return PokemonType.getAllTypes();
        } catch (Exception e) {
            throw new RuntimeException("Error retrieving all types: " + e.getMessage());
        }
    }
}
