#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <unistd.h>
#include <fcntl.h>
#include <pthread.h>

void* shared_memory(size_t size, int key) {
    // Create a shared memory segment with the specified size and key
    void* shm = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (shm == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    // Write data to the shared memory segment
    char* data = "Hello, world!";
    memcpy(shm, data, strlen(data));

    // Read back the data from the shared memory segment
    printf("Reading back data: %s\n", (char*)shm);

    // Clean up properly by unmapping the shared memory segment
    munmap(shm, size);

    return NULL;
}
