namespace logging {
    class Logger {
        public:
            Logger(const std::string& logFilePath, LogLevel level) : logFilePath_(logFilePath), level_(level) {}
            ~Logger() = default;

            void log(LogLevel level, const std::string& message);

        private:
            std::string logFilePath_;
            LogLevel level_;
    };

    class DebugLogger : public Logger {
        public:
            DebugLogger(const std::string& logFilePath) : Logger(logFilePath, LogLevel::DEBUG) {}
            ~DebugLogger() = default;
    };

    class InfoLogger : public Logger {
        public:
            InfoLogger(const std::string& logFilePath) : Logger(logFilePath, LogLevel::INFO) {}
            ~InfoLogger() = default;
    };

    class WarningLogger : public Logger {
        public:
            WarningLogger(const std::string& logFilePath) : Logger(logFilePath, LogLevel::WARNING) {}
            ~WarningLogger() = default;
    };

    class ErrorLogger : public Logger {
        public:
            ErrorLogger(const std::string& logFilePath) : Logger(logFilePath, LogLevel::ERROR) {}
            ~ErrorLogger() = default;
    };

    class CriticalLogger : public Logger {
        public:
            CriticalLogger(const std::string& logFilePath) : Logger(logFilePath, LogLevel::CRITICAL) {}
            ~CriticalLogger() = default;
    };
}

void logging::Logger::log(LogLevel level, const std::string& message) {
    // Check if the current thread is allowed to log
    if (!isAllowedToLog()) {
        return;
    }

    // Get the current time and format it as a string
    auto now = std::chrono::system_clock::now();
    auto timeStr = std::chrono::format("%Y-%m-%d %H:%M:%S", now);

    // Open the log file in append mode
    std::ofstream logFile(logFilePath_, std::ios::app);

    // Write the log entry to the file
    logFile << timeStr << " - " << level_ << ": " << message << std::endl;

    // Close the log file
    logFile.close();
}

bool logging::isAllowedToLog() {
    static std::mutex mutex;
    static bool allowed = true;

    // Check if the current thread is allowed to log
    std::lock_guard<std::mutex> lock(mutex);
    return allowed;
}
```
