        }
    }

    // Save user account data
    $saveResult = saveUser($_REQUEST);
    if (!$saveResult['status']) {
        return json_encode(['message' => 'error', 'errors' => $saveResult['errors']]);
    }

    // Return success message
    return json_encode(['message' => 'success']);
}

function validateInput($_REQUEST) {
    $validation = [];
    if (!isset($_REQUEST['name']) || !isset($_REQUEST['email']) || !isset($_REQUEST['password'])) {
        $validation['status'] = 'error';
        $validation['errors'][] = 'Missing required fields: name, email, password';
    } elseif (strlen($_REQUEST['name']) < 3) {
        $validation['status'] = 'error';
        $validation['errors'][] = 'Name must be at least 3 characters long';
    } elseif (!filter_var($_REQUEST['email'], FILTER_VALIDATE_EMAIL)) {
        $validation['status'] = 'error';
        $validation['errors'][] = 'Invalid email address';
    } elseif (strlen($_REQUEST['password']) < 8) {
        $validation['status'] = 'error';
        $validation['errors'][] = 'Password must be at least 8 characters long';
    }
    return $validation;
}

function getUser($id) {
    // Use caching mechanism to retrieve user account data
    $cacheKey = 'user_' . $id;
    if (isset($_SESSION[$cacheKey])) {
        return $_SESSION[$cacheKey];
    } else {
        $query = "SELECT * FROM users WHERE id = ?";
        $stmt = $pdo->prepare($query);
        $stmt->execute([$id]);
        $user = $stmt->fetch();
        if ($user) {
            $_SESSION[$cacheKey] = $user;
            return $user;
        } else {
            return false;
        }
    }
}

function checkEmailExistence($email) {
    // Use caching mechanism to retrieve user account data
    $cacheKey = 'email_' . $email;
    if (isset($_SESSION[$cacheKey])) {
        return $_SESSION[$cacheKey];
    } else {
        $query = "SELECT * FROM users WHERE email = ?";
        $stmt = $pdo->prepare($query);
        $stmt->execute([$email]);
        $user = $stmt->fetch();
        if ($user) {
            $_SESSION[$cacheKey] = true;
            return true;
        } else {
            $_SESSION[$cacheKey] = false;
            return false;
        }
    }
}

function saveUser($_REQUEST) {
    // Use prepared statements and parameterized queries to prevent SQL injection attacks
    $query = "INSERT INTO users (name, email, password) VALUES (:name, :email, :password)";
    $stmt = $pdo->prepare($query);
    $stmt->bindValue(':name', $_REQUEST['name']);
    $stmt->bindValue(':email', $_REQUEST['email']);
    $stmt->bindValue(':password', password_hash($_REQUEST['password'], PASSWORD_DEFAULT));
    $saveResult = $stmt->execute();
    if (!$saveResult) {
        return ['status' => false, 'errors' => $stmt->errorInfo()];
    } else {
        return ['status' => true];
    }
}

function deleteUser($id) {
    // Use prepared statements and parameterized queries to prevent SQL injection attacks
    $query = "DELETE FROM users WHERE id = ?";
    $stmt = $pdo->prepare($query);
    $stmt->execute([$id]);
    if ($stmt->rowCount() > 0) {
        return ['status' => true];
    } else {
        return ['status' => false, 'errors' => ['Invalid user ID']];
    }
}
