namespace MyApp.Identity
{
    public class Startup
    {
        public void ConfigureServices(IServiceCollection services)
        {
            // Add ASP.NET Identity framework
            services.AddIdentity<User, Role>()
                .AddEntityFrameworkStores<MyDbContext>();

            // Add custom username and password requirements
            services.Configure<IdentityOptions>(options =>
            {
                options.User.AllowedUserNameCharacters = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-._@+";
                options.User.RequireUniqueEmail = true;
            });

            // Add custom user lockout defaults
            services.Configure<IdentityOptions>(options =>
            {
                options.Lockout.DefaultLockoutTimeSpan = TimeSpan.FromMinutes(5);
                options.Lockout.MaxFailedAccessAttempts = 10;
                options.Lockout.AllowedForNewUsers = true;
            });

            // Add multi-factor authentication (MFA) setup and verification
            services.AddAuthentication()
                .AddGoogle(options =>
                {
                    options.ClientId = Configuration["Authentication:Google:ClientId"];
                    options.ClientSecret = Configuration["Authentication:Google:ClientSecret"];
                });

            // Add external identity provider for single sign-on (SSO)
            services.AddAuthentication()
                .AddOpenIdConnect("oidc", options =>
                {
                    options.Authority = "https://login.microsoftonline.com/common";
                    options.ClientId = Configuration["Authentication:OpenIdConnect:ClientId"];
                    options.ClientSecret = Configuration["Authentication:OpenIdConnect:ClientSecret"];
                });

            // Add session timeout and cookie lifetime settings
            services.Configure<CookieAuthenticationOptions>(options =>
            {
                options.ExpireTimeSpan = TimeSpan.FromMinutes(60);
                options.SlidingExpiration = true;
            });
        }

        public void Configure(IApplicationBuilder app, ILoggerFactory loggerFactory)
        {
            // Use ASP.NET Identity framework for authentication
            app.UseAuthentication();

            // Use session timeout and cookie lifetime settings
            app.UseSession();

            // Use multi-factor authentication (MFA) setup and verification
            app.UseMiddleware<MultiFactorAuthenticationMiddleware>();

            // Use external identity provider for single sign-on (SSO)
            app.UseAuthentication();
        }
    }
}
