const fileLoader = (function() {
  const files = {}; // Map of file names to file objects
  const dependencies = {}; // Map of file names to dependency lists
  const loadedFiles = []; // List of loaded file names
  const loadingQueue = []; // Queue of files to load
  const errorHandlers = []; // List of error handlers

  function addFile(file) {
    if (files[file.name]) {
      return;
    }
    files[file.name] = file;
    dependencies[file.name] = [];
