import java.io.File;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;

public class FilePathProcessor {
    public static int processFilePaths(List<String> filePaths) {
        long startTime = System.nanoTime();
        Map<String, Integer> directoryCounts = new HashMap<>();
        for (String filePath : filePaths) {
            File file = new File(filePath);
            if (!file.exists()) {
                continue;
            }
            String directoryPath = file.getParent();
            int count = directoryCounts.getOrDefault(directoryPath, 0);
            directoryCounts.put(directoryPath, count + 1);
        }
        long endTime = System.nanoTime();
        long duration = TimeUnit.NANOSECONDS.toMillis(endTime - startTime);
        System.out.println("Directory traversal time: " + duration + "ms");
        return directoryCounts.size();
    }
}
