use std::net::TcpStream;
use std::sync::Arc;
use std::thread::{self, JoinHandle};
use std::time::Duration;
use url::Url;

struct HttpClient {
    pool: Arc<Pool>,
}

impl HttpClient {
    fn new() -> Self {
        let pool = Pool::new();
        Self { pool }
    }

    fn get(&self, url: &str) -> Result<String, Error> {
        let mut response = self.pool.get(url)?;
        let body = response.body()?;
        Ok(String::from_utf8(body)?)
    }

    fn post(&self, url: &str, data: &[u8]) -> Result<String, Error> {
        let mut response = self.pool.post(url, data)?;
        let body = response.body()?;
        Ok(String::from_utf8(body)?)
    }
}

struct Pool {
    connections: Vec<TcpStream>,
}

impl Pool {
    fn new() -> Self {
        Self {
            connections: Vec::new(),
        }
    }

    fn get(&self, url: &str) -> Result<Response, Error> {
        let mut connection = self.get_connection(url)?;
        let response = connection.get(url)?;
        Ok(response)
    }

    fn post(&self, url: &str, data: &[u8]) -> Result<Response, Error> {
        let mut connection = self.get_connection(url)?;
        let response = connection.post(url, data)?;
        Ok(response)
    }

    fn get_connection(&self, url: &str) -> Result<TcpStream, Error> {
        let url = Url::parse(url)?;
        let mut connection = self.connections.pop();
        if connection.is_none() {
            connection = Some(TcpStream::connect(&url.host())?);
        }
        Ok(connection.unwrap())
    }
}

struct Response {
    body: Vec<u8>,
}

impl Response {
    fn body(&self) -> Result<Vec<u8>, Error> {
        Ok(self.body.clone())
    }
}

enum Error {
    ConnectionError,
    RequestError,
    ResponseError,
}
```
