using System.Configuration;

namespace DynamicSQLQuery
{
    class Program
    {
        static void Main(string[] args)
        {
            // Read connection string from configuration file
            var connectionString = ConfigurationManager.ConnectionStrings["MyDbConnection"].ConnectionString;

            // Create a new SqlConnection object
            using (var conn = new SqlConnection(connectionString))
            {
                // Open the connection to the database
                conn.Open();

                // Define the SQL query with parameterized approach to prevent SQL injection
                var sqlQuery = "SELECT e.Name, e.City, e.Address FROM Employees AS e WHERE e.SupervisorID = @supervisorId";

                // Create a new SqlCommand object with the query and connection
                using (var cmd = new SqlCommand(sqlQuery, conn))
                {
                    // Add parameter for supervisor ID
                    var supervisorIdParam = new SqlParameter("@supervisorId", SqlDbType.Int);
                    supervisorIdParam.Value = args[0];
                    cmd.Parameters.Add(supervisorIdParam);

                    // Execute the query and read the results
                    using (var reader = cmd.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            Console.WriteLine("Employee Name: {0}", reader["Name"]);
                            Console.WriteLine("City: {0}", reader["City"]);
                            Console.WriteLine("Address: {0}", reader["Address"]);
                            Console.WriteLine();
                        }
                    }
                }
            }
        }
    }
}
