import requests
import json
from datetime import datetime, timedelta

def get_weather_data(location):
    # Set up API endpoint and headers
    api_endpoint = "https://api.openweathermap.org/data/2.5/weather"
    headers = {
        "Content-Type": "application/json",
        "x-api-key": "YOUR_API_KEY"
    }

    # Set up cache for storing API responses
    cache = {}

    # Check if the location is in the cache and return it if it's within 15 minutes
    if location in cache:
        cached_data = cache[location]
        if datetime.now() - cached_data["timestamp"] < timedelta(minutes=15):
            return cached_data["data"]

    # Make API request and get response
    params = {
        "q": location,
        "units": "metric",
        "appid": headers["x-api-key"]
    }
    response = requests.get(api_endpoint, headers=headers, params=params)

    # Check if the API request was successful and return the data
    if response.status_code == 200:
        data = json.loads(response.text)
        cache[location] = {
            "timestamp": datetime.now(),
            "data": data
        }
        return data

    # If the API request was not successful, check if the cache is up to date and return it if it is
    elif response.status_code == 429:
        if location in cache:
            cached_data = cache[location]
            if datetime.now() - cached_data["timestamp"] < timedelta(minutes=15):
                return cached_data["data"]

    # If the API request was not successful and the cache is not up to date, return an error message
    else:
        return "Error: {}".format(response.status_code)
