struct OctreeNode {
    std::vector<OctreeNode*> children;
    std::vector<float> data;
};

class Octree {
public:
    Octree(int featureSize, int numLeafNodes, int dataCapacity) {
        // Initialize the root node of the octree
        root_ = new OctreeNode();
        root_->children.resize(8);
        root_->data.resize(featureSize * dataCapacity);

        // Set the number of leaf nodes and data capacity
        numLeafNodes_ = numLeafNodes;
        dataCapacity_ = dataCapacity;
    }

    ~Octree() {
        delete root_;
    }

    void insert(const std::vector<float>& data) {
        // Insert the data into the octree
        OctreeNode* node = root_;
        for (int i = 0; i < data.size(); ++i) {
            int index = i % numLeafNodes_;
            if (node->children[index] == nullptr) {
                // Create a new leaf node if necessary
                OctreeNode* newNode = new OctreeNode();
                newNode->data.resize(featureSize_ * dataCapacity_);
                node->children[index] = newNode;
            }
            node = node->children[index];
        }
        // Copy the data into the leaf node
        std::copy(data.begin(), data.end(), node->data.begin());
    }

    void traverse(std::function<void(const std::vector<float>&)> callback) {
        // Traverse the octree and call the callback function for each leaf node
        std::mutex mutex;
        std::lock_guard<std::mutex> lock(mutex);
        traverseRecursive(root_, callback);
    }

private:
    void traverseRecursive(OctreeNode* node, std::function<void(const std::vector<float>&)> callback) {
        // Recursively traverse the octree and call the callback function for each leaf node
        if (node->children.empty()) {
            // Call the callback function with the data from this leaf node
            callback(node->data);
        } else {
            for (int i = 0; i < node->children.size(); ++i) {
                traverseRecursive(node->children[i], callback);
            }
        }
    }

    OctreeNode* root_;
    int numLeafNodes_;
    int dataCapacity_;
};
```
