const reduceAsync = async (arr, initialValue, callback) => {
  // Initialize variables for tracking progress
  let currentIndex = 0;
  let accumulatedValue = initialValue;
  let errorMessage = null;

  // Create a promise chain to handle asynchronous operations
  const promiseChain = new Promise((resolve, reject) => {
    // Recursively call the callback function for each element in the array
    const next = async (index) => {
      try {
        // If the current index is beyond the bounds of the array, return the accumulated value
        if (index >= arr.length) {
          resolve(accumulatedValue);
          return;
        }

        // Compute the next reduction using the callback function
        const result = await callback(accumulatedValue, arr[index]);

        // Update the accumulated value and current index for the next iteration
        accumulatedValue = result;
        currentIndex++;

        // Recursively call the next iteration with the updated values
        next(currentIndex);
      } catch (error) {
        errorMessage = `Error occurred during reduction: ${error.message}`;
        reject(errorMessage);
      }
    };

    // Start the promise chain by calling the first iteration
    next(0);
  });

  // Return the final reduced value or an appropriate error message
  return promiseChain.then((value) => {
    if (errorMessage) {
      throw new Error(errorMessage);
    } else {
      return value;
    }
  }).catch((error) => {
    console.log(`Error occurred during reduction: ${error.message}`);
  });
};
