// Function to load a resource bundle from a file
int loadResourceBundle(const char *filename, LanguageBundle *bundle) {
    // Open the file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        return ERROR_NO_FILE;
    }

    // Read the first line of the file to determine the language
    char language[MAX_STRING_LENGTH];
    if (fgets(language, MAX_STRING_LENGTH, file) == NULL) {
        fclose(file);
        return ERROR_INVALID_KEY;
    }

    // Allocate memory for the language bundle data structure
    bundle->language = malloc(strlen(language) + 1);
    if (bundle->language == NULL) {
        fclose(file);
        return ERROR_MEMORY_ALLOCATION;
    }
    strcpy(bundle->language, language);

    // Read the number of key-value pairs in the file
    int num_keys = 0;
    if (fscanf(file, "%d", &num_keys) != 1) {
        fclose(file);
        return ERROR_INVALID_KEY;
    }

    // Allocate memory for the keys and values arrays
    bundle->keys = malloc(sizeof(char *) * num_keys);
    if (bundle->keys == NULL) {
        fclose(file);
        return ERROR_MEMORY_ALLOCATION;
    }
    bundle->values = malloc(sizeof(char *) * num_keys);
    if (bundle->values == NULL) {
        fclose(file);
        return ERROR_MEMORY_ALLOCATION;
    }

    // Read the key-value pairs from the file
    for (int i = 0; i < num_keys; i++) {
        char *key = malloc(MAX_STRING_LENGTH);
        if (key == NULL) {
            fclose(file);
            return ERROR_MEMORY_ALLOCATION;
        }
        char *value = malloc(MAX_STRING_LENGTH);
        if (value == NULL) {
            free(key);
            fclose(file);
            return ERROR_MEMORY_ALLOCATION;
        }
        if (fscanf(file, "%s %s", key, value) != 2) {
            free(key);
            free(value);
            fclose(file);
            return ERROR_INVALID_KEY;
        }
        bundle->keys[i] = key;
        bundle->values[i] = value;
    }

    // Close the file and return the number of keys in the bundle
    fclose(file);
    return num_keys;
}

// Function to get a value from a language bundle
char *getResourceBundleValue(LanguageBundle *bundle, const char *key) {
    // Check if the key is present in the primary language bundle
    for (int i = 0; i < bundle->num_keys; i++) {
        if (strcasecmp(bundle->keys[i], key) == 0) {
            return bundle->values[i];
        }
    }

    // Check if the key is present in a fallback language bundle
    LanguageBundle *fallback_bundle = getFallbackLanguageBundle();
    if (fallback_bundle != NULL) {
        for (int i = 0; i < fallback_bundle->num_keys; i++) {
            if (strcasecmp(fallback_bundle->keys[i], key) == 0) {
                return fallback_bundle->values[i];
            }
        }
    }

    // Return an error code if the key is not found in any language bundle
    return NULL;
}

// Function to validate that all required keys are present in at least one of the bundles
int validateResourceBundles(LanguageBundle *bundle, const char **required_keys) {
    // Check if each required key is present in the primary language bundle
    for (int i = 0; i < MAX_KEYS; i++) {
        if (required_keys[i] != NULL && getResourceBundleValue(bundle, required_keys[i]) == NULL) {
            return ERROR_FALLBACK_NOT_FOUND;
        }
    }

    // Return success if all required keys are present in the primary language bundle or a fallback language bundle
    return 0;
}

// Function to get a fallback language bundle
LanguageBundle *getFallbackLanguageBundle() {
    // Load the fallback language bundle from a file
    LanguageBundle *fallback_bundle = malloc(sizeof(LanguageBundle));
    if (fallback_bundle == NULL) {
        return NULL;
    }
    int num_keys = loadResourceBundle(FALLBACK_LANGUAGE LANGUAGE_EXTENSION, fallback_bundle);
    if (num_keys < 0) {
        free(fallback_bundle);
        return NULL;
    }

    // Return the fallback language bundle
    return fallback_bundle;
}
