char* append_slash(const char *str, size_t limit, struct Config config) {
    // Validate input
    if (str == NULL || limit <= 0) {
        return NULL;
    }

    // Append slash to end of string if necessary
    size_t len = strlen(str);
    if (len >= limit) {
        return NULL;
    }
    char *new_str = malloc(limit + 1);
    memcpy(new_str, str, len);
    new_str[len] = '/';
    new_str[len + 1] = '\0';

    // Add space before slash if necessary
    if (config.strict_mode && len < limit / 2) {
        new_str[len] = ' ';
    }

    // Handle multi-byte characters correctly
    size_t i;
    for (i = 0; i < len + 1; i++) {
        if (new_str[i] & 0x80) {
            break;
        }
    }
    if (i == len + 1) {
        return new_str;
    }

    // Optimize for memory usage
    size_t new_len = i + 1;
    char *new_str2 = malloc(new_len + 1);
    memcpy(new_str2, new_str, new_len);
    free(new_str);
    return new_str2;
}
