char* modify_filename(const char* filename, const char* filetype) {
    // Validate the user-specified file type to prevent injection attacks
    if (!validate_filetype(filetype)) {
        return "Invalid file type";
    }

    // Determine the number of digits in the sequence based on the filename's length and vowels
    int num_digits = 0;
    for (int i = 0; i < strlen(filename); i++) {
        if (isvowel(filename[i])) {
            num_digits++;
        }
    }

    // Allocate memory for the new filename using malloc
