        return "Memory allocation failed";
    }

    // Construct the new filename using sprintf and strcat
    sprintf(new_filename, "%s%d", filename, num_digits);
    strcat(new_filename, filetype);

    // Ensure the new filename does not exceed the maximum length constraint
    if (strlen(new_filename) > 256) {
        free(new_filename);
        return "New filename too long";
    }

    return new_filename;
}

