// Function to initialize AES-256-CBC cipher using PBKDF2-HMAC-SHA256 key derivation and fresh IV generation
EVP_CIPHER_CTX* init_aes_cbc(const char* password, const char* salt) {
    // Derive 256-bit key from password and salt using PBKDF2-HMAC-SHA256 with at least 20,000 iterations for key stretching
    unsigned char key[32];
    int key_len = EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), 20000, salt, password, strlen(password), key, NULL);
    if (key_len != 32) {
        // Handle error: invalid key length
        return NULL;
    }

    // Generate fresh 128-bit IV for each encryption operation
    unsigned char iv[16];
    RAND_bytes(iv, 16);

    // Set up AES-256-CBC cipher context and return pointer to it
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        // Handle error: unable to create cipher context
        return NULL;
    }
    int ret = EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    if (ret != 1) {
        // Handle error: unable to initialize cipher context
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Implement error handling to manage potential OpenSSL errors during key derivation and cipher setup
    ERR_load_crypto_strings();
    ERR_clear_error();

    // Provide a separate function to securely clean up and disable the cipher context when it is no longer needed, ensuring that sensitive data is not leaked
    void cleanup_aes_cbc(EVP_CIPHER_CTX* ctx) {
        EVP_CIPHER_CTX_free(ctx);
        ERR_remove_state(0);
    }

    return ctx;
}
