#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <png.h>

int convert_raw_to_png(const char* file_name, const char* tmp_dir, const char* output_file) {
    FILE* input = fopen(file_name, "rb");
    if (!input) {
        perror("fopen");
        return 1;
    }

    // Get the size of the input file
    fseek(input, 0, SEEK_END);
    long input_size = ftell(input);
    rewind(input);

    // Allocate memory for the input buffer
    unsigned char* input_buffer = malloc(input_size);
    if (!input_buffer) {
        perror("malloc");
        fclose(input);
        return 1;
    }

    // Read the entire input file into the buffer
    size_t bytes_read = fread(input_buffer, 1, input_size, input);
    if (bytes_read != input_size) {
        perror("fread");
        free(input_buffer);
        fclose(input);
        return 1;
    }

    // Create a temporary file for the output PNG
    FILE* output = tmpfile();
    if (!output) {
        perror("tmpfile");
        free(input_buffer);
        fclose(input);
        return 1;
    }

    // Initialize the PNG writer
    png_structp png_ptr = png_create_write_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, NULL);
    if (!png_ptr) {
        perror("png_create_write_struct");
        fclose(output);
        free(input_buffer);
        fclose(input);
        return 1;
    }

    // Initialize the PNG writer's error handling
    png_infop info_ptr = png_create_info_struct(png_ptr);
    if (!info_ptr) {
        perror("png_create_info_struct");
        png_destroy_write_struct(&png_ptr, NULL);
        fclose(output);
        free(input_buffer);
        fclose(input);
        return 1;
    }

    // Set the PNG writer's output file
    if (setjmp(png_jmpbuf(png_ptr))) {
        perror("setjmp");
        png_destroy_write_struct(&png_ptr, &info_ptr);
        fclose(output);
        free(input_buffer);
        fclose(input);
        return 1;
    }
    png_init_io(png_ptr, output);

    // Write the PNG header and image data to the temporary file
    png_set_IHDR(png_ptr, info_ptr, width, height, 8, PNG_COLOR_TYPE_RGB, PNG_INTERLACE_NONE, PNG_COMPRESSION_TYPE_DEFAULT, PNG_FILTER_TYPE_DEFAULT);
    png_write_info(png_ptr, info_ptr);
    png_set_rows(png_ptr, info_ptr, rows);
    png_write_image(png_ptr, rows);
    png_write_end(png_ptr, NULL);

    // Clean up the PNG writer and temporary file
    png_destroy_write_struct(&png_ptr, &info_ptr);
    fclose(output);

    // Rename the temporary file to the output file name
    if (rename(tmp_file, output_file) == -1) {
        perror("rename");
        free(input_buffer);
        fclose(input);
        return 1;
    }

    // Clean up the input buffer and file
    free(input_buffer);
    fclose(input);

    return 0;
}
