#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

int run_command(char* command) {
    int pid, status;
    char* args[2];
    args[0] = command;
    args[1] = NULL;

    // Fork a child process to execute the command
    if ((pid = fork()) < 0) {
        perror("fork");
        return 0;
    } else if (pid == 0) {
        // Child process: execute the command and exit
        execvp(args[0], args);
        perror("execvp");
        exit(1);
    }

    // Parent process: wait for the child process to finish
    if (waitpid(pid, &status, 0) < 0) {
        perror("waitpid");
        return 0;
    }

    // Check if the command was executed successfully
    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        return 1;
    } else {
        return 0;
    }
}
```
