import java.util.logging.Logger;

public class CommandExecutor {
    private static final Logger LOGGER = Logger.getLogger(CommandExecutor.class.getName());

    public void executeCommand(String command, String configFile) throws IOException {
        // Check if the configuration file exists and is valid
        File config = new File(configFile);
        if (!config.exists() || !validateConfig(config)) {
            LOGGER.warning("Invalid configuration file: " + configFile);
            return;
        }

        // Execute the command using Runtime.getRuntime().exec()
        Process process = Runtime.getRuntime().exec(command);

        // Capture both standard output and error streams from the executed command
        BufferedReader stdInput = new BufferedReader(new InputStreamReader(process.getInputStream()));
        BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));

        // Handle the captured output and errors appropriately
        String line;
        while ((line = stdInput.readLine()) != null) {
            LOGGER.info("Standard output: " + line);
        }
        while ((line = stdError.readLine()) != null) {
            LOGGER.severe("Standard error: " + line);
        }

        // Ensure resources are properly closed after processing the streams
        stdInput.close();
        stdError.close();

        // Retry the command execution up to three times if it fails due to a transient error
        int retryCount = 0;
        while (retryCount < 3) {
            try {
                process.waitFor();
                break;
            } catch (InterruptedException e) {
                LOGGER.warning("Command execution interrupted: " + command);
                retryCount++;
            }
        }

        // Log detailed information about each attempt, including the command executed, exit value, and any captured output or errors
        if (retryCount > 0) {
            LOGGER.info("Retried command execution: " + command);
        }
        int exitValue = process.exitValue();
        LOGGER.info("Command execution completed with exit value: " + exitValue);
    }

    private boolean validateConfig(File config) throws IOException {
        // Implement configuration validation logic here
        return true;
    }
