using System;
using System.Collections.Generic;
using System.IO;
using System.Threading.Tasks;
using CloudStorageService;

public class FileUploader
{
    public async Task<List<UploadStatus>> UploadFilesAsync(IEnumerable<string> filePaths)
    {
        var uploadStatuses = new List<UploadStatus>();

        foreach (var filePath in filePaths)
        {
            try
            {
                if (!File.Exists(filePath))
                {
                    throw new FileNotFoundException($"File not found: {filePath}");
                }

                using var stream = File.OpenRead(filePath);
                await CloudStorageService.UploadAsync(stream, filePath);
                uploadStatuses.Add(new UploadStatus(true));
            }
            catch (Exception ex)
            {
                uploadStatuses.Add(new UploadStatus(false, ex.Message));
            }
        }

        return uploadStatuses;
    }
}

public class UploadStatus
{
    public bool Success { get; set; }
    public string ErrorMessage { get; set; }

    public UploadStatus(bool success, string errorMessage = null)
    {
        Success = success;
        ErrorMessage = errorMessage;
    }
}
```
