using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public static string DecryptAndHashFile(string base64EncodedMessage, string filePath, int bufferSize = 1024 * 1024)
{
    // Decode the Base64-encoded message
    byte[] encryptedBytes = Convert.FromBase64String(base64EncodedMessage);

    // Create a new TripleDES instance with the given key and IV
    using (TripleDESCryptoServiceProvider csp = new TripleDESCryptoServiceProvider())
    {
        // Decrypt the encrypted bytes using the TripleDES algorithm
        byte[] decryptedBytes = csp.CreateDecryptor().TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);

        // Create a new MD5 instance
        using (MD5 md5 = MD5.Create())
        {
            // Compute the hash of the decrypted bytes
            byte[] hashBytes = md5.ComputeHash(decryptedBytes);

            // Convert the hash to a hexadecimal string
            string hashString = BitConverter.ToString(hashBytes).Replace("-", "");

            // Read the file in chunks, using a buffer size of 1 MB
            using (FileStream fs = new FileStream(filePath, FileMode.Open))
            {
                byte[] buffer = new byte[bufferSize];
                int bytesRead;

                while ((bytesRead = fs.Read(buffer, 0, buffer.Length)) > 0)
                {
                    // Compute the hash of the current chunk
                    md5.TransformBlock(buffer, 0, bytesRead, null, 0);
                }

                // Complete the hash computation
                md5.TransformFinalBlock(buffer, 0, 0);

                // Return the decrypted message and the hexadecimal string of the hash
                return Encoding.UTF8.GetString(decryptedBytes) + "|" + hashString;
            }
        }
    }
}
