public class Hasher
{
    private static readonly ConcurrentDictionary<string, string> _hashCache = new ConcurrentDictionary<string, string>();
    private static readonly object _lockObject = new object();

    public async Task<string> GetHashAsync(string input)
    {
        if (_hashCache.TryGetValue(input, out var hash))
        {
            return hash;
        }

        lock (_lockObject)
        {
            using (var md5 = MD5.Create())
            {
                var inputBytes = Encoding.UTF8.GetBytes(input);
                var hashBytes = md5.ComputeHash(inputBytes);
                hash = BitConverter.ToString(hashBytes).Replace("-", "");
                _hashCache[input] = hash;
            }
        }

        return hash;
    }
}
