public static class CompressedDataLoader
{
    public static T Load<T>(string filePath) where T : new()
    {
        try
        {
            using (var stream = File.OpenRead(filePath))
            {
                var formatter = new BinaryFormatter();
                var compressedStream = new GZipStream(stream, CompressionMode.Decompress);
                var data = (T)formatter.Deserialize(compressedStream);
                return data;
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading compressed data from file '{filePath}': {ex.Message}");
            throw;
        }
    }
}
