const fs = require('fs');
const vm = require('vm');

function loadScript(filePath) {
  try {
    const script = fs.readFileSync(filePath, 'utf8');
    return vm.runInThisContext(script);
  } catch (e) {
    console.error(`Error while loading script ${filePath}: ${e.message}`);
    return null;
  }
}

function executeScripts(scripts) {
  for (const script of scripts) {
    try {
      const result = loadScript(script);
      if (result !== null) {
        console.log(`Executed script ${script}`);
      } else {
        console.error(`Failed to execute script ${script}`);
      }
    } catch (e) {
      console.error(`Error while executing script ${script}: ${e.message}`);
    }
  }
}
