    for (int i = 0; i < numEntries; i++) {
        if (!isValidEventCode(logList[i].eventCode)) {
            logList[i].eventCode = -1;
        }
        if (strlen(logList[i].eventMessage) > MAX_EVENT_MESSAGE_LENGTH) {
            logList[i].eventMessage[MAX_EVENT_MESSAGE_LENGTH] = '\0';
