void merge_arrays(Record **offset, Record **key, Record **timestamp) {
    // Create a new array to store the merged records
    int merged_size = (*offset)->size + (*key)->size + (*timestamp)->size;
    Record *merged = (Record *)malloc(sizeof(Record) * merged_size);

    // Merge the arrays based on the 'key' values
    int i = 0, j = 0, k = 0;
    while (i < (*offset)->size && j < (*key)->size && k < (*timestamp)->size) {
        if ((*offset)[i].key == (*key)[j].key && (*offset)[i].key == (*timestamp)[k].key) {
