        } else if ((*key)[j].key < (*offset)[i].key && (*key)[j].key < (*timestamp)[k].key) {
            merged[merged_size - 2] = (*key)[j];
            j++;
        } else if ((*timestamp)[k].key < (*offset)[i].key && (*timestamp)[k].key < (*key)[j].key) {
            merged[merged_size - 3] = (*timestamp)[k];
            k++;
        }
    }

    // Free the original arrays and assign the new merged array
    free(*offset);
    free(*key);
    free(*timestamp);
    *offset = merged;
}

// Function to purge less frequently accessed records
void purge_records(Record **offset, Record **key, Record **timestamp) {
    // Create a new array to store the purged records
    int purged_size = (*offset)->size / 2;
    Record *purged = (Record *)malloc(sizeof(Record) * purged_size);

    // Purge the records based on their access frequency
    for (int i = 0, j = 0; i < (*offset)->size && j < purged_size; i++) {
        if ((*offset)[i].access_frequency < 10) {
            purged[j] = (*offset)[i];
            j++;
        }
