    init_arrays(&offset, &key, &timestamp);

    // Merge the arrays based on the 'key' values
    merge_arrays(offset, key, timestamp);

    // Purge less frequently accessed records to maintain performance and resource utilization
    purge_records(offset, key, timestamp);

