void init_log_list(int num_entries) {
    // Allocate memory for the list of logs
    log_list = (DeviceStatusLog*)malloc(num_entries * sizeof(DeviceStatusLog));
    if (!log_list) {
        perror("Failed to allocate memory for log list");
        exit(1);
