        log_list[i].timestamp = 0;
        log_list[i].deviceID = 0;
        log_list[i].eventCode = 0;
        log_list[i].eventMessage = NULL;
    }
}

// Function to add a new DeviceStatusLog entry to the list
void add_log(time_t timestamp, int deviceID, int eventCode, char* eventMessage) {
    // Acquire the lock on the log list
    pthread_mutex_lock(&log_list_lock);

    // Check if there is a duplicate entry in the list for the same device within the specified time window
    for (int i = 0; i < num_entries; i++) {
        if (log_list[i].deviceID == deviceID && timestamp - log_list[i].timestamp <= TIME_WINDOW) {
            // Release the lock on the log list and return
            pthread_mutex_unlock(&log_list_lock);
            return;
