import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.logging.Level;
import java.util.logging.Logger;

public class MD5Hash {
    private static final Logger LOGGER = Logger.getLogger(MD5Hash.class.getName());

    public static String computeMD5Hash(String filePath) throws IOException, NoSuchAlgorithmException {
        // Validate input path and file existence
        if (filePath == null || !new File(filePath).exists()) {
            throw new IllegalArgumentException("Invalid file path: " + filePath);
        }

        // Open the file for reading in memory-efficient chunks
        try (FileInputStream fis = new FileInputStream(filePath)) {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] buffer = new byte[1024];
            int read;

            // Update the hash with each chunk of data
            while ((read = fis.read(buffer)) > 0) {
                md.update(buffer, 0, read);
            }

            // Return the hexdigest of the hash as a String
            return md.digest().toString();
        } catch (IOException | NoSuchAlgorithmException e) {
            LOGGER.log(Level.SEVERE, "Error computing MD5 hash", e);
            return null;
        }
    }
}
```
