// Initialize the log buffer with a specified capacity
void initLogBuffer(struct LogBuffer* buffer, size_t capacity) {
    buffer->capacity = capacity;
    buffer->count = 0;
    buffer->entries = (DeviceStatusLog*)malloc(sizeof(DeviceStatusLog) * capacity);
}

// Add a new log entry to the log buffer
void addLogEntry(struct LogBuffer* buffer, time_t timestamp, int deviceID, int eventCode, char* eventMessage) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->count < buffer->capacity) {
        buffer->entries[buffer->count].timestamp = timestamp;
        buffer->entries[buffer->count].deviceID = deviceID;
        buffer->entries[buffer->count].eventCode = eventCode;
        buffer->entries[buffer->count].eventMessage = strdup(eventMessage);
        buffer->count++;
    } else {
        // Buffer is full, drop the oldest entry to make room for new one
        free(buffer->entries[0].eventMessage);
        memmove(&buffer->entries[0], &buffer->entries[1], sizeof(DeviceStatusLog) * (buffer->capacity - 1));
        buffer->count--;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

