// Define function to manage pool of sensor data
void manageSensorData(SensorData* data) {
    // Check if memory allocation failed
    if (data == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Check if sensor ID is unique
    for (int i = 0; i < data->id; i++) {
        if (data[i].id == data->id) {
            printf("Duplicate sensor ID detected\n");
            return;
        }
    }

    // Validate reading values and enforce limits on number of readings per sensor
    for (int i = 0; i < 3; i++) {
        if (data->readings[i] < -10 || data->readings[i] > 50) {
            printf("Invalid reading value detected\n");
            return;
        }
    }

    // Add sensor data to pool
    data->timestamp = time(NULL);
    for (int i = 0; i < 3; i++) {
        data[i].readings[i] = data->readings[i];
    }
}

// Define function to query data by sensor ID within specified time frame
void queryDataBySensorID(int id, time_t startTime, time_t endTime) {
    // Check if memory allocation failed
    SensorData* data = malloc(sizeof(SensorData));
    if (data == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Query data from database within specified time frame
    for (int i = 0; i < data->id; i++) {
        if (data[i].timestamp >= startTime && data[i].timestamp <= endTime) {
            printf("Sensor ID: %d\n", data[i].id);
            printf("Timestamp: %s\n", ctime(&data[i].timestamp));
            for (int j = 0; j < 3; j++) {
                printf("Reading %d: %.2f\n", j, data[i].readings[j]);
            }
        }
    }
}

// Define function to integrate with external data processing pipeline
void integrateWithPipeline(SensorData* data) {
    // Check if memory allocation failed
    if (data == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Process sensor data in real-time and trigger alerts based on predefined thresholds
    for (int i = 0; i < data->id; i++) {
        if (data[i].readings[0] > 30 || data[i].readings[1] < 40) {
            printf("Alert triggered: Sensor ID %d\n", data[i].id);
        }
    }
}
