import os
import re
from sprintf import sprintf

def upload_file(filename, filetype):
    # Validate file type
    if not re.match(r'^[a-zA-Z0-9\-]+$', filetype):
        return "Invalid file type"

    # Open file and read lines
    with open(filename, 'r') as f:
        lines = f.readlines()

    # Sort lines and extract sequence number from last line
    sorted_lines = sorted(lines)
    sequence_number = int(sorted_lines[-1].split(' ')[-1])

    # Construct new filename based on original filename and sequence number
    new_filename = sprintf("%s-%d.%s", filename, sequence_number, filetype)

    # Upload file using library for file upload
    uploaded_file = upload_file(new_filename)

    # Return URL of uploaded file
    return uploaded_file
```
