#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

// Function to compute and print the mean, median, and mode of a list of numbers
void compute_stats(float *numbers, int size) {
    // Compute the sum of all the numbers
    float sum = 0;
    for (int i = 0; i < size; i++) {
        sum += numbers[i];
    }

    // Compute the mean
    float mean = sum / size;
    printf("Mean: %f\n", mean);

    // Sort the list in ascending order
    qsort(numbers, size, sizeof(float), compare_floats);

    // Compute the median
    if (size % 2 == 0) {
        float median = (numbers[size / 2 - 1] + numbers[size / 2]) / 2;
        printf("Median: %f\n", median);
    } else {
        float median = numbers[size / 2];
        printf("Median: %f\n", median);
    }

    // Compute the mode
    int max_count = 0;
    int mode_index = -1;
    for (int i = 0; i < size; i++) {
        int count = 1;
        for (int j = i + 1; j < size && numbers[i] == numbers[j]; j++) {
            count++;
        }
        if (count > max_count) {
            mode_index = i;
            max_count = count;
        }
    }
    if (mode_index != -1) {
        printf("Mode: %f\n", numbers[mode_index]);
    } else {
        printf("No mode found.\n");
    }
}

// Function to handle interruptions during input and ensure the program terminates gracefully
void handle_interrupt(int signal) {
    // Print a message indicating that the program has been interrupted
    printf("\nProgram interrupted. Exiting...\n");

    // Free any dynamically allocated memory
    free(numbers);

    // Exit the program with an error code
    exit(1);
}

// Main function to process the list of floating-point numbers received from standard input
int main() {
    // Declare a pointer to hold the dynamically allocated array of numbers
    float *numbers = NULL;

    // Read the number of elements in the list from standard input
    int size;
    scanf("%d", &size);

    // Check if the input size is valid and greater than 0
    if (size <= 0) {
        printf("Invalid input size. Exiting...\n");
        return 1;
    }

    // Dynamically allocate an array to hold the numbers
    numbers = malloc(size * sizeof(float));
    if (!numbers) {
        printf("Error: Unable to allocate memory for the list of numbers.\n");
        return 1;
    }

    // Read the numbers from standard input and store them in the array
    for (int i = 0; i < size; i++) {
        scanf("%f", &numbers[i]);
    }

    // Compute and print the mean, median, and mode of the numbers
    compute_stats(numbers, size);

    // Free any dynamically allocated memory
    free(numbers);

    return 0;
}
```
This code uses a dynamically allocated array to store the list of floating-point numbers received from standard input. It also includes a helper function `compute_stats` that computes and prints the mean, median, and mode of the numbers. The main function reads the number of elements in the list from standard input and then reads the numbers from standard input and stores them in the array. If an interruption occurs during input, the program terminates gracefully by printing a message indicating that it has been interrupted and freeing any dynamically allocated memory.']

