import java.security.MessageDigest;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.Logger;

public class HashingUtil {
    private static final Logger logger = Logger.getLogger(HashingUtil.class.getName());
    private static final AtomicInteger concurrentRequests = new AtomicInteger();

    public static String hashString(String input, boolean useSHA256) {
        if (input == null || input.trim().isEmpty()) {
            return null;
        }

        try {
            MessageDigest digester = useSHA256 ? MessageDigest.getInstance("SHA-256") : MessageDigest.getInstance("MD5");
            byte[] hash = digester.digest(input.getBytes());
            return bytesToHexString(hash);
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error hashing string", e);
            return null;
        }
    }

    private static String bytesToHexString(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < bytes.length; i++) {
            sb.append(Integer.toHexString((bytes[i] & 0xFF) | 0x100).substring(1, 3));
        }
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        String input = "Hello World!";
        boolean useSHA256 = false;
        if (args.length > 0) {
            useSHA256 = Boolean.parseBoolean(args[0]);
        }
        System.out.println("Hashing string: " + input);
        String hash = hashString(input, useSHA256);
        System.out.println("Hash: " + hash);
    }
}
