import os
import re
from urllib.parse import quote

def generate_new_filename(original_filename, sequence_number):
    # Validate file type
    if not re.match(r'^[a-zA-Z0-9\-]+$', original_filename):
        return "Invalid file type"

    # Get vowel count
    vowel_count = len([c for c in original_filename if c in 'aeiou'])

    # Construct new filename
    new_filename = f"{original_filename[:-4]}_{sequence_number}{quote(original_filename[-4:])}"

    # Check maximum length constraint
    if len(new_filename) > 256:
        return "Maximum filename length exceeded"

    # Return new filename
    return new_filename
```
C Function:
```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

char* generate_new_filename(const char* original_filename, int sequence_number) {
    // Validate file type
    if (!is_valid_file_type(original_filename)) {
        return "Invalid file type";
    }

    // Get vowel count
    int vowel_count = get_vowel_count(original_filename);

    // Construct new filename
    char* new_filename = (char*)malloc(256 * sizeof(char));
    if (!new_filename) {
        return "Memory allocation error";
    }
    sprintf(new_filename, "%s_%d%s", original_filename, sequence_number, quote(original_filename + 4));

    // Check maximum length constraint
    if (strlen(new_filename) > 256) {
        free(new_filename);
        return "Maximum filename length exceeded";
    }

    // Return new filename
    return new_filename;
}

int is_valid_file_type(const char* original_filename) {
    // Check if file type contains only alphanumeric characters and hyphens
    for (int i = 0; i < strlen(original_filename); i++) {
        if (!isalnum(original_filename[i]) && original_filename[i] != '-') {
            return 0;
        }
    }

    // File type is valid
    return 1;
}

int get_vowel_count(const char* original_filename) {
    int vowel_count = 0;
    for (int i = 0; i < strlen(original_filename); i++) {
        if (original_filename[i] == 'a' || original_filename[i] == 'e' || original_filename[i] == 'i' || original_filename[i] == 'o' || original_filename[i] == 'u') {
            vowel_count++;
        }
    }

    return vowel_count;
}
```
