import os
import re
from sprintf import sprintf
from strcat import strcat

def generate_filename(filepath, extension):
    # Validate file type
    if not re.match(r'^[a-zA-Z0-9\-]+$', filepath):
        return "Invalid file type"

    # Read file and sort lines
    with open(filepath, 'r') as f:
        lines = sorted(f.readlines())

    # Extract sequence number from last line
    try:
        sequence_number = int(lines[-1].strip()) + 1
    except ValueError:
        return "Invalid file format"

    # Construct new filename
    new_filename = sprintf("%s-%d.%s", filepath, sequence_number, extension)

    # Upload file to server
    url = upload_file(new_filename)

    return url
