#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sprintf.h>
#include <strcat.h>

struct task {
    char* args;
    int priority;
};

void init_task_list(struct task** list, int capacity) {
    *list = (struct task*)malloc(capacity * sizeof(struct task));
    if (*list == NULL) {
        printf("Error: Failed to allocate memory for task list\n");
        exit(1);
    }

    // Initialize tasks with randomly generated arguments and priority levels
    for (int i = 0; i < capacity; i++) {
        struct task* task = &(*list)[i];
        task->args = generate_random_string();
        task->priority = generate_random_number(1, 10);
    }
}

void add_task(struct task** list, int capacity) {
    if (*list == NULL || *capacity == 0) {
        init_task_list(list, capacity);
    } else {
        // Dynamically resize list if necessary
        struct task* new_list = (struct task*)realloc(*list, (*capacity + 1) * sizeof(struct task));
        if (new_list == NULL) {
            printf("Error: Failed to reallocate memory for task list\n");
            exit(1);
        }

        // Initialize new task with randomly generated arguments and priority level
        struct task* task = &new_list[*capacity];
        task->args = generate_random_string();
        task->priority = generate_random_number(1, 10);

        *list = new_list;
        (*capacity)++;
    }
}

void remove_task(struct task** list, int* capacity) {
    if (*list == NULL || *capacity == 0) {
        return;
    } else {
        // Dynamically resize list if necessary
        struct task* new_list = (struct task*)realloc(*list, (*capacity - 1) * sizeof(struct task));
        if (new_list == NULL) {
            printf("Error: Failed to reallocate memory for task list\n");
            exit(1);
        }

        *list = new_list;
        (*capacity)--;
    }
}

void print_task_list(struct task* list, int capacity) {
    if (list == NULL || capacity == 0) {
        printf("Task list is empty\n");
        return;
    }

    for (int i = 0; i < capacity; i++) {
        struct task* task = &list[i];
        printf("%s: %d\n", task->args, task->priority);
    }
}

void free_task_list(struct task** list) {
    if (*list == NULL) {
        return;
    }

    free(*list);
    *list = NULL;
}
