#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to validate input number for non-negative value
int isValidNumber(float num) {
    return (num >= 0);
}

// Function to compute average of valid numbers
float computeAverage(float *numbers, int count) {
    float sum = 0;
    for (int i = 0; i < count; i++) {
        sum += numbers[i];
    }
    return sum / count;
}

// Function to read input from standard input and calculate average
void calculateAverage() {
    // Allocate memory for array of floating-point numbers
    float *numbers = (float *)malloc(sizeof(float) * 10);
    if (!numbers) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Read input from standard input and validate each number for non-negative value
    int count = 0;
    while (scanf("%f", &numbers[count]) == 1 && isValidNumber(numbers[count])) {
        count++;
    }

    // Compute average of valid numbers
    float average = computeAverage(numbers, count);

    // Print the average
    printf("Average: %f\n", average);

    // Free allocated memory
    free(numbers);
}

int main() {
    calculateAverage();
    return 0;
}
