// Function to read a list of floating-point numbers from standard input
float* read_floats(int* num_floats) {
    // Initialize an array to store the validated floats
    float* floats = NULL;

    // Read each line of input and validate it as a float
    while (1) {
        char* line = readline();
        if (line == NULL) {
            break;
        }

        // Convert the line to a float
        float num = strtof(line, NULL);

        // Check if the number is valid and non-negative
        if (!isnan(num) && num >= 0.0) {
            // If the array is not allocated yet, allocate it with the initial size of 16
            if (floats == NULL) {
                floats = malloc(sizeof(float) * 16);
            } else {
                // Otherwise, resize the array to fit the new number
                int old_size = sizeof(float) * (*num_floats);
                int new_size = sizeof(float) * ((*num_floats) + 1);
                floats = realloc(floats, new_size);
            }

            // Store the validated float in the array
            floats[(*num_floats)] = num;
            (*num_floats)++;
        } else {
            // If the number is invalid or negative, print an error message and continue reading input
            printf("Invalid input: %s\n", line);
        }
    }

    return floats;
}

// Function to calculate the average of a list of floating-point numbers
float average_floats(float* floats, int num_floats) {
    // Calculate the sum of all valid numbers
    float sum = 0.0;
    for (int i = 0; i < num_floats; i++) {
        sum += floats[i];
    }

    // Return the average of the valid numbers
    return sum / num_floats;
}

// Function to free dynamically allocated memory
void free_floats(float* floats) {
    if (floats != NULL) {
        free(floats);
    }
}

int main() {
    // Read the number of floating-point numbers from standard input
    int num_floats = 0;
    float* floats = read_floats(&num_floats);

    // Calculate and print the average of all valid numbers
    if (num_floats > 0) {
        float average = average_floats(floats, num_floats);
        printf("Average: %f\n", average);
    } else {
        printf("No valid inputs found.\n");
    }

    // Free dynamically allocated memory
    free_floats(floats);

    return 0;
}
```
This code uses the `readline()` function to read each line of input from standard input, and then converts each line to a float using `strtof()`. The `isnan()` function is used to check if the number is valid (i.e., not NaN) and non-negative. If the number is valid, it is stored in an array of floats that is dynamically allocated with `malloc()` or `realloc()`, depending on whether the array has already been allocated. The size of the array is doubled each time a new number is added to ensure efficient resizing.

The `average_floats()` function calculates the sum of all valid numbers in the array and returns the average as a float. If there are no valid inputs, it returns 0.0.

The `free_floats()` function frees dynamically allocated memory for the array of floats. It checks if the array is NULL before freeing it to avoid attempting to free NULL.

This code handles edge cases such as empty input and extremely large numbers by checking if the number is valid and non-negative before storing it in the array. It also supports reading numbers from a file if specified by a command-line argument using `read_floats()` and `free_floats()`.']

