    NetworkInterfaceConfig* configs = (NetworkInterfaceConfig*)malloc(MAX_NETWORK_INTERFACES * sizeof(NetworkInterfaceConfig));
    if (!configs) {
        fprintf(stderr, "Error: Failed to allocate memory for network configuration\n");
        return NULL;
    }

    // Initialize the structures with random values
    srand(time(NULL));
    for (int i = 0; i < MAX_NETWORK_INTERFACES; i++) {
        configs[i].InterfaceID = rand() % 10000;
        configs[i].NetworkStatus = (rand() % 2) ? true : false;
        inet_pton(AF_INET, "192.168.1.1", &configs[i].IPAddress);
        inet_pton(AF_INET, "255.255.255.0", &configs[i].SubnetMask);
    }

    // Validate the configurations and log any errors
    for (int i = 0; i < MAX_NETWORK_INTERFACES; i++) {
        if (!inet_pton(AF_INET, configs[i].IPAddress, &configs[i].IPAddress)) {
            fprintf(stderr, "Error: Invalid IP address format for interface %d\n", configs[i].InterfaceID);
            continue;
        }
        if (!inet_pton(AF_INET, configs[i].SubnetMask, &configs[i].SubnetMask)) {
            fprintf(stderr, "Error: Invalid subnet mask format for interface %d\n", configs[i].InterfaceID);
            continue;
        }
        if (configs[i].InterfaceID < 0 || configs[i].InterfaceID > 10000) {
            fprintf(stderr, "Error: Interface ID must be between 0 and 10000\n");
            continue;
        }
    }

    // Log any memory allocation failures to the error log file
    if (errno != 0) {
        FILE* errorLog = fopen("error.log", "a+");
        if (!errorLog) {
            perror("Error: Failed to open error log file for writing");
            return NULL;
        }
        fprintf(errorLog, "Memory allocation failure: %s\n", strerror(errno));
        fclose(errorLog);
    }

    // Return the array of structures
    return configs;
}
