public class MD5Hash {
    public static String getMD5Hash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hash = md.digest(input.getBytes());
            return bytesToHex(hash);
        } catch (NoSuchAlgorithmException e) {
            // Log the exception to the error log file
            try {
                FileWriter fw = new FileWriter("error.log", true);
                BufferedWriter bw = new BufferedWriter(fw);
                bw.write("Error: Failed to generate MD5 hash for input string\n");
                bw.close();
            } catch (IOException ex) {
                System.out.println("Error: Failed to write to error log file");
            }
        }
        return null;
    }

    private static String bytesToHex(byte[] hash) {
        StringBuilder hexString = new StringBuilder();
        for (int i = 0; i < hash.length; i++) {
            String hex = Integer.toHexString(0xff & hash[i]);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }
        return hexString.toString();
    }
}
