        if (config->InterfaceID == configs[i].InterfaceID) {
            return false;
        }
    }

    // Check that the network status is valid
    if (config->NetworkStatus != ACTIVE && config->NetworkStatus != INACTIVE) {
        return false;
    }

    // If all checks pass, return true
    return true;
