import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.locks.ReentrantReadWriteLock;
import java.util.logging.Logger;

public class MD5Hash {
    private static final Logger LOGGER = Logger.getLogger(MD5Hash.class.getName());
    private static final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    public static String getMD5Hash(String input) {
        try {
            // Create a MessageDigest object for the MD5 algorithm
            MessageDigest md = MessageDigest.getInstance("MD5");

            // Update the digest with the input string
            md.update(input.getBytes());

            // Get the resulting hash as a 32-character hexadecimal string
            byte[] bytes = md.digest();
            StringBuilder sb = new StringBuilder();
            for (byte b : bytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            LOGGER.log(Level.SEVERE, "Error: Failed to get MD5 hash for input string", e);
            return null;
        } finally {
            lock.readLock().unlock();
        }
    }
}
