        if (interface == NULL) {
            printf("Error: unable to find interface %d in JSON file\n", i);
            return;
        }
        int InterfaceID = json_integer_value(json_object_get(interface, "InterfaceID"));
        if (InterfaceID < 0 || InterfaceID >= MAX_INTERFACES) {
            printf("Error: invalid InterfaceID %d in JSON file\n", InterfaceID);
            return;
        }
        const char *IPAddress = json_string_value(json_object_get(interface, "IPAddress"));
        if (IPAddress == NULL || !validateIPAddress(IPAddress)) {
            printf("Error: invalid IP address %s in JSON file\n", IPAddress);
