        bool NetworkStatus = json_boolean_value(json_object_get(interface, "NetworkStatus"));
        if (NetworkStatus != ACTIVE && NetworkStatus != INACTIVE) {
            printf("Error: invalid network status %s in JSON file\n", NetworkStatus);
            return;
        }
    }

    // Initialize the array of network interface configurations
    configs = malloc(sizeof(struct NetworkInterfaceConfig) * numInterfaces);
    if (configs == NULL) {
        printf("Error: unable to allocate memory for network interface configurations\n");
        return;
    }
    for (int i = 0; i < numInterfaces; i++) {
        json_t *interface = json_array_get(interfaces, i);
        configs[i].InterfaceID = json_integer_value(json_object_get(interface, "InterfaceID"));
