    pthread_mutex_lock(&config_lock);

    // Check if the maximum number of interfaces has been exceeded
    if (numInterfaces >= MAX_INTERFACES) {
        printf("Error: maximum number of interfaces exceeded\n");
        return;
    }

    // Validate the IP address and ensure that no two configurations have the same InterfaceID
