            return;
        }
    }

    // Add the new network interface configuration to the array
    configs[numInterfaces].InterfaceID = InterfaceID;
    strcpy(configs[numInterfaces].IPAddress, IPAddress);
    strcpy(configs[numInterfaces].SubnetMask, SubnetMask);
    configs[numInterfaces].NetworkStatus = NetworkStatus;
    numInterfaces++;

    // Release the lock for thread safety
    pthread_mutex_unlock(&config_lock);
}

// Function to remove a network interface configuration
void removeNetworkInterfaceConfig(int InterfaceID) {
    // Acquire the lock for thread safety
    pthread_mutex_lock(&config_lock);

    // Find the index of the network interface configuration to be removed
    int i = 0;
    while (i < numInterfaces && configs[i].InterfaceID != InterfaceID) {
        i++;
    }
    if (i == numInterfaces) {
        printf("Error: unable to find network interface configuration with InterfaceID %d\n", InterfaceID);
        return;
    }

    // Remove the network interface configuration from the array
    for (int j = i; j < numInterfaces - 1; j++) {
        configs[j] = configs[j + 1];
    }
    numInterfaces--;

    // Release the lock for thread safety
    pthread_mutex_unlock(&config_lock);
}

