    pthread_mutex_lock(&config_lock);

    // Return a copy of the array of network interface configurations
    struct NetworkInterfaceConfig **configsCopy = malloc(sizeof(struct NetworkInterfaceConfig *) * numInterfaces);
    memcpy(configsCopy, configs, sizeof(struct NetworkInterfaceConfig) * numInterfaces);

    // Release the lock for thread safety
    pthread_mutex_unlock(&config_lock);

    return configsCopy;
}
