    if (errorLog) {
        for (int i = 0; i < MAX_NETWORK_INTERFACES; i++) {
            if (!configs[i].NetworkStatus) {
                fprintf(errorLog, "Error: Network interface %d is not active\n", configs[i].InterfaceID);
            }
        }
        fclose(errorLog);
    }

    return configs;
}

bool validateConfig(NetworkInterfaceConfig config) {
    // Validate the IP address format
    if (!isValidIPAddress(config.IPAddress)) {
        return false;
    }

    // Validate that no two configurations share the same InterfaceID
    for (int i = 0; i < MAX_NETWORK_INTERFACES; i++) {
        if (configs[i].InterfaceID == config.InterfaceID) {
            return false;
        }
    }

    return true;
}

bool isValidIPAddress(const char* ipAddress) {
    // Check that the IP address is in a valid format
    if (strlen(ipAddress) != 15 || strncmp(ipAddress, "192.168.", 8)) {
        return false;
    }

    // Check that the IP address is not reserved for local use
    if (strcmp(ipAddress + 8, "0.0.0.0") == 0 || strcmp(ipAddress + 8, "127.0.0.1") == 0) {
        return false;
    }

    // Check that the IP address is not a broadcast address
    if (strcmp(ipAddress + 8, "255.255.255.255") == 0) {
        return false;
    }

    return true;
}
