import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;
import java.util.Base64;
import java.util.concurrent.ConcurrentHashMap;

public class MD5Hash {
    private static final ConcurrentHashMap<String, String> hashCache = new ConcurrentHashMap<>();

    public static String getMD5Hash(String input) {
        if (input == null || input.trim().isEmpty()) {
            return null;
        }

        // Check if the input is already in the cache
        String cachedHash = hashCache.get(input);
        if (cachedHash != null) {
            return cachedHash;
        }

        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(input.getBytes());
            String hash = Base64.getEncoder().encodeToString(digest);
            if (hash.length() != 32) {
                return null;
            }
            hashCache.put(input, hash);
            return hash;
        } catch (NoSuchAlgorithmException e) {
            // Log the exception and return null
            System.err.println("Error: Failed to compute MD5 hash");
            e.printStackTrace();
            return null;
        }
    }

    public static String getMD5Hash(File file) throws IOException {
        if (file == null || !file.exists()) {
            return null;
        }

        // Check if the input is already in the cache
        String cachedHash = hashCache.get(file.getAbsolutePath());
        if (cachedHash != null) {
            return cachedHash;
        }

        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(Files.readAllBytes(file.toPath()));
            String hash = Base64.getEncoder().encodeToString(digest);
            if (hash.length() != 32) {
                return null;
            }
            hashCache.put(file.getAbsolutePath(), hash);
            return hash;
        } catch (NoSuchAlgorithmException e) {
            // Log the exception and return null
            System.err.println("Error: Failed to compute MD5 hash");
            e.printStackTrace();
            return null;
        }
    }
}
