public class NetworkInterfaceConfigReader {
    private static final int BATCH_SIZE = 10000;
    private static final String CSV_FILENAME = "network-interface-configs.csv";

    public static void main(String[] args) throws Exception {
        List<NetworkInterfaceConfig> configs = new ArrayList<>();
        BufferedReader reader = new BufferedReader(new FileReader(CSV_FILENAME));
        String line;
        while ((line = reader.readLine()) != null) {
            String[] tokens = line.split(",");
            int interfaceID = Integer.parseInt(tokens[0]);
