LTE_PHY_TX_TASK_T* allocate_and_initialize_array(int num_elements) {
    // Check if the input is valid
    if (num_elements <= 0 || num_elements > 50000) {
        printf("Error: Invalid number of elements specified. Must be between 1 and 50000.\n");
        return NULL;
    }

    // Allocate memory for the array
    LTE_PHY_TX_TASK_T* array = (LTE_PHY_TX_TASK_T*)malloc(num_elements * sizeof(LTE_PHY_TX_TASK_T));
    if (!array) {
        printf("Error: Memory allocation failed. Out of memory?\n");
        return NULL;
    }

    // Initialize the array elements
    for (int i = 0; i < num_elements; i++) {
        array[i].frame_parameters.frame_number = i + 1;
        array[i].frame_parameters.subframe_number = i % 10;
        array[i].frame_parameters.tdd_state = (i % 2 == 0) ? 0 : 1;
        array[i].task_params.tx_power = 10 * (i + 1);
        array[i].task_params.bandwidth = i % 3 + 1;
        array[i].task_params.carrier_frequency = 2400 + i * 5;
    }

    // Log the number of elements successfully created
    printf("Successfully created %d elements in the array.\n", num_elements);

    return array;
}

// Define a function to release all allocated memory when done
void free_array(LTE_PHY_TX_TASK_T* array) {
    if (array) {
        free(array);
    }
}
