// Define the structure to hold the data
typedef struct NFDataRecord {
    UEContext ue_context;
    PDUSessionID pdu_session_id;
    NASMessageContent nas_message_content;
} NFDataRecord;

// Define the function to populate the structures with random data
void populate_data(NFDataRecord *records, int num_records) {
    // Initialize a random number generator
    srand(time(NULL));

    // Loop through each record and populate it with random data
    for (int i = 0; i < num_records; i++) {
        NFDataRecord *record = &records[i];

        // Generate a random UE context
        record->ue_context.imsi = rand() % 1000000000;
        record->ue_context.msin = rand() % 1000000000;

        // Generate a random PDU session ID
        record->pdu_session_id.session_id = rand() % 1000000000;
        record->pdu_session_id.pdu_type = rand() % 2;

        // Generate a random NAS message content
        record->nas_message_content.sequence_number = rand() % 1000000000;
        record->nas_message_content.timestamp = time(NULL);
        record->nas_message_content.data = malloc(sizeof(char) * 1024);
        memset(record->nas_message_content.data, 'a', 1024);

        // Generate a random hash signature for the NAS message content
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256((unsigned char *)&record->nas_message_content, sizeof(NASMessageContent), hash);
        memcpy(record->nas_message_content.hash_signature, hash, SHA256_DIGEST_LENGTH);
    }
}

// Define the function to validate the integrity of the NAS message content
bool validate_integrity(NFDataRecord *records, int num_records) {
    // Loop through each record and verify the hash signature
    for (int i = 0; i < num_records; i++) {
        NFDataRecord *record = &records[i];

        // Generate a new hash signature for the NAS message content
        unsigned char new_hash[SHA256_DIGEST_LENGTH];
        SHA256((unsigned char *)&record->nas_message_content, sizeof(NASMessageContent), new_hash);

        // Compare the generated hash signature with the stored one
        if (memcmp(new_hash, record->nas_message_content.hash_signature, SHA256_DIGEST_LENGTH) != 0) {
            return false;
        }
    }

    // If all hash signatures match, return true
    return true;
}
