bool verify_access_token(const char *json) {
    // Parse the JSON object representing the access token response
    json_object *root = json_tokener_parse(json);
    if (!root) {
        return false;
    }

    // Check that the token type is 'Bearer' and the expires in field is a positive integer
    const char *token_type = json_object_get_string(json_object_object_get(root, "token_type"));
    if (strcmp(token_type, "Bearer") != 0) {
        return false;
    }
    int expires_in = json_object_get_int(json_object_object_get(root, "expires_in"));
    if (expires_in <= 0) {
        return false;
    }

    // Check that the refresh token field is not present or is a string
    const char *refresh_token = json_object_get_string(json_object_object_get(root, "refresh_token"));
    if (refresh_token && strlen(refresh_token) > 0) {
        return false;
    }

    // Check that the access token field is a string
