// Define the function to dynamically allocate and initialize an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocateAndInitializeArray(int numElements) {
    // Check for insufficient heap space
    if (numElements > 10000) {
        printf("Error: Insufficient heap space to allocate %d elements\n", numElements);
        return NULL;
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        printf("Error: Failed to allocate memory for %d elements\n", numElements);
        return NULL;
    }

    // Initialize each structure in the array
    for (int i = 0; i < numElements; i++) {
        array[i].rxUeInformationTag = RX_UE_INFORMATION_TAG_INIT;
        array[i].rnti = RNTI_INIT;
        array[i].crcIndicationRel8Tag = CRC_INDICATION_REL8_TAG_INIT;
        array[i].crcFlag = (rand() % 2) ? true : false; // Randomly set crcFlag to either 0 or 1
    }

    return array;
}

// Define the function to release all allocated memory when done
void freeArray(NFAPI_CRC_INDICATION_PDU_T* array) {
