    numElements = 1000;
    array = allocateAndInitializeArray(numElements);
    if (!array) {
        printf("Error: Failed to allocate memory for %d elements\n", numElements);
        return 1;
    }
    freeArray(array);

    // Log the number of elements successfully created, any errors encountered during allocation, and the total memory usage in kilobytes
