// Define the structure for a linked list node
typedef struct NFAPI_MESSAGE_T {
    UE_IDENTIFIER ue_identifier;
    CELL_ID cell_id;
    NETWORK_EVENT_TAG network_event_tag;
    struct NFAPI_MESSAGE_T* next;
} NFAPI_MESSAGE_T;

// Define the function to integrate the creation and management of a linked list of NFAPI_MESSAGE_T structures
int create_and_manage_linked_list(NFAPI_MESSAGE_T** head) {
    // Initialize the head pointer to NULL
    *head = NULL;

    // Loop until all network events have been processed
    while (1) {
        // Read a network event from the input stream
        NETWORK_EVENT_TAG network_event_tag;
        read_network_event(&network_event_tag);

        // Check if the network event is valid
        if (!validate_network_event(network_event_tag)) {
            continue;
        }

        // Create a new linked list node for the network event
        NFAPI_MESSAGE_T* new_node = (NFAPI_MESSAGE_T*)malloc(sizeof(NFAPI_MESSAGE_T));
        if (!new_node) {
            return -1; // Memory allocation failed
        }

        // Initialize the fields of the linked list node
        new_node->ue_identifier = network_event_tag.ue_identifier;
        new_node->cell_id = network_event_tag.cell_id;
        new_node->network_event_tag = network_event_tag;
        new_node->next = NULL;

        // Add the linked list node to the head of the linked list
        if (*head == NULL) {
            *head = new_node;
        } else {
            NFAPI_MESSAGE_T* current = *head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_node;
        }
    }

    // Return success
    return 0;
}

// Define the function to handle and log network connectivity events
void handle_and_log_network_event(NFAPI_MESSAGE_T* head) {
    // Loop through all linked list nodes in the linked list
    while (head != NULL) {
        // Log the type of event, timestamp, and UE identifier associated with each event
        printf("Event: %s\n", get_event_type(head->network_event_tag));
        printf("Timestamp: %lu\n", head->network_event_tag.timestamp);
        printf("UE Identifier: %d\n", head->ue_identifier);

        // Move to the next linked list node
        head = head->next;
    }
}

// Define the function to filter and retrieve specific types of network events based on a provided CELL_ID
void filter_and_retrieve_network_events(NFAPI_MESSAGE_T* head, CELL_ID cell_id) {
    // Loop through all linked list nodes in the linked list
    while (head != NULL) {
        // Check if the current node has a matching CELL_ID
        if (head->cell_id == cell_id) {
            // Log the type of event, timestamp, and UE identifier associated with each event
            printf("Event: %s\n", get_event_type(head->network_event_tag));
            printf("Timestamp: %lu\n", head->network_event_tag.timestamp);
            printf("UE Identifier: %d\n", head->ue_identifier);
        }

        // Move to the next linked list node
        head = head->next;
    }
}

// Define the function to validate network events before processing
int validate_network_event(NETWORK_EVENT_TAG network_event_tag) {
    // Check if the UE identifier is valid
    if (network_event_tag.ue_identifier < 0) {
        return 0; // Invalid UE identifier
    }

    // Check if the CELL ID is valid
    if (network_event_tag.cell_id < 0) {
        return 0; // Invalid CELL ID
    }

    // Check if the network event tag is valid
    if (!is_valid_network_event_tag(network_event_tag)) {
        return 0; // Invalid network event tag
    }

    // Return success
    return 1;
}

// Define the function to retrieve the type of event from a NETWORK_EVENT_TAG structure
char* get_event_type(NETWORK_EVENT_TAG network_event_tag) {
    switch (network_event_tag.event_type) {
        case ATTACHED:
            return "Attached";
        case DETACHED:
            return "Detached";
        case HANDOVER:
            return "Handover";
        default:
            return "Unknown";
    }
}

// Define the function to check if a NETWORK_EVENT_TAG structure is valid
int is_valid_network_event_tag(NETWORK_EVENT_TAG network_event_tag) {
    // Check if the event type is valid
    if (network_event_tag.event_type < 0 || network_event_tag.event_type > 2) {
        return 0; // Invalid event type
    }

    // Check if the timestamp is valid
    if (network_event_tag.timestamp < 0) {
        return 0; // Invalid timestamp
    }

    // Return success
    return 1;
}
