// Define the structure for DeviceStatusLog
typedef struct {
    time_t timestamp;
    int deviceID;
    int eventCode;
    char* eventMessage;
} DeviceStatusLog;

// Define the function to initialize the list of DeviceStatusLog entries
void initDeviceStatusLog(int numEntries) {
    // Allocate memory for the list of DeviceStatusLog entries
    DeviceStatusLog** logList = (DeviceStatusLog**)malloc(numEntries * sizeof(DeviceStatusLog*));
    if (!logList) {
        printf("Error: Failed to allocate memory for the list of DeviceStatusLog entries\n");
        return;
    }

    // Initialize each entry in the list with a timestamp, device ID, event code, and event message
    for (int i = 0; i < numEntries; i++) {
        logList[i] = (DeviceStatusLog*)malloc(sizeof(DeviceStatusLog));
        if (!logList[i]) {
            printf("Error: Failed to allocate memory for DeviceStatusLog entry %d\n", i);
            return;
        }
        logList[i]->timestamp = time(NULL);
        logList[i]->deviceID = 0;
        logList[i]->eventCode = 0;
        logList[i]->eventMessage = NULL;
    }

    // Handle interruptions during input and terminate the program gracefully if necessary
    signal(SIGINT, handleInterrupt);

    // Manage concurrency safely when multiple threads attempt to log events simultaneously
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Process a list of floating-point numbers received from standard input, ensuring the input size does not exceed 1000 elements
    int numInputs = 0;
    float* inputs = (float*)malloc(numEntries * sizeof(float));
    if (!inputs) {
        printf("Error: Failed to allocate memory for the list of floating-point numbers\n");
        return;
    }
    while (fscanf(stdin, "%f", &inputs[numInputs]) == 1 && numInputs < numEntries) {
        numInputs++;
    }

    // Store these numbers in a dynamically allocated array, handling edge cases such as all numbers being identical or the dataset containing only negative values
    if (numInputs == 0) {
        printf("No numbers provided\n");
        return;
    } else if (numInputs == numEntries) {
        // All numbers are identical, so just use the first number as the mean, median, and mode
        float mean = inputs[0];
        float median = inputs[0];
        int mode = 0;
        for (int i = 1; i < numInputs; i++) {
            if (inputs[i] > mean) {
                mean = inputs[i];
            } else if (inputs[i] == mean) {
                mode++;
            }
        }
        printf("Mean: %f\nMedian: %f\nMode: %d\n", mean, median, mode);
    } else {
        // Sort the list of numbers in ascending order
        qsort(inputs, numInputs, sizeof(float), compareFloats);

        // Compute and print the mean, median, and mode of the numbers
        float sum = 0;
        for (int i = 0; i < numInputs; i++) {
            sum += inputs[i];
        }
        float mean = sum / numInputs;
        int medianIndex = numInputs / 2;
        if (numInputs % 2 == 0) {
            // Even number of elements, so take the average of the two middle elements
            float median1 = inputs[medianIndex - 1];
            float median2 = inputs[medianIndex];
            float median = (median1 + median2) / 2;
        } else {
            // Odd number of elements, so just take the middle element
            float median = inputs[medianIndex];
        }
        int mode = 0;
        for (int i = 1; i < numInputs; i++) {
            if (inputs[i] > mean) {
                mean = inputs[i];
            } else if (inputs[i] == mean) {
                mode++;
            }
        }
        printf("Mean: %f\nMedian: %f\nMode: %d\n", mean, median, mode);
    }

    // Free the memory allocated for the list of DeviceStatusLog entries and the list of floating-point numbers
    free(logList);
    free(inputs);
}

// Define a helper function to compute and print the mean, median, and mode of the numbers
void computeMeanMedianMode(float* inputs, int numInputs) {
    // Sort the list of numbers in ascending order
    qsort(inputs, numInputs, sizeof(float), compareFloats);

    // Compute and print the mean, median, and mode of the numbers
    float sum = 0;
    for (int i = 0; i < numInputs; i++) {
        sum += inputs[i];
    }
    float mean = sum / numInputs;
    int medianIndex = numInputs / 2;
    if (numInputs % 2 == 0) {
        // Even number of elements, so take the average of the two middle elements
        float median1 = inputs[medianIndex - 1];
        float median2 = inputs[medianIndex];
        float median = (median1 + median2) / 2;
    } else {
        // Odd number of elements, so just take the middle element
        float median = inputs[medianIndex];
    }
    int mode = 0;
    for (int i = 1; i < numInputs; i++) {
        if (inputs[i] > mean) {
            mean = inputs[i];
        } else if (inputs[i] == mean) {
            mode++;
        }
    }
    printf("Mean: %f\nMedian: %f\nMode: %d\n", mean, median, mode);
}

// Define a function to handle interruptions during input and terminate the program gracefully if necessary
void handleInterrupt(int sig) {
    // Free the memory allocated for the list of DeviceStatusLog entries and the list of floating-point numbers
    free(logList);
    free(inputs);

    // Print a message indicating that the program has been terminated
    printf("Program terminated due to interruption\n");

    // Exit the program with an error code
    exit(1);
}

// Define a function to compare two floating-point numbers and return their difference
int compareFloats(const void* a, const void* b) {
    float diff = *(float*)a - *(float*)b;
    if (diff < 0) {
        return -1;
    } else if (diff > 0) {
        return 1;
    } else {
        return 0;
    }
}
