#include <stdio.h>
#include <string.h>
#include <stdlib.h>

char* generate_new_filename(const char* filename) {
    // Calculate the maximum number of digits in the new extension
    int max_digits = 10;

    // Determine the number of vowels in the original filename
    int num_vowels = 0;
    for (int i = 0; i < strlen(filename); i++) {
        if (filename[i] == 'a' || filename[i] == 'e' || filename[i] == 'i' || filename[i] == 'o' || filename[i] == 'u') {
            num_vowels++;
        }
    }

    // Calculate the number of digits in the new extension
    int num_digits = num_vowels > max_digits ? max_digits : num_vowels;

    // Generate a random sequence of digits for the new extension
    char* digits = (char*)malloc(num_digits + 1);
    for (int i = 0; i < num_digits; i++) {
        digits[i] = '0' + rand() % 10;
    }
    digits[num_digits] = '\0';

    // Construct the new filename
    char* new_filename = (char*)malloc(strlen(filename) + num_digits + strlen(".txt") + 1);
    sprintf(new_filename, "%s%s.txt", filename, digits);

    // Handle potential buffer overflows by calculating the necessary buffer size beforehand
    int new_filename_length = strlen(new_filename);
    if (new_filename_length > 256) {
        free(new_filename);
        return NULL;
    }

    // Ensure the new filename does not exceed a maximum length of 256 characters
    if (new_filename_length > 256) {
        new_filename[256] = '\0';
    }

    // Correctly manage file extensions, even when they are missing or incorrectly formatted
    char* extension = strrchr(new_filename, '.');
    if (extension == NULL || strlen(extension) > 4) {
        free(new_filename);
        return NULL;
    }

    // Return the new filename
    return new_filename;
}
