#define MAX_FILENAME_LENGTH 256
#define MAX_IDENTIFIER_LENGTH 100
#define MAX_RETRY_COUNT 5
#define RETRY_DELAY_MS 1000

typedef struct {
    char* filename;
    char* filetype;
    int max_length;
} FileMetadata;

char* processAndPersistFileMetadata(const char* filename, const char* filetype, int max_length) {
    // Validate input parameters
    if (filename == NULL || filetype == NULL) {
        return "Invalid input parameters";
    }

    // Initialize variables
    char* identifier = NULL;
    char* new_filename = NULL;
    int retry_count = 0;
    sqlite3* db = NULL;
    sqlite3_stmt* stmt = NULL;

    // Open the database connection
    if (sqlite3_open("filemetadata.db", &db) != SQLITE_OK) {
        return "Failed to open database";
    }

    // Create a statement for inserting file metadata
    char* insert_stmt = "INSERT INTO filemetadata (filename, filetype, identifier) VALUES (?, ?, ?);";
    if (sqlite3_prepare_v2(db, insert_stmt, -1, &stmt, NULL) != SQLITE_OK) {
        return "Failed to prepare statement";
    }

    // Validate the file type
    int valid_filetype = 1;
    for (int i = 0; i < strlen(filetype); i++) {
        if (!isalnum(filetype[i]) && filetype[i] != '-') {
            valid_filetype = 0;
            break;
        }
    }
    if (!valid_filetype) {
        return "Invalid file type";
    }

    // Generate a unique identifier for the file
    int filename_length = strlen(filename);
    int vowel_count = 0;
    for (int i = 0; i < filename_length; i++) {
        if (isvowel(filename[i])) {
            vowel_count++;
        }
    }
    identifier = malloc((MAX_IDENTIFIER_LENGTH + 1) * sizeof(char));
    sprintf(identifier, "%d-%d", filename_length, vowel_count);

    // Construct the new filename
    int new_filename_length = MAX_FILENAME_LENGTH - strlen(identifier);
    new_filename = malloc((new_filename_length + 1) * sizeof(char));
    sprintf(new_filename, "%s%s", filename, identifier);

    // Persist the file metadata to the database
    int result;
    do {
        result = sqlite3_step(stmt);
        if (result == SQLITE_BUSY) {
            retry_count++;
            usleep(RETRY_DELAY_MS * 1000);
        } else if (result != SQLITE_DONE) {
            return "Failed to persist file metadata";
        }
    } while (retry_count < MAX_RETRY_COUNT && result == SQLITE_BUSY);
    if (retry_count >= MAX_RETRY_COUNT) {
        return "Maximum retries exceeded";
    }

    // Free dynamically allocated memory
    sqlite3_finalize(stmt);
    free(identifier);
    free(new_filename);

    // Log the operation and return the persisted file metadata
    char* log_message = malloc((strlen(filename) + 100) * sizeof(char));
    sprintf(log_message, "Processed file %s with identifier %s", filename, identifier);
    printf("%s\n", log_message);
    free(log_message);
    return new_filename;
}
