    char* filetype;
    size_t maxlength;
    time_t expiration;
} FileMetadata;

char* processAndPersistFileMetadata(const char* filename, const char* filetype, size_t maxlength, time_t expiration) {
    // Validate input parameters
    if (filename == NULL || filetype == NULL || maxlength > MAX_FILENAME_LENGTH) {
        return "Invalid input";
    }

    // Generate unique identifier for the file
    size_t filenameLength = strlen(filename);
    size_t vowelCount = 0;
    char* identifier = (char*)malloc(MAX_IDENTIFIER_LENGTH);
    if (identifier == NULL) {
        return "Memory allocation failed";
    }
    for (size_t i = 0; i < filenameLength; i++) {
        if (isalpha(filename[i]) && isvowel(filename[i])) {
            vowelCount++;
        }
    }
    snprintf(identifier, MAX_IDENTIFIER_LENGTH, "%s-%zu", filename, vowelCount);

    // Construct new filename and validate its length
    size_t identifierLength = strlen(identifier);
    if (identifierLength > maxlength) {
        free(identifier);
        return "Maximum file name length exceeded";
    }
    char* newFilename = (char*)malloc(maxlength + 1);
    if (newFilename == NULL) {
        free(identifier);
        return "Memory allocation failed";
    }
    snprintf(newFilename, maxlength + 1, "%s", identifier);

    // Validate file type and convert to lowercase
    size_t filetypeLength = strlen(filetype);
    if (filetypeLength > MAX_FILENAME_LENGTH) {
        free(identifier);
        free(newFilename);
        return "Maximum file type length exceeded";
    }
    char* lowercaseFiletype = (char*)malloc(filetypeLength + 1);
    if (lowercaseFiletype == NULL) {
        free(identifier);
        free(newFilename);
        return "Memory allocation failed";
    }
    for (size_t i = 0; i < filetypeLength; i++) {
        lowercaseFiletype[i] = tolower(filetype[i]);
    }
    lowercaseFiletype[filetypeLength] = '\0';

    // Persist metadata to database
    sqlite3* db = NULL;
    int rc = sqlite3_open("metadata.db", &db);
    if (rc != SQLITE_OK) {
        free(identifier);
        free(newFilename);
        free(lowercaseFiletype);
        return "Database open failed";
    }
    char* sql = "INSERT INTO file_metadata VALUES(?, ?, ?, ?)";
    sqlite3_stmt* stmt = NULL;
    rc = sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
    if (rc != SQLITE_OK) {
        free(identifier);
        free(newFilename);
        free(lowercaseFiletype);
        return "SQL prepare failed";
    }
    sqlite3_bind_text(stmt, 1, newFilename, -1, SQLITE_STATIC);
    sqlite3_bind_text(stmt, 2, lowercaseFiletype, -1, SQLITE_STATIC);
    sqlite3_bind_int64(stmt, 3, expiration);
    rc = sqlite3_step(stmt);
    if (rc != SQLITE_DONE) {
        free(identifier);
        free(newFilename);
        free(lowercaseFiletype);
        return "SQL execution failed";
    }
    sqlite3_finalize(stmt);
    sqlite3_close(db);

    // Free memory and return success
    free(identifier);
    free(newFilename);
    free(lowercaseFiletype);
    return NULL;
}
