// Function to create and populate a list of CRC indication PDUs
NFAPI_CRC_INDICATION_LIST* create_crc_indication_list(size_t max_count) {
    // Allocate memory for the list
    NFAPI_CRC_INDICATION_LIST *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST));
    if (list == NULL) {
        printf("Error: Failed to allocate memory for CRC indication list\n");
        return NULL;
    }

    // Initialize the count and pdu pointers
    list->count = 0;
    list->pdu = NULL;

    // Set the maximum size of the list
    if (max_count > 0) {
        list->max_size = max_count;
    } else {
        list->max_size = SIZE_MAX;
    }

    return list;
}

// Function to add a CRC indication PDU to the list
int add_crc_indication_pdu(NFAPI_CRC_INDICATION_LIST *list, uint16_t RX_UE_INFORMATION_TAG, uint32_t RNTI, uint8_t CRCFLAG) {
    // Check if the list is full
    if (list->count >= list->max_size) {
        printf("Error: CRC indication list is full\n");
        return -1;
    }

    // Allocate memory for the new PDU
