#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

// Define the structure for the request body
typedef struct REQUEST_BODY {
    char *data;
    size_t size;
} REQUEST_BODY;

// Function to update an existing resource using the HTTP PUT method and return the updated resource
int put_resource(char *url, REQUEST_BODY *body) {
    // Initialize the CURL handle
    CURL *curl = curl_easy_init();
    if (curl == NULL) {
        printf("Error: Failed to initialize CURL\n");
        return -1;
    }

    // Set the URL and request body for the PUT request
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_PUT, 1L);
    curl_easy_setopt(curl, CURLOPT_INFILESIZE, (long)body->size);
    curl_easy_setopt(curl, CURLOPT_READDATA, body->data);

    // Perform the PUT request and check for errors
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        printf("Error: Failed to perform PUT request\n");
        return -1;
    }

    // Get the response code from the server
    long response_code;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
    if (response_code != 200) {
        printf("Error: Received non-OK response code %ld\n", response_code);
        return -1;
    }

    // Clean up the CURL handle and request body
    curl_easy_cleanup(curl);
    free(body->data);

    return 0;
}
