// Define a struct to store the measurement data
struct Measurement {
    char *unit; // Unit of measurement (e.g., meters, feet, inches)
    double value; // Value of the measurement in centimeters
};

// Function to read input from file or standard input
void readInput(char *filename, struct Measurement **measurements, int *num_measurements) {
    FILE *file = NULL;
    if (filename != NULL) {
        // Open the file for reading
        file = fopen(filename, "r");
        if (file == NULL) {
            printf("Error: Could not open file %s\n", filename);
            exit(1);
        }
    } else {
        // Use standard input as the source of data
        file = stdin;
    }

    // Read each line of the file and parse it into a measurement struct
    *num_measurements = 0;
    while (fgets(line, sizeof(line), file) != NULL) {
        char *token = strtok(line, " ");
        if (token == NULL) {
            // Ignore blank lines or lines with no data
            continue;
        }

        struct Measurement measurement;
        measurement.unit = token;
        token = strtok(NULL, " ");
        if (token != NULL) {
            measurement.value = atof(token);
        } else {
            // Ignore lines with no value
            continue;
        }

        // Add the measurement to the array of measurements
        (*measurements)[*num_measurements] = measurement;
        *num_measurements += 1;
    }

    if (file != stdin) {
        fclose(file);
    }
}

// Function to convert a measurement from one unit to another
double convertUnit(struct Measurement measurement, char *unit) {
    double value = 0.0;
    if (strcmp(measurement.unit, "meters") == 0) {
        // Convert meters to the specified unit
        if (strcmp(unit, "centimeters") == 0) {
            value = measurement.value * 100.0;
        } else if (strcmp(unit, "feet") == 0) {
            value = measurement.value * 3.28084;
        } else if (strcmp(unit, "inches") == 0) {
            value = measurement.value * 39.3701;
        } else {
            // Unsupported unit type
            printf("Error: Unsupported unit type %s\n", unit);
            exit(1);
        }
    } else if (strcmp(measurement.unit, "feet") == 0) {
        // Convert feet to the specified unit
        if (strcmp(unit, "centimeters") == 0) {
            value = measurement.value * 30.48;
        } else if (strcmp(unit, "meters") == 0) {
            value = measurement.value / 3.28084;
        } else if (strcmp(unit, "inches") == 0) {
            value = measurement.value * 12.0;
        } else {
            // Unsupported unit type
            printf("Error: Unsupported unit type %s\n", unit);
            exit(1);
        }
    } else if (strcmp(measurement.unit, "inches") == 0) {
        // Convert inches to the specified unit
        if (strcmp(unit, "centimeters") == 0) {
            value = measurement.value * 2.54;
        } else if (strcmp(unit, "feet") == 0) {
            value = measurement.value / 12.0;
        } else if (strcmp(unit, "meters") == 0) {
            value = measurement.value / 39.3701;
        } else {
            // Unsupported unit type
            printf("Error: Unsupported unit type %s\n", unit);
            exit(1);
        }
    } else {
        // Unsupported unit type
        printf("Error: Unsupported unit type %s\n", measurement.unit);
        exit(1);
    }

    return value;
}

// Function to calculate the total length in a specified unit
double calculateTotalLength(struct Measurement *measurements, int num_measurements, char *unit) {
    double total = 0.0;
    for (int i = 0; i < num_measurements; i++) {
        struct Measurement measurement = measurements[i];
        double convertedValue = convertUnit(measurement, unit);
        if (convertedValue == -1) {
            // Invalid input
            printf("Error: Invalid input for measurement %d\n", i + 1);
            exit(1);
        } else {
            total += convertedValue;
        }
    }

    return total;
}

int main(int argc, char *argv[]) {
    // Check command-line arguments
    if (argc < 2) {
        printf("Usage: %s [input file]\n", argv[0]);
        exit(1);
    }

    // Read input from file or standard input
    char *filename = NULL;
    if (argc > 2) {
        filename = argv[2];
    }
    struct Measurement *measurements = NULL;
    int num_measurements = 0;
    readInput(filename, &measurements, &num_measurements);

    // Calculate the total length in the specified unit
    char *unit = argv[1];
    double total = calculateTotalLength(measurements, num_measurements, unit);

    // Print the total length
    printf("Total length: %f %s\n", total, unit);

    // Free dynamically allocated memory
    free(measurements);

    return 0;
}
