            fprintf(stderr, "Error: %s is not a valid file or directory\n", path);
            continue;
        }

        // check if input is a compressed file and decompress if necessary
        char *file_ext = strrchr(path, '.');
        if (file_ext != NULL && strcmp(file_ext, FILE_EXT_GZ) == 0) {
            gzFile fp = gzopen(path, "rb");
            if (fp == NULL) {
                fprintf(stderr, "Error: unable to open compressed file %s\n", path);
                continue;
            }
            char *decompressed_path = malloc(strlen(path) - strlen(FILE_EXT_GZ) + 1);
            strncpy(decompressed_path, path, strlen(path) - strlen(FILE_EXT_GZ));
            decompressed_path[strlen(path) - strlen(FILE_EXT_GZ)] = '\0';
            gzclose(fp);
            path = decompressed_path;
        }

        // process file/directory recursively if necessary
        if (S_ISDIR(st.st_mode)) {
            DIR *dir = opendir(path);
            struct dirent *entry;
            while ((entry = readdir(dir)) != NULL) {
                char *file_name = entry->d_name;
                if (strcmp(file_name, ".") == 0 || strcmp(file_name, "..") == 0) {
                    continue;
