                char *full_path = malloc(strlen(path) + strlen(file_name) + 2);
                sprintf(full_path, "%s/%s", path, file_name);
                process_input(&full_path, 1);
            }
            closedir(dir);
        } else {
            // read lines from file and count line breaks
            FILE *fp = fopen(path, "r");
            if (fp == NULL) {
                fprintf(stderr, "Error: unable to open file %s\n", path);
                continue;
            }
            char *line = NULL;
            size_t len = 0;
            ssize_t read;
            while ((read = getline(&line, &len, fp)) != -1) {
                num_lines++;
            }
            free(line);
            fclose(fp);
        }
    }
}

