// Define a function to process a single file
void process_file(input_source_t *src) {
    FILE *fp = fopen(src->path, "r");
    if (!fp) {
        perror("fopen");
        return;
    }

    // Read the file line by line and count the lines
    int line_count = 0;
    char buf[1024];
    while (fgets(buf, sizeof(buf), fp)) {
        line_count++;
    }

    // Close the file
    fclose(fp);

    printf("File %s has %d lines\n", src->path, line_count);
}

// Define a function to process a single directory
void process_directory(input_source_t *src) {
    DIR *dir = opendir(src->path);
    if (!dir) {
        perror("opendir");
        return;
    }

    // Read the directory entries and process each file or sub-directory
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char *path = entry->d_name;
        if (strcmp(path, ".") == 0 || strcmp(path, "..") == 0) {
            continue; // Skip the current and parent directory
        }

        input_source_t subsrc = {.path = path, .type = src->type};
        if (subsrc.type == FILE_TYPE) {
            process_file(&subsrc);
        } else {
            process_directory(&subsrc);
        }
    }

    // Close the directory
    closedir(dir);
}

// Define a function to process an input source
void process_input_source(input_source_t *src) {
    if (src->type == FILE_TYPE) {
        process_file(src);
    } else {
        process_directory(src);
    }
}

