    // Check the number of arguments and print usage if necessary
    if (argc < 2) {
        printf("Usage: %s [input sources]\n", argv[0]);
        return;
    }

    // Create an array to hold the input sources
    int num_sources = argc - 1;
    input_source_t *sources = malloc(num_sources * sizeof(input_source_t));
    if (!sources) {
        perror("malloc");
        return;
    }

    // Parse the command-line arguments and create input sources
    for (int i = 1; i < argc; i++) {
        char *path = argv[i];
        struct stat st;
        if (stat(path, &st) == -1) {
            perror("stat");
            continue; // Skip unsupported input sources
        }

        int type = FILE_TYPE;
        if (S_ISDIR(st.st_mode)) {
            type = DIR_TYPE;
        } else if (!S_ISREG(st.st_mode)) {
            fprintf(stderr, "Unsupported input source: %s\n", path);
            continue; // Skip unsupported input sources
        }

        sources[i - 1] = (input_source_t){.path = path, .type = type};
    }

    // Process each input source in parallel threads with a fixed thread pool size
    int num_threads = 4; // Fixed thread pool size
    pthread_t *threads = malloc(num_threads * sizeof(pthread_t));
    if (!threads) {
        perror("malloc");
        return;
    }

    for (int i = 0; i < num_sources; i++) {
        input_source_t *src = &sources[i];
        pthread_create(&threads[i], NULL, process_input_source, src);
    }

    // Wait for all threads to complete and print the total line count
    int total_line_count = 0;
    for (int i = 0; i < num_sources; i++) {
        pthread_join(threads[i], NULL);
        input_source_t *src = &sources[i];
        if (src->type == FILE_TYPE) {
            total_line_count += src->line_count;
        } else {
            total_line_count += process_directory(src);
        }
    }

    printf("Total line count: %d\n", total_line_count);
}

int main(int argc, char **argv) {
    handle_arguments(argc, argv);
    return 0;
}
