void parseCommandLineArguments(int argc, char **argv) {
    // Check if input file is provided
    if (argc == 1) {
        printf("Usage: %s <input file>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    // Parse command line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-d") == 0) {
            // Set delimiter
            if (i + 1 >= argc) {
                printf("Error: Missing delimiter argument\n");
                exit(EXIT_FAILURE);
            }
            i++;
        } else if (strcmp(argv[i], "-o") == 0) {
            // Set output file
            if (i + 1 >= argc) {
                printf("Error: Missing output file argument\n");
                exit(EXIT_FAILURE);
            }
            i++;
        } else {
            // Add input file to list
            inputFiles.push_back(argv[i]);
        }
    }
}

void readInputFile(const char *filename) {
    // Open input file
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        printf("Error: Could not open input file %s\n", filename);
        exit(EXIT_FAILURE);
    }

    // Read input file line by line
    char buffer[BUFSIZ];
    size_t bytesRead;
    while ((bytesRead = read(fd, buffer, BUFSIZ)) > 0) {
        // Count lines in buffer
        int lines = 0;
        for (int i = 0; i < bytesRead; i++) {
            if (buffer[i] == '\n') {
                lines++;
            }
        }

        // Print line count
        printf("%s: %d\n", filename, lines);
    }

    // Close input file
    close(fd);
}

void readCompressedInputFile(const char *filename) {
    // Open compressed input file
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        printf("Error: Could not open compressed input file %s\n", filename);
        exit(EXIT_FAILURE);
    }

    // Decompress input file
    z_stream strm;
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;
    strm.avail_in = 0;
    strm.next_in = Z_NULL;
    inflateInit(&strm);
    char buffer[BUFSIZ];
    size_t bytesRead;
    while ((bytesRead = read(fd, buffer, BUFSIZ)) > 0) {
        // Decompress buffer
        strm.avail_in = bytesRead;
        strm.next_in = (unsigned char *)buffer;
        inflate(&strm, Z_NO_FLUSH);
    }
    inflateEnd(&strm);

    // Read decompressed input file line by line
    int lines = 0;
    for (int i = 0; i < strm.total_out; i++) {
        if (buffer[i] == '\n') {
            lines++;
        }
    }

    // Print line count
    printf("%s: %d\n", filename, lines);

    // Close compressed input file
    close(fd);
}

void readInputFiles() {
    // Read each input file
    for (int i = 0; i < inputFiles.size(); i++) {
        const char *filename = inputFiles[i];
        if (strcmp(filename, ".gz") == 0) {
            readCompressedInputFile(filename);
        } else {
            readInputFile(filename);
        }
    }
}

void printUsage() {
    printf("Usage: %s <input file>\n", argv[0]);
    exit(EXIT_FAILURE);
}

int main(int argc, char **argv) {
    // Parse command line arguments
    parseCommandLineArguments(argc, argv);

    // Read input files
    readInputFiles();

    return 0;
}
