    // If the interface was found, update its status and return
    if (i < MAX_NETWORK_INTERFACES) {
        configs[i].NetworkStatus = NetworkStatus;
        return;
    }

    // Otherwise, log an error message and return
    fprintf(stderr, "Error: Interface with ID %s not found\n", InterfaceID);
}

// Define function to generate a unique identifier for each configuration based on a combination of the interface ID and current timestamp
char* generateUniqueIdentifier(NetworkInterfaceConfig* config) {
    // Get the current timestamp in milliseconds
    time_t t = time(NULL);
    struct tm* now = localtime(&t);
    int ms = (int)(now->tm_sec * 1000 + now->tm_min * 60000 + now->tm_hour * 3600000);

    // Generate a unique identifier based on the interface ID and current timestamp
    char* id = (char*)malloc(INTERFACE_ID_LENGTH + 1);
    sprintf(id, "%s-%d", config->InterfaceID, ms);

    return id;
}

// Define function to compute MD5 hash of a string or file
char* getMD5Hash(const char* input) {
    // Allocate memory for the MD5 hash
    unsigned char* md5 = (unsigned char*)malloc(16);
    if (!md5) {
        fprintf(stderr, "Error: Failed to allocate memory for MD5 hash\n");
        return NULL;
    }

    // Compute the MD5 hash of the input string or file
    int len = strlen(input);
    if (len > 0) {
        MD5_CTX ctx;
        MD5_Init(&ctx);
        MD5_Update(&ctx, input, len);
        MD5_Final(md5, &ctx);
    } else {
        fprintf(stderr, "Error: Input string is empty\n");
        free(md5);
        return NULL;
    }

    // Convert the MD5 hash to a hexadecimal string
    char* hash = (char*)malloc(32 + 1);
    for (int i = 0; i < 16; i++) {
        sprintf(hash + i * 2, "%02x", md5[i]);
    }

    // Free memory allocated for the MD5 hash
    free(md5);

    return hash;
}

