    public static boolean compressLogs(List<LogEntry> logEntries) {
        try (ZipOutputStream zipOut = new ZipOutputStream(new File("log_archive.zip"))) {
            for (LogEntry logEntry : logEntries) {
                // Compress the log entry into the ZIP archive
                byte[] buffer = logEntry.getMessage().getBytes();
