        } else {
            fprintf(stderr, "Error: missing IP address in network interface %d\n", i + 1);
            goto cleanup;
        }

        // Check that the gateway is valid
        if (json_object_has_member(interface, "Gateway")) {
            const char *gateway = json_object_get_string(json_object_get_member(interface, "Gateway"));
            if (!inet_pton(AF_INET, gateway, NULL)) {
