#include <iostream>
#include <fstream>
#include <vector>
#include <zlib.h>

void compressAndStoreData(const std::vector<std::string> &data) {
    // Open the output file for writing
    std::ofstream outfile("compressed_data.bin", std::ios::binary);
    if (!outfile) {
        std::cerr << "Error: unable to open output file\n";
        return;
    }

    // Compress the data using zlib
    uLongf compressed_size = compressBound(data.size());
    Bytef *compressed_data = (Bytef *)malloc(compressed_size);
    if (!compressed_data) {
        std::cerr << "Error: unable to allocate memory for compressed data\n";
        return;
    }
    int status = compress2(compressed_data, &compressed_size, (const Bytef *)&data[0], data.size(), Z_BEST_COMPRESSION);
    if (status != Z_OK) {
        std::cerr << "Error: compression failed with error code " << status << "\n";
        free(compressed_data);
        return;
    }

    // Write the compressed data to the output file
    outfile.write((char *)compressed_data, compressed_size);
    if (!outfile) {
        std::cerr << "Error: unable to write compressed data to output file\n";
        free(compressed_data);
        return;
    }

    // Verify the integrity of the stored data by decompressing it and comparing it with the original data
    uLongf uncompressed_size = data.size();
    Bytef *uncompressed_data = (Bytef *)malloc(uncompressed_size);
    if (!uncompressed_data) {
        std::cerr << "Error: unable to allocate memory for decompressed data\n";
        free(compressed_data);
        return;
    }
    status = uncompress(uncompressed_data, &uncompressed_size, compressed_data, compressed_size);
    if (status != Z_OK) {
        std::cerr << "Error: decompression failed with error code " << status << "\n";
        free(compressed_data);
        free(uncompressed_data);
        return;
    }
    if (memcmp(uncompressed_data, &data[0], data.size()) != 0) {
        std::cerr << "Error: decompressed data does not match original data\n";
        free(compressed_data);
        free(uncompressed_data);
        return;
    }

    // Clean up any memory allocated for the compressed and uncompressed data
    free(compressed_data);
    free(uncompressed_data);
}
