#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <pthread.h>
#include <errno.h>

// Define the shared memory segment size and key
#define SHM_SIZE 1024
#define SHM_KEY 1234

// Define a mutex to synchronize access to the shared data
pthread_mutex_t shm_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a function to initialize the shared memory segment
void init_shm(int size, int key) {
  // Create the shared memory segment with the specified size and key
  void* shm = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
  if (shm == MAP_FAILED) {
    perror("Error creating shared memory segment");
    exit(EXIT_FAILURE);
  }

  // Set the size of the shared memory segment
  *(int*)shm = size;

  // Set the key of the shared memory segment
  *((int*)(shm + sizeof(int))) = key;
}

// Define a function to write data to the shared memory segment
void write_shm(void* shm, void* data, int size) {
  // Lock the mutex to synchronize access to the shared data
  pthread_mutex_lock(&shm_mutex);

  // Copy the data to the shared memory segment
  memcpy(shm, data, size);

  // Unlock the mutex
  pthread_mutex_unlock(&shm_mutex);
}

// Define a function to read data from the shared memory segment
void* read_shm(void* shm) {
  // Lock the mutex to synchronize access to the shared data
  pthread_mutex_lock(&shm_mutex);

  // Return a copy of the data from the shared memory segment
  void* data = malloc(sizeof(int));
  memcpy(data, shm, sizeof(int));

  // Unlock the mutex
  pthread_mutex_unlock(&shm_mutex);

  return data;
}

// Define a function to clean up the shared memory segment
void cleanup_shm(void* shm) {
  // Lock the mutex to synchronize access to the shared data
  pthread_mutex_lock(&shm_mutex);

  // Unmap the shared memory segment
  munmap(shm, *(int*)shm);

  // Destroy the mutex
  pthread_mutex_destroy(&shm_mutex);
}

// Define a function to handle errors gracefully
void error_handler(char* message) {
  perror(message);
  exit(EXIT_FAILURE);
}

int main() {
  // Initialize the shared memory segment with a size and key
  init_shm(SHM_SIZE, SHM_KEY);

  // Write data to the shared memory segment
  write_shm((void*)SHM_KEY, "Hello, world!", strlen("Hello, world!") + 1);

  // Read data from the shared memory segment
  void* data = read_shm((void*)SHM_KEY);

  // Print the data to the console
  printf("%s\n", (char*)data);

  // Clean up the shared memory segment
  cleanup_shm((void*)SHM_KEY);

  return 0;
}
