    FILE* fp = fopen(config_file, "rb");
    if (fp == NULL) {
        printf("Error opening binary configuration file: %s\n", strerror(errno));
        return;
    }

    // Allocate memory for the list of network activity logs
    NETWORK_ACTIVITY_LOG* logs = malloc(num_structs * sizeof(NETWORK_ACTIVITY_LOG));
    if (logs == NULL) {
        printf("Error allocating memory for network activity logs: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    // Read the binary configuration file and populate the list of network activity logs
    int i = 0;
    while (fread(&logs[i], sizeof(NETWORK_ACTIVITY_LOG), 1, fp) == 1 && i < num_structs) {
        // Parse the client IP address and server hostname from the binary data
        char* client_ip = logs[i].client_ip;
        char* server_hostname = logs[i].server_hostname;

        // Parse the port number, timestamp, connection type, and session state from the binary data
        int port = logs[i].port;
        time_t timestamp = logs[i].timestamp;
        char* connection_type = logs[i].connection_type;
        char* session_state = logs[i].session_state;

        // Print the parsed metadata to the console (for debugging purposes)
        printf("Client IP: %s\n", client_ip);
        printf("Server Hostname: %s\n", server_hostname);
        printf("Port: %d\n", port);
        printf("Timestamp: %ld\n", timestamp);
        printf("Connection Type: %s\n", connection_type);
        printf("Session State: %s\n", session_state);

        // Increment the index for the next iteration of the loop
        i++;
    }

    // Close the binary configuration file
    fclose(fp);

    // Free the memory allocated for the list of network activity logs
    free(logs);
}

// Function to generate traffic analysis report from list of network activity logs
void generate_report(char* output_file, char* session_management_rules, int num_structs) {
    // Open the output file for writing
    FILE* fp = fopen(output_file, "w");
    if (fp == NULL) {
        printf("Error opening output file: %s\n", strerror(errno));
        return;
    }

    // Write the header for the traffic analysis report to the output file
    fprintf(fp, "Client IP,Server Hostname,Port,Timestamp,Connection Type,Session State\n");

    // Iterate over the list of network activity logs and generate a traffic analysis report
    int i = 0;
    while (i < num_structs) {
        // Get the current network activity log structure
        NETWORK_ACTIVITY_LOG* log = &logs[i];

        // Parse the client IP address and server hostname from the binary data
        char* client_ip = log->client_ip;
        char* server_hostname = log->server_hostname;

        // Parse the port number, timestamp, connection type, and session state from the binary data
        int port = log->port;
        time_t timestamp = log->timestamp;
        char* connection_type = log->connection_type;
        char* session_state = log->session_state;

        // Print the parsed metadata to the output file (for debugging purposes)
        fprintf(fp, "%s,%s,%d,%ld,%s,%s\n", client_ip, server_hostname, port, timestamp, connection_type, session_state);

        // Increment the index for the next iteration of the loop
        i++;
    }

    // Close the output file
    fclose(fp);
}

// Main function to manage creation and population of list of network activity logs
int main(int argc, char* argv[]) {
    // Check if the correct number of command-line arguments was provided
    if (argc != 6) {
        printf("Usage: %s <input binary configuration file> <output report file> <session management rules> <number of structures to populate> <enable detailed logging>\n", argv[0]);
        return 1;
    }

    // Get the names of the input binary configuration file, output report file, session management rules, and number of structures to populate from the command-line arguments
    char* config_file = argv[1];
    char* output_file = argv[2];
    char* session_management_rules = argv[3];
    int num_structs = atoi(argv[4]);
    bool detailed_logging = strcmp(argv[5], "true") == 0;

    // Parse the binary configuration file and populate the list of network activity logs
    parse_binary_config(config_file, num_structs, detailed_logging);

    // Generate a traffic analysis report from the list of network activity logs
    generate_report(output_file, session_management_rules, num_structs);

    return 0;
}
