// Function to create and populate a list of TCP_CONNECTION_LOG structures
void manage_tcp_connections(char* config_file, char* output_file, char* anomaly_rules, int num_structures, bool enable_logging) {
    // Initialize variables
    FILE* config_fp = NULL;
    FILE* output_fp = NULL;
    TCP_CONNECTION_LOG* connections = NULL;
    size_t num_connections = 0;
    int i = 0;
    bool anomaly_detected = false;
    char* line = NULL;
    size_t len = 0;
    ssize_t read;

    // Open configuration file and output file for reading and writing
    config_fp = fopen(config_file, "r");
    if (config_fp == NULL) {
        perror("Error opening configuration file");
        return;
    }
    output_fp = fopen(output_file, "w");
    if (output_fp == NULL) {
        perror("Error opening output file");
        fclose(config_fp);
        return;
    }

    // Dynamically allocate memory for the list of TCP_CONNECTION_LOG structures
    connections = malloc(num_structures * sizeof(TCP_CONNECTION_LOG));
    if (connections == NULL) {
        perror("Error allocating memory for TCP connection logs");
        fclose(config_fp);
        fclose(output_fp);
        return;
    }

    // Parse the binary configuration file and populate the list of TCP_CONNECTION_LOG structures
    while ((read = getline(&line, &len, config_fp)) != -1) {
        if (num_connections >= num_structures) {
            break;
        }
        // Parse the line and extract the necessary information
        char* token = strtok(line, " ");
        while (token != NULL) {
            if (strcmp(token, "IP") == 0) {
                inet_pton(AF_INET6, strtok(NULL, " "), &connections[num_connections].ip_address);
            } else if (strcmp(token, "PORT") == 0) {
                connections[num_connections].port = atoi(strtok(NULL, " "));
            } else if (strcmp(token, "TIMESTAMP") == 0) {
                connections[num_connections].timestamp = atol(strtok(NULL, " "));
            } else if (strcmp(token, "STATE") == 0) {
                connections[num_connections].state = atoi(strtok(NULL, " "));
            }
            token = strtok(NULL, " ");
        }
        num_connections++;
    }
    fclose(config_fp);

    // Apply anomaly detection rules to the list of TCP_CONNECTION_LOG structures
    for (i = 0; i < num_connections; i++) {
        if (strcmp(anomaly_rules, "STATISTICAL") == 0) {
            // Statistical analysis anomaly detection rules
            if (connections[i].state == 1) {
                // Connection is in the established state
                if (connections[i].timestamp - connections[i].previous_timestamp > 30) {
                    // The connection has been idle for more than 30 seconds, which is an anomaly
                    anomaly_detected = true;
                }
            } else if (connections[i].state == 2) {
                // Connection is in the closed state
                if (connections[i].timestamp - connections[i].previous_timestamp < 10) {
                    // The connection has been closed within the last 10 seconds, which is an anomaly
                    anomaly_detected = true;
                }
            } else if (connections[i].state == 3) {
                // Connection is in the syn-sent state
                if (connections[i].timestamp - connections[i].previous_timestamp > 10) {
                    // The connection has been in the syn-sent state for more than 10 seconds, which is an anomaly
                    anomaly_detected = true;
                }
            } else if (connections[i].state == 4) {
                // Connection is in the syn-recv state
                if (connections[i].timestamp - connections[i].previous_timestamp > 10) {
                    // The connection has been in the syn-recv state for more than 10 seconds, which is an anomaly
                    anomaly_detected = true;
                }
            } else if (connections[i].state == 5) {
                // Connection is in the fin-wait-1 state
                if (connections[i].timestamp - connections[i].previous_timestamp > 30) {
                    // The connection has been in the fin-wait-1 state for more than 30 seconds, which is an anomaly
                    anomaly_detected = true;
                }
            } else if (connections[i].state == 6) {
                // Connection is in the fin-wait-2 state
                if (connections[i].timestamp - connections[i].previous_timestamp > 30) {
                    // The connection has been in the fin-wait-2 state for more than 30 seconds, which is an anomaly
                    anomaly_detected = true;
                }
            } else if (connections[i].state == 7) {
                // Connection is in the closing state
                if (connections[i].timestamp - connections[i].previous_timestamp > 30) {
                    // The connection has been in the closing state for more than 30 seconds, which is an anomaly
                    anomaly_detected = true;
                }
            } else if (connections[i].state == 8) {
                // Connection is in the time-wait state
                if (connections[i].timestamp - connections[i].previous_timestamp > 30) {
                    // The connection has been in the time-wait state for more than 30 seconds, which is an anomaly
                    anomaly_detected = true;
                }
            } else if (connections[i].state == 9) {
                // Connection is in the last-ack state
                if (connections[i].timestamp - connections[i].previous_timestamp > 30) {
                    // The connection has been in the last-ack state for more than 30 seconds, which is an anomaly
                    anomaly_detected = true;
                }
            } else if (connections[i].state == 10) {
                // Connection is in the closing state
                if (connections[i].timestamp - connections[i].previous_timestamp > 30) {
                    // The connection has been in the closing state for more than 30 seconds, which is an anomaly
