#include <errno.h>

#define MAX_LOG_ENTRIES 1000

typedef struct LogEntry {
    time_t timestamp;
    int logLevel;
    char* message;
    char* sourceFilePath;
} LogEntry;

LogEntry* parseAndValidateLogs(const char* filePath) {
    // Open the log file for reading
    FILE* fp = fopen(filePath, "r");
    if (fp == NULL) {
        perror("fopen");
        return NULL;
    }

    // Create an array to store the parsed log entries
    LogEntry** logEntries = malloc(sizeof(LogEntry*) * MAX_LOG_ENTRIES);
    if (logEntries == NULL) {
        perror("malloc");
        fclose(fp);
        return NULL;
    }

    // Read the log file line by line and parse each entry
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    int i = 0;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Parse the log entry and validate it
        LogEntry* entry = parseLogEntry(line);
        if (entry == NULL) {
            continue;
        }
        if (!validateLogEntry(entry)) {
            free(entry);
            continue;
        }

        // Add the validated log entry to the array
        logEntries[i++] = entry;
    }

    // Close the log file and return the parsed log entries
    fclose(fp);
    return logEntries;
}

LogEntry* parseLogEntry(const char* line) {
    // Parse the timestamp, log level, message, and source file path from the line
    time_t timestamp = 0;
    int logLevel = 0;
    char* message = NULL;
    char* sourceFilePath = NULL;
    sscanf(line, "%lu %d %s %s", &timestamp, &logLevel, &message, &sourceFilePath);

    // Create a new LogEntry structure and return it
    LogEntry* entry = malloc(sizeof(LogEntry));
    if (entry == NULL) {
        perror("malloc");
        return NULL;
    }
    entry->timestamp = timestamp;
    entry->logLevel = logLevel;
    entry->message = message;
    entry->sourceFilePath = sourceFilePath;
    return entry;
}

bool validateLogEntry(const LogEntry* entry) {
    // Validate the timestamp format and log level
    if (entry->timestamp == 0 || entry->logLevel < 1 || entry->logLevel > 4) {
        return false;
    }

    // Validate the message is non-empty
    if (strlen(entry->message) == 0) {
        return false;
    }

    // Validate the source file path matches the pattern of paths allowed within the application's configuration
    if (!validateSourceFilePath(entry->sourceFilePath)) {
        return false;
    }

    return true;
}

bool validateSourceFilePath(const char* sourceFilePath) {
    // Implement your own logic to validate the source file path
    // For example, you can check if the path is a valid directory or file and if it matches the pattern of paths allowed within the application's configuration
    return true;
}
