import java.io.FileOutputStream;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

public class LogCompression {
    public static boolean compressLogs(List<LogEntry> logEntries) {
        // Check if the input list is non-null and contains only valid LogEntry objects
        if (logEntries == null || logEntries.isEmpty()) {
            return false;
        }

        try {
            // Create a ZIP archive named "log_archive.zip" in the application's working directory
            FileOutputStream fos = new FileOutputStream("log_archive.zip");
            ZipOutputStream zos = new ZipOutputStream(fos);

            // Add each log entry to the ZIP archive as a separate file
            for (LogEntry entry : logEntries) {
                ZipEntry zipEntry = new ZipEntry(entry.getSourceFilePath());
                zos.putNextEntry(zipEntry);
                zos.write(entry.getMessage().getBytes());
                zos.closeEntry();
            }

            // Close the ZIP archive and return true if no exceptions were encountered during compression
            zos.close();
            return true;
        } catch (Exception e) {
            // Log any exceptions encountered during compression to the "error.log" file in the application's working directory
            System.out.println("Error compressing logs: " + e.getMessage());
            return false;
        }
    }
}
