#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <openssl/sha.h>
#include <openssl/aes.h>
#include <openssl/modes.h>

#define MAX_FILE_ENTRIES 1000
#define VALIDATION_LOG "validation.log"
#define ENCRYPTION_LOG "encryption.log"

typedef struct {
    char *filename;
    size_t filesize;
    time_t modificationtime;
    unsigned char hashvalue[SHA256_DIGEST_LENGTH];
} filemetadata_t;

void processAndCacheFileMetadata(const char *directory) {
    DIR *dir = opendir(directory);
    if (dir == NULL) {
        perror("opendir");
        return;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip hidden files and directories
        if (strncmp(entry->d_name, ".", 1) == 0 || strncmp(entry->d_name, "..", 2) == 0) {
            continue;
        }

        char *filename = entry->d_name;
        struct stat st;
        if (stat(filename, &st) != 0) {
            perror("stat");
            closedir(dir);
            return;
        }

        // Check that the file is not a directory
        if (S_ISDIR(st.st_mode)) {
            continue;
        }

        // Read the file metadata
        FILE *file = fopen(filename, "r");
        if (file == NULL) {
            perror("fopen");
            closedir(dir);
            return;
        }

        size_t filesize = st.st_size;
        time_t modificationtime = st.st_mtime;
        unsigned char hashvalue[SHA256_DIGEST_LENGTH];
        SHA256_CTX ctx;
        SHA256_Init(&ctx);
        while (filesize > 0) {
            size_t read = fread(hashvalue, 1, sizeof(hashvalue), file);
            if (read == 0) {
                break;
            }
            filesize -= read;
            SHA256_Update(&ctx, hashvalue, read);
        }
        SHA256_Final(hashvalue, &ctx);

        // Check that the file size and modification time are accurate
        if (filesize != st.st_size || modificationtime != st.st_mtime) {
            fprintf(stderr, "Validation failed: %s\n", filename);
            closedir(dir);
            return;
        }

        // Check that the hash value is correct
        if (memcmp(hashvalue, entry->d_name, SHA256_DIGEST_LENGTH) != 0) {
            fprintf(stderr, "Validation failed: %s\n", filename);
            closedir(dir);
            return;
        }

        // Add the file metadata to the cache
        filemetadata_t *metadata = malloc(sizeof(filemetadata_t));
        if (metadata == NULL) {
            fprintf(stderr, "Memory allocation failed: %s\n", filename);
            closedir(dir);
            return;
        }
        metadata->filename = strdup(filename);
        metadata->filesize = st.st_size;
        metadata->modificationtime = st.st_mtime;
        memcpy(metadata->hashvalue, hashvalue, SHA256_DIGEST_LENGTH);

        // Check that the total number of valid entries does not exceed the limit
        if (cache_size >= MAX_FILE_ENTRIES) {
            fprintf(stderr, "Cache size exceeded: %s\n", filename);
            closedir(dir);
            return;
        }

        // Add the metadata to the cache
        cache[cache_size++] = metadata;
    }

    closedir(dir);
}
