```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <openssl/aes.h>
#include <openssl/modes.h>

using namespace std;

void encryptAndStoreMetadata(const vector<filemetadata_t>& metadata) {
    // Check that the input vector is not empty
    if (metadata.empty()) {
        cerr << "Input vector is empty" << endl;
        return;
    }

    // Open the binary file for writing
    ofstream outfile("encrypted_data", ios::binary | ios::out);
    if (!outfile) {
        cerr << "Failed to open output file: " << strerror(errno) << endl;
        return;
    }

    // Encrypt the metadata using AES-256-CBC
    AES_KEY key;
    AES_set_encrypt_key(&key, 256, NULL);
    vector<unsigned char> iv(AES_BLOCK_SIZE);
    for (size_t i = 0; i < metadata.size(); ++i) {
        // Encrypt the file name and size
        unsigned char *encrypted_filename = AES_cbc_encrypt((const unsigned char *)metadata[i].filename, strlen(metadata[i].filename), &key, iv.data(), NULL);
        outfile.write((char *)encrypted_filename, strlen(metadata[i].filename));
        free(encrypted_filename);

        // Encrypt the file size and modification time
        unsigned char *encrypted_filesize = AES_cbc_encrypt((const unsigned char *)&metadata[i].filesize, sizeof(size_t), &key, iv.data(), NULL);
        outfile.write((char *)encrypted_filesize, sizeof(size_t));
        free(encrypted_filesize);

        // Encrypt the hash value
        unsigned char *encrypted_hashvalue = AES_cbc_encrypt((const unsigned char *)metadata[i].hashvalue, SHA256_DIGEST_LENGTH, &key, iv.data(), NULL);
        outfile.write((char *)encrypted_hashvalue, SHA256_DIGEST_LENGTH);
        free(encrypted_hashvalue);
    }

    // Close the output file
    outfile.close();
}
