#define OPTION_CS "--cs"
#define OPTION_O "--o"

// Define structure to store statistics
typedef struct {
    int num_lines;
    float avg_line_length;
} stats_t;

// Function to handle command line arguments and process input file
int main(int argc, char **argv) {
    // Initialize variables for command line options and input file
    int manpage = 0;
    int case_sensitive = 0;
    char *output_file = NULL;
    char *input_file = NULL;

    // Parse command line arguments
    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], OPTION_MANPAGE)) {
            manpage = 1;
        } else if (!strcmp(argv[i], OPTION_CS)) {
            case_sensitive = 1;
        } else if (!strcmp(argv[i], OPTION_O)) {
            output_file = argv[++i];
        } else {
            input_file = argv[i];
        }
    }

    // Open input file for reading
    int fd = open(input_file, O_RDONLY);
    if (fd == -1) {
        perror("Error opening input file");
        return 1;
    }

    // Initialize statistics structure
    stats_t stats = {0};

    // Process input file line by line
    char buffer[BUFSIZ];
    while (read(fd, buffer, BUFSIZ) > 0) {
        // Handle case-sensitive mode if enabled
        if (case_sensitive) {
            for (int i = 0; i < strlen(buffer); i++) {
                buffer[i] = tolower(buffer[i]);
            }
        }

        // Increment line count and compute average line length
        stats.num_lines++;
        stats.avg_line_length += strlen(buffer);
    }

    // Close input file
    close(fd);

    // Redirect output to specified file if provided
    if (output_file) {
        fd = open(output_file, O_WRONLY | O_CREAT, 0644);
        if (fd == -1) {
            perror("Error opening output file");
            return 1;
        }
    } else {
        // Redirect output to standard output if no output file specified
        fd = STDOUT_FILENO;
    }

    // Print statistics to output file or standard output
    printf("Total number of lines: %d\n", stats.num_lines);
    printf("Average line length: %.2f\n", stats.avg_line_length / stats.num_lines);

    // Close output file
    close(fd);

    return 0;
}
