// Define constants for command line options
#define OPTION_HELP "--help"
#define OPTION_SOURCE "-s"
#define OPTION_OUTPUT_DIR "-o"
#define OPTION_PRINT "p"

// Define a structure to hold information about each file being processed
typedef struct {
    char *filename;
    FILE *file;
} file_info_t;

// Define a function to handle command line arguments and options
void handle_options(int argc, char **argv) {
    // Initialize variables for handling command line arguments and options
    int i, j;
    char *option;
    char *value;
    file_info_t *files = NULL;
    size_t num_files = 0;

    // Iterate over the command line arguments and handle each option
    for (i = 1; i < argc; i++) {
        option = argv[i];
        if (strcmp(option, OPTION_HELP) == 0) {
            // Display help message and exit
            printf("Usage: %s [options]...\n", argv[0]);
            printf("Options:\n");
            printf("  --help       Display this message and exit\n");
            printf("  -s source    Specify the source directory containing text files to process\n");
            printf("  -o output_dir Redirect output to specified directories, creating them if they do not exist\n");
            printf("  -p           Print processed data directly to standard output in JSON format for easy integration with other systems\n");
            exit(0);
        } else if (strcmp(option, OPTION_SOURCE) == 0) {
            // Read the source directory and add each file to the list of files to process
            value = argv[++i];
            struct stat st;
            if (stat(value, &st) != 0 || !S_ISDIR(st.st_mode)) {
                fprintf(stderr, "Error: %s is not a valid directory\n", value);
                exit(1);
            }
            DIR *dir = opendir(value);
            if (dir == NULL) {
                fprintf(stderr, "Error: unable to open directory %s\n", value);
                exit(1);
            }
            struct dirent *entry;
            while ((entry = readdir(dir)) != NULL) {
                char *filename = entry->d_name;
                if (strcmp(filename, ".") == 0 || strcmp(filename, "..") == 0) {
                    continue;
                }
                file_info_t *file = malloc(sizeof(file_info_t));
                file->filename = filename;
                file->file = fopen(filename, "r");
                if (file->file == NULL) {
                    fprintf(stderr, "Error: unable to open file %s\n", filename);
                    exit(1);
                }
                files = realloc(files, sizeof(file_info_t) * (num_files + 1));
                files[num_files++] = file;
            }
            closedir(dir);
        } else if (strcmp(option, OPTION_OUTPUT_DIR) == 0) {
            // Create the output directory and redirect output to it
            value = argv[++i];
            struct stat st;
            if (stat(value, &st) != 0 || !S_ISDIR(st.st_mode)) {
                fprintf(stderr, "Error: %s is not a valid directory\n", value);
                exit(1);
            }
            chdir(value);
        } else if (strcmp(option, OPTION_PRINT) == 0) {
            // Print processed data directly to standard output in JSON format
            printf("{\"processed\": true}\n");
        } else {
            fprintf(stderr, "Error: invalid option %s\n", option);
            exit(1);
        }
    }

    // Process each file asynchronously to improve performance
    pthread_t *threads = malloc(sizeof(pthread_t) * num_files);
    for (i = 0; i < num_files; i++) {
        file_info_t *file = files[i];
        pthread_create(&threads[i], NULL, process_file, file);
    }
    for (i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
    }
    free(threads);
}

// Define a function to handle each file asynchronously
void *process_file(void *arg) {
    file_info_t *file = arg;
    char buffer[BUFSIZ];
    size_t num_bytes;
    while ((num_bytes = fread(buffer, 1, BUFSIZ, file->file)) > 0) {
        // Process the contents of the file asynchronously
        printf("Processing %s...\n", file->filename);
        sleep(1);
    }
    fclose(file->file);
    free(file);
}

int main(int argc, char **argv) {
    handle_options(argc, argv);
    return 0;
}
```
