// Function to add a new task to the list
void add_task(const char *args, int priority) {
    if (task_count >= task_capacity) {
        resize_tasks(task_capacity * 2);
    }

    Task *new_task = &tasks[task_count++];
    new_task->args = malloc(strlen(args) + 1);
    if (!new_task->args) {
        fprintf(LOGGING_SYSTEM, "Error: Failed to allocate memory for task arguments\n");
        exit(1);
    }
