// Define a struct to store information about each input file
typedef struct {
    char* filename;
    long line_count;
} file_info_t;

// Define a function to count lines in a file
long count_lines(char* filename, char* delimiter) {
    // Open the file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return -1;
    }

    // Initialize variables for counting lines and bytes read
    long line_count = 0;
    long byte_count = 0;

    // Read the file in chunks, using the delimiter to determine when a new line starts
    char buffer[BUFSIZ];
    while (fgets(buffer, BUFSIZ, fp)) {
        // Increment the line count for each newline character found
        for (char* c = buffer; *c != '\0'; c++) {
            if (*c == delimiter) {
                line_count++;
            }
        }

        // Update the byte count with the number of bytes read
        byte_count += strlen(buffer);
    }

    // Close the file and return the line count
    fclose(fp);
    return line_count;
}

// Define a function to decompress a gzip file
int decompress_file(char* filename, char* output_filename) {
    // Open the input file for reading
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return -1;
    }

    // Create a new output file for writing
    FILE* out_fp = fopen(output_filename, "wb");
    if (out_fp == NULL) {
        printf("Error: unable to create output file %s\n", output_filename);
        return -1;
    }

    // Decompress the input file and write it to the output file
    int ret = gzread(fp, out_fp);
    if (ret < 0) {
        printf("Error: unable to decompress file %s\n", filename);
        return -1;
    }

    // Close the input and output files
    fclose(fp);
    fclose(out_fp);

    // Return success
    return 0;
}

// Define a function to handle command line arguments
int main(int argc, char* argv[]) {
    // Check for the correct number of arguments
    if (argc < 2) {
        printf("Usage: %s [input files]\n", argv[0]);
        return -1;
    }

    // Initialize variables for storing information about input files
    file_info_t* files = malloc(sizeof(file_info_t) * (argc - 1));
    int num_files = 0;

    // Iterate over the command line arguments, parsing each one as an input file
    for (int i = 1; i < argc; i++) {
        char* filename = argv[i];

        // Check if the file is a gzip file and decompress it if necessary
        if (strstr(filename, FILE_EXTENSIONS) != NULL) {
            char output_filename[BUFSIZ];
            strcpy(output_filename, filename);
            strtok(output_filename, ".");
            if (decompress_file(filename, output_filename) < 0) {
                printf("Error: unable to decompress file %s\n", filename);
                return -1;
            }
            filename = output_filename;
        }

        // Count the lines in the input file and store the result
        files[num_files].filename = filename;
        files[num_files].line_count = count_lines(filename, DELIMITER);
        num_files++;
    }

    // Print the results for each input file
    printf("File\tLine Count\n");
    for (int i = 0; i < num_files; i++) {
        printf("%s\t%ld\n", files[i].filename, files[i].line_count);
    }

    // Free the memory used to store information about input files
    free(files);

    // Return success
    return 0;
}
