```java
import java.io.*;
import java.net.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import org.json.*;

public class TaskQueue {
  private static final String TASK_ENDPOINT = "https://api.example.com/tasks";
  private static final int MAX_ATTEMPTS = 5;
  private static final long DELAY_INTERVAL = 1000L; // in milliseconds
  private static final String JSON_FORMAT = "json";
  private static final String XML_FORMAT = "xml";

  public static void main(String[] args) {
    if (args.length != 4) {
      System.out.println("Usage: TaskQueue <task-type> <num-tasks> <target-endpoint> <format>");
      return;
    }

    String taskType = args[0];
    int numTasks = Integer.parseInt(args[1]);
    String targetEndpoint = args[2];
    String format = args[3];

    if (!JSON_FORMAT.equalsIgnoreCase(format) && !XML_FORMAT.equalsIgnoreCase(format)) {
      System.out.println("Invalid format: " + format);
      return;
    }

    // Create a thread pool for submitting tasks asynchronously
    ExecutorService executor = Executors.newFixedThreadPool(numTasks);

    try {
      // Enqueue tasks in the target endpoint
      for (int i = 0; i < numTasks; i++) {
        String taskId = UUID.randomUUID().toString();
        Task task = new Task(taskType, taskId);
        executor.submit(() -> submitTask(targetEndpoint, format, task));
      }
    } catch (Exception e) {
      System.out.println("Error submitting tasks: " + e.getMessage());
    } finally {
      executor.shutdown();
    }
  }

  private static void submitTask(String targetEndpoint, String format, Task task) throws Exception {
    // Create a JSON object for the task payload
    JSONObject json = new JSONObject();
    json.put("taskType", task.getTaskType());
    json.put("taskId", task.getTaskId());

    // Submit the task to the target endpoint
    URL url = new URL(targetEndpoint);
    HttpURLConnection conn = (HttpURLConnection) url.openConnection();
    conn.setRequestMethod("POST");
    conn.setDoOutput(true);
    conn.setRequestProperty("Content-Type", "application/json");

    OutputStream os = conn.getOutputStream();
    os.write(json.toString().getBytes());
    os.flush();

    // Handle the response from the target endpoint
    int statusCode = conn.getResponseCode();
    if (statusCode == HttpURLConnection.HTTP_OK) {
      System.out.println("Task submitted successfully: " + task.getTaskId());
    } else {
      System.out.println("Error submitting task: " + statusCode);
    }
  }
}
```
This program takes four command line arguments: the type of tasks to enqueue, the number of tasks to process, the target queue endpoint, and the format for the task payloads (JSON or XML). It creates a thread pool with the specified number of threads to submit tasks asynchronously. The `submitTask` method is responsible for submitting each task to the target endpoint using an HTTP POST request. If the submission is successful, it prints a message indicating that the task was submitted successfully. Otherwise, it prints an error message indicating the status code returned by the target endpoint.

The program also includes retry logic for failed submissions, with configurable maximum attempts and delay intervals. It uses the `ExecutorService` class to manage the thread pool and the `Future` interface to handle asynchronous task submissions. The `JSONObject` class is used to create JSON objects for the task payloads, and the `HttpURLConnection` class is used to submit HTTP POST requests to the target endpoint.

