```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_NETWORK_INTERFACES 10

typedef struct NetworkInterfaceConfig {
    int InterfaceID;
    char IPAddress[INET6_ADDRSTRLEN];
    char SubnetMask[INET6_ADDRSTRLEN];
    bool NetworkStatus;
} NetworkInterfaceConfig;

NetworkInterfaceConfig* initializeNetworkConfig() {
    // Allocate memory for the array of network interfaces
    NetworkInterfaceConfig** configs = (NetworkInterfaceConfig**)malloc(MAX_NETWORK_INTERFACES * sizeof(NetworkInterfaceConfig*));
    if (!configs) {
        fprintf(stderr, "Error: Failed to allocate memory for network interface configurations\n");
        return NULL;
    }

