import java.util.List;
import java.util.ArrayList;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;
import java.io.FileWriter;
import java.io.IOException;

public class NetworkInterfaceConfig {
    private int InterfaceID;
    private String IPAddress;
    private String SubnetMask;
    private boolean NetworkStatus;

    public NetworkInterfaceConfig(int InterfaceID, String IPAddress, String SubnetMask, boolean NetworkStatus) {
        this.InterfaceID = InterfaceID;
        this.IPAddress = IPAddress;
        this.SubnetMask = SubnetMask;
        this.NetworkStatus = NetworkStatus;
    }

    public static List<NetworkInterfaceConfig> validateAndTransformData(List<NetworkInterfaceConfig> configs) {
        // Create a concurrent hash map to store the transformed configurations
        ConcurrentHashMap<Integer, NetworkInterfaceConfig> transformedConfigs = new ConcurrentHashMap<>();

        // Lock the hash map to prevent race conditions when accessing it from multiple threads
        ReentrantLock lock = new ReentrantLock();

        for (NetworkInterfaceConfig config : configs) {
            try {
                // Validate the configuration based on specific criteria
                if (!config.isValid()) {
                    continue;
                }

                // Transform the configuration into a more optimized format suitable for high-speed data transmission
                NetworkInterfaceConfig transformedConfig = config.transform();

                // Add the transformed configuration to the hash map
                lock.lock();
                try {
                    transformedConfigs.put(config.getInterfaceID(), transformedConfig);
                } finally {
                    lock.unlock();
                }
            } catch (Exception e) {
                // Log any exceptions encountered during validation and transformation to the error log file
                FileWriter writer = new FileWriter("error.log", true);
                try {
                    writer.write(e.getMessage());
                } finally {
                    writer.close();
                }
            }
        }

        return transformedConfigs;
    }
}
