public class NetworkInterfaceHealthChecker {
    private static final Logger logger = Logger.getLogger(NetworkInterfaceHealthChecker.class.getName());

    private List<NetworkInterfaceConfig> configs;
    private int healthCheckInterval;
    private int healthTimeout;

    public NetworkInterfaceHealthChecker(int numInterfaces, int healthCheckInterval, int healthTimeout) {
        this.configs = new ArrayList<>();
        for (int i = 0; i < numInterfaces; i++) {
            configs.add(new NetworkInterfaceConfig(i + 1, "192.168." + (i + 1) + ".1", "255.255.255.0"));
        }
        this.healthCheckInterval = healthCheckInterval;
        this.healthTimeout = healthTimeout;
    }

    public void checkHealth() {
        for (NetworkInterfaceConfig config : configs) {
            if (config.isNetworkStatus()) {
                try {
                    Socket socket = new Socket(config.getIPAddress(), 80);
                    OutputStream outputStream = socket.getOutputStream();
                    InputStream inputStream = socket.getInputStream();
                    byte[] buffer = new byte[1024];
                    int bytesRead = inputStream.read(buffer);
                    if (bytesRead < 0) {
                        logger.warning("Failed to read data from network interface " + config.getInterfaceID());
                        continue;
                    }
                    outputStream.write(buffer, 0, bytesRead);
                    outputStream.flush();
                    socket.close();
                } catch (IOException e) {
                    logger.warning("Failed to check health of network interface " + config.getInterfaceID());
                    continue;
                }
            }
        }
    }
}
