import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;

public class SymlinkResolver {
    public static List<FileSystemNode> resolveSymlinks(String filePath) throws IOException {
        // Validate the file path and ensure it exists
        if (!Files.exists(Paths.get(filePath))) {
            throw new IOException("The specified file does not exist: " + filePath);
        }

        // Create a list to store the resolved symlinks
        List<FileSystemNode> nodes = new ArrayList<>();

        // Iterate over the files and directories in the file system
        Files.walk(Paths.get(filePath)).forEach(path -> {
            // Get the metadata for the current file or directory
            FileAttributes attributes = Files.readAttributes(path, "basic:*");

            // If the current node is a symlink, resolve it and add the resolved nodes to the list
            if (attributes.isSymbolicLink()) {
                List<FileSystemNode> resolvedNodes = resolveSymlinks(attributes.symbolicLinkTarget());
                nodes.addAll(resolvedNodes);
            } else {
                // Add the current node to the list
                nodes.add(new FileSystemNode(attributes.fileKey(), attributes.fileName(), attributes.size(), attributes.lastModifiedTime(), attributes.isDirectory(), attributes.permissions()));
            }
        });

        return nodes;
    }
}
