// Define constants for command line options
#define OPTION_DIRECTORY "d"
#define OPTION_FORMAT "f"
#define OPTION_OUTPUT "o"
#define OPTION_STATS "s"

// Define structure to store file information
struct FileInfo {
    char *filename;
    size_t line_count;
};

int main(int argc, char **argv) {
    // Check for correct number of arguments
    if (argc < 3) {
        fprintf(stderr, "Usage: %s -%c <directory> -%c <format> [-%c <output_file>] [-%c]\n", argv[0], OPTION_DIRECTORY, OPTION_FORMAT, OPTION_OUTPUT, OPTION_STATS);
        return 1;
    }

    // Parse command line options
    char *directory = NULL;
    char *format = NULL;
    char *output_file = NULL;
    int stats = 0;
    for (int i = 1; i < argc - 1; i++) {
        if (!strcmp(argv[i], "-" OPTION_DIRECTORY)) {
            directory = argv[++i];
        } else if (!strcmp(argv[i], "-" OPTION_FORMAT)) {
            format = argv[++i];
        } else if (!strcmp(argv[i], "-" OPTION_OUTPUT)) {
            output_file = argv[++i];
        } else if (!strcmp(argv[i], "-" OPTION_STATS)) {
            stats = 1;
        }
    }

    // Check for valid directory and format
    if (directory == NULL || format == NULL) {
        fprintf(stderr, "Error: Missing required option -%c or -%c\n", OPTION_DIRECTORY, OPTION_FORMAT);
        return 1;
    }

    // Open output file if specified
    FILE *output = NULL;
    if (output_file != NULL) {
        output = fopen(output_file, "w");
        if (output == NULL) {
            fprintf(stderr, "Error: Failed to open output file %s\n", output_file);
            return 1;
        }
    }

    // Initialize statistics variables
    size_t total_line_count = 0;
    size_t unique_word_count = 0;

    // Iterate over files in directory and aggregate contents
    DIR *dir = opendir(directory);
    if (dir == NULL) {
        fprintf(stderr, "Error: Failed to open directory %s\n", directory);
        return 1;
    }
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip hidden files and directories
        if (entry->d_name[0] == '.') continue;

        // Open file and read contents
        char *filename = entry->d_name;
        FILE *file = fopen(filename, "r");
        if (file == NULL) {
            fprintf(stderr, "Error: Failed to open file %s\n", filename);
            continue;
        }
        char line[1024];
        while (fgets(line, sizeof(line), file)) {
            // Increment line count and unique word count
            total_line_count++;
            char *word = strtok(line, " ");
            while (word != NULL) {
                unique_word_count++;
                word = strtok(NULL, " ");
            }
        }
        fclose(file);
    }
    closedir(dir);

    // Print statistics if requested
    if (stats) {
        printf("Total line count: %zu\n", total_line_count);
        printf("Unique word count: %zu\n", unique_word_count);
    }

    // Write aggregated contents to output file
    if (output != NULL) {
        DIR *dir = opendir(directory);
        struct dirent *entry;
        while ((entry = readdir(dir)) != NULL) {
            // Skip hidden files and directories
            if (entry->d_name[0] == '.') continue;

            // Open file and read contents
            char *filename = entry->d_name;
            FILE *file = fopen(filename, "r");
            if (file == NULL) {
                fprintf(stderr, "Error: Failed to open file %s\n", filename);
                continue;
            }
            char line[1024];
            while (fgets(line, sizeof(line), file)) {
                // Write line to output file
                fputs(line, output);
            }
            fclose(file);
        }
        closedir(dir);
    }

    // Clean up and exit
    if (output != NULL) fclose(output);
    return 0;
}
