typedef struct {
    int RRC_UE_ID;
    int CELL_ID;
    char *NAS_MESSAGE;
} LTE_RRC_UE_CONTEXT;

// Define the pool of LTE_RRC_UE_CONTEXT structures
static LTE_RRC_UE_CONTEXT *pool = NULL;

// Define the mutex for synchronizing access to the pool
static pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the semaphore for signaling when a new element is available in the pool
static sem_t pool_sem;

// Initialize the pool of LTE_RRC_UE_CONTEXT structures
void init_pool(int size) {
    // Allocate memory for the pool
    pool = (LTE_RRC_UE_CONTEXT *)malloc(size * sizeof(LTE_RRC_UE_CONTEXT));
    if (!pool) {
        printf("Error: Failed to allocate memory for the pool\n");
        exit(1);
    }

    // Initialize the mutex and semaphore
    pthread_mutex_init(&pool_mutex, NULL);
    sem_init(&pool_sem, 0, 0);
}

// Destroy the pool of LTE_RRC_UE_CONTEXT structures
void destroy_pool() {
    // Release the mutex and semaphore
    pthread_mutex_destroy(&pool_mutex);
    sem_destroy(&pool_sem);

    // Free the memory for the pool
    free(pool);
}

// Allocate a new LTE_RRC_UE_CONTEXT structure from the pool
LTE_RRC_UE_CONTEXT *allocate_context() {
    // Acquire the mutex to synchronize access to the pool
    pthread_mutex_lock(&pool_mutex);

    // Wait for a new element to become available in the pool
    sem_wait(&pool_sem);

    // Find the first available element in the pool and allocate it
    int i;
    for (i = 0; i < size; i++) {
        if (!pool[i].RRC_UE_ID) {
            break;
        }
