    if (i == size) {
        printf("Error: No available elements in the pool\n");
        pthread_mutex_unlock(&pool_mutex);
        return NULL;
    }
    LTE_RRC_UE_CONTEXT *context = &pool[i];
    context->RRC_UE_ID = 0;
    context->CELL_ID = 0;
    context->NAS_MESSAGE = NULL;

    // Release the mutex and signal that a new element is available in the pool
    pthread_mutex_unlock(&pool_mutex);
    sem_post(&pool_sem);

    return context;
}

// Free an LTE_RRC_UE_CONTEXT structure from the pool
void free_context(LTE_RRC_UE_CONTEXT *context) {
    // Acquire the mutex to synchronize access to the pool
    pthread_mutex_lock(&pool_mutex);

    // Set the RRC_UE_ID, CELL_ID, and NAS_MESSAGE fields to NULL
    context->RRC_UE_ID = 0;
    context->CELL_ID = 0;
    free(context->NAS_MESSAGE);
    context->NAS_MESSAGE = NULL;

    // Release the mutex and signal that a new element is available in the pool
    pthread_mutex_unlock(&pool_mutex);
    sem_post(&pool_sem);
}

// Monitor the health of an LTE_RRC_UE_CONTEXT structure
void monitor_context(LTE_RRC_UE_CONTEXT *context) {
    // Acquire the mutex to synchronize access to the pool
    pthread_mutex_lock(&pool_mutex);

    // Perform periodic health checks and diagnostic logging
    if (context->RRC_UE_ID == 0 || context->CELL_ID == 0) {
        printf("Error: Invalid RRC_UE_ID or CELL_ID\n");
        pthread_mutex_unlock(&pool_mutex);
        return;
    }
    if (context->NAS_MESSAGE == NULL) {
        printf("Error: NAS_MESSAGE is NULL\n");
