void *process_directory(void *arg) {
    // Get the directory name from the argument
    char *dirname = (char *)arg;

    // Open the directory and read its contents
    DIR *dir = opendir(dirname);
    if (!dir) {
        perror("opendir");
        return NULL;
    }

    // Loop through each file in the directory
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip over directories and hidden files
        if (entry->d_type == DT_DIR || entry->d_name[0] == '.') {
            continue;
        }

        // Create a new thread to process the file
        pthread_t thread;
        int rc = pthread_create(&thread, NULL, process_file, (void *)entry->d_name);
        if (rc != 0) {
            perror("pthread_create");
            closedir(dir);
            return NULL;
        }
    }

    // Close the directory and free the memory for the thread pool
    closedir(dir);
    pthread_t *threads = malloc(sizeof(pthread_t) * NUM_THREADS);
    if (!threads) {
        perror("malloc");
        return NULL;
    }
    threads[NUM_THREADS - 1] = thread;
    for (int i = 0; i < NUM_THREADS - 1; i++) {
        rc = pthread_join(threads[i], NULL);
        if (rc != 0) {
            perror("pthread_join");
            free(threads);
            return NULL;
        }
    }
    free(threads);

    return NULL;
}

