    void* memory_pool = malloc(num_elements * element_size);
    if (!memory_pool) {
        LOG_ERROR("Failed to allocate memory for the memory pool");
        return NULL;
    }

    // Initialize each element in the memory pool with a valid PHY test parameter ID, test mode, and physical layer status
    for (int i = 0; i < num_elements; i++) {
        ((LTE_PHY_TEST_CONFIG*)memory_pool)[i].phy_test_parameter_id = i + 1;
        ((LTE_PHY_TEST_CONFIG*)memory_pool)[i].test_mode = i % 2 == 0 ? TEST_MODE_A : TEST_MODE_B;
        ((LTE_PHY_TEST_CONFIG*)memory_pool)[i].physical_layer_status = PHYSICAL_LAYER_STATUS_OK;
    }

    return memory_pool;
}

