    public static void compressLogs(List<LogEntry> logEntries) throws Exception {
        // Create a ZIP archive named "log_archive.zip" in the application's working directory
        File zipFile = new File("log_archive.zip");
        ZipOutputStream zipOut = new ZipOutputStream(new FileOutputStream(zipFile));

        // Iterate over the list of log entries and add each entry to the ZIP archive
        for (LogEntry logEntry : logEntries) {
            // Create a ZIP entry for the current log entry
            ZipEntry zipEntry = new ZipEntry(logEntry.getTimestamp() + ".txt");

            // Add the ZIP entry to the ZIP output stream
            zipOut.putNextEntry(zipEntry);

            // Write the log message to the ZIP entry
            zipOut.write(logEntry.getMessage().getBytes());

            // Close the ZIP entry
            zipOut.closeEntry();
        }

        // Close the ZIP output stream
        zipOut.close();
    }
}
