// Define the structure for a MAC Protocol Data Unit (PDU)
typedef struct {
    int entity_id;
    int sequence_number;
    int priority_level;
} MAC_PDU;

// Define the dynamic array of PDUs
MAC_PDU *pdu_array = NULL;

// Define the maximum number of PDUs that can be stored in the array
int max_num_pdus = 0;

// Define a function to load optional parameters from an external YAML configuration file
void load_config(const char *filename) {
    // Open the YAML configuration file
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open configuration file\n");
        return;
    }

    // Parse the YAML configuration file
    yaml_parser_t parser;
    yaml_event_t event;
    int done = 0;
    while (!done) {
        if (!yaml_parser_load(file, &parser)) {
            printf("Error: unable to parse configuration file\n");
            break;
        }

        // Check for the start of a mapping event
        if (event.type == YAML_MAPPING_START_EVENT) {
            // Get the entity ID and sequence number from the mapping
            int entity_id = 0, sequence_number = 0;
            while (!done) {
                yaml_parser_parse(file, &event);
                if (event.type == YAML_SCALAR_EVENT) {
                    // Check for the "entity_id" key
                    if (strcmp((char *) event.data.scalar.value, "entity_id") == 0) {
                        yaml_parser_parse(file, &event);
                        entity_id = atoi((char *) event.data.scalar.value);
                    } else if (strcmp((char *) event.data.scalar.value, "sequence_number") == 0) {
                        yaml_parser_parse(file, &event);
                        sequence_number = atoi((char *) event.data.scalar.value);
                    } else if (strcmp((char *) event.data.scalar.value, "priority_level") == 0) {
                        yaml_parser_parse(file, &event);
                        priority_level = atoi((char *) event.data.scalar.value);
                    } else {
                        // Ignore unknown keys
                    }
                } else if (event.type == YAML_MAPPING_END_EVENT) {
                    break;
                }
            }

            // Add the PDU to the array
            MAC_PDU *pdu = malloc(sizeof(MAC_PDU));
            pdu->entity_id = entity_id;
            pdu->sequence_number = sequence_number;
            pdu->priority_level = priority_level;
            if (max_num_pdus == 0) {
                max_num_pdus = 1;
                pdu_array = malloc(sizeof(MAC_PDU));
            } else {
                max_num_pdus++;
                pdu_array = realloc(pdu_array, sizeof(MAC_PDU) * max_num_pdus);
            }
            memcpy(&pdu_array[max_num_pdus - 1], pdu, sizeof(MAC_PDU));
        } else if (event.type == YAML_STREAM_END_EVENT) {
            done = 1;
        }
    }

    // Close the YAML configuration file
    fclose(file);
}

// Define a function to allocate memory for a new PDU
MAC_PDU *allocate_pdu() {
    if (max_num_pdus == 0) {
        max_num_pdus = 1;
        pdu_array = malloc(sizeof(MAC_PDU));
    } else {
        max_num_pdus++;
        pdu_array = realloc(pdu_array, sizeof(MAC_PDU) * max_num_pdus);
    }
    return &pdu_array[max_num_pdus - 1];
}

// Define a function to deallocate memory for a PDU
void deallocate_pdu(MAC_PDU *pdu) {
    if (pdu == NULL) {
        return;
    }
    free(pdu);
}

// Define a function to add a new PDU to the array
void add_pdu(MAC_PDU *pdu) {
    if (max_num_pdus == 0) {
        max_num_pdus = 1;
        pdu_array = malloc(sizeof(MAC_PDU));
    } else {
        max_num_pdus++;
        pdu_array = realloc(pdu_array, sizeof(MAC_PDU) * max_num_pdus);
    }
    memcpy(&pdu_array[max_num_pdus - 1], pdu, sizeof(MAC_PDU));
}

// Define a function to remove a PDU from the array
void remove_pdu(int index) {
    if (index < 0 || index >= max_num_pdus) {
        return;
    }
    memmove(&pdu_array[index], &pdu_array[index + 1], sizeof(MAC_PDU) * (max_num_pdus - index - 1));
    max_num_pdus--;
}

// Define a function to get the number of PDUs in the array
int get_num_pdus() {
    return max_num_pdus;
}

// Define a function to get a PDU from the array by index
