void parse_command_line(int argc, char **argv) {
    if (argc > 1) {
        int i;
        for (i = 1; i < argc; i++) {
            if (!strcmp(argv[i], "-s") || !strcmp(argv[i], "--size")) {
                max_message_count = atoi(argv[++i]);
            } else if (!strcmp(argv[i], "-o") || !strcmp(argv[i], "--output")) {
                output_file = fopen(argv[++i], "w");
            }
        }
    }
}

// Initialize the list of NFAPI_RRC_MSG_T structures
void init_messages() {
    messages = (NFAPI_RRC_MSG_T *)malloc(max_message_count * sizeof(NFAPI_RRC_MSG_T));
    if (!messages) {
        perror("Failed to allocate memory for message list");
        exit(1);
    }
}

// Add a new NFAPI_RRC_MSG_T structure to the list
void add_message(char *mac_header, char *payload, int metadata) {
    if (message_count >= max_message_count) {
        perror("Message list is full");
        return;
    }
    messages[message_count].mac_header = mac_header;
    messages[message_count].payload = payload;
    messages[message_count].metadata = metadata;
    message_count++;
}

// Update the size of the list dynamically post-initialization without reallocation
void update_list_size(int new_size) {
    if (new_size > max_message_count) {
        perror("New list size is larger than maximum allowed");
        return;
    }
    NFAPI_RRC_MSG_T *new_messages = (NFAPI_RRC_MSG_T *)realloc(messages, new_size * sizeof(NFAPI_RRC_MSG_T));
    if (!new_messages) {
        perror("Failed to reallocate memory for message list");
        return;
    }
    messages = new_messages;
    max_message_count = new_size;
}

// Log errors and warnings to a specified file, ensuring thread safety for simultaneous initialization by multiple threads
