NFAPI_CRC_INDICATION_PDU_T* alloc_crc_indication(size_t num_structures) {
    // Check if the requested number of structures is valid
    if (num_structures == 0 || num_structures > SIZE_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return NULL;
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* arr = malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (arr == NULL) {
