// Define the TUNNEL_MESSAGE structure
typedef struct {
    uint32_t session_id;
    uint8_t message_type;
    void* payload;
} tunnel_message_t;

// Define the memory pool for small allocations
#define MEMORY_POOL_SIZE 1024 * 1024 // 1 MB
static char memory_pool[MEMORY_POOL_SIZE];
static size_t memory_pool_used = 0;

// Define the packet parser function
void parse_packet(const uint8_t* packet, size_t length) {
    // Check if the packet is valid and has enough data to be parsed
    if (length < sizeof(uint32_t)) {
        return;
    }

    // Extract the session ID from the packet header
    uint32_t session_id = *((const uint32_t*)packet);

    // Extract the message type from the packet header
    uint8_t message_type = *(packet + sizeof(uint32_t));

    // Allocate memory for the payload
    size_t payload_size = length - (sizeof(uint32_t) + sizeof(uint8_t));
    void* payload = malloc(payload_size);
    if (!payload) {
        return;
    }

    // Copy the payload data from the packet to the allocated memory
    memcpy(payload, packet + (sizeof(uint32_t) + sizeof(uint8_t)), payload_size);

    // Create a new tunnel message structure and populate it with the extracted data
    tunnel_message_t* message = malloc(sizeof(tunnel_message_t));
    if (!message) {
        free(payload);
        return;
    }
    message->session_id = session_id;
    message->message_type = message_type;
    message->payload = payload;

    // Add the new message to the array of tunnel messages
    pthread_mutex_lock(&messages_mutex);
    if (messages_count >= messages_capacity) {
        messages_capacity *= 2;
        messages = realloc(messages, messages_capacity * sizeof(tunnel_message_t*));
        if (!messages) {
            free(payload);
            free(message);
            pthread_mutex_unlock(&messages_mutex);
            return;
        }
    }
    messages[messages_count++] = message;
    pthread_mutex_unlock(&messages_mutex);
}

// Define the function to parse and process incoming network packets
void process_packets(const uint8_t* packet, size_t length) {
    // Check if the packet is valid and has enough data to be parsed
    if (length < sizeof(uint32_t)) {
        return;
    }

    // Parse the packet using the packet parser function
    parse_packet(packet, length);
}

// Define the main entry point for the program
int main() {
    // Initialize the memory pool and messages array
    memset(memory_pool, 0, MEMORY_POOL_SIZE);
    messages = malloc(16 * sizeof(tunnel_message_t*));
    if (!messages) {
        return -1;
    }
    messages_capacity = 16;
    messages_count = 0;

    // Initialize the mutex for protecting the messages array
    pthread_mutex_init(&messages_mutex, NULL);

    // Start the packet processing loop
    while (true) {
        // Read a packet from the network interface
        uint8_t* packet = read_packet();
        if (!packet) {
            continue;
        }

        // Process the packet using the process_packets function
        process_packets(packet, length);
    }

    return 0;
}
