```java
import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

public class LogCompression {
    public static void compressLogs(List<LogEntry> logEntries, File outputFile) throws Exception {
        // Create a ZipOutputStream for the output file
        try (ZipOutputStream zipOut = new ZipOutputStream(outputFile)) {
            // Iterate over the log entries and add them to the ZipOutputStream
            for (LogEntry logEntry : logEntries) {
                // Get the name of the log entry as a ZipEntry
                String entryName = logEntry.getFileName();
                ZipEntry zipEntry = new ZipEntry(entryName);

                // Write the log entry to the ZipOutputStream
                zipOut.putNextEntry(zipEntry);
                zipOut.write(logEntry.getLogData());
            }
        }
    }
}
