void parse_body(char* body, char** body_buffer, size_t* body_length) {
    // Parse HTTP body and store in buffer
    *body_buffer = malloc(RESPONSE_BUFFER_SIZE);
    *body_length = 0;
    for (int i = 0; i < strlen(body); i++) {
        if (body[i] == '\n') {
            (*body_length)++;
        } else {
            (*body_buffer)[*body_length] = body[i];
            (*body_length)++;
        }
    }
}

char* generate_cache_key(char* url) {
    // Generate cache key for URL
    char* cache_key = malloc(strlen(url));
    strcpy(cache_key, url);
    return cache_key;
}

void store_response_in_cache(char* cache_key, char* response, size_t length) {
