            printf("Critical event: %d, timestamp: %lu\n", event->event_type, event->timestamp);
        }
        for (int i = 0; i < error_buffer.size; i++) {
            NETWORK_EVENT_T* event = &error_buffer[i];
            printf("Error: %d, timestamp: %lu\n", event->event_type, event->timestamp);
        }
    }
}

