    NETWORK_EVENT_T* event_buffer = malloc(sizeof(NETWORK_EVENT_T) * EVENT_BUFFER_SIZE);
    NETWORK_EVENT_T* packet_loss_buffer = malloc(sizeof(NETWORK_EVENT_T) * EVENT_BUFFER_SIZE);

