#define LOG_LEVEL_WARNING 2
#define LOG_LEVEL_ERROR 3

typedef struct {
    char *macHeader;
    char *payload;
    int metadata;
} NFAPI_RRC_MSG_T;

typedef struct {
    int phyTestParameterId;
    int testMode;
    int physicalLayerStatus;
} LTE_PHY_TEST_CONFIG;

typedef struct {
    NFAPI_RRC_MSG_T *rrcMessages[MAX_RRC_MESSAGES];
    LTE_PHY_TEST_CONFIG *phyTestConfigs[MAX_PHY_TEST_CONFIGS];
} DATA_STRUCTURE;

DATA_STRUCTURE dataStructure = {NULL, NULL};
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
sem_t semaphore = SEM_INITIALIZER(0);
int logLevel = LOG_LEVEL_INFO;
char *logBuffer = (char *)malloc(LOG_BUFFER_SIZE * sizeof(char));
FILE *logFile = fopen(LOG_FILE, "a");

void initDataStructure() {
    dataStructure.rrcMessages = (NFAPI_RRC_MSG_T **)calloc(MAX_RRC_MESSAGES, sizeof(NFAPI_RRC_MSG_T *));
    dataStructure.phyTestConfigs = (LTE_PHY_TEST_CONFIG **)calloc(MAX_PHY_TEST_CONFIGS, sizeof(LTE_PHY_TEST_CONFIG *));
}

void destroyDataStructure() {
    for (int i = 0; i < MAX_RRC_MESSAGES; i++) {
        if (dataStructure.rrcMessages[i] != NULL) {
            free(dataStructure.rrcMessages[i]);
        }
    }
    for (int j = 0; j < MAX_PHY_TEST_CONFIGS; j++) {
        if (dataStructure.phyTestConfigs[j] != NULL) {
            free(dataStructure.phyTestConfigs[j]);
        }
    }
}

void logMessage(int level, char *message) {
    pthread_mutex_lock(&mutex);
    if (level <= logLevel) {
        fprintf(logFile, "%s\n", message);
        fflush(logFile);
    }
    pthread_mutex_unlock(&mutex);
}

void *processRRCMessage(void *arg) {
    NFAPI_RRC_MSG_T *message = (NFAPI_RRC_MSG_T *)arg;
    if (message != NULL) {
        // Process RRC message here
        logMessage(LOG_LEVEL_INFO, "Processing RRC message");
    } else {
        logMessage(LOG_LEVEL_WARNING, "Received null RRC message");
    }
}

void *processPHYTestConfig(void *arg) {
    LTE_PHY_TEST_CONFIG *config = (LTE_PHY_TEST_CONFIG *)arg;
    if (config != NULL) {
        // Process PHY test configuration here
        logMessage(LOG_LEVEL_INFO, "Processing PHY test configuration");
    } else {
        logMessage(LOG_LEVEL_WARNING, "Received null PHY test configuration");
    }
}

void *processDataStructure() {
    while (1) {
        sem_wait(&semaphore);
        pthread_mutex_lock(&mutex);
        for (int i = 0; i < MAX_RRC_MESSAGES; i++) {
            if (dataStructure.rrcMessages[i] != NULL) {
                processRRCMessage(dataStructure.rrcMessages[i]);
            }
        }
        for (int j = 0; j < MAX_PHY_TEST_CONFIGS; j++) {
            if (dataStructure.phyTestConfigs[j] != NULL) {
                processPHYTestConfig(dataStructure.phyTestConfigs[j]);
            }
        }
        pthread_mutex_unlock(&mutex);
    }
}

int main() {
    initDataStructure();
    pthread_t thread;
    pthread_create(&thread, NULL, processDataStructure, NULL);
    while (1) {
        // Receive RRC messages and PHY test configurations from external API here
        NFAPI_RRC_MSG_T *message = receiveRRCMessage();
        LTE_PHY_TEST_CONFIG *config = receivePHYTestConfig();
        if (message != NULL) {
            pthread_mutex_lock(&mutex);
            dataStructure.rrcMessages[0] = message;
            sem_post(&semaphore);
            pthread_mutex_unlock(&mutex);
        } else {
            logMessage(LOG_LEVEL_WARNING, "Received null RRC message");
        }
        if (config != NULL) {
            pthread_mutex_lock(&mutex);
            dataStructure.phyTestConfigs[0] = config;
            sem_post(&semaphore);
            pthread_mutex_unlock(&mutex);
        } else {
            logMessage(LOG_LEVEL_WARNING, "Received null PHY test configuration");
        }
    }
}

