// Define the structure for a PHY layer event
typedef struct {
    RX_SIB1_TAG rx_sib1;
    CELL_ID cell_id;
    PHY_LAYER_EVENT_TAG event;
} PHY_LAYER_EVENT_PDU_T;

// Define the list of PHY layer events
typedef struct {
    PHY_LAYER_EVENT_PDU_T* events;
    size_t capacity;
    size_t count;
} PHY_LAYER_EVENT_LIST_T;

// Define the function to manage the list of PHY layer events
void manage_phy_layer_events(PHY_LAYER_EVENT_LIST_T* event_list, void (*operation)(PHY_LAYER_EVENT_PDU_T*)) {
    // Lock the list to prevent concurrent modifications
    pthread_mutex_lock(&event_list->mutex);

    // Iterate over each event in the list and perform the specified operation
    for (size_t i = 0; i < event_list->count; ++i) {
        PHY_LAYER_EVENT_PDU_T* event = &event_list->events[i];
        operation(event);
    }

    // Unlock the list to allow other threads to modify it
    pthread_mutex_unlock(&event_list->mutex);
}

// Define the function to add a new PHY layer event to the list
void add_phy_layer_event(PHY_LAYER_EVENT_LIST_T* event_list, RX_SIB1_TAG rx_sib1, CELL_ID cell_id, PHY_LAYER_EVENT_TAG event) {
    // Check if the list is full and needs to be resized
    if (event_list->count == event_list->capacity) {
        // Double the capacity of the list
        size_t new_capacity = event_list->capacity * 2;
        PHY_LAYER_EVENT_PDU_T* new_events = realloc(event_list->events, sizeof(PHY_LAYER_EVENT_PDU_T) * new_capacity);
        if (new_events == NULL) {
            // Handle memory allocation failure
            printf("Error: Failed to allocate memory for PHY layer event list\n");
            return;
        }
        event_list->events = new_events;
        event_list->capacity = new_capacity;
    }

    // Add the new event to the end of the list
    PHY_LAYER_EVENT_PDU_T* new_event = &event_list->events[event_list->count++];
    new_event->rx_sib1 = rx_sib1;
    new_event->cell_id = cell_id;
    new_event->event = event;
}

// Define the function to remove a PHY layer event from the list
void remove_phy_layer_event(PHY_LAYER_EVENT_LIST_T* event_list, size_t index) {
    // Check if the index is valid
    if (index >= event_list->count) {
        printf("Error: Invalid index for PHY layer event\n");
        return;
    }

    // Shift all events after the specified index to fill the gap
    for (size_t i = index + 1; i < event_list->count; ++i) {
        event_list->events[i - 1] = event_list->events[i];
    }

    // Decrement the count of events in the list
    --event_list->count;
}

// Define the function to iterate over all PHY layer events in the list
void iterate_phy_layer_events(PHY_LAYER_EVENT_LIST_T* event_list, void (*operation)(PHY_LAYER_EVENT_PDU_T*)) {
    // Lock the list to prevent concurrent modifications
    pthread_mutex_lock(&event_list->mutex);

    // Iterate over each event in the list and perform the specified operation
    for (size_t i = 0; i < event_list->count; ++i) {
        PHY_LAYER_EVENT_PDU_T* event = &event_list->events[i];
        operation(event);
    }

    // Unlock the list to allow other threads to modify it
    pthread_mutex_unlock(&event_list->mutex);
}

