        event_list->events = new_events;
        event_list->capacity = new_capacity;
    }

    // Add the new event type and tag to the end of the list
    PHY_LAYER_EVENT_PDU_T* new_event = &event_list->events[event_list->count++];
    new_event->event.tag = event_tag;
}

