char* generate_unique_filename(const char* original_filename, const char* file_type) {
    // Determine the number of vowels in the original filename
    int num_vowels = 0;
    for (int i = 0; i < strlen(original_filename); i++) {
        if (original_filename[i] == 'a' || original_filename[i] == 'e' || original_filename[i] == 'i' || original_filename[i] == 'o' || original_filename[i] == 'u') {
            num_vowels++;
        }
    }

    // Calculate the buffer size for the new filename
    int buffer_size = strlen(original_filename) + num_vowels + 1;
    if (buffer_size > MAX_FILENAME_LENGTH) {
        buffer_size = MAX_FILENAME_LENGTH;
    }

    // Construct the new filename using sprintf and strcat
    char* new_filename = malloc(buffer_size);
    snprintf(new_filename, buffer_size, "%s", original_filename);
    for (int i = 0; i < num_vowels; i++) {
        int random_digit = rand() % 10;
        strcat(new_filename, &random_digit);
    }
    if (file_type != NULL) {
        strcat(new_filename, ".");
        strcat(new_filename, file_type);
    } else {
        strcat(new_filename, DEFAULT_FILE_TYPE);
    }

    // Check for duplicate filenames and retry with a modified extension if necessary
    int num_retries = 0;
    while (1) {
        struct stat file_info;
        if (stat(new_filename, &file_info) == 0) {
            // File exists, try again with a modified extension
            char* new_extension = malloc(strlen(new_filename) + 2);
            snprintf(new_extension, strlen(new_filename) + 2, "%s.%d", new_filename, num_retries);
            free(new_filename);
            new_filename = new_extension;
            num_retries++;
        } else {
            // File does not exist, break out of the loop
            break;
        }
    }

    // Log a message to the error log if the file system operations fail
    if (num_retries > 0) {
        char* error_message = malloc(strlen(new_filename) + 100);
        snprintf(error_message, strlen(new_filename) + 100, "Failed to generate unique filename after %d retries", num_retries);
        va_list args;
        va_start(args, error_message);
        vfprintf(stderr, error_message, args);
        va_end(args);
        free(error_message);
    }

    return new_filename;
}
