// Define the structure for storing TCP connection statistics
typedef struct {
    int connection_id;
    char* source_ip;
    char* destination_ip;
    long bytes_sent;
    long bytes_received;
    time_t last_seen_timestamp;
    int status_code;
    char* error_reason;
} TCP_CONNECTION_STATS;

