    char* source_ip;
    char* destination_ip;
    long bytes_sent;
    long bytes_received;
} NETWORK_PERFORMANCE_MONITOR;

// Define the maximum number of concurrent network sessions
#define MAX_CONCURRENT_SESSIONS 5000

// Define the mutex for synchronizing access to the connection pool
pthread_mutex_t connection_pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the array of TCP connection statistics structures
TCP_CONNECTION_STATS* connection_pool = NULL;

// Define the function for initializing the connection pool
void initialize_connection_pool() {
    // Allocate memory for the connection pool
    connection_pool = (TCP_CONNECTION_STATS*)malloc(sizeof(TCP_CONNECTION_STATS) * MAX_CONCURRENT_SESSIONS);
    if (!connection_pool) {
        fprintf(stderr, "Error: Failed to allocate memory for the connection pool\n");
        exit(1);
    }

    // Initialize each structure in the pool with default values
    for (int i = 0; i < MAX_CONCURRENT_SESSIONS; i++) {
        connection_pool[i].connection_id = -1;
        connection_pool[i].source_ip = NULL;
        connection_pool[i].destination_ip = NULL;
        connection_pool[i].bytes_sent = 0;
        connection_pool[i].bytes_received = 0;
        connection_pool[i].last_seen_timestamp = time(NULL);
        connection_pool[i].status_code = -1;
        connection_pool[i].error_reason = NULL;
    }
}

// Define the function for adding a new TCP connection to the pool
void add_connection(int connection_id, char* source_ip, char* destination_ip) {
    // Acquire the mutex for synchronizing access to the connection pool
    pthread_mutex_lock(&connection_pool_mutex);

    // Find an empty slot in the connection pool and initialize it with the new connection details
    int i;
    for (i = 0; i < MAX_CONCURRENT_SESSIONS; i++) {
        if (connection_pool[i].connection_id == -1) {
            break;
        }
    }
    if (i >= MAX_CONCURRENT_SESSIONS) {
        fprintf(stderr, "Error: Connection pool is full\n");
        pthread_mutex_unlock(&connection_pool_mutex);
        return;
    }
    connection_pool[i].connection_id = connection_id;
    connection_pool[i].source_ip = source_ip;
    connection_pool[i].destination_ip = destination_ip;
    connection_pool[i].bytes_sent = 0;
    connection_pool[i].bytes_received = 0;
    connection_pool[i].last_seen_timestamp = time(NULL);
    connection_pool[i].status_code = -1;
    connection_pool[i].error_reason = NULL;

    // Release the mutex for synchronizing access to the connection pool
    pthread_mutex_unlock(&connection_pool_mutex);
}

// Define the function for updating the status of a TCP connection in the pool
void update_status(int connection_id, int status_code, char* error_reason) {
    // Acquire the mutex for synchronizing access to the connection pool
    pthread_mutex_lock(&connection_pool_mutex);

    // Find the slot in the connection pool corresponding to the given connection ID and update its status
    int i;
    for (i = 0; i < MAX_CONCURRENT_SESSIONS; i++) {
        if (connection_pool[i].connection_id == connection_id) {
            break;
        }
    }
    if (i >= MAX_CONCURRENT_SESSIONS) {
        fprintf(stderr, "Error: Connection pool does not contain the given connection ID\n");
        pthread_mutex_unlock(&connection_pool_mutex);
        return;
    }
    connection_pool[i].status_code = status_code;
    connection_pool[i].error_reason = error_reason;

    // Release the mutex for synchronizing access to the connection pool
    pthread_mutex_unlock(&connection_pool_mutex);
}

// Define the function for releasing a TCP connection from the pool
void release_connection(int connection_id) {
    // Acquire the mutex for synchronizing access to the connection pool
    pthread_mutex_lock(&connection_pool_mutex);

    // Find the slot in the connection pool corresponding to the given connection ID and mark it as available
    int i;
    for (i = 0; i < MAX_CONCURRENT_SESSIONS; i++) {
        if (connection_pool[i].connection_id == connection_id) {
            break;
        }
    }
    if (i >= MAX_CONCURRENT_SESSIONS) {
