// Define the function for processing a line of text from an input source
void process_line(char* line) {
    // Parse the line and extract the relevant information
    char* delimiter = strchr(line, '|');
    if (!delimiter) {
        fprintf(stderr, "Error: Invalid delimiter in line\n");
        return;
    }
    int connection_id = atoi(line);
    char* source_ip = strtok(delimiter + 1, '|');
    char* destination_ip = strtok(NULL, '|');
    long bytes_sent = atol(strtok(NULL, '|'));
    long bytes_received = atol(strtok(NULL, '|'));

    // Add the new connection to the pool if it does not already exist
    add_connection(connection_id, source_ip, destination_ip);

    // Update the status of the connection in the pool
    update_status(connection_id, 200, "OK");

    // Release the connection from the pool when it is no longer needed
    release_connection(connection_id);
}

// Define the function for processing a file or directory of text files
void process_file(char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error: Failed to open file %s\n", filename);
        return;
    }

    // Read each line of the file and process it
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        process_line(line);
    }

    // Close the file
    fclose(file);
}

// Define the function for processing a directory of text files recursively
void process_directory(char* directory) {
    DIR* dir = opendir(directory);
    if (!dir) {
        fprintf(stderr, "Error: Failed to open directory %s\n", directory);
        return;
    }

    // Read each file in the directory and process it
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        char filename[1024];
        snprintf(filename, sizeof(filename), "%s/%s", directory, entry->d_name);
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        process_file(filename);
    }

    // Close the directory
    closedir(dir);
}

// Define the function for processing a mix of files and directories recursively
void process_input_sources() {
    // Read each input source from the command line arguments and process it
    int argc = 0;
    char** argv = NULL;
    while (argc < argc) {
        char* filename = argv[argc++];
        if (is_directory(filename)) {
            process_directory(filename);
        } else {
            process_file(filename);
        }
    }
}

// Define the function for handling command-line arguments and starting the program
