// Define structure for camera stream processor
typedef struct {
    int camera_id;
    int stream_resolution;
    int frames_per_second;
} CAMERA_STREAM_PROCESSOR;

// Define structure for frame processor
typedef struct {
    unsigned char* frame_data;
    long process_time;
    int error_code;
} FRAME_PROCESSOR_T;

// Define queue for frame processor structures
FRAME_PROCESSOR_T* frame_processor_queue = NULL;

// Define mutex for thread-safe memory allocation
pthread_mutex_t mem_alloc_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to manage pool of camera stream processors
void manage_camera_stream_processors(int num_cameras, int frames_per_second) {
    // Allocate memory for camera stream processors
    CAMERA_STREAM_PROCESSOR* cameras = (CAMERA_STREAM_PROCESSOR*)malloc(num_cameras * sizeof(CAMERA_STREAM_PROCESSOR));
    if (!cameras) {
        printf("Error: Failed to allocate memory for camera stream processors\n");
        return;
    }

    // Initialize camera stream processors
    for (int i = 0; i < num_cameras; i++) {
        cameras[i].camera_id = i + 1;
        cameras[i].stream_resolution = frames_per_second;
        cameras[i].frames_per_second = frames_per_second;
    }

    // Allocate memory for frame processor structures
    FRAME_PROCESSOR_T* frame_processors = (FRAME_PROCESSOR_T*)malloc(num_cameras * sizeof(FRAME_PROCESSOR_T));
    if (!frame_processors) {
        printf("Error: Failed to allocate memory for frame processor structures\n");
        free(cameras);
        return;
    }

    // Initialize frame processor structures
    for (int i = 0; i < num_cameras; i++) {
        frame_processors[i].frame_data = NULL;
        frame_processors[i].process_time = 0;
        frame_processors[i].error_code = 0;
    }

    // Populate queue with frame processor structures
    for (int i = 0; i < num_cameras; i++) {
        pthread_mutex_lock(&mem_alloc_mutex);
        FRAME_PROCESSOR_T* new_frame_processor = (FRAME_PROCESSOR_T*)malloc(sizeof(FRAME_PROCESSOR_T));
        if (!new_frame_processor) {
            printf("Error: Failed to allocate memory for frame processor structure\n");
            free(cameras);
            free(frame_processors);
            pthread_mutex_unlock(&mem_alloc_mutex);
            return;
        }
        new_frame_processor->frame_data = NULL;
        new_frame_processor->process_time = 0;
        new_frame_processor->error_code = 0;
        frame_processor_queue = (FRAME_PROCESSOR_T*)realloc(frame_processor_queue, (i + 1) * sizeof(FRAME_PROCESSOR_T));
        if (!frame_processor_queue) {
            printf("Error: Failed to reallocate memory for frame processor queue\n");
            free(cameras);
            free(frame_processors);
            pthread_mutex_unlock(&mem_alloc_mutex);
            return;
        }
        frame_processor_queue[i] = *new_frame_processor;
        pthread_mutex_unlock(&mem_alloc_mutex);
    }

    // Process frames
    while (1) {
        // Check if any frames are available in the queue
        if (frame_processor_queue[0].frame_data == NULL) {
            break;
        }

        // Process frame
        for (int i = 0; i < num_cameras; i++) {
            CAMERA_STREAM_PROCESSOR* camera = &cameras[i];
            FRAME_PROCESSOR_T* frame_processor = &frame_processors[i];
            if (camera->frames_per_second > 0) {
                // Allocate memory for frame data
                unsigned char* frame_data = (unsigned char*)malloc(camera->stream_resolution * camera->stream_resolution * sizeof(unsigned char));
                if (!frame_data) {
                    printf("Error: Failed to allocate memory for frame data\n");
                    free(cameras);
                    free(frame_processors);
                    pthread_mutex_unlock(&mem_alloc_mutex);
                    return;
                }
                // Set frame data and process time
                frame_processor->frame_data = frame_data;
                frame_processor->process_time = 0;
                // Process frame
                for (int j = 0; j < camera->frames_per_second; j++) {
                    // Do something with the frame data
                    printf("Processing frame %d from camera %d\n", j + 1, i + 1);
                }
            } else {
                // Set error code and process time
                frame_processor->error_code = -1;
                frame_processor->process_time = 0;
            }
        }

        // Flush and reset stream data if necessary
        if (frame_processor_queue[0].frame_data == NULL) {
            for (int i = 0; i < num_cameras; i++) {
                CAMERA_STREAM_PROCESSOR* camera = &cameras[i];
                FRAME_PROCESSOR_T* frame_processor = &frame_processors[i];
                if (camera->frames_per_second > 0) {
                    // Free memory for frame data
                    free(frame_processor->frame_data);
                    frame_processor->frame_data = NULL;
                }
            }
        }

        // Log number of frames successfully processed and any errors encountered during allocation
        printf("Number of frames successfully processed: %d\n", num_cameras);
        for (int i = 0; i < num_cameras; i++) {
            CAMERA_STREAM_PROCESSOR* camera = &cameras[i];
            FRAME_PROCESSOR_T* frame_processor = &frame_processors[i];
            if (camera->frames_per_second > 0) {
                if (frame_processor->error_code == -1) {
                    printf("Error: Failed to allocate memory for frame data\n");
                } else {
                    printf("Frame %d from camera %d processed successfully\n", i + 1, camera->camera_id);
                }
            }
        }

        // Release all allocated memory upon completion
        free(cameras);
        free(frame_processors);
        pthread_mutex_unlock(&mem_alloc_mutex);
    }
}
