// Define the event structure
typedef struct {
    time_t timestamp;
    int priority;
    char* message;
} Event;

// Define the linked list node for storing events
typedef struct Node {
    Event event;
    struct Node* next;
} Node;

// Define the event collection structure
typedef struct {
    Node* head;
    int size;
    int capacity;
    float growth_factor;
} EventCollection;

// Initialize the event collection with a given capacity and growth factor
void initEventCollection(EventCollection* ec, int capacity, float growth_factor) {
    ec->head = NULL;
    ec->size = 0;
    ec->capacity = capacity;
    ec->growth_factor = growth_factor;
}

// Add an event to the collection
void addEvent(EventCollection* ec, Event event) {
    // Check if the collection is full and needs to be resized
    if (ec->size == ec->capacity) {
        resizeEventCollection(ec);
    }

    // Create a new node for the event
    Node* new_node = malloc(sizeof(Node));
    new_node->event = event;
    new_node->next = NULL;

    // Add the new node to the end of the linked list
    if (ec->head == NULL) {
        ec->head = new_node;
    } else {
        Node* current = ec->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    // Increment the size of the collection
    ec->size++;
}

// Resize the event collection when it is full
void resizeEventCollection(EventCollection* ec) {
    int new_capacity = (int)(ec->capacity * ec->growth_factor);
    Node* new_head = malloc(sizeof(Node) * new_capacity);
    Node* current = ec->head;
    for (int i = 0; i < ec->size; i++) {
        new_head[i] = current->event;
        current = current->next;
    }
    free(ec->head);
    ec->head = new_head;
    ec->capacity = new_capacity;
}

// Filter and sort the events based on priority and timestamp
void filterAndSortEvents(EventCollection* ec) {
    // Create a temporary array to store the filtered events
    Event* temp_events = malloc(sizeof(Event) * ec->size);

    // Copy the events into the temporary array
    int i = 0;
    Node* current = ec->head;
    while (current != NULL) {
        temp_events[i] = current->event;
        i++;
        current = current->next;
    }

    // Sort the events based on priority and timestamp
    qsort(temp_events, ec->size, sizeof(Event), compareEvents);

    // Check if the number of filtered events exceeds a predefined threshold
    int num_filtered_events = (int)(ec->size * 0.5);
    if (num_filtered_events > 100) {
        triggerPerformanceAlert(num_filtered_events);
    }

    // Free the temporary array
    free(temp_events);
}

// Trigger a performance monitoring alert when the number of filtered events exceeds a predefined threshold
void triggerPerformanceAlert(int num_filtered_events) {
    printf("Performance alert: %d filtered events\n", num_filtered_events);
}

// Compare two events based on their priority and timestamp
int compareEvents(const void* event1, const void* event2) {
    Event* e1 = (Event*)event1;
    Event* e2 = (Event*)event2;
    if (e1->priority > e2->priority) {
        return 1;
    } else if (e1->priority < e2->priority) {
        return -1;
    } else {
        return e1->timestamp - e2->timestamp;
    }
}
