        crc_indications[i].RX_UE_INFORMATION_TAG = rand_r(&seed) % UINT16_MAX;
        crc_indications[i].RNTI = rand_r(&seed) % UINT32_MAX;
        crc_indications[i].CRCFLAG = rand_r(&seed) % 256;
    }

    return crc_indications;
}

// Define the function to insert a CRC indication PDU into a message queue
void insert_crc_indication(NFAPI_CRC_INDICATION_PDU_T* pdu, sem_t* sem) {
    // Check if the message queue is full
    if (sem_wait(sem) == -1) {
        perror("sem_wait");
        return;
    }

    // Insert the CRC indication PDU into the message queue
    pthread_mutex_lock(&mutex);
    queue[tail] = pdu;
    tail = (tail + 1) % QUEUE_SIZE;
    pthread_mutex_unlock(&mutex);

    // Signal the condition variable to wake up a thread that is waiting for messages
    if (sem_post(sem) == -1) {
        perror("sem_post");
        return;
    }
}

// Define the function to retrieve a CRC indication PDU from a message queue
NFAPI_CRC_INDICATION_PDU_T* retrieve_crc_indication(sem_t* sem) {
    // Check if the message queue is empty
    if (sem_wait(sem) == -1) {
        perror("sem_wait");
        return NULL;
    }

    // Retrieve the CRC indication PDU from the message queue
    pthread_mutex_lock(&mutex);
    NFAPI_CRC_INDICATION_PDU_T* pdu = queue[head];
    head = (head + 1) % QUEUE_SIZE;
    pthread_mutex_unlock(&mutex);

    // Signal the condition variable to wake up a thread that is waiting for messages
    if (sem_post(sem) == -1) {
        perror("sem_post");
        return NULL;
    }

    return pdu;
}
