    if (strlen(newConfigurationID) > 128) {
        fprintf(stderr, "Error: Resulting configuration ID exceeds maximum length of 128 characters\n");
        free(randomHexString);
        free(newConfigurationID);
        return NULL;
    }

    // Validate that the resulting configuration ID is unique within the specified network configuration directory
