// Define the structure for CRC indication PDUs
typedef struct {
    RX_UE_INFORMATION_TAG rxUeInformationTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the maximum size for each structure
#define MAX_STRUCTURE_SIZE 1024

// Define the number of structures to allocate
#define NUM_STRUCTURES 100000

// Define the seed for the random number generator
#define SEED 123456789

// Define the maximum size constraint for each structure
#define MAX_SIZE 1000

// Define the total number of allocated structures
static int numAllocatedStructures = 0;

// Define a mutex to protect concurrent access to the list and message queue
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a semaphore to signal when memory allocation fails
static semaphore_t memAllocSem;

// Define a function to allocate memory for the list of structures
void* allocateMemory(int numStructures) {
    // Check if the number of structures is valid
    if (numStructures <= 0 || numStructures > NUM_STRUCTURES) {
        return NULL;
    }

    // Allocate memory for the list of structures
    NFAPI_CRC_INDICATION_PDU_T* list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * numStructures);
    if (list == NULL) {
        return NULL;
    }

    // Initialize the list of structures
    for (int i = 0; i < numStructures; i++) {
        list[i].rxUeInformationTag = RX_UE_INFORMATION_TAG_INIT;
        list[i].rnti = RNTI_INIT;
        list[i].crcIndicationRel8Tag = CRC_INDICATION_REL8_TAG_INIT;
    }

    // Increment the total number of allocated structures
    numAllocatedStructures += numStructures;

    return list;
}

// Define a function to populate the list of structures with random data
void populateList(NFAPI_CRC_INDICATION_PDU_T* list, int numStructures) {
    // Check if the number of structures is valid
    if (numStructures <= 0 || numStructures > NUM_STRUCTURES) {
        return;
    }

    // Populate the list of structures with random data
    for (int i = 0; i < numStructures; i++) {
        list[i].rxUeInformationTag.RX_UE_INFORMATION_TAG_MEMBER_CRNTI = rand() % MAX_SIZE + 1;
        list[i].rnti.RNTI_MEMBER_CRNTI = rand() % MAX_SIZE + 1;
        list[i].crcIndicationRel8Tag.CRC_INDICATION_REL8_TAG_MEMBER_CRCFLAG = rand() % 2;
    }
}

// Define a function to deallocate memory for the list of structures
void deallocateMemory(NFAPI_CRC_INDICATION_PDU_T* list, int numStructures) {
    // Check if the number of structures is valid
    if (numStructures <= 0 || numStructures > NUM_STRUCTURES) {
        return;
    }

    // Decrement the total number of allocated structures
    numAllocatedStructures -= numStructures;

    // Deallocate memory for the list of structures
    free(list);
}

// Define a function to handle memory allocation failures
void memAllocFailed() {
    semaphore_wait(&memAllocSem);
    printf("Memory allocation failed\n");
    semaphore_post(&memAllocSem);
}

// Define a function to manage the lifecycle of the list and message queue
void manageLifecycle(NFAPI_CRC_INDICATION_PDU_T* list, int numStructures) {
    // Check if the number of structures is valid
    if (numStructures <= 0 || numStructures > NUM_STRUCTURES) {
        return;
    }

    // Lock the mutex to protect concurrent access to the list and message queue
    pthread_mutex_lock(&mutex);

    // Allocate memory for the list of structures
    NFAPI_CRC_INDICATION_PDU_T* newList = allocateMemory(numStructures);
    if (newList == NULL) {
        memAllocFailed();
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Populate the list of structures with random data
    populateList(newList, numStructures);

    // Deallocate memory for the old list of structures
    deallocateMemory(list, numStructures);

    // Update the list and message queue
    list = newList;

