// Define a custom structure for the UDP header
typedef struct {
    uint32_t SRC_IP;
    uint32_t DEST_IP;
    uint16_t SRC_PORT;
    uint16_t DEST_PORT;
    uint32_t SEQ_NUMBER;
    bool ACK_FLAG;
} UDP_HEADER_T;

// Define a function to dynamically allocate memory for an array of custom structures
UDP_HEADER_T* alloc_udp_header(size_t num_structures, size_t max_seq_number) {
    // Check if the number of structures is valid
    if (num_structures == 0 || num_structures > SIZE_MAX / sizeof(UDP_HEADER_T)) {
        return NULL;
    }

    // Allocate memory for the array of structures
    UDP_HEADER_T* headers = malloc(num_structures * sizeof(UDP_HEADER_T));
    if (headers == NULL) {
        return NULL;
    }

    // Initialize each structure with a random SEQ_NUMBER within the specified range
    for (size_t i = 0; i < num_structures; i++) {
        headers[i].SEQ_NUMBER = rand() % max_seq_number + 1;
    }

    // Set the ACK_FLAG based on a probability parameter
    double prob = 0.5; // Change this value to simulate different network conditions
    for (size_t i = 0; i < num_structures; i++) {
        headers[i].ACK_FLAG = (rand() % 100) / 100.0 <= prob;
    }

    // Return the allocated array of structures
