#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>

// Define a structure for MAC frame information
typedef struct {
    S1AP_MESSAGE message;
    MAC_PDU pdu;
} MAC_FRAME_INFO;

// Define a custom memory pool for reusing memory blocks
typedef struct {
    void* block;
    size_t size;
} MemoryPool;

// Function to dynamically allocate an array of MAC frame information structures
MAC_FRAME_INFO* alloc_mac_frames(size_t num_frames, bool use_pool) {
    // Check if the number of frames is valid
    if (num_frames == 0) {
        return NULL;
    }

    // Allocate memory for the array of MAC frame information structures
    MAC_FRAME_INFO* mac_frames = malloc(sizeof(MAC_FRAME_INFO) * num_frames);
    if (mac_frames == NULL) {
        return NULL;
    }

    // Initialize the memory pool for reusing memory blocks
    MemoryPool* pool = NULL;
    if (use_pool) {
        pool = malloc(sizeof(MemoryPool));
        if (pool == NULL) {
            free(mac_frames);
            return NULL;
        }
        pool->block = NULL;
        pool->size = 0;
    }

    // Initialize the number of allocations and deallocations
    size_t num_allocs = 0;
    size_t num_deallocs = 0;

    // Loop through each MAC frame information structure
    for (size_t i = 0; i < num_frames; i++) {
        // Allocate memory for the S1AP message and MAC PDU
        mac_frames[i].message = malloc(sizeof(S1AP_MESSAGE));
        if (mac_frames[i].message == NULL) {
            free(mac_frames);
            return NULL;
        }
        num_allocs++;

        mac_frames[i].pdu.payload = malloc(1500);
        if (mac_frames[i].pdu.payload == NULL) {
            free(mac_frames[i].message);
            free(mac_frames);
            return NULL;
        }
        num_allocs++;

        // Generate a random MAC sequence number for the PDU
        mac_frames[i].pdu.seq_num = rand();

        // Add the allocated memory blocks to the pool if necessary
        if (use_pool) {
            MemoryPool* new_block = malloc(sizeof(MemoryPool));
            if (new_block == NULL) {
                free(mac_frames[i].pdu.payload);
                free(mac_frames[i].message);
                free(mac_frames);
                return NULL;
            }
            new_block->block = mac_frames[i].pdu.payload;
            new_block->size = 1500;
            pool->block = new_block;
            pool->size++;
        }
    }

    // Check for memory leaks and deallocate the memory properly
    if (use_pool) {
        MemoryPool* current_block = pool;
        while (current_block != NULL) {
            free(current_block->block);
            current_block = current_block->next;
        }
        free(pool);
    } else {
        for (size_t i = 0; i < num_frames; i++) {
            free(mac_frames[i].pdu.payload);
            free(mac_frames[i].message);
        }
    }

    // Return the array of MAC frame information structures
    return mac_frames;
}

// Function to deallocate an array of MAC frame information structures
void dealloc_mac_frames(MAC_FRAME_INFO* mac_frames, size_t num_frames) {
    // Check if the number of frames is valid
    if (num_frames == 0 || mac_frames == NULL) {
        return;
    }

    // Loop through each MAC frame information structure and deallocate its memory
    for (size_t i = 0; i < num_frames; i++) {
        free(mac_frames[i].pdu.payload);
        free(mac_frames[i].message);
    }

    // Deallocate the memory pool if necessary
    if (use_pool) {
        MemoryPool* current_block = pool;
        while (current_block != NULL) {
            free(current_block->block);
            current_block = current_block->next;
        }
        free(pool);
