uint8_t calculate_crc(void *data, size_t length) {
    // Initialize the CRC calculation with a predefined polynomial
    uint32_t crc = 0xFFFFFFFF;

    // Iterate over each byte in the PDU data
    for (size_t i = 0; i < length; i++) {
        // Calculate the next value of the CRC using the predefined polynomial
        crc = (crc >> 8) ^ (crc & 0xFF) ^ ((uint32_t *)data)[i];
