        printf("Error: Invalid array size %d\n", size);
        return NULL;
    }

    // Allocate memory for the array of structures
    NFAPI_RX_FRAME_T* frames = (NFAPI_RX_FRAME_T*)malloc(size * sizeof(NFAPI_RX_FRAME_T));
    if (!frames) {
        printf("Error: Failed to allocate memory for the array of structures\n");
        return NULL;
    }

    // Initialize each structure in the array with a valid RX frame header, TX power level, and signal strength tag
    for (int i = 0; i < size; i++) {
        frames[i].header.rx_frame_number = i + 1;
        frames[i].tx_power_level = rand() % 300; // Random TX power level
        frames[i].signal_strength.signal_strength = rand() % 300; // Random signal strength
    }

    return frames;
}

// Define the function to dynamically deallocate an array of NFAPI_RX_FRAME_T structures
