    // Check if the input pointer is NULL
    if (!frames) {
        printf("Error: Input pointer is NULL\n");
        return;
    }

    // Deallocate memory for the array of structures
    free(frames);
}

// Define the function to validate the signal strength values against a predefined threshold
void nfapi_rx_frame_validate_signal_strength(NFAPI_RX_FRAME_T* frames, int size) {
    // Check if the input pointer is NULL
    if (!frames) {
        printf("Error: Input pointer is NULL\n");
        return;
    }

    // Validate each signal strength value against the predefined threshold
    for (int i = 0; i < size; i++) {
        if (frames[i].signal_strength.signal_strength > 300) {
