    }
}

// Define the function to handle concurrent calls from multiple threads efficiently
void nfapi_rx_frame_concurrent(NFAPI_RX_FRAME_T* frames, int size) {
    // Check if the input pointer is NULL
    if (!frames) {
        printf("Error: Input pointer is NULL\n");
        return;
    }

    // Define a semaphore to manage concurrent access to shared resources
    sem_t sem;
    sem_init(&sem, 0, 1);

    // Define a lock to protect the memory pool from concurrent access
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Define a custom memory pool for efficient allocation and deallocation of structures
    NFAPI_RX_FRAME_POOL* pool = (NFAPI_RX_FRAME_POOL*)malloc(sizeof(NFAPI_RX_FRAME_POOL));
    pool->size = size * sizeof(NFAPI_RX_FRAME_T);
    pool->data = malloc(pool->size);

    // Allocate memory for the array of structures in the custom memory pool
    NFAPI_RX_FRAME_T* frames_pool = (NFAPI_RX_FRAME_T*)malloc(pool->size);
    if (!frames_pool) {
        printf("Error: Failed to allocate memory for the array of structures in the custom memory pool\n");
        return;
    }

    // Initialize each structure in the array with a valid RX frame header, TX power level, and signal strength tag
    for (int i = 0; i < size; i++) {
        frames_pool[i].header.rx_frame_number = i + 1;
        frames_pool[i].tx_power_level = rand() % 300; // Random TX power level
        frames_pool[i].signal_strength.signal_strength = rand() % 300; // Random signal strength
    }

    // Define a thread function to handle concurrent access to the custom memory pool
    void* thread_function(void* arg) {
        // Acquire the lock to protect the memory pool from concurrent access
        pthread_mutex_lock(&lock);

        // Allocate memory for the array of structures in the custom memory pool
        NFAPI_RX_FRAME_T* frames = (NFAPI_RX_FRAME_T*)malloc(pool->size);
        if (!frames) {
            printf("Error: Failed to allocate memory for the array of structures in the custom memory pool\n");
            return NULL;
        }

        // Initialize each structure in the array with a valid RX frame header, TX power level, and signal strength tag
        for (int i = 0; i < size; i++) {
            frames[i].header.rx_frame_number = i + 1;
            frames[i].tx_power_level = rand() % 300; // Random TX power level
            frames[i].signal_strength.signal_strength = rand() % 300; // Random signal strength
        }

        // Release the lock to allow other threads to access the memory pool
        pthread_mutex_unlock(&lock);

        return NULL;
    }

    // Create a thread for each structure in the array
    for (int i = 0; i < size; i++) {
        pthread_t thread;
        if (pthread_create(&thread, NULL, thread_function, NULL) != 0) {
            printf("Error: Failed to create a thread\n");
            return;
        }
    }

    // Join the threads to ensure all structures in the array are initialized correctly
    for (int i = 0; i < size; i++) {
        pthread_join(threads[i], NULL);
    }

    // Deallocate memory for the custom memory pool and the thread function
    free(pool->data);
    free(pool);
    free(threads);
}
