#define TCP_CONNECTION_INFO_SIZE sizeof(struct tcp_connection_info)
#define NFAPI_CRC_INDICATION_PDU_T_SIZE sizeof(struct nfapi_crc_indication_pdu_t)
#define CRC_LOG_FILE "crc_log.txt"
#define DATABASE_CONNECTION_CHECK_THRESHOLD 30 // seconds
#define MEMORY_POOL_SIZE (MAX_N * NFAPI_CRC_INDICATION_PDU_T_SIZE)

struct tcp_connection_info {
    char ip_address[16];
    uint16_t port_number;
    uint8_t connection_state;
    time_t timestamp;
};

struct nfapi_crc_indication_pdu_t {
    uint32_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
};

struct memory_pool {
    void *memory;
    size_t size;
    pthread_mutex_t lock;
};

struct database_connection {
    char *host;
    char *username;
    char *password;
    int port;
    bool connected;
};

void *allocate_memory(size_t size) {
    void *memory = malloc(size);
    if (memory == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory. %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    return memory;
}

void *deallocate_memory(void *memory) {
    free(memory);
}

struct nfapi_crc_indication_pdu_t *create_nfapi_crc_indication_pdu_t(uint32_t rx_ue_information_tag, uint16_t rnti) {
    struct nfapi_crc_indication_pdu_t *pdu = allocate_memory(NFAPI_CRC_INDICATION_PDU_T_SIZE);
    pdu->rx_ue_information_tag = rx_ue_information_tag;
    pdu->rnti = rnti;
    pdu->crc_indication_rel8_tag = CRCFLAG;
    return pdu;
}

struct tcp_connection_info *create_tcp_connection_info(char *ip_address, uint16_t port_number) {
    struct tcp_connection_info *info = allocate_memory(TCP_CONNECTION_INFO_SIZE);
    strcpy(info->ip_address, ip_address);
    info->port_number = port_number;
    info->connection_state = 0; // set to disconnected by default
    return info;
}

void validate_crc_indication_pdu_t(struct nfapi_crc_indication_pdu_t *pdu) {
    uint8_t crc = calculate_crc(pdu, NFAPI_CRC_INDICATION_PDU_T_SIZE - sizeof(uint8_t));
    if (crc != pdu->crc_indication_rel8_tag) {
        fprintf(stderr, "Error: CRC validation failed. %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void validate_tcp_connection_info(struct tcp_connection_info *info) {
    if (strlen(info->ip_address) == 0 || info->port_number == 0) {
        fprintf(stderr, "Error: TCP connection information is invalid. %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void log_error(char *message) {
    FILE *log = fopen(CRC_LOG_FILE, "a");
    if (log == NULL) {
        fprintf(stderr, "Error: Failed to open log file. %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    fprintf(log, "%s\n", message);
    fclose(log);
}

void *allocate_memory_pool() {
    struct memory_pool *pool = allocate_memory(sizeof(struct memory_pool));
    pool->memory = allocate_memory(MEMORY_POOL_SIZE);
    pool->size = MEMORY_POOL_SIZE;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void deallocate_memory_pool(struct memory_pool *pool) {
    pthread_mutex_destroy(&pool->lock);
    deallocate_memory(pool->memory);
    deallocate_memory(pool);
}

void *allocate_nfapi_crc_indication_pdu_t(struct memory_pool *pool) {
    pthread_mutex_lock(&pool->lock);
    void *memory = pool->memory;
    pool->memory += NFAPI_CRC_INDICATION_PDU_T_SIZE;
    pool->size -= NFAPI_CRC_INDICATION_PDU_T_SIZE;
    pthread_mutex_unlock(&pool->lock);
    return memory;
}

void deallocate_nfapi_crc_indication_pdu_t(struct memory_pool *pool, void *memory) {
    pthread_mutex_lock(&pool->lock);
    pool->memory -= NFAPI_CRC_INDICATION_PDU_T_SIZE;
    pool->size += NFAPI_CRC_INDICATION_PDU_T_SIZE;
    pthread_mutex_unlock(&pool->lock);
}

void *allocate_tcp_connection_info(struct memory_pool *pool) {
    pthread_mutex_lock(&pool->lock);
    void *memory = pool->memory;
    pool->memory += TCP_CONNECTION_INFO_SIZE;
    pool->size -= TCP_CONNECTION_INFO_SIZE;
    pthread_mutex_unlock(&pool->lock);
    return memory;
}

void deallocate_tcp_connection_info(struct memory_pool *pool, void *memory) {
    pthread_mutex_lock(&pool->lock);
    pool->memory -= TCP_CONNECTION_INFO_SIZE;
    pool->size += TCP_CONNECTION_INFO_SIZE;
    pthread_mutex_unlock(&pool->lock);
}

uint8_t calculate_crc(void *data, size_t length) {
    uint8_t crc = 0xFF; // initial value for CRC calculation
    unsigned char *ptr = data;
    while (length--) {
        crc ^= *ptr++;
        for (int i = 0; i < 8; i++) {
            if ((crc & 0x80) != 0) {
                crc <<= 1;
                crc ^= CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

