#include <stdbool.h>

// Define the structure for MAC frame information
typedef struct {
    S1AP_MESSAGE message;
    MAC_PDU pdu;
} MAC_FRAME_INFO;

// Define the memory pool for dynamic allocation of MAC frames
#define MEMORY_POOL_SIZE 1024 * 1024 // 1 MB
static char memory_pool[MEMORY_POOL_SIZE];
static int memory_pool_index = 0;

// Define the custom memory pool for free lists
#define FREE_LISTS_COUNT 64
static struct {
    int size;
    void *memory;
} free_lists[FREE_LISTS_COUNT];

// Define the function to allocate a new MAC frame
MAC_FRAME_INFO* alloc_mac_frame(int size) {
    // Check if the requested size is within the memory pool limit
    if (size > MEMORY_POOL_SIZE - memory_pool_index) {
        return NULL;
    }

    // Allocate a new MAC frame from the memory pool
    MAC_FRAME_INFO *frame = (MAC_FRAME_INFO*) &memory_pool[memory_pool_index];
    memory_pool_index += size;

    // Initialize the MAC frame with random sequence number and payload
    frame->message.seq_num = rand();
    frame->pdu.payload = (char*) malloc(size);
    memset(frame->pdu.payload, 0, size);

    return frame;
}

// Define the function to deallocate a MAC frame
void free_mac_frame(MAC_FRAME_INFO *frame) {
    // Check if the frame is within the memory pool
    if (frame < &memory_pool[0] || frame >= &memory_pool[MEMORY_POOL_SIZE]) {
        return;
    }

    // Deallocate the MAC payload and update the memory pool index
    free(frame->pdu.payload);
    memory_pool_index -= sizeof(MAC_FRAME_INFO) + frame->message.length;
}

// Define the function to add a new MAC frame to the free lists
void add_free_list(int size, void *memory) {
    // Check if the requested size is within the memory pool limit
    if (size > MEMORY_POOL_SIZE - memory_pool_index) {
        return;
    }

    // Add the new MAC frame to the free lists
    int list_index = 0;
    while (list_index < FREE_LISTS_COUNT && size > free_lists[list_index].size) {
        list_index++;
    }
    if (list_index == FREE_LISTS_COUNT) {
        return;
    }
    free_lists[list_index].size = size;
    free_lists[list_index].memory = memory;
}

// Define the function to remove a MAC frame from the free lists
void* remove_free_list(int size) {
    // Check if there are any free frames of the requested size
    for (int i = 0; i < FREE_LISTS_COUNT; i++) {
        if (size == free_lists[i].size) {
            void *memory = free_lists[i].memory;
            free_lists[i].size = 0;
            free_lists[i].memory = NULL;
            return memory;
        }
    }
    return NULL;
}

// Define the function to handle concurrent access from multiple threads
void* mac_frame_alloc(int size) {
    // Check if there are any free frames of the requested size
    void *memory = remove_free_list(size);
    if (memory != NULL) {
        return memory;
    }

    // Allocate a new MAC frame from the memory pool
    MAC_FRAME_INFO *frame = alloc_mac_frame(size);
    if (frame == NULL) {
        return NULL;
    }

    // Add the new MAC frame to the free lists
    add_free_list(size, frame);

    return frame;
}

// Define the function to handle concurrent access from multiple threads
void mac_frame_dealloc(MAC_FRAME_INFO *frame) {
    // Check if the frame is within the memory pool
    if (frame < &memory_pool[0] || frame >= &memory_pool[MEMORY_POOL_SIZE]) {
        return;
    }

    // Deallocate the MAC payload and update the memory pool index
    free(frame->pdu.payload);
    memory_pool_index -= sizeof(MAC_FRAME_INFO) + frame->message.length;
}

// Define the function to detect and resolve fragmentation hotspots
void mac_frame_compact() {
    // Check if there are any free frames in the memory pool
    if (memory_pool_index == 0) {
        return;
    }

    // Compact the memory pool by removing all free frames
    int compacted_size = 0;
    for (int i = 0; i < FREE_LISTS_COUNT; i++) {
        if (free_lists[i].memory != NULL) {
            compacted_size += sizeof(MAC_FRAME_INFO) + free_lists[i].size;
            free_lists[i].memory = NULL;
