        udp_headers[i].dest_ip = rand() % 256;
        udp_headers[i].src_port = rand() % 65536;
        udp_headers[i].dest_port = rand() % 65536;
        udp_headers[i].seq_number = rand() % 1000000;
        udp_headers[i].ack_flag = (rand() % 2) ? true : false;
    }

    // Allocate memory for the array of network interface configurations
    NetworkInterfaceConfig* network_interfaces = (NetworkInterfaceConfig*)malloc(max_size * sizeof(NetworkInterfaceConfig));
    if (!network_interfaces) {
        fprintf(stderr, "Failed to allocate memory for network interfaces\n");
        free(udp_headers);
        return;
    }

