        network_interfaces[i].ip_address = malloc(16 * sizeof(char));
        if (!network_interfaces[i].ip_address) {
            fprintf(stderr, "Failed to allocate memory for IP address\n");
            free(udp_headers);
            free(network_interfaces);
            return;
        }
        network_interfaces[i].subnet_mask = malloc(16 * sizeof(char));
        if (!network_interfaces[i].subnet_mask) {
            fprintf(stderr, "Failed to allocate memory for subnet mask\n");
            free(udp_headers);
            free(network_interfaces);
            return;
        }
        network_interfaces[i].active = (rand() % 2) ? true : false;
    }

    // Validate the IP addresses and prevent duplicates
    for (int i = 0; i < max_size; i++) {
        for (int j = i + 1; j < max_size; j++) {
            if (!strcmp(network_interfaces[i].ip_address, network_interfaces[j].ip_address)) {
                fprintf(stderr, "Duplicate IP address detected\n");
                free(udp_headers);
                free(network_interfaces);
                return;
            }
        }
    }

    // Log errors to error.log in a thread-safe manner
    FILE* error_log = fopen("error.log", "a");
    if (!error_log) {
