    for (int i = 0; i < max_size; i++) {
        if (!inet_pton(AF_INET, network_interfaces[i].ip_address, &network_interfaces[i].ip_address)) {
            fprintf(error_log, "Invalid IP address: %s\n", network_interfaces[i].ip_address);
        }
    }
    fclose(error_log);

    // Check the health of each network interface using ping responses within a specified timeout
    for (int i = 0; i < max_size; i++) {
        if (!network_interfaces[i].active) continue;
        int sock = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP);
