// Define the function to populate the array with terrain feature points
void populate_terrain_feature_points(int count) {
    // Lock the mutex to avoid race conditions
    pthread_mutex_lock(&mutex);

    // Check if the array has been initialized
    if (terrain_feature_points == NULL) {
        // Allocate memory for the array
        terrain_feature_points = (TERRAIN_FEATURE_POINT *)malloc(count * sizeof(TERRAIN_FEATURE_POINT));
        if (terrain_feature_points == NULL) {
            printf("Error: Failed to allocate memory for terrain feature points\n");
            pthread_mutex_unlock(&mutex);
            return;
        }
    } else {
        // Reallocate the array to accommodate more points
        terrain_feature_points = (TERRAIN_FEATURE_POINT *)realloc(terrain_feature_points, count * sizeof(TERRAIN_FEATURE_POINT));
        if (terrain_feature_points == NULL) {
            printf("Error: Failed to reallocate memory for terrain feature points\n");
            pthread_mutex_unlock(&mutex);
            return;
        }
    }

    // Initialize the array with the new count
    terrain_feature_point_count = count;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
