// Function to dynamically allocate and initialize an array of structures
void init_ue_sessions() {
    // Initialize semaphore with value 1
    sem_init(&sem, 0, 1);

    // Loop through each UE session in the array
    for (int i = 0; i < 100000; i++) {
        // Allocate memory for SIM_CARD_IDENTIFIER and IMSI
        ue_sessions[i].SIM_CARD_IDENTIFIER = malloc(sizeof(char) * 20);
        ue_sessions[i].IMSI = malloc(sizeof(char) * 15);

        // Generate unique SIM_CARD_IDENTIFIER and IMSI for each UE session
        sprintf(ue_sessions[i].SIM_CARD_IDENTIFIER, "UE%d", i);
        sprintf(ue_sessions[i].IMSI, "%015d", i);

        // Initialize MESSAGE_TYPE and RX_UE_INFORMATION_TAG to NULL
        ue_sessions[i].MESSAGE_TYPE = NULL;
        ue_sessions[i].RX_UE_INFORMATION_TAG = NULL;

        // Generate random MESSAGE_FLAG and CRCFLAG for each UE session
        ue_sessions[i].MESSAGE_FLAG = rand() % 2;
        ue_sessions[i].CRCFLAG = rand() % 2;
    }
}

// Function to dynamically allocate memory for a new UE session
void add_ue_session(char *SIM_CARD_IDENTIFIER, char *IMSI) {
    // Acquire mutex lock
    pthread_mutex_lock(&mutex);

    // Check if there is space available in the array for a new UE session
    if (sem_wait(&sem) == 0) {
        // Loop through each UE session in the array to find an empty slot
        for (int i = 0; i < 100000; i++) {
            if (ue_sessions[i].SIM_CARD_IDENTIFIER == NULL) {
                // Allocate memory for SIM_CARD_IDENTIFIER and IMSI
                ue_sessions[i].SIM_CARD_IDENTIFIER = malloc(sizeof(char) * 20);
                ue_sessions[i].IMSI = malloc(sizeof(char) * 15);

                // Copy SIM_CARD_IDENTIFIER and IMSI from input parameters
                strcpy(ue_sessions[i].SIM_CARD_IDENTIFIER, SIM_CARD_IDENTIFIER);
                strcpy(ue_sessions[i].IMSI, IMSI);

                // Initialize MESSAGE_TYPE and RX_UE_INFORMATION_TAG to NULL
                ue_sessions[i].MESSAGE_TYPE = NULL;
                ue_sessions[i].RX_UE_INFORMATION_TAG = NULL;

                // Generate random MESSAGE_FLAG and CRCFLAG for each UE session
                ue_sessions[i].MESSAGE_FLAG = rand() % 2;
                ue_sessions[i].CRCFLAG = rand() % 2;

                break;
            }
        }
    } else {
        // Release mutex lock and return if there is no space available in the array for a new UE session
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Release mutex lock
    pthread_mutex_unlock(&mutex);
}

// Function to release memory allocated for a specific UE session
void remove_ue_session(char *SIM_CARD_IDENTIFIER) {
    // Acquire mutex lock
    pthread_mutex_lock(&mutex);

    // Loop through each UE session in the array to find the specified SIM_CARD_IDENTIFIER
    for (int i = 0; i < 100000; i++) {
        if (strcmp(ue_sessions[i].SIM_CARD_IDENTIFIER, SIM_CARD_IDENTIFIER) == 0) {
            // Release memory allocated for SIM_CARD_IDENTIFIER and IMSI
            free(ue_sessions[i].SIM_CARD_IDENTIFIER);
            free(ue_sessions[i].IMSI);

            // Set SIM_CARD_IDENTIFIER and IMSI to NULL
            ue_sessions[i].SIM_CARD_IDENTIFIER = NULL;
            ue_sessions[i].IMSI = NULL;

            break;
        }
    }

    // Release mutex lock and signal semaphore to release one slot in the array for a new UE session
    pthread_mutex_unlock(&mutex);
    sem_post(&sem);
}
