std::string processAndAnalyzeData(const std::string& url) {
  // Upload file to URL using libcurl
  CURL* curl = curl_easy_init();
  if (curl) {
    CURLcode res;
    std::string uploadUrl = url + "/upload";
    curl_easy_setopt(curl, CURLOPT_URL, uploadUrl.c_str());
    curl_easy_setopt(curl, CURLOPT_VERBOSE, 1L);
    curl_easy_setopt(curl, CURLOPT_UPLOAD, 1L);
    curl_easy_setopt(curl, CURLOPT_INFILESIZE, -1L);
    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
      std::cerr << "Error: " << curl_easy_strerror(res) << std::endl;
    }
  }
  curl_easy_cleanup(curl);

  // Parse JSON data from uploaded file
  Json::Value root;
  std::ifstream ifs("uploaded.json");
  if (ifs.is_open()) {
    Json::Reader reader;
    if (!reader.parse(ifs, root)) {
      std::cerr << "Error: " << reader.getFormattedErrorMessages() << std::endl;
    }
  } else {
    std::cerr << "Error: unable to open uploaded file" << std::endl;
  }

  // Extract numerical values from specific field and store in vector
  std::vector<int> values;
  for (const auto& obj : root) {
    if (obj.isMember("specific_field")) {
      values.push_back(obj["specific_field"].asInt());
    }
  }

  // Find largest numerical value using helper function
  int largest = findLargestValue(values);

  return std::to_string(largest);
}

int findLargestValue(const std::vector<int>& values) {
  if (values.empty()) {
    return -1;
  }
  int largest = values[0];
  for (const auto& value : values) {
    if (value > largest) {
      largest = value;
    }
  }
  return largest;
}
