// Define the function to dynamically manage the list of NFAPI_RRC_MSG_T structures
void manageNfapiRrcMsgList(int numRrcMsgs, int numLtePhyTestConfigs) {
    // Allocate memory for the RRC message list
    NFAPI_RRC_MSG_T* rrcMsgList = (NFAPI_RRC_MSG_T*)malloc(numRrcMsgs * sizeof(NFAPI_RRC_MSG_T));
    if (!rrcMsgList) {
        // Handle allocation failure
        printf("Error: Failed to allocate memory for RRC message list\n");
        return;
    }

    // Allocate memory for the LTE PHY test configuration list
    LTE_PHY_TEST_CONFIG* ltePhyTestConfigList = (LTE_PHY_TEST_CONFIG*)malloc(numLtePhyTestConfigs * sizeof(LTE_PHY_TEST_CONFIG));
    if (!ltePhyTestConfigList) {
        // Handle allocation failure
        printf("Error: Failed to allocate memory for LTE PHY test configuration list\n");
        free(rrcMsgList);
        return;
    }

    // Initialize the RRC message list and LTE PHY test configuration list
    for (int i = 0; i < numRrcMsgs; i++) {
        rrcMsgList[i].macHeader = NULL;
        rrcMsgList[i].payload = NULL;
        rrcMsgList[i].metadata = 0;
    }
    for (int j = 0; j < numLtePhyTestConfigs; j++) {
        ltePhyTestConfigList[j].phyTestParameterId = 0;
        ltePhyTestConfigList[j].testMode = 0;
        ltePhyTestConfigList[j].physicalLayerStatus = 0;
    }

    // Create a thread-safe mutex for protecting the lists from simultaneous access
    pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;

    // Create a Tokio task to monitor the RRC message list and log messages
    tokio_task_t* rrcMsgTask = tokio_create_task(NULL, NULL);
    if (!rrcMsgTask) {
        printf("Error: Failed to create Tokio task for RRC message list\n");
        free(rrcMsgList);
        free(ltePhyTestConfigList);
        pthread_mutex_destroy(&listMutex);
        return;
    }

    // Create a Tokio task to monitor the LTE PHY test configuration list and log messages
    tokio_task_t* ltePhyTestConfigTask = tokio_create_task(NULL, NULL);
    if (!ltePhyTestConfigTask) {
        printf("Error: Failed to create Tokio task for LTE PHY test configuration list\n");
        free(rrcMsgList);
        free(ltePhyTestConfigList);
        pthread_mutex_destroy(&listMutex);
        tokio_destroy_task(rrcMsgTask);
        return;
    }

    // Define the Tokio task function for monitoring the RRC message list and logging messages
    void rrcMsgTaskFunction(void* arg) {
        while (1) {
            pthread_mutex_lock(&listMutex);
            if (!rrcMsgList[0].macHeader) {
                // Wait for a new RRC message to be added to the list
                pthread_cond_wait(&listMutex, NULL);
            }
            // Log the creation of an element in the RRC message list
            printf("RRC message list: Created element %d\n", rrcMsgList[0].metadata);
            // Remove the first element from the list and log its metadata
            NFAPI_RRC_MSG_T temp = rrcMsgList[0];
            memmove(&rrcMsgList[0], &rrcMsgList[1], (numRrcMsgs - 1) * sizeof(NFAPI_RRC_MSG_T));
            free(temp.macHeader);
            free(temp.payload);
            temp.metadata = 0;
            pthread_mutex_unlock(&listMutex);
        }
    }

    // Define the Tokio task function for monitoring the LTE PHY test configuration list and logging messages
    void ltePhyTestConfigTaskFunction(void* arg) {
        while (1) {
            pthread_mutex_lock(&listMutex);
            if (!ltePhyTestConfigList[0].phyTestParameterId) {
                // Wait for a new LTE PHY test configuration to be added to the list
                pthread_cond_wait(&listMutex, NULL);
            }
            // Log the creation of an element in the LTE PHY test configuration list
            printf("LTE PHY test configuration list: Created element %d\n", ltePhyTestConfigList[0].metadata);
            // Remove the first element from the list and log its metadata
            LTE_PHY_TEST_CONFIG temp = ltePhyTestConfigList[0];
            memmove(&ltePhyTestConfigList[0], &ltePhyTestConfigList[1], (numLtePhyTestConfigs - 1) * sizeof(LTE_PHY_TEST_CONFIG));
            temp.phyTestParameterId = 0;
            temp.testMode = 0;
            temp.physicalLayerStatus = 0;
            pthread_mutex_unlock(&listMutex);
        }
    }

    // Start the Tokio tasks for monitoring the RRC message list and LTE PHY test configuration list
    tokio_start_task(rrcMsgTask, rrcMsgTaskFunction, NULL);
    tokio_start_task(ltePhyTestConfigTask, ltePhyTestConfigTaskFunction, NULL);
}
