            printf("Error: Failed to allocate memory for logging events for test configuration %d\n", i + 1);
        } else {
            printf("Test configuration %d successfully created with %d logging events\n", i + 1, num_elements);
        }
    }

    // Return the array of CELLULAR_TEST_CONFIG structures
    return configs;
}

// Function to release all allocated memory upon completion
void destroy_test_configs(CELLULAR_TEST_CONFIG* configs, int num_elements) {
    if (configs == NULL) {
        return;
    }
    for (int i = 0; i < num_elements; i++) {
        custom_free(configs[i].logging_events);
