    fclose(input_file);
    fclose(output_file);
}

// Define the function to apply transformation rules to a structure
LTE_PHY_TEST_CONFIG *apply_transformation_rules(LTE_PHY_TEST_CONFIG *config, char *transformation_rule) {
    // Parse the transformation rule and extract the parameters
    int num_parameters = 0;
    char **parameters = parse_transformation_rule(transformation_rule, &num_parameters);
    if (parameters == NULL) {
        printf("Error: Failed to parse the transformation rule\n");
        return NULL;
    }

    // Apply the transformation rules to the structure
    for (int i = 0; i < num_parameters; i++) {
        char *parameter = parameters[i];
        if (strcmp(parameter, "PHY_TEST_PARAMETER_ID") == 0) {
            config->PHY_TEST_PARAMETER_ID = atoi(parameters[++i]);
        } else if (strcmp(parameter, "TEST_MODE") == 0) {
            config->TEST_MODE = atoi(parameters[++i]);
        } else if (strcmp(parameter, "PHYSICAL_LAYER_STATUS") == 0) {
            config->PHYSICAL_LAYER_STATUS = atoi(parameters[++i]);
        } else {
            printf("Error: Unknown parameter %s\n", parameter);
            return NULL;
        }
    }

    // Release the memory allocated for the parameters
    for (int i = 0; i < num_parameters; i++) {
        free(parameters[i]);
    }
    free(parameters);

    // Return the processed structure
    return config;
}

// Define the function to parse a transformation rule and extract the parameters
char **parse_transformation_rule(char *transformation_rule, int *num_parameters) {
    // Tokenize the transformation rule using spaces as delimiters
    char **tokens = strtok(transformation_rule, " ");
    if (tokens == NULL) {
        printf("Error: Failed to tokenize the transformation rule\n");
        return NULL;
    }

    // Count the number of parameters in the transformation rule
    int num_tokens = 0;
    while (tokens[num_tokens] != NULL) {
        num_tokens++;
    }

    // Allocate memory for the parameters and copy them from the tokens
    char **parameters = malloc(sizeof(char *) * num_tokens);
    if (parameters == NULL) {
        printf("Error: Failed to allocate memory for the parameters\n");
        return NULL;
    }
    for (int i = 0; i < num_tokens; i++) {
        char *token = tokens[i];
        int token_length = strlen(token);
        parameters[i] = malloc(sizeof(char) * (token_length + 1));
        if (parameters[i] == NULL) {
            printf("Error: Failed to allocate memory for the %dth parameter\n", i);
            return NULL;
        }
        strcpy(parameters[i], token);
    }

    // Release the memory allocated for the tokens
    free(tokens);

    // Return the parameters and the number of parameters
    *num_parameters = num_tokens;
    return parameters;
}
