LTE_PHY_TEST_CONFIG* allocate_phy_test_config(int num_elements) {
    // Allocate memory for the array of LTE_PHY_TEST_CONFIG structures
    LTE_PHY_TEST_CONFIG* phy_test_config = (LTE_PHY_TEST_CONFIG*)malloc(num_elements * sizeof(LTE_PHY_TEST_CONFIG));
    if (!phy_test_config) {
        // Handle memory allocation failure
        printf("Error: Failed to allocate memory for phy_test_config\n");
        return NULL;
    }

    // Initialize each element in the array with valid values
    for (int i = 0; i < num_elements; i++) {
        phy_test_config[i].phy_test_parameter_id = i + 1;
        phy_test_config[i].test_mode = i % 2 == 0 ? 1 : 2;
        phy_test_config[i].physical_layer_status = i % 3 == 0 ? 1 : 2;
    }

    return phy_test_config;
}

