// Define the function to parse a binary configuration file and generate an output file
void parse_binary_config(char* input_file, char* output_file, char* transformation_rules, int num_elements, bool logging) {
    // Open the input file in binary mode
    FILE* input = fopen(input_file, "rb");
    if (!input) {
        printf("Error: Failed to open input file %s\n", input_file);
        return;
    }

    // Allocate memory for the array of LTE_PHY_TEST_CONFIG structures
    LTE_PHY_TEST_CONFIG* phy_test_config = allocate_phy_test_config(num_elements);
    if (!phy_test_config) {
        printf("Error: Failed to allocate memory for phy_test_config\n");
        fclose(input);
        return;
    }

    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu = allocate_crc_indication_pdu(num_elements);
    if (!crc_indication_pdu) {
        printf("Error: Failed to allocate memory for crc_indication_pdu\n");
        free_memory(phy_test_config, NULL);
        fclose(input);
        return;
    }

    // Initialize variables for tracking the number of elements successfully created and any errors encountered during allocation
    int num_elements_created = 0;
    int error_count = 0;

    // Read the input file in chunks and process each chunk using the transformation rules
    while (!feof(input)) {
        // Allocate memory for the current chunk of data
        char* chunk = (char*)malloc(CHUNK_SIZE);
        if (!chunk) {
            printf("Error: Failed to allocate memory for chunk\n");
            error_count++;
            continue;
        }

        // Read the next CHUNK_SIZE bytes from the input file into the current chunk
        size_t num_bytes = fread(chunk, 1, CHUNK_SIZE, input);
        if (num_bytes == 0) {
            printf("Error: Failed to read data from input file\n");
            error_count++;
            continue;
        }

        // Process the current chunk using the transformation rules
        for (int i = 0; i < num_elements; i++) {
            // Apply the transformation rules to each element in the chunk
            phy_test_config[i].phy_test_parameter_id = apply_transformation(chunk, i);
            crc_indication_pdu[i].rx_ue_information_tag = apply_transformation(chunk, i + 1);
            crc_indication_pdu[i].rnti = apply_transformation(chunk, i + 2);
            crc_indication_pdu[i].crc_indication_rel8_tag = apply_transformation(chunk, i + 3);
        }

        // Increment the number of elements successfully created
        num_elements_created += num_bytes / sizeof(LTE_PHY_TEST_CONFIG);
    }

    // Close the input file
    fclose(input);

    // Log any errors encountered during allocation and release memory for the arrays
    if (error_count > 0) {
        printf("Error: %d errors encountered during allocation\n", error_count);
        free_memory(phy_test_config, crc_indication_pdu);
        return;
    }

    // Open the output file in binary mode for writing
    FILE* output = fopen(output_file, "wb");
    if (!output) {
        printf("Error: Failed to open output file %s\n", output_file);
        free_memory(phy_test_config, crc_indication_pdu);
        return;
    }

    // Write the array of LTE_PHY_TEST_CONFIG structures to the output file
    fwrite(phy_test_config, sizeof(LTE_PHY_TEST_CONFIG), num_elements, output);

    // Write the array of NFAPI_CRC_INDICATION_PDU_T structures to the output file
    fwrite(crc_indication_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), num_elements, output);

    // Close the output file
    fclose(output);

    // Log the number of elements successfully created and any errors encountered during allocation
    printf("Created %d elements successfully\n", num_elements_created);
    if (error_count > 0) {
        printf("Error: %d errors encountered during allocation\n", error_count);
    }
}

