#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/ssl.h>
#include <openssl/err.h>

// Define the maximum number of active connections
#define MAX_CONNECTIONS 512

// Define the hard limit for the number of active connections
#define HARD_LIMIT 1024

// Define the initial pool size for new connections
#define INITIAL_POOL_SIZE 8

// Define the idle timeout for connections in seconds
#define IDLE_TIMEOUT 300

// Define the log settings for the system
#define LOG_FILE "tcp_connection_pool.log"
#define LOG_LEVEL LOG_INFO

// Define the error codes for the system
#define ERROR_CONNECTION_ESTABLISHED 1001
#define ERROR_CONNECTION_TERMINATED 1002
#define ERROR_CONNECTION_IDLE_TIMEOUT 1003
#define ERROR_CRYPTOGRAPHIC_FAILURE 1004

// Define the connection pool structure
typedef struct {
    int size; // The current number of active connections
    int max_size; // The maximum number of active connections
    int hard_limit; // The hard limit for the number of active connections
    int idle_timeout; // The idle timeout for connections in seconds
    SSL_CTX* ssl_ctx; // The OpenSSL context for secure communication
    SSL** ssl_connections; // An array of SSL connections
} connection_pool;

// Define the function to manage the pool of TCP connections
void tcp_connection_pool(int argc, char** argv) {
    // Initialize the connection pool with the initial pool size and hard limit
    connection_pool* pool = (connection_pool*) malloc(sizeof(connection_pool));
    pool->size = INITIAL_POOL_SIZE;
    pool->max_size = MAX_CONNECTIONS;
    pool->hard_limit = HARD_LIMIT;
    pool->idle_timeout = IDLE_TIMEOUT;
    pool->ssl_ctx = SSL_CTX_new(TLSv1_2_client_method());
    pool->ssl_connections = (SSL**) malloc(sizeof(SSL*) * INITIAL_POOL_SIZE);

    // Initialize the OpenSSL context for secure communication
    SSL_CTX_set_options(pool->ssl_ctx, SSL_OP_NO_TLSv1 | SSL_OP_NO_TLSv1_1 | SSL_OP_NO_COMPRESSION);
    SSL_CTX_set_cipher_list(pool->ssl_ctx, "HIGH:!aNULL:!eNULL:!EXPORT:!DES:!RC4:!MD5:!PSK:!SRP:!CAMELLIA");

    // Initialize the connection pool with the initial number of connections
    for (int i = 0; i < INITIAL_POOL_SIZE; i++) {
        SSL* ssl = SSL_new(pool->ssl_ctx);
        SSL_set_fd(ssl, socket());
        SSL_connect(ssl);
        pool->ssl_connections[i] = ssl;
    }

    // Start the connection pool monitoring thread
    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, tcp_connection_pool_monitor, (void*) pool);

    // Start the connection pool handling thread
    pthread_t handle_thread;
    pthread_create(&handle_thread, NULL, tcp_connection_pool_handle, (void*) pool);

    // Wait for the monitor and handle threads to finish
    pthread_join(monitor_thread, NULL);
    pthread_join(handle_thread, NULL);
}

// Define the function to monitor the connection pool
void* tcp_connection_pool_monitor(void* arg) {
    // Cast the argument to a connection pool structure
    connection_pool* pool = (connection_pool*) arg;

    // Loop indefinitely, monitoring the connection pool for errors and idle timeouts
    while (1) {
        // Check if any connections have failed due to cryptographic failures
        for (int i = 0; i < pool->size; i++) {
            SSL* ssl = pool->ssl_connections[i];
            int error = SSL_get_error(ssl, 0);
            if (error == SSL_ERROR_SYSCALL) {
                // Handle the connection failure due to a cryptographic failure
                log_error("Connection failed due to a cryptographic failure");
                tcp_connection_pool_handle_failure(pool, i);
            } else if (error == SSL_ERROR_WANT_READ || error == SSL_ERROR_WANT_WRITE) {
                // Handle the connection failure due to an idle timeout
                log_info("Connection failed due to an idle timeout");
                tcp_connection_pool_handle_failure(pool, i);
            }
        }

        // Check if any connections have exceeded the hard limit
        for (int i = 0; i < pool->size; i++) {
            SSL* ssl = pool->ssl_connections[i];
            if (SSL_get_fd(ssl) > pool->hard_limit) {
                // Handle the connection failure due to exceeding the hard limit
                log_error("Connection failed due to exceeding the hard limit");
                tcp_connection_pool_handle_failure(pool, i);
            }
        }

        // Sleep for a short period of time before checking again
        sleep(10);
    }
}

// Define the function to handle connection failures
void tcp_connection_pool_handle_failure(connection_pool* pool, int index) {
    // Close the failed connection and remove it from the pool
    SSL* ssl = pool->ssl_connections[index];
    SSL_free(ssl);
    memmove(&pool->ssl_connections[index], &pool->ssl_connections[index + 1], sizeof(SSL*) * (pool->size - index - 1));
    pool->size--;

    // Create a new connection and add it to the pool
    SSL* ssl = SSL_new(pool->ssl_ctx);
    SSL_set_fd(ssl, socket());
    SSL_connect(ssl);
    pool->ssl_connections[index] = ssl;
}

// Define the function to handle incoming connections
void tcp_connection_pool_handle(void* arg) {
    // Cast the argument to a connection pool structure
    connection_pool* pool = (connection_pool*) arg;

    // Loop indefinitely, handling incoming connections and sending data over the connections
    while (1) {
        // Accept an incoming connection
        int client_fd = accept(socket(), NULL, NULL);
        if (client_fd < 0) {
            log_error("Failed to accept incoming connection");
            continue;
        }

        // Create a new SSL object for the incoming connection
        SSL* ssl = SSL_new(pool->ssl_ctx);
        SSL_set_fd(ssl, client_fd);

        // Check if there are any available connections in the pool
        int index = -1;
        for (int i = 0; i < pool->size; i++) {
            if (pool->ssl_connections[i] == NULL) {
                index = i;
                break;
            }
        }

        // If there are no available connections, create a new one and add it to the pool
        if (index < 0) {
            SSL* ssl = SSL_new(pool->ssl_ctx);
            SSL_set_fd(ssl, socket());
            pool->size++;
            index = pool->size - 1;
        }

        // Set the SSL object for the incoming connection and send data over it
        pool->ssl_connections[index] = ssl;
        while (1) {
            char buffer[BUFSIZ];
            int bytes_read = SSL_read(ssl, buffer, BUFSIZ);
            if (bytes_read < 0) {
                log_error("Failed to read data from the connection");
                break;
            } else if (bytes_read == 0) {
                // Handle the connection termination
                log_info("Connection terminated");
                tcp_connection_pool_handle_failure(pool, index);
                break;
            }
            SSL_write(ssl, buffer, bytes_read);
        }
    }
}

// Define the function to handle outgoing connections
void tcp_connection_pool_send(connection_pool* pool, char* data) {
    // Loop over all active connections in the pool and send the data over each one
    for (int i = 0; i < pool->size; i++) {
        SSL* ssl = pool->ssl_connections[i];
        if (SSL_write(ssl, data, strlen(data)) < 0) {
            log_error("Failed to send data over the connection");
        }
    }
}

// Define the function to handle incoming data
void tcp_connection_pool_receive(connection_pool* pool, char* buffer, int size) {
    // Loop over all active connections in the pool and receive data from each one
    for (int i = 0; i < pool->size; i++) {
        SSL* ssl = pool->ssl_connections[i];
        if (SSL_read(ssl, buffer, size) < 0) {
            log_error("Failed to receive data from the connection");
        }
    }
}
