// Define the minimum and maximum payload sizes
#define MIN_PAYLOAD_SIZE 10
#define MAX_PAYLOAD_SIZE 100

// Define the function to allocate memory for the dynamic array
LTE_PHY_TXDU* allocate_memory(int num_elements) {
    // Check if the number of elements is valid
    if (num_elements <= 0 || num_elements > N) {
        return NULL;
    }

    // Allocate memory for the array
    LTE_PHY_TXDU* array = malloc(sizeof(LTE_PHY_TXDU) * num_elements);
    if (array == NULL) {
        return NULL;
    }

    // Initialize each element in the array with a unique ID and random payload size
    for (int i = 0; i < num_elements; i++) {
        array[i].TXDU_ID = i + 1;
        int payload_size = MIN_PAYLOAD_SIZE + rand() % (MAX_PAYLOAD_SIZE - MIN_PAYLOAD_SIZE);
        array[i].TXDU_PAYLOAD = malloc(payload_size);
        if (array[i].TXDU_PAYLOAD == NULL) {
            return NULL;
        }
    }

    // Return the allocated memory
    return array;
}

// Define the function to deallocate memory for the dynamic array
void deallocate_memory(LTE_PHY_TXDU* array, int num_elements) {
    // Check if the number of elements is valid
    if (num_elements <= 0 || num_elements > N) {
        return;
    }

    // Deallocate memory for each element in the array
    for (int i = 0; i < num_elements; i++) {
        free(array[i].TXDU_PAYLOAD);
    }

    // Deallocate memory for the array itself
    free(array);
}

// Define the function to handle potential overflows gracefully
void handle_overflow(int num_elements) {
    if (num_elements > N) {
        printf("Error: Number of elements exceeds maximum allowed value.\n");
    }
}

// Define the function to track the number of successfully allocated elements
int get_num_allocated_elements() {
    return num_elements;
}
