Here is an example implementation of a C function that manages a dynamic pool of `LTE_RRC_UE_CONTEXT` structures, supporting up to 50,000 concurrent radio network transactions:
```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

// Define the structure for a LTE_RRC_UE_CONTEXT
typedef struct {
    int RRC_UE_ID;
    int CELL_ID;
    char *NAS_MESSAGE;
} LTE_RRC_UE_CONTEXT;

// Define the pool of LTE_RRC_UE_CONTEXT structures
static LTE_RRC_UE_CONTEXT *pool = NULL;

// Define the mutex for protecting access to the pool
static pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the semaphore for signaling when a new context is available
static sem_t new_context_sem;

// Function to allocate a new LTE_RRC_UE_CONTEXT structure
LTE_RRC_UE_CONTEXT *allocate_context(int RRC_UE_ID, int CELL_ID) {
    // Lock the mutex to protect access to the pool
    pthread_mutex_lock(&pool_mutex);

    // Check if there is a free context in the pool
    for (int i = 0; i < MAX_CONTEXT_COUNT; i++) {
        if (pool[i].RRC_UE_ID == -1) {
            // Found a free context, allocate it and return it
            pool[i].RRC_UE_ID = RRC_UE_ID;
            pool[i].CELL_ID = CELL_ID;
            pool[i].NAS_MESSAGE = NULL;
            pthread_mutex_unlock(&pool_mutex);
            return &pool[i];
        }
    }

    // No free contexts found, allocate a new one and add it to the pool
    LTE_RRC_UE_CONTEXT *new_context = malloc(sizeof(LTE_RRC_UE_CONTEXT));
    if (new_context == NULL) {
        pthread_mutex_unlock(&pool_mutex);
        return NULL;
    }
    new_context->RRC_UE_ID = RRC_UE_ID;
    new_context->CELL_ID = CELL_ID;
    new_context->NAS_MESSAGE = NULL;
    pool[MAX_CONTEXT_COUNT++] = *new_context;
    pthread_mutex_unlock(&pool_mutex);
    return new_context;
}

// Function to free a LTE_RRC_UE_CONTEXT structure
void free_context(LTE_RRC_UE_CONTEXT *context) {
    // Lock the mutex to protect access to the pool
    pthread_mutex_lock(&pool_mutex);

    // Find the context in the pool and mark it as free
    for (int i = 0; i < MAX_CONTEXT_COUNT; i++) {
        if (&pool[i] == context) {
            pool[i].RRC_UE_ID = -1;
            pool[i].CELL_ID = -1;
            pool[i].NAS_MESSAGE = NULL;
            pthread_mutex_unlock(&pool_mutex);
            return;
        }
    }

    // Context not found, free it and remove it from the pool
    free(context);
    for (int i = 0; i < MAX_CONTEXT_COUNT; i++) {
        if (&pool[i] == context) {
            pool[i].RRC_UE_ID = -1;
            pool[i].CELL_ID = -1;
            pool[i].NAS_MESSAGE = NULL;
            pthread_mutex_unlock(&pool_mutex);
            return;
        }
    }
}

// Function to handle a new transaction
void handle_transaction(int RRC_UE_ID, int CELL_ID) {
    // Allocate a new context for the transaction
    LTE_RRC_UE_CONTEXT *context = allocate_context(RRC_UE_ID, CELL_ID);
    if (context == NULL) {
        // No free contexts found, wait for one to become available
        sem_wait(&new_context_sem);
        context = allocate_context(RRC_UE_ID, CELL_ID);
        if (context == NULL) {
            // Still no free contexts found, return an error
            printf("Error: No free contexts available\n");
            return;
        }
    }

    // Handle the transaction using the allocated context
    // ...

    // Free the context when it is no longer needed
    free_context(context);
}
