        structures[i].rachConfigDlsch.rach_flag = rand_r(&seed) % 2;
    }

    return structures;
}

// Define the function to generate a new configuration ID based on an existing one
char* generateNewConfigurationID(const char* configID, int N, unsigned int seed) {
    // Calculate the length of the new configuration ID
    size_t newConfigIDLen = strlen(configID) + 16;

    // Allocate memory for the new configuration ID
    char* newConfigID = malloc(newConfigIDLen);

    // Check if memory allocation failed
    if (newConfigID == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Generate a random hexadecimal string for the new configuration ID
    srand_r(&seed, time(NULL));
    char* randHexStr = malloc(16);
    for (int i = 0; i < 16; i++) {
        randHexStr[i] = "0123456789abcdef"[rand_r(&seed) % 16];
    }

    // Concatenate the random hexadecimal string with the existing configuration ID
    strcpy(newConfigID, configID);
    strcat(newConfigID, randHexStr);

    return newConfigID;
}

// Define the function to validate the uniqueness of a configuration ID within a specified network configuration directory
int isConfigurationIDUnique(const char* configID, const char* dirPath) {
    // Open the network configuration directory
    DIR* dir = opendir(dirPath);

    // Check if the directory could not be opened
    if (dir == NULL) {
        fprintf(stderr, "Could not open directory %s\n", dirPath);
        return 0;
    }

    // Read each file in the directory and check if the configuration ID is unique
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        char* fileName = entry->d_name;
        if (strcmp(fileName, ".") == 0 || strcmp(fileName, "..") == 0) {
            continue;
        }

        // Open the file and read its contents
        FILE* file = fopen(fileName, "r");
        if (file == NULL) {
            fprintf(stderr, "Could not open file %s\n", fileName);
            return 0;
        }

        char line[128];
        while (fgets(line, sizeof(line), file) != NULL) {
            if (strcmp(configID, line) == 0) {
                fclose(file);
                closedir(dir);
                return 0;
            }
        }

        fclose(file);
    }

    // Close the directory and return success
    closedir(dir);
    return 1;
}

// Define the function to generate a unique configuration ID within a specified network configuration directory
char* generateUniqueConfigurationID(const char* dirPath, int N, unsigned int seed) {
    // Generate a new configuration ID based on an existing one
    char* configID = generateNewConfigurationID("config", N, seed);

    // Check if the generated configuration ID is unique within the directory
    while (!isConfigurationIDUnique(configID, dirPath)) {
        // If not unique, modify the ID slightly and try again
        configID[strlen(configID) - 1]++;
    }

    return configID;
}

// Define the function to perform a specific operation based on a given command line option using the OpenSSL library
void* performOperationUsingOpenSSL(const char* cmdLineOption, void* data) {
    // Check if the command line option is valid
    if (strcmp(cmdLineOption, "encrypt") == 0) {
        // Encrypt the data using the OpenSSL library
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL);
        int len = EVP_EncryptUpdate(ctx, data, strlen((char*)data));
        EVP_EncryptFinal_ex(ctx, data + len, &len);
        EVP_CIPHER_CTX_free(ctx);
    } else if (strcmp(cmdLineOption, "decrypt") == 0) {
        // Decrypt the data using the OpenSSL library
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL);
        int len = EVP_DecryptUpdate(ctx, data, strlen((char*)data));
        EVP_DecryptFinal_ex(ctx, data + len, &len);
        EVP_CIPHER_CTX_free(ctx);
    } else {
        // If the command line option is not valid, print an error message and return NULL
        fprintf(stderr, "Invalid command line option %s\n", cmdLineOption);
        return NULL;
    }

    return data;
}
