char* generate_unique_filename(const char* original_filename, const char* filetype) {
    // Calculate the maximum length of the new filename
    int max_length = 256 - strlen(filetype);

    // Initialize a buffer for the new filename
    char* new_filename = malloc(max_length + 1);
    if (!new_filename) {
        fprintf(stderr, "Error: Failed to allocate memory for new filename\n");
        return NULL;
    }

    // Copy the original filename into the buffer
    strcpy(new_filename, original_filename);

    // Replace the file extension with a random sequence of uppercase letters
    char* ext = strrchr(new_filename, '.');
    if (ext) {
        *ext = '\0';
        int len = strlen(new_filename);
        for (int i = 0; i < len; i++) {
            new_filename[i] = toupper(new_filename[i]);
        }
    } else {
        fprintf(stderr, "Error: Failed to find file extension in original filename\n");
        free(new_filename);
        return NULL;
    }

    // Append the new file type to the end of the filename
    strcat(new_filename, filetype);

    // Check if the resulting filename is unique within the specified directory
    char* dir = "."; // Replace with the desired directory path
    DIR* dp = opendir(dir);
    if (!dp) {
        fprintf(stderr, "Error: Failed to open directory %s\n", dir);
        free(new_filename);
        return NULL;
    }
    struct dirent* de;
    while ((de = readdir(dp)) != NULL) {
        if (strcmp(de->d_name, new_filename) == 0) {
            // If the filename is not unique, try again with a modified extension
            char* ext2 = strrchr(new_filename, '.');
            *ext2 = '\0';
            int len = strlen(new_filename);
            for (int i = 0; i < len; i++) {
                new_filename[i] = toupper(new_filename[i]);
            }
            strcat(new_filename, filetype);
        } else {
            break;
        }
    }
    closedir(dp);

    return new_filename;
}

// Function to dynamically allocate memory for a list of TCP connection information structures
TCP_CONNECTION_INFO* allocate_tcp_connection_info(int n, int seed) {
    // Calculate the size of the structure array
    size_t struct_size = sizeof(TCP_CONNECTION_INFO) * n;

    // Allocate memory for the structure array
    TCP_CONNECTION_INFO* tcp_connection_info = malloc(struct_size);
    if (!tcp_connection_info) {
        fprintf(stderr, "Error: Failed to allocate memory for TCP connection information\n");
        return NULL;
    }

    // Initialize the structure array with random values
    srand(seed);
    for (int i = 0; i < n; i++) {
        tcp_connection_info[i].ip_address[0] = '\0';
        tcp_connection_info[i].port_number = rand() % 65536;
        tcp_connection_info[i].connection_state = rand() % 2;
        tcp_connection_info[i].timestamp = time(NULL);
    }

    return tcp_connection_info;
}

// Function to deallocate memory for a list of TCP connection information structures
void deallocate_tcp_connection_info(TCP_CONNECTION_INFO* tcp_connection_info) {
    free(tcp_connection_info);
}

int main() {
    // Define the number of structures and the seed for the random number generator
    int n = 10;
    int seed = time(NULL);

    // Allocate memory for the list of TCP connection information structures
    TCP_CONNECTION_INFO* tcp_connection_info = allocate_tcp_connection_info(n, seed);
    if (!tcp_connection_info) {
        fprintf(stderr, "Error: Failed to allocate memory for TCP connection information\n");
        return 1;
    }

    // Generate a unique filename based on an existing one
    char* original_filename = "example.txt";
    char* filetype = ".pdf";
    char* new_filename = generate_unique_filename(original_filename, filetype);
    if (!new_filename) {
        fprintf(stderr, "Error: Failed to generate unique filename\n");
        deallocate_tcp_connection_info(tcp_connection_info);
        return 1;
    }

    // Log a message to the error log if a given condition is met
    if (strlen(new_filename) > max_length) {
        char msg[256];
        snprintf(msg, sizeof(msg), "Error: Generated filename exceeds maximum length of %d characters\n", max_length);
        va_list args;
        va_start(args, msg);
        vfprintf(stderr, msg, args);
        va_end(args);
    }

    // Deallocate memory for the list of TCP connection information structures
    deallocate_tcp_connection_info(tcp_connection_info);

    return 0;
}
