// Function to manage a collection of network device contexts
class ContextManager {
private:
    std::mutex mutex_; // mutex for synchronizing access to the context map
    std::unordered_map<int, NetworkDeviceContext*> contextMap_; // map of context IDs to context structures
    MemoryPool memoryPool_; // memory pool for allocating and deallocating context structures
    int numContexts_; // number of network device contexts in the collection
    int maxNumContexts_; // maximum number of network device contexts allowed in the collection
    bool isRunning_; // flag indicating whether the manager is running
public:
    ContextManager(int maxNumContexts) {
        mutex_ = std::mutex();
        contextMap_ = std::unordered_map<int, NetworkDeviceContext*>();
        memoryPool_ = MemoryPool(MEMORY_POOL_SIZE);
        numContexts_ = 0;
        maxNumContexts_ = maxNumContexts;
        isRunning_ = true;
    }

    ~ContextManager() {
        stop();
    }

    // Start the context manager
    void start() {
        if (!isRunning_) {
            isRunning_ = true;
        }
    }

    // Stop the context manager
    void stop() {
        if (isRunning_) {
            isRunning_ = false;
        }
    }

    // Create a new network device context
    NetworkDeviceContext* createContext(const char* ipAddress, const char* username, const char* password) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (numContexts_ >= maxNumContexts_) {
            return NULL;
        }
        NetworkDeviceContext* ctx = createContext(ipAddress, username, password);
        contextMap_.insert({ctx->id, ctx});
        numContexts_++;
        return ctx;
    }

    // Delete a network device context
    void deleteContext(NetworkDeviceContext* ctx) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (ctx) {
            contextMap_.erase(ctx->id);
            numContexts_--;
            deleteContext(ctx);
        }
    }

    // Update a network device context
    void updateContext(NetworkDeviceContext* ctx, const char* ipAddress, const char* username, const char* password) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (ctx) {
            updateContext(ctx, ipAddress, username, password);
        }
    }

    // Connect a network device context
    void connectContext(NetworkDeviceContext* ctx) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (ctx) {
            connectContext(ctx);
        }
    }

    // Disconnect a network device context
    void disconnectContext(NetworkDeviceContext* ctx) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (ctx) {
            disconnectContext(ctx);
        }
    }

    // Get the error code of a network device context
    int getErrorCode(NetworkDeviceContext* ctx) {
        std::lock_guard<std::mutex> lock(mutex_);
        return getErrorCode(ctx);
    }

    // Set the error code of a network device context
    void setErrorCode(NetworkDeviceContext* ctx, int errorCode) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (ctx) {
            setErrorCode(ctx, errorCode);
        }
    }

    // Get the status indicator of a network device context
    bool getStatusIndicator(NetworkDeviceContext* ctx) {
        std::lock_guard<std::mutex> lock(mutex_);
        return getStatusIndicator(ctx);
    }

    // Set the status indicator of a network device context
    void setStatusIndicator(NetworkDeviceContext* ctx, bool statusIndicator) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (ctx) {
            setStatusIndicator(ctx, statusIndicator);
        }
    }
};
