// Define the list of NFAPI_RRC_MSG_T structures
NFAPI_RRC_MSG_T* rrcMsgList = NULL;
size_t rrcMsgCount = 0;
pthread_mutex_t rrcMutex = PTHREAD_MUTEX_INITIALIZER;

// Define the list of LTE_PHY_TEST_CONFIG structures
LTE_PHY_TEST_CONFIG* phyTestConfigList = NULL;
size_t phyTestConfigCount = 0;
pthread_mutex_t phyMutex = PTHREAD_MUTEX_INITIALIZER;

// Define the function to dynamically manage the lists
void manageLists(NFAPI_RRC_MSG_T* rrcMsg, LTE_PHY_TEST_CONFIG* phyTestConfig) {
    // Acquire the mutex for the RRC list
    pthread_mutex_lock(&rrcMutex);

    // Add the RRC message to the list
    if (rrcMsg != NULL) {
        rrcMsgList = realloc(rrcMsgList, sizeof(NFAPI_RRC_MSG_T) * (rrcMsgCount + 1));
        rrcMsgList[rrcMsgCount] = *rrcMsg;
        rrcMsgCount++;
    }

    // Release the mutex for the RRC list
    pthread_mutex_unlock(&rrcMutex);

    // Acquire the mutex for the PHY test config list
    pthread_mutex_lock(&phyMutex);

    // Add the PHY test configuration to the list
    if (phyTestConfig != NULL) {
        phyTestConfigList = realloc(phyTestConfigList, sizeof(LTE_PHY_TEST_CONFIG) * (phyTestConfigCount + 1));
        phyTestConfigList[phyTestConfigCount] = *phyTestConfig;
        phyTestConfigCount++;
    }

    // Release the mutex for the PHY test config list
    pthread_mutex_unlock(&phyMutex);
}

// Define the function to dynamically resize the RRC message list without reallocation
void resizeRrcMsgList(size_t newSize) {
    // Acquire the mutex for the RRC list
    pthread_mutex_lock(&rrcMutex);

    // Reallocate the memory for the RRC message list
    rrcMsgList = realloc(rrcMsgList, sizeof(NFAPI_RRC_MSG_T) * newSize);

    // Release the mutex for the RRC list
    pthread_mutex_unlock(&rrcMutex);
}

// Define the function to dynamically resize the PHY test configuration list without reallocation
void resizePhyTestConfigList(size_t newSize) {
    // Acquire the mutex for the PHY test config list
    pthread_mutex_lock(&phyMutex);

    // Reallocate the memory for the PHY test configuration list
    phyTestConfigList = realloc(phyTestConfigList, sizeof(LTE_PHY_TEST_CONFIG) * newSize);

    // Release the mutex for the PHY test config list
    pthread_mutex_unlock(&phyMutex);
}

// Define the function to monitor the lists for updates and log messages
void monitorLists() {
    // Acquire the mutex for the RRC list
    pthread_mutex_lock(&rrcMutex);

    // Monitor the RRC message list for updates
    if (rrcMsgCount > 0) {
        // Log the RRC messages
        printf("RRC Messages: ");
        for (size_t i = 0; i < rrcMsgCount; i++) {
            printf("%s ", rrcMsgList[i].macHeader);
        }
        printf("\n");
    }

    // Release the mutex for the RRC list
    pthread_mutex_unlock(&rrcMutex);

    // Acquire the mutex for the PHY test config list
    pthread_mutex_lock(&phyMutex);

    // Monitor the PHY test configuration list for updates
    if (phyTestConfigCount > 0) {
        // Log the PHY test configurations
        printf("PHY Test Configurations: ");
        for (size_t i = 0; i < phyTestConfigCount; i++) {
            printf("%d ", phyTestConfigList[i].phyTestParameterId);
        }
        printf("\n");
    }

    // Release the mutex for the PHY test config list
    pthread_mutex_unlock(&phyMutex);
}

// Define the function to pause and resume monitoring the lists
void pauseResumeMonitoring(int pause) {
    if (pause) {
        // Acquire the mutex for the RRC list
        pthread_mutex_lock(&rrcMutex);

        // Pause the RRC message list monitor
        rrcMsgCount = 0;

        // Release the mutex for the RRC list
        pthread_mutex_unlock(&rrcMutex);

        // Acquire the mutex for the PHY test config list
        pthread_mutex_lock(&phyMutex);

        // Pause the PHY test configuration list monitor
        phyTestConfigCount = 0;

        // Release the mutex for the PHY test config list
        pthread_mutex_unlock(&phyMutex);
    } else {
        // Acquire the mutex for the RRC list
        pthread_mutex_lock(&rrcMutex);

        // Resume the RRC message list monitor
        rrcMsgCount = 0;

        // Release the mutex for the RRC list
        pthread_mutex_unlock(&rrcMutex);

        // Acquire the mutex for the PHY test config list
        pthread_mutex_lock(&phyMutex);

        // Resume the PHY test configuration list monitor
        phyTestConfigCount = 0;

        // Release the mutex for the PHY test config list
        pthread_mutex_unlock(&phyMutex);
    }
}
