// Function to dynamically allocate memory for an array of nodes
node* create_nodes(int num_nodes) {
    node* nodes = malloc(num_nodes * sizeof(node));
    if (nodes == NULL) {
        printf("Error: Failed to allocate memory for nodes\n");
        return NULL;
    }

    // Initialize each node with a new data block
    for (int i = 0; i < num_nodes; i++) {
        nodes[i].data_block = malloc(sizeof(data_block));
        if (nodes[i].data_block == NULL) {
            printf("Error: Failed to allocate memory for data block\n");
            return NULL;
        }
    }

    // Initialize the next pointer of each node to NULL
    for (int i = 0; i < num_nodes; i++) {
        nodes[i].next = NULL;
    }

    return nodes;
}

// Function to traverse the linked list and print the integer and string values of each data block
void traverse_list(node* head) {
    node* current = head;
    while (current != NULL) {
        if (current->data_block == NULL) {
            printf("Error: Data block is null\n");
            return;
        }
        printf("%d, %s\n", current->integer, current->data_block->string);
        current = current->next;
    }
}

// Function to free the memory allocated for the nodes and data blocks
void free_nodes(node* head) {
    node* current = head;
    while (current != NULL) {
        if (current->data_block == NULL) {
            printf("Error: Data block is null\n");
            return;
        }
        free(current->data_block);
        current = current->next;
    }
}

// Function to insert a new node at the beginning of the linked list
void insert_node(node* head, int integer, char* string) {
    // Create a new data block with the given integer and string values
    data_block* new_data_block = malloc(sizeof(data_block));
    if (new_data_block == NULL) {
        printf("Error: Failed to allocate memory for new data block\n");
        return;
    }
    new_data_block->integer = integer;
    new_data_block->string = strdup(string);

    // Create a new node with the given data block and insert it at the beginning of the linked list
    node* new_node = malloc(sizeof(node));
    if (new_node == NULL) {
        printf("Error: Failed to allocate memory for new node\n");
        return;
    }
    new_node->data_block = new_data_block;
    new_node->next = head;
    head = new_node;
}

// Function to delete a node from the linked list based on its integer value
void delete_node(node* head, int integer) {
    // Find the node with the given integer value and remove it from the linked list
    node* current = head;
    while (current != NULL && current->integer != integer) {
        current = current->next;
    }
    if (current == NULL) {
        printf("Error: Node with integer %d not found\n", integer);
        return;
    }
    node* previous = head;
    while (previous->next != current) {
        previous = previous->next;
    }
    previous->next = current->next;
}
