transaction* create_transactions(int num_transactions, bool update_status) {
    // Check if the number of transactions is valid
    if (num_transactions <= 0) {
        return NULL;
    }

    // Allocate memory for the array of transactions
    transaction* transactions = malloc(sizeof(transaction) * num_transactions);
    if (!transactions) {
        printf("Error: Failed to allocate memory for transactions\n");
        return NULL;
    }

    // Initialize the status of each transaction to a default value
    for (int i = 0; i < num_transactions; i++) {
        strcpy(transactions[i].status, "pending");
    }

    // Update the status of some transactions based on probabilistic events
    if (update_status) {
        int num_completed = 0;
        int num_failed = 0;
        for (int i = 0; i < num_transactions; i++) {
            float random_value = ((float)rand() / RAND_MAX);
            if (random_value <= 0.5) {
                strcpy(transactions[i].status, "completed");
                num_completed++;
            } else {
                strcpy(transactions[i].status, "failed");
                num_failed++;
            }
        }
        printf("Updated %d transactions to completed and %d transactions to failed\n", num_completed, num_failed);
    }

    // Return the allocated array of transactions
    return transactions;
}

// Function to deallocate memory for an array of transactions
void destroy_transactions(transaction* transactions) {
    if (transactions) {
        free(transactions);
    }
}
