// Define the transaction structure
typedef struct {
    long timestamp;
    int transaction_id;
    float transaction_amount;
    char status[10];
} transaction;

// Define the function to dynamically allocate memory for an array of transactions
int allocate_transactions(transaction **transactions, size_t num_transactions) {
    // Check if the input is valid
    if (num_transactions == 0) {
        return -1;
    }

    // Allocate memory for the array of transactions
    *transactions = malloc(sizeof(transaction) * num_transactions);
    if (*transactions == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for transactions\n");
        return -1;
    }

    // Initialize the status of each transaction to a default value
    for (size_t i = 0; i < num_transactions; i++) {
        (*transactions)[i].status[0] = 'P';
        (*transactions)[i].status[1] = '\0';
    }

    // Simulate real-world transaction processing conditions by updating the status of some transactions to "completed" or "failed" probabilistically
    for (size_t i = 0; i < num_transactions; i++) {
        if (rand() % 100 < 5) { // Probability of updating a transaction status to "completed" is 5%
            strcpy((*transactions)[i].status, "completed");
        } else if (rand() % 100 < 20) { // Probability of updating a transaction status to "failed" is 20%
            strcpy((*transactions)[i].status, "failed");
        }
    }

    return 0;
}

// Define the function to dynamically generate a new filename based on an existing one
char *generate_new_filename(const char *filename) {
    // Check if the input is valid
    if (filename == NULL || strlen(filename) > 256) {
        return NULL;
    }

    // Allocate memory for the new filename
    size_t len = strlen(filename);
    char *new_filename = malloc(sizeof(char) * (len + 10));
    if (new_filename == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for new filename\n");
        return NULL;
    }

    // Copy the original filename and modify its extension with a sequence of random digits
    strcpy(new_filename, filename);
    int num_digits = 0;
    for (size_t i = len - 1; i >= 0 && num_digits < 5; i--) {
        if (isdigit(new_filename[i])) {
            new_filename[i] = '0' + rand() % 10;
            num_digits++;
        }
    }

    // Append a specific file type to the new filename
    strcat(new_filename, ".txt");

    return new_filename;
}

// Define the function to deallocate memory for an array of transactions
void deallocate_transactions(transaction **transactions) {
    // Check if the input is valid
    if (transactions == NULL || *transactions == NULL) {
        return;
    }

    // Deallocate memory for the array of transactions
    free(*transactions);
    *transactions = NULL;
}
