// Define the structure to hold the sensor data
typedef struct {
    long timestamp; // Timestamp of the measurement
    int sensor_id; // ID of the sensor that took the measurement
    float measurements[10]; // Array of 10 measurements for each sensor
} SENSOR_RECORD_T;

// Define the function to allocate and initialize the array of sensor records
void allocate_sensor_records(int array_size) {
    // Check if the input size is valid
    if (array_size < 1000 || array_size > 100000) {
        printf("Error: Invalid array size specified. Must be between 1000 and 100000.\n");
        return;
    }

    // Allocate the memory for the array of sensor records
    SENSOR_RECORD_T* records = (SENSOR_RECORD_T*)malloc(array_size * sizeof(SENSOR_RECORD_T));
    if (!records) {
        printf("Error: Failed to allocate memory for the array of sensor records.\n");
        return;
    }

    // Initialize the timestamp and sensor ID for each record
    for (int i = 0; i < array_size; i++) {
        records[i].timestamp = time(NULL);
        records[i].sensor_id = i + 1;
    }

    // Validate the measurement values against predefined thresholds based on sensor type
    for (int i = 0; i < array_size; i++) {
        // Check if the temperature measurement is within the realistic operating range
        if (records[i].measurements[0] > 50 || records[i].measurements[0] < -20) {
            printf("Error: Temperature measurement %f for sensor %d is outside of the realistic operating range.\n", records[i].measurements[0], records[i].sensor_id);
        }

        // Check if the humidity measurement is within the realistic operating range
        if (records[i].measurements[1] > 100 || records[i].measurements[1] < 0) {
            printf("Error: Humidity measurement %f for sensor %d is outside of the realistic operating range.\n", records[i].measurements[1], records[i].sensor_id);
        }
    }

    // Free the memory allocated for the array of sensor records
    free(records);
}
