    // Add a sequence of random hexadecimal digits to the end of the new configuration ID
    for (int i = 0; i < MAX_RETRIES; i++) {
        char random_hexadecimal_digit = rand() % 16;
        sprintf(new_configuration_id + existing_configuration_id_length, "%x", random_hexadecimal_digit);
    }

    // Append a specific identifier type to the end of the new configuration ID
    strcat(new_configuration_id, "_ID");

    return new_configuration_id;
}

// Function to validate the uniqueness of a configuration ID within a specified network configuration directory
int is_configuration_id_unique(char* configuration_id) {
    // Open the network configuration directory for reading
    DIR* dir = opendir(NETWORK_CONFIGURATION_DIRECTORY);

    // Check if the directory could not be opened
    if (!dir) {
        printf("Could not open network configuration directory\n");
        return 0;
    }

    // Read each file in the directory and compare the configuration ID with the existing ones
    struct dirent* entry = NULL;
    while ((entry = readdir(dir)) != NULL) {
        char* filename = entry->d_name;
        if (strcmp(filename, ".") == 0 || strcmp(filename, "..") == 0) continue;

        // Open the file for reading
        FILE* file = fopen(filename, "r");

        // Check if the file could not be opened
        if (!file) {
            printf("Could not open network configuration file\n");
            return 0;
        }

        // Read each line in the file and compare the configuration ID with the existing ones
        char* line = NULL;
        size_t len = 0;
        ssize_t read;
        while ((read = getline(&line, &len, file)) != -1) {
            if (strcmp(configuration_id, line) == 0) {
                // Close the file and return false if a duplicate configuration ID is found
                fclose(file);
                free(line);
                return 0;
            }
        }

        // Close the file and continue reading the next file in the directory
        fclose(file);
    }

    // Return true if no duplicate configuration ID was found
    closedir(dir);
    return 1;
}

