    // Initialize the mutex for protecting shared resources
    pthread_mutex_lock(&mutex);

    // Generate a new configuration ID based on the existing one
    char* new_configuration_id = generate_configuration_id(existing_configuration_id);

    // Check if the generated configuration ID is unique within the specified network configuration directory
    int is_unique = is_configuration_id_unique(new_configuration_id);

    // If the generated configuration ID is not unique, retry generating a new one with slight modifications until a unique name is found
    while (!is_unique) {
        // Modify the existing configuration ID with slight modifications and generate a new configuration ID based on it
        char* modified_existing_configuration_id = modify_existing_configuration_id(existing_configuration_id);
        new_configuration_id = generate_configuration_id(modified_existing_configuration_id);

        // Check if the generated configuration ID is unique within the specified network configuration directory
        is_unique = is_configuration_id_unique(new_configuration_id);
    }

    // Release the mutex for protecting shared resources
    pthread_mutex_unlock(&mutex);

    return new_configuration_id;
}

// Function to modify an existing configuration ID with slight modifications, generating a new configuration ID based on it
char* modify_existing_configuration_id(char* existing_configuration_id) {
