// Define the shared memory key and size
#define SHM_KEY 1234
#define SHM_SIZE 1024

// Define the mutex for synchronizing access to the shared memory
pthread_mutex_t shm_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the shared memory and create a new segment
void* init_shm(size_t size) {
  // Create a new shared memory segment with the specified size and key
  void* shm = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
  if (shm == MAP_FAILED) {
    perror("Error creating shared memory segment");
    exit(EXIT_FAILURE);
  }
  return shm;
}

// Function to write data to the shared memory
void write_shm(void* shm, char* data) {
  // Lock the mutex to prevent race conditions during concurrent access
  pthread_mutex_lock(&shm_mutex);

  // Write the data to the shared memory segment
  strcpy((char*)shm, data);

  // Unlock the mutex and return
  pthread_mutex_unlock(&shm_mutex);
}

// Function to read data from the shared memory
void* read_shm(void* shm) {
  // Lock the mutex to prevent race conditions during concurrent access
  pthread_mutex_lock(&shm_mutex);

  // Read the data from the shared memory segment
  char* data = (char*)shm;

  // Unlock the mutex and return
  pthread_mutex_unlock(&shm_mutex);
  return data;
}

// Function to clean up the shared memory segment
void cleanup_shm(void* shm) {
  // Lock the mutex to prevent race conditions during concurrent access
  pthread_mutex_lock(&shm_mutex);

  // Unmap the shared memory segment
  munmap(shm, SHM_SIZE);

  // Destroy the mutex
  pthread_mutex_destroy(&shm_mutex);
}

// Function to calculate the average of the last two fields for each line
void* calculate_average(char* line) {
  // Split the line into fields using a comma as the delimiter
  char* fields = strtok(line, ",");

  // Calculate the sum of the first two fields
  int sum = atoi(fields) + atoi(strtok(NULL, ","));

  // Calculate the average of the last two fields
  float average = (sum / 2.0);

  // Return the average as a string
  return malloc(16);
}

// Function to print the contents of the shared memory segment in a comma-separated format, including the computed averages as the last field
void print_shm(void* shm) {
  // Lock the mutex to prevent race conditions during concurrent access
  pthread_mutex_lock(&shm_mutex);

  // Read the data from the shared memory segment
  char* data = (char*)shm;

  // Split the data into lines using a newline as the delimiter
  char* lines = strtok(data, "\n");

  // Iterate over each line and calculate the average of the last two fields
  while (lines != NULL) {
    char* average = calculate_average(lines);
    printf("%s,%s\n", lines, average);
    free(average);
    lines = strtok(NULL, "\n");
  }

  // Unlock the mutex and return
  pthread_mutex_unlock(&shm_mutex);
}

int main() {
  // Initialize the shared memory segment with a specified size and key
  void* shm = init_shm(SHM_SIZE);

  // Read data from a text file line by line, dynamically allocate memory for each line, calculate the average of the last two fields for each line, and print the contents in a comma-separated format, including the computed averages as the last field
  FILE* fp = fopen("data.txt", "r");
  char* line = NULL;
  size_t len = 0;
  ssize_t read;

  while ((read = getline(&line, &len, fp)) != -1) {
    // Write the data to the shared memory segment
    write_shm(shm, line);

    // Read the data from the shared memory segment
    char* data = read_shm(shm);

    // Calculate the average of the last two fields for each line
    char* average = calculate_average(data);

    // Print the contents in a comma-separated format, including the computed averages as the last field
    printf("%s,%s\n", data, average);

    // Free the memory allocated for the current line
    free(line);
  }

  // Clean up the shared memory segment
  cleanup_shm(shm);

  return 0;
}
