// Function to initialize the shared memory segment with a specified size and key
void init_shm(int size, char *key) {
    // Create the shared memory segment
    shmid = shmget(key, size, IPC_CREAT | 0644);
    if (shmid < 0) {
        perror("Error creating shared memory segment");
        exit(1);
    }
}

// Function to write a list of floating-point numbers into the shared memory segment
void write_numbers(number_list_t *list) {
    // Lock the shared memory segment for writing
    sem_wait(&write_sem);

    // Write the list of numbers to the shared memory segment
    memcpy(shmaddr, list->numbers, list->size * sizeof(float));

    // Unlock the shared memory segment
    sem_post(&write_sem);
}

// Function to read a list of floating-point numbers from the shared memory segment
void read_numbers(number_list_t *list) {
    // Lock the shared memory segment for reading
    sem_wait(&read_sem);

    // Read the list of numbers from the shared memory segment
    memcpy(list->numbers, shmaddr, list->size * sizeof(float));

    // Unlock the shared memory segment
    sem_post(&read_sem);
}

// Function to calculate and print the average of all valid numbers stored in the shared memory segment
void calculate_average() {
    // Lock the shared memory segment for reading
    sem_wait(&read_sem);

    // Calculate the sum of all valid numbers
    float sum = 0;
    for (int i = 0; i < list.size; i++) {
        if (list.numbers[i] >= 0) {
            sum += list.numbers[i];
        }
    }

    // Calculate the average of all valid numbers
    float average = sum / list.size;

    // Print the average
    printf("Average: %f\n", average);

    // Unlock the shared memory segment
    sem_post(&read_sem);
}

// Main function to initialize, write, read, and calculate the average of a list of floating-point numbers in a shared memory segment
int main(int argc, char *argv[]) {
    // Initialize the shared memory segment with a specified size and key
    init_shm(MAX_SIZE, SHM_KEY);

    // Define the number list structure
    number_list_t list;
    list.numbers = malloc(MAX_SIZE * sizeof(float));
    list.size = 0;

    // Read the input from standard input or a specified file
