    while (token != NULL) {
        float num = atof(token);
        if (num >= 0) {
            list.numbers[list.size++] = num;
        } else {
            printf("Invalid input: %s\n", token);
        }
        token = strtok(NULL, " ");
    }

    // Write the list of numbers to the shared memory segment
    write_numbers(&list);

    // Read the list of numbers from the shared memory segment and validate each number for correctness
    read_numbers(&list);

    // Calculate and print the average of all valid numbers stored in the shared memory segment
    calculate_average();

    // Clean up the shared memory segment and free the memory allocated for the number list structure
    shmctl(shmid, IPC_RMID, NULL);
