#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <semaphore.h>
#include <pthread.h>
#include <errno.h>

// Define the semaphore structure
struct semaphore {
    int value;
    pthread_mutex_t mutex;
};

// Define the logging mechanism
void log(const char* message) {
    printf("%s\n", message);
}

// Create a new semaphore with the specified initial value
semaphore_t create_semaphore(int initial_value) {
    semaphore_t semaphore = malloc(sizeof(struct semaphore));
    if (semaphore == NULL) {
        log("Error: Failed to allocate memory for semaphore");
        return NULL;
    }
    semaphore->value = initial_value;
    pthread_mutex_init(&semaphore->mutex, NULL);
    return semaphore;
}

// Destroy a semaphore and release its resources
void destroy_semaphore(semaphore_t semaphore) {
    if (semaphore == NULL) {
        log("Error: Attempted to destroy null semaphore");
        return;
    }
    pthread_mutex_destroy(&semaphore->mutex);
    free(semaphore);
}

// Acquire a semaphore, blocking until it is available
void acquire_semaphore(semaphore_t semaphore) {
    if (semaphore == NULL) {
        log("Error: Attempted to acquire null semaphore");
        return;
    }
    pthread_mutex_lock(&semaphore->mutex);
    while (semaphore->value <= 0) {
        pthread_cond_wait(&semaphore->cond, &semaphore->mutex);
    }
    semaphore->value--;
}

// Release a semaphore, making it available for acquisition by other threads
void release_semaphore(semaphore_t semaphore) {
    if (semaphore == NULL) {
        log("Error: Attempted to release null semaphore");
        return;
    }
    pthread_mutex_lock(&semaphore->mutex);
    semaphore->value++;
    pthread_cond_signal(&semaphore->cond);
    pthread_mutex_unlock(&semaphore->mutex);
}

// Main function for the program
int main(void) {
    // Create a semaphore with an initial value of 1
    semaphore_t semaphore = create_semaphore(1);
    if (semaphore == NULL) {
        log("Error: Failed to create semaphore");
        return 1;
    }

    // Create a thread that acquires the semaphore and prints "Hello"
    pthread_t thread;
    int error = pthread_create(&thread, NULL, acquire_semaphore, (void*)semaphore);
    if (error != 0) {
        log("Error: Failed to create thread");
        return 1;
    }

    // Sleep for a short period of time to allow the thread to acquire the semaphore
    sleep(1);

    // Release the semaphore, making it available for other threads to acquire
    release_semaphore(semaphore);

    // Join the thread and destroy the semaphore
    pthread_join(thread, NULL);
    destroy_semaphore(semaphore);

    return 0;
}
```
This code creates a semaphore with an initial value of 1 using `create_semaphore` function. It then creates a thread that acquires the semaphore and prints "Hello" using `acquire_semaphore` function. The thread is created using `pthread_create` function.

The code also uses `pthread_join` function to join the thread with the main thread, and `destroy_semaphore` function to destroy the semaphore when it is no longer needed.

Note that this code assumes that the `sleep` function is available in the system. If the `sleep` function is not available, you can use a different method to delay the execution of the main thread for a short period of time.']

