    int size;
    UE_CONTEXT* entries[];
} ue_context_list = {0, NULL};

// Function to insert a new UE context into the list
int insert_ue_context(UE_CONTEXT* new_ue_context) {
    pthread_mutex_lock(&ue_context_list_lock);
    int index = ue_context_list.size++;
    ue_context_list.entries[index] = new_ue_context;
    pthread_mutex_unlock(&ue_context_list_lock);
    return 0;
}

// Function to remove a UE context from the list
int remove_ue_context(int ue_id) {
    pthread_mutex_lock(&ue_context_list_lock);
    for (int i = 0; i < ue_context_list.size; i++) {
        if (ue_context_list.entries[i]->ue_id == ue_id) {
            UE_CONTEXT* removed_ue_context = ue_context_list.entries[i];
            memmove(&ue_context_list.entries[i], &ue_context_list.entries[i+1], (ue_context_list.size - i - 1) * sizeof(UE_CONTEXT*));
            ue_context_list.size--;
            pthread_mutex_unlock(&ue_context_list_lock);
            free(removed_ue_context);
            return 0;
        }
    }
    pthread_mutex_unlock(&ue_context_list_lock);
    return -1; // UE context not found
}

// Function to update a UE context in the list
