char* generate_unique_filename(const char* filename, const char* filetype) {
    // Calculate the maximum length of the new filename
    size_t max_len = 256 - strlen(filetype);

    // Initialize a buffer for the new filename
    char *new_filename = malloc(max_len + 1);
    if (new_filename == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for new filename\n");
        return NULL;
    }

    // Copy the original filename into the buffer
    strcpy(new_filename, filename);

    // Replace the file extension with a random sequence of lowercase letters
    char *ext = strrchr(new_filename, '.');
    if (ext != NULL) {
        size_t len = ext - new_filename;
        int vowels = 0;
        for (size_t i = 0; i < len; i++) {
            char c = new_filename[i];
            if (isalpha(c) && islower(c)) {
                if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
                    vowels++;
                }
            } else {
                break;
            }
        }
        size_t new_ext_len = vowels + 1;
        if (new_ext_len > max_len) {
            fprintf(stderr, "Error: New filename extension is too long\n");
            free(new_filename);
            return NULL;
        }
        ext[0] = '\0';
        snprintf(ext + 1, new_ext_len, "%s", generate_random_string(vowels));
    } else {
        fprintf(stderr, "Error: Failed to find file extension in filename\n");
        free(new_filename);
        return NULL;
    }

    // Append the filetype to the new filename
    strcat(new_filename, filetype);

    // Validate that the resulting filename is unique within the specified directory
    char *dir = ".";
    DIR *dp = opendir(dir);
    if (dp == NULL) {
        fprintf(stderr, "Error: Failed to open directory %s\n", dir);
        free(new_filename);
        return NULL;
    }
    struct dirent *ep;
    while ((ep = readdir(dp)) != NULL) {
        if (strcmp(ep->d_name, new_filename) == 0) {
            // The generated filename is not unique, try again with a modified extension
            free(new_filename);
            new_filename = generate_unique_filename(filename, filetype);
            break;
        }
    }
    closedir(dp);

    return new_filename;
}

