    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        // Handle error
        printf("Error initializing cipher context: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return -1;
    }

    // Set the encryption key and initialization vector
    ret = EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, derived_key, iv);
    if (ret != 1) {
        // Handle error
        printf("Error setting encryption key and IV: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return -1;
    }

    // Set the padding mode to PKCS#7
    ret = EVP_CIPHER_CTX_set_padding(ctx, 1);
    if (ret != 1) {
        // Handle error
        printf("Error setting padding mode: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return -1;
    }

    // Return the cipher context
    return ctx;
}

// Define the function to clean up and disable the cipher context when it is no longer needed
void cleanup_aes_cbc(EVP_CIPHER_CTX *ctx) {
    // Declare variables
    int ret = 0;

    // Check if the cipher context is valid
    if (ctx == NULL) {
        return;
    }

    // Disable the cipher context
    ret = EVP_CIPHER_CTX_cleanup(ctx);
    if (ret != 1) {
        // Handle error
        printf("Error cleaning up cipher context: %s\n", ERR_error_string(ERR_get_error(), NULL));
    }

    // Free the cipher context
    EVP_CIPHER_CTX_free(ctx);
}

// Define the function to securely clean up and disable the cipher context when it is no longer needed, ensuring that sensitive data is not inadvertently exposed or retained longer than necessary. This function should also free any resources held by external dependencies, such as logging systems or memory pools.
