        return NULL;
    }

    // Initialize the array of network interface configurations
    for (int i = 0; i < MAX_NETWORK_INTERFACES; i++) {
        configs[i].InterfaceID = i + 1;
        configs[i].IPAddress[0] = '\0';
        configs[i].SubnetMask[0] = '\0';
        configs[i].NetworkStatus = -1;
    }

    // Read the network interface configurations from standard input
    char line[256];
    while (fgets(line, sizeof(line), stdin)) {
        // Parse the line and extract the interface ID, IP address, and subnet mask
        int interfaceID = -1;
        char ipAddress[INET6_ADDRSTRLEN] = "";
        char subnetMask[INET6_ADDRSTRLEN] = "";
        if (sscanf(line, "%d %s %s", &interfaceID, ipAddress, subnetMask) != 3) {
            fprintf(stderr, "Error: Failed to parse network interface configuration\n");
            continue;
        }

        // Validate the IP address and subnet mask
        if (!inet_pton(AF_INET6, ipAddress, &configs[interfaceID].IPAddress) || !inet_pton(AF_INET6, subnetMask, &configs[interfaceID].SubnetMask)) {
            fprintf(stderr, "Error: Invalid IP address or subnet mask\n");
            continue;
        }

        // Set the network status flag randomly to either active or inactive
        configs[interfaceID].NetworkStatus = (rand() % 2) ? 1 : 0;
    }

    return configs;
}
