```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <math.h>

#define MAX_VALID_NUMBERS 10

float* readValidNumbers(int* numValid) {
    // Allocate memory for the array of valid numbers
    float* numbers = (float*)malloc(MAX_VALID_NUMBERS * sizeof(float));
    if (!numbers) {
        fprintf(stderr, "Error: Failed to allocate memory for valid numbers\n");
        return NULL;
    }

    // Read the list of floating-point numbers from standard input
    char line[256];
    while (fgets(line, sizeof(line), stdin)) {
        // Parse the line and extract the number
        float number = -1.0f;
        if (sscanf(line, "%f", &number) != 1) {
            fprintf(stderr, "Error: Failed to parse floating-point number\n");
            continue;
        }

        // Validate the number for non-negative values
        if (number < 0.0f) {
            fprintf(stderr, "Error: Invalid number %f\n", number);
            continue;
        }

        // Store the valid number in the array of valid numbers
        numbers[*numValid] = number;
        (*numValid)++;
    }

    return numbers;
}

void calculateAverage(float* numbers, int numValid) {
    if (numValid == 0) {
        fprintf(stderr, "Error: No valid numbers to calculate average\n");
        return;
    }

    // Calculate the sum of all valid numbers
    float sum = 0.0f;
    for (int i = 0; i < numValid; i++) {
        sum += numbers[i];
    }

    // Print the average of all valid numbers
    printf("Average: %f\n", sum / numValid);
}
