```java
import java.security.MessageDigest;
import java.util.Arrays;
import java.util.logging.Logger;

public class MD5Hash {
    private static final Logger logger = Logger.getLogger(MD5Hash.class.getName());

    public static String[] getMD5Hashes(String... inputs) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            String[] hashes = new String[inputs.length];
            for (int i = 0; i < inputs.length; i++) {
                byte[] hash = md.digest(inputs[i].getBytes());
                hashes[i] = Arrays.toString(hash);
            }
            return hashes;
        } catch (Exception e) {
            logger.severe("Error: Failed to compute MD5 hash for input strings " + Arrays.toString(inputs));
            return null;
        }
    }
}
