void remove_element(NFAPI_CRC_INDICATION_LIST_T *list, size_t index) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list_mutex);

    // Check if the index is valid
    if (index >= list->size) {
        fprintf(stderr, "Error: Invalid index for removing element from NFAPI_CRC_INDICATION_LIST_T\n");
        pthread_mutex_unlock(&list_mutex);
        return;
