using namespace std;

// Command-line options
struct Options {
    string inputFile; // Input file path
    string outputFile; // Output file path
    char delimiter = '\n'; // Line delimiter character
    bool skipLines = false; // Skip certain line numbers during processing
    vector<int> skipLineNumbers; // List of line numbers to skip
    int threadCount = 1; // Number of threads for parallel processing
};

// File reader class
class FileReader {
public:
    FileReader(const string& filePath, char delimiter) : filePath_(filePath), delimiter_(delimiter) {}

    void readFile() {
        ifstream fileStream(filePath_);
        if (!fileStream.is_open()) {
            cerr << "Error: Could not open input file '" << filePath_ << "'." << endl;
            return;
        }

        string line;
        while (getline(fileStream, line)) {
            // Skip certain line numbers if requested
            if (options_.skipLines && find(options_.skipLineNumbers.begin(), options_.skipLineNumbers.end(), ++lineCount_) != options_.skipLineNumbers.end()) {
                continue;
            }

            // Process line
            processLine(line);
        }
    }

private:
    string filePath_; // Input file path
    char delimiter_; // Line delimiter character
    int lineCount_ = 0; // Current line number
    Options options_; // Command-line options
};

// File writer class
class FileWriter {
public:
    FileWriter(const string& filePath) : filePath_(filePath) {}

    void writeFile() {
        ofstream fileStream(filePath_);
        if (!fileStream.is_open()) {
            cerr << "Error: Could not open output file '" << filePath_ << "'." << endl;
            return;
        }

        // Write line count to file
        fileStream << totalLineCount_ << endl;
    }

private:
    string filePath_; // Output file path
    int totalLineCount_ = 0; // Total number of lines processed
};

// Main function
int main(int argc, char* argv[]) {
    // Parse command-line options
    Options options;
    if (!parseOptions(argc, argv, options)) {
        return EXIT_FAILURE;
    }

    // Initialize file reader and writer objects
    FileReader fileReader(options.inputFile, options.delimiter);
    FileWriter fileWriter(options.outputFile);

    // Read input file line by line
    auto startTime = chrono::steady_clock::now();
    fileReader.readFile();
    auto endTime = chrono::steady_clock::now();

    // Calculate total number of lines processed
    int totalLineCount = 0;
    for (const auto& line : fileReader.lineCounts_) {
        totalLineCount += line.second;
    }

    // Write output file with line count
    fileWriter.writeFile();

    // Print processing time and line count
    cout << "Processed " << totalLineCount << " lines in " << chrono::duration_cast<chrono::milliseconds>(endTime - startTime).count() << " ms." << endl;

    return EXIT_SUCCESS;
}

// Parse command-line options and store in Options struct
bool parseOptions(int argc, char* argv[], Options& options) {
    // Check for correct number of arguments
    if (argc < 2) {
        cerr << "Error: Incorrect number of arguments. Usage: " << argv[0] << " [options] inputFile" << endl;
        return false;
    }

    // Parse command-line options
    for (int i = 1; i < argc; ++i) {
        string option(argv[i]);

        if (option == "-h" || option == "--help") {
            printUsage();
            return false;
        } else if (option == "-d" || option == "--delimiter") {
            options.delimiter = argv[++i][0];
        } else if (option == "-s" || option == "--skip-lines") {
            options.skipLines = true;
            string skipLineNumbersStr(argv[++i]);
            istringstream iss(skipLineNumbersStr);
            copy(istream_iterator<int>(iss), istream_iterator<int>(), back_inserter(options.skipLineNumbers));
        } else if (option == "-t" || option == "--thread-count") {
            options.threadCount = atoi(argv[++i]);
        } else if (option == "-o" || option == "--output-file") {
            options.outputFile = argv[++i];
        } else {
            options.inputFile = option;
        }
    }

    // Check for required options
    if (options.inputFile.empty()) {
        cerr << "Error: Input file not specified." << endl;
        return false;
    }

    // Set default output file path if not specified
    if (options.outputFile.empty()) {
        options.outputFile = options.inputFile + ".linecount";
    }

    return true;
}

// Print usage information for the program
void printUsage() {
    cout << "Usage: " << argv[0] << " [options] inputFile" << endl;
    cout << "Options:" << endl;
    cout << "\t-h, --help\t\tPrint this help message." << endl;
    cout << "\t-d, --delimiter <char>\tSet the line delimiter character (default: \\n)." << endl;
    cout << "\t-s, --skip-lines <int>...\tSkip certain line numbers during processing (e.g., -s 1 2 3)." << endl;
    cout << "\t-t, --thread-count <int>\tSet the number of threads for parallel processing (default: 1)." << endl;
    cout << "\t-o, --output-file <string>\tSet the output file path (default: inputFile.linecount)." << endl;
}']

