    // Allocate memory for the list
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize each structure in the list with a random RX_UE_INFORMATION_TAG and RNTI, along with a CRC_INDICATION_REL8_TAG
