    // Iterate through each structure in the list and validate its integrity
    for (int i = 0; i < n; i++) {
        if ((*list)[i].rx_ue_information_tag == 0 || (*list)[i].rnti == 0) {
            // If the RX_UE_INFORMATION_TAG or RNTI is 0, then the structure is invalid
