    // Open the output file for writing
    FILE *output = fopen(filename, "w");

    // Iterate through each structure in the list and serialize it to the output file
    for (int i = 0; i < n; i++) {
        fprintf(output, "%d %d %d %d\n", (*list)[i].rx_ue_information_tag, (*list)[i].rnti, (*list)[i].crc_indication_rel8_tag, (*list)[i].crcflag);
    }

    // Close the output file
    fclose(output);
}

