void deserialize_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T **list, int n, char *filename) {
    // Open the input file for reading
    FILE *input = fopen(filename, "r");

    // Allocate memory for the list of structures
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Iterate through each line in the input file and deserialize a structure from it
    for (int i = 0; i < n; i++) {
        fscanf(input, "%d %d %d %d", &(*list)[i].rx_ue_information_tag, &(*list)[i].rnti, &(*list)[i].crc_indication_rel8_tag, &(*list)[i].crcflag);
