            return false;
        }
    }

    // Check that the RNTI is within the specified range
    if (pdu->rnti < MIN_RNTI || pdu->rnti > MAX_RNTI) {
        // Handle out-of-range RNTI value
        printf("Error: Out-of-range RNTI value detected\n");
        return false;
