// Define the structure for a MAC Entity Context (MAC_EC_T)
typedef struct {
    uint32_t UE_ID; // Unique identifier for the UE
    uint8_t PDCP_SN_SIZE; // Size of the PDCP sequence number
    SecurityKeys keys; // Set of security keys for the context
} MAC_EC_T;

// Define a list data structure to store the MAC Entity Contexts (MAC_EC_T)
typedef struct {
    uint32_t size; // Number of elements in the list
    uint32_t capacity; // Maximum number of elements that can be stored in the list
    MAC_EC_T* data; // Pointer to the array of MAC Entity Contexts (MAC_EC_T)
} List;

// Define a function to generate random initialization vectors (IVs) for each structure
void generate_iv(MAC_EC_T* context) {
    // Generate a random IV using a cryptographically secure PRNG
    uint8_t iv[16];
    for (int i = 0; i < 16; i++) {
        iv[i] = rand() % 256;
    }
    context->keys.iv = iv;
}

// Define a function to add a new MAC Entity Context (MAC_EC_T) to the list
void add_context(List* list, uint32_t UE_ID, uint8_t PDCP_SN_SIZE) {
    // Check if the list is full
    if (list->size == list->capacity) {
        // If the list is full, double its capacity and reallocate memory for the data array
        list->capacity *= 2;
        list->data = realloc(list->data, list->capacity * sizeof(MAC_EC_T));
    }

    // Create a new MAC Entity Context (MAC_EC_T) with the given UE_ID and PDCP_SN_SIZE
    MAC_EC_T* context = malloc(sizeof(MAC_EC_T));
    context->UE_ID = UE_ID;
    context->PDCP_SN_SIZE = PDCP_SN_SIZE;
    generate_iv(context); // Generate a random initialization vector (IV) for the context

