void init_lte_phy_test_configs(int num_structures, int min_rnti, int max_rnti) {
    // Allocate memory for the structures and initialize them
    LTE_PHY_TEST_CONFIG *structures = (LTE_PHY_TEST_CONFIG *)malloc(num_structures * sizeof(LTE_PHY_TEST_CONFIG));
    for (int i = 0; i < num_structures; i++) {
        structures[i].PHY_TEST_PARAMETER_ID = i + 1;
        structures[i].TEST_MODE = rand() % 2;
        structures[i].PHYSICAL_LAYER_STATUS = rand() % 3;
        structures[i].crc_indication_pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        structures[i].crc_indication_pdu->RX_UE_INFORMATION_TAG = rand() % 2;
        structures[i].crc_indication_pdu->RNTI = min_rnti + (rand() % (max_rnti - min_rnti));
        structures[i].crc_indication_pdu->CRCFLAG = rand() % 2;
    }

    // Validate the structures for duplicate RNTIs and invalid combinations
    for (int i = 0; i < num_structures; i++) {
        for (int j = i + 1; j < num_structures; j++) {
