                structures[i].PHY_TEST_PARAMETER_ID = 0;
            } else if (structures[i].crc_indication_pdu->RX_UE_INFORMATION_TAG != structures[j].crc_indication_pdu->RX_UE_INFORMATION_TAG) {
                // Invalid combination of RX_UE_INFORMATION_TAG and RNTI found, invalidate the structure
                structures[i].PHY_TEST_PARAMETER_ID = 0;
            }
        }
    }

    // Serialize the list to a file in a structured binary format with versioning
    FILE *file = fopen("lte_phy_test_configs.bin", "wb");
    if (file == NULL) {
        printf("Error: Failed to open file for writing\n");
        return;
