    // Write the version number and the number of structures to the file
    fwrite(&VERSION, sizeof(int), 1, file);
    fwrite(&num_structures, sizeof(int), 1, file);
    // Write each structure to the file
    for (int i = 0; i < num_structures; i++) {
        fwrite(&structures[i], sizeof(LTE_PHY_TEST_CONFIG), 1, file);
    }
    fclose(file);
}

