            continue;
        }
        add_lte_ue_context(list, list->ues[i]);
    }
}

// Validate an LTE UE context structure
bool validate_lte_ue_context(lte_ue_context_t *ctx) {
    // Check for duplicate UE identifiers and invalid NAS PDU combinations
    for (int i = 0; i < ctx->num_ues; i++) {
        if (ctx->ues[i]->ue_id == ctx->ue_id && !validate_nas_pdu(ctx->ues[i]->nas_pdu)) {
            return false;
        }
    }

    // Check for consistent QoS flow priorities across related structures
    for (int i = 0; i < ctx->num_ues; i++) {
        if (ctx->ues[i]->qos_flow_priorities[0] != ctx->ues[i]->qos_flow_priorities[1] ||
            ctx->ues[i]->qos_flow_priorities[1] != ctx->ues[i]->qos_flow_priorities[2]) {
            return false;
        }
    }

    // All checks passed, the UE context is valid
    return true;
}

// Add an LTE UE context structure to the list
void add_lte_ue_context(lte_ue_context_list_t *list, lte_ue_context_t *ctx) {
    // Check if the list is full and allocate more memory if necessary
    if (list->num_ues == 100) {
        list->ues = (lte_ue_context_t **)realloc(list->ues, sizeof(lte_ue_context_t *) * (list->num_ues + 1));
        list->ues[list->num_ues] = (lte_ue_context_t *)malloc(sizeof(lte_ue_context_t));
    }

    // Add the UE context to the list and increment the number of UEs
    memcpy(list->ues[list->num_ues], ctx, sizeof(lte_ue_context_t));
    list->num_ues++;
}

// Serialize the list of LTE UE context structures to a file
void serialize_lte_ue_context_list(lte_ue_context_list_t *list, char *filename) {
    // Open the output file for writing
    FILE *outfile = fopen(filename, "wb");

    // Write the number of UE contexts to the file
    int num_ues = list->num_ues;
    fwrite(&num_ues, sizeof(int), 1, outfile);

    // Write each UE context structure to the file
    for (int i = 0; i < num_ues; i++) {
        lte_ue_context_t *ctx = list->ues[i];
        fwrite(&ctx->ue_id, sizeof(int), 1, outfile);
        fwrite(ctx->nas_pdu, strlen(ctx->nas_pdu) + 1, 1, outfile);
        for (int j = 0; j < 3; j++) {
            fwrite(&ctx->qos_flow_ids[j], sizeof(int), 1, outfile);
            fwrite(&ctx->qos_flow_priorities[j], sizeof(float), 1, outfile);
        }
    }

    // Close the output file
    fclose(outfile);
}

// Deserialize the list of LTE UE context structures from a file
void deserialize_lte_ue_context_list(lte_ue_context_list_t *list, char *filename) {
    // Open the input file for reading
    FILE *infile = fopen(filename, "rb");

    // Read the number of UE contexts from the file
    int num_ues;
    fread(&num_ues, sizeof(int), 1, infile);

    // Allocate memory for the list and its elements
    list->num_ues = num_ues;
    list->ues = (lte_ue_context_t **)malloc(sizeof(lte_ue_context_t *) * num_ues);
    for (int i = 0; i < num_ues; i++) {
        list->ues[i] = (lte_ue_context_t *)malloc(sizeof(lte_ue_context_t));
    }

    // Read each UE context structure from the file
    for (int i = 0; i < num_ues; i++) {
        lte_ue_context_t *ctx = list->ues[i];
        fread(&ctx->ue_id, sizeof(int), 1, infile);
        ctx->nas_pdu = (char *)malloc(sizeof(char) * 256);
        fread(ctx->nas_pdu, strlen(ctx->nas_pdu) + 1, 1, infile);
        for (int j = 0; j < 3; j++) {
            fread(&ctx->qos_flow_ids[j], sizeof(int), 1, infile);
            fread(&ctx->qos_flow_priorities[j], sizeof(float), 1, infile);
        }
    }

    // Close the input file
    fclose(infile);
}
