#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdarg.h>

// Define structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    RX_UE_INFORMATION_TAG rxUeInformationTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define function to dynamically allocate memory for list of structures
NFAPI_CRC_INDICATION_PDU_T* allocateList(int n, int seed) {
    // Calculate buffer size based on number of structures and structure size
    int bufferSize = sizeof(NFAPI_CRC_INDICATION_PDU_T) * n;

    // Allocate memory for list of structures
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(bufferSize);

    // Check if memory allocation failed
    if (!list) {
        return NULL;
    }

    // Initialize each structure in the list with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (int i = 0; i < n; i++) {
        list[i].rxUeInformationTag = RX_UE_INFORMATION_TAG_VALID;
        list[i].rnti = rand() % 65536 + seed;
        list[i].crcIndicationRel8Tag = CRC_INDICATION_REL8_TAG_VALID;
    }

    // Set CRCFLAG to a randomly set value for each structure in the list
    for (int i = 0; i < n; i++) {
        list[i].crcIndicationRel8Tag.crcFlag = rand() % 2 ? 1 : 0;
    }

    return list;
}

// Define function to generate a new filename based on an existing one
char* generateNewFilename(const char* filename, int seed) {
    // Calculate the number of vowels in the original filename
    int numVowels = 0;
    for (int i = 0; i < strlen(filename); i++) {
        if (filename[i] == 'a' || filename[i] == 'e' || filename[i] == 'i' || filename[i] == 'o' || filename[i] == 'u') {
            numVowels++;
        }
    }

    // Calculate the buffer size for the new filename
    int bufferSize = strlen(filename) + numVowels;

    // Allocate memory for the new filename
    char* newFilename = (char*)malloc(bufferSize);

    // Check if memory allocation failed
    if (!newFilename) {
        return NULL;
    }

    // Copy the original filename to the new filename, appending a sequence of random digits
    strcpy(newFilename, filename);
    for (int i = 0; i < numVowels; i++) {
        newFilename[strlen(filename) + i] = '0' + rand() % 10;
    }

    return newFilename;
}

// Define function to validate a filename for uniqueness within a specified directory
int isUniqueFilename(const char* filename, const char* directory) {
    // Open the directory and read its contents
    DIR* dir = opendir(directory);
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(filename, entry->d_name) == 0) {
            return 0;
        }
    }

    // If the filename is not found in the directory, it is unique and can be used
    return 1;
}

// Define function to log messages using snprintf and va_start/va_end
void logMessage(const char* format, ...) {
    // Calculate the buffer size for the message
    int bufferSize = strlen(format) + 1024;

    // Allocate memory for the message
    char* message = (char*)malloc(bufferSize);

    // Check if memory allocation failed
