pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate a new record in the memory pool
SENSOR_RECORD_T* allocate_record(int sensor_id, int measurements) {
    // Acquire the lock on the memory pool
    pthread_mutex_lock(&mutex);

    // Check if there is enough space in the memory pool for a new record
    if (used + sizeof(SENSOR_RECORD_T) > POOL_SIZE) {
        // Release the lock on the memory pool
        pthread_mutex_unlock(&mutex);

        // Handle memory allocation failure
        return NULL;
    }

    // Allocate a new record in the memory pool
    SENSOR_RECORD_T* record = (SENSOR_RECORD_T*)malloc(sizeof(SENSOR_RECORD_T));

    if (record == NULL) {
        // Release the lock on the memory pool
        pthread_mutex_unlock(&mutex);

        // Handle memory allocation failure
        return NULL;
    }

    // Initialize the record with the given sensor ID and measurements
    record->timestamp = get_current_timestamp();
    record->sensor_id = sensor_id;
    record->measurements = measurements;

    // Update the used space in the memory pool
    used += sizeof(SENSOR_RECORD_T);

    // Release the lock on the memory pool
    pthread_mutex_unlock(&mutex);

    return record;
}

// Function to free a record in the memory pool
void free_record(SENSOR_RECORD_T* record) {
    // Acquire the lock on the memory pool
    pthread_mutex_lock(&mutex);

    // Free the record from the memory pool
    free(record);

    // Update the used space in the memory pool
    used -= sizeof(SENSOR_RECORD_T);

    // Release the lock on the memory pool
    pthread_mutex_unlock(&mutex);
}
