    nfapi_pdu_t* tail;
} nfapi_pdus_list_t;

// Function to generate NFAPI PDUS
nfapi_pdus_list_t* generate_nfapi_pdus(int n) {
    // Allocate memory for the linked list
    nfapi_pdus_list_t* pdus = (nfapi_pdus_list_t*)malloc(sizeof(nfapi_pdus_list_t));
    if (!pdus) {
        return NULL;
    }

    // Initialize the linked list
    pdus->head = NULL;
    pdus->tail = NULL;

    // Allocate memory for each PDU and initialize it
    for (int i = 0; i < n; ++i) {
        nfapi_pdu_t* pdu = (nfapi_pdu_t*)malloc(sizeof(nfapi_pdu_t));
        if (!pdu) {
            // Handle memory allocation failure
            return NULL;
        }

        // Initialize the PDU fields
        pdu->rnti = generate_rnti();
        switch (generate_pdu_type()) {
            case NFAPI_CRC_INDICATION:
                generate_crc_indication(&pdu->crc_indication);
                break;
            case NFAPI_RX_UE_INFORMATION:
                generate_rx_ue_information(&pdu->rx_ue_information);
                break;
            // Add other PDU types as needed
        }

        // Add the PDU to the linked list
        if (pdus->head == NULL) {
            pdus->head = pdu;
        } else {
            pdus->tail->next = pdu;
        }
        pdus->tail = pdu;
    }

    return pdus;
}
