```java
import java.io.File;
import java.security.SecureRandom;
import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.PBEKeySpec;
import javax.crypto.spec.SecretKeySpec;
import org.json.JSONObject;

public class MoSTState {
    private static final int ITERATIONS = 20_000;
    private static final int KEY_LENGTH = 256;
    private static final int IV_LENGTH = 128;
    private static final String ALGORITHM = "PBKDF2WithHmacSHA256";
    private static final String CIPHER_ALGORITHM = "AES/CBC/PKCS5Padding";
    private static final String FILE_FORMAT = "JSON";

    public static MoSTState loadMoSTStateFromFile(String filePath, String password) {
        // Validate input parameters
        if (filePath == null || password == null) {
            throw new IllegalArgumentException("Invalid input parameters");
        }

        // Load the state object from the specified file path
        JSONObject json = loadJSONFromFile(filePath);
        if (json == null) {
            return null;
        }

        // Derive a 256-bit key from the user-provided password and salt using PBKDF2-HMAC-SHA256 with at least 20,000 iterations for key stretching
        byte[] salt = json.getBytes("salt");
        byte[] derivedKey = deriveKey(password, salt);
        if (derivedKey == null) {
            return null;
        }

        // Ensure the derived key is used consistently across all encryption sessions for a particular user
        SecretKeySpec secretKey = new SecretKeySpec(derivedKey, ALGORITHM);

        // Generate a fresh 128-bit IV for each decryption operation
        byte[] iv = generateIV();
        IvParameterSpec ivSpec = new IvParameterSpec(iv);

        // Decrypt the state object using AES/CBC/PKCS5Padding with the derived key and IV
        Cipher cipher = Cipher.getInstance(CIPHER_ALGORITHM);
        cipher.init(Cipher.DECRYPT_MODE, secretKey, ivSpec);
        byte[] encryptedState = json.getBytes("state");
        byte[] decryptedState = cipher.doFinal(encryptedState);

        // Deserialize the decrypted state object
        MoSTState state = deserializeState(decryptedState);
        if (state == null) {
            return null;
        }

        // Clean up and disable the cipher context and file handles when they are no longer needed
        cipher.cleanUp();
        json.close();

        // Return the deserialized state object
        return state;
    }

    private static JSONObject loadJSONFromFile(String filePath) {
        try {
            File file = new File(filePath);
            if (!file.exists()) {
                return null;
            }
            JSONObject json = new JSONObject(file);
            return json;
        } catch (Exception e) {
            // Handle exception
            return null;
        }
    }

    private static byte[] deriveKey(String password, byte[] salt) {
