        } catch (Exception e) {
            // Handle exception
            return null;
        }
    }

    private static byte[] generateIV() {
        try {
            SecureRandom random = new SecureRandom();
            byte[] iv = new byte[IV_LENGTH];
            random.nextBytes(iv);
            return iv;
        } catch (Exception e) {
            // Handle exception
            return null;
        }
    }

    private static MoSTState deserializeState(byte[] state) {
        try {
            ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(state));
            MoSTState result = (MoSTState) ois.readObject();
            ois.close();
            return result;
        } catch (Exception e) {
            // Handle exception
            return null;
        }
    }
}
