        free(stream->buffer);
        stream->buffer = malloc(stream->buffer_size);
    }
}

void enqueue_packet(struct network_interface *ni, int stream_id, char *data, size_t len) {
    struct stream *stream = &ni->streams[stream_id];
    pthread_mutex_lock(&ni->mutex);
    if (len > stream->buffer_size) {
        // handle buffer overflow gracefully
        pthread_mutex_unlock(&ni->mutex);
        return;
    }
    memcpy(stream->buffer, data, len);
    pthread_mutex_unlock(&ni->mutex);
}

void dequeue_packet(struct network_interface *ni, int stream_id) {
    struct stream *stream = &ni->streams[stream_id];
    pthread_mutex_lock(&ni->mutex);
    char *data = stream->buffer;
    size_t len = stream->buffer_size;
    memset(stream->buffer, 0, len);
    pthread_mutex_unlock(&ni->mutex);
}
