    NRCellConfig* sibs = malloc(sizeof(NRCellConfig) * size);
    if (!sibs) {
        fprintf(stderr, "Error: Failed to allocate memory for SIBs\n");
        return NULL;
    }

    // Initialize the array of SIBs
    for (int i = 0; i < size; i++) {
        // Set default values for sib1 and sib2 fields
        sibs[i].sib1_field1 = 0;
        sibs[i].sib1_field2 = 0;
        sibs[i].sib2_field1 = 0;
        sibs[i].sib2_field2 = 0;

        // Set default values for sib3 fields
        sibs[i].sib3_field1 = 0;
        sibs[i].sib3_field2 = 0;

        // Randomly set specific fields to a default value with the given probability
        if (prob_default_val > 0.0f && rand() / (float)RAND_MAX < prob_default_val) {
            sibs[i].sib1_field1 = 1;
            sibs[i].sib2_field1 = 1;
