    if (log_file) {
        for (int i = 0; i < size; i++) {
            if (!validate_SIB(&sibs[i])) {
                fprintf(log_file, "Error: Failed to validate SIB %d\n", i);
            }
        }
        fclose(log_file);
    }

    // Handle memory allocation failures gracefully by freeing all allocated memory upon failure
    if (!sibs) {
        free(sibs);
        return NULL;
    }

    // Provide a callback mechanism for reporting statistics, such as the number of successful allocations, failed allocations, and logged errors
