bool is_valid_directory_char(UChar32 c) {
    // Check if the character is a valid directory character (alphanumeric, underscore, hyphen)
    return u_isalnum(c) || u_isalpha(c) || u_isdigit(c) || c == '_' || c == '-';
}

bool is_valid_directory_string(const UChar *str, size_t len) {
    // Check if the string contains only valid directory characters and reject any invalid characters
    for (size_t i = 0; i < len; i++) {
        UChar32 c = u_charAt(str, i);
        if (!is_valid_directory_char(c)) {
            return false;
        }
    }
    return true;
}

bool is_unicode_normalized(const UChar *str, size_t len) {
    // Check if the string meets proper Unicode normalization for directory names
    UErrorCode status = U_ZERO_ERROR;
    UNormalizer2 *norm = unorm2_getInstance(NULL, "nfc", NULL, &status);
    if (U_FAILURE(status)) {
        fprintf(stderr, "Failed to get Unicode normalizer: %s\n", u_errorName(status));
        return false;
    }
    UChar *normalized = unorm2_normalize(norm, str, len, NULL, &status);
    if (U_FAILURE(status)) {
        fprintf(stderr, "Failed to normalize Unicode string: %s\n", u_errorName(status));
        return false;
    }
    bool result = u_strcmp(normalized, str) == 0;
    unorm2_close(norm);
    free(normalized);
    return result;
}

