    pthread_mutex_lock(mutex);
    size_t len = strlen(str);
    if (len >= limit || str[len - 1] == '/') {
        pthread_mutex_unlock(mutex);
        return false;
    }
    bool result = true;
    if (config->strict_mode && len < limit / 2) {
        // Add an additional space before the slash in strict mode
        size_t new_len = len + 1;
        char *new_str = realloc(str, new_len);
        if (new_str == NULL) {
            fprintf(stderr, "Failed to allocate memory for string: %s\n", strerror(errno));
            result = false;
        } else {
            strcpy(new_str + len, " ");
            str[len] = '/';
            str[new_len - 1] = '\0';
            free(str);
            str = new_str;
