    if (log_str == NULL) {
        fclose(fp);
        sem_post(sem);
        return NULL;
    }
    strcpy(log_str, str);
    log_str[byte_len] = '\0';
    fprintf(fp, "%s\n", log_str);
    free(log_str);

    // Return the modified string if it fits within the size limit; otherwise, return NULL
    if (byte_len <= limit) {
        sem_post(sem);
        return str;
    } else {
        fclose(fp);
        sem_post(sem);
        return NULL;
    }
}
