    for (int i = 0; i < size_threshold + 1; i++) {
        char* filename = filenames[i];
        if (filename == NULL) {
            continue;
        }

        // Append a directory separator to the end of the filename if it does not already end with one and does not exceed the size threshold.
        int filename_length = strlen(filename);
        if (filename_length > 0 && filename[filename_length - 1] != '/') {
            char* new_filename = malloc(sizeof(char) * (filename_length + 2));
            if (new_filename == NULL) {
                fprintf(stderr, "Failed to allocate memory for new filename\n");
                exit(EXIT_FAILURE);
            }

            strcpy(new_filename, filename);
            new_filename[filename_length] = '/';
            new_filename[filename_length + 1] = '\0';
            output[i] = new_filename;
