            fprintf(stderr, "Failed to write logging message to file\n");
            exit(EXIT_FAILURE);
        }

        fclose(log_file);
    }

    // Optimize for memory usage by allocating only the necessary memory for the output array of strings and freeing any allocated memory before returning. Consider using a stack-allocated buffer for temporary operations to minimize heap allocations.
    char* temp_buffer = malloc(sizeof(char) * (size_threshold + 1));
    if (temp_buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for temporary buffer\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < size_threshold + 1; i++) {
        char* filename = output[i];
        if (filename == NULL) {
            continue;
        }

        int filename_length = strlen(filename);
        memcpy(temp_buffer, filename, filename_length);
        temp_buffer[filename_length] = '\0';
        free(output[i]);
        output[i] = temp_buffer;
    }

    free(temp_buffer);

    // Provide a mechanism to dynamically reconfigure the logging settings at runtime, ensuring that changes take effect without requiring a restart of the application. This includes handling cases where the new configuration requires immediate changes due to critical log file paths.
    if (config.logging_file == NULL) {
        fprintf(stderr, "Invalid external configuration\n");
        exit(EXIT_FAILURE);
    }

    // Integrate with a system that can handle concurrent requests efficiently without affecting the integrity of the output filenames, using the provided semaphore to manage access to shared resources. Ensure that the function can handle up to 1000 concurrent requests without performance degradation.
    if (sem_init(&config.semaphore, 0, 1) != 0) {
        fprintf(stderr, "Failed to initialize semaphore\n");
        exit(EXIT_FAILURE);
    }

    // Consider performance implications when handling very large lists or high-frequency requests, implementing efficient string manipulation techniques and minimizing the number of system calls. Optimize for both time and space complexity.
    if (size_threshold > 1000) {
        fprintf(stderr, "Size threshold exceeds maximum value\n");
        exit(EXIT_FAILURE);
    }

    return output;
}
