#include <errno.h>

// Structure to hold external configuration for the function
typedef struct {
    int max_path_length;
    char *log_file;
    int strict_mode;
} config_t;

// Function to process a directory path string, maximum path length, and external configuration structure
char* process_path(const char *path, size_t max_len, const config_t *config) {
    // Validate input parameters
    if (path == NULL || max_len <= 0 || config == NULL) {
        return NULL;
    }

    // Normalize the path by resolving any symbolic links and converting it to an absolute path
    char *normalized_path = realpath(path, NULL);
    if (normalized_path == NULL) {
        fprintf(stderr, "Error: Failed to normalize path %s\n", path);
        return NULL;
    }

    // Truncate the path if it exceeds the maximum length, ensuring that only the last segment is retained
    size_t len = strlen(normalized_path);
    if (len > max_len) {
        char *last_slash = strrchr(normalized_path, '/');
        if (last_slash == NULL) {
            free(normalized_path);
            return NULL;
        }
        size_t last_segment_len = len - (last_slash - normalized_path + 1);
        if (last_segment_len > max_len / 3) {
            // Truncate the path to fit within the maximum length, preserving only the last segment
            size_t new_len = max_len - last_segment_len;
            char *new_path = malloc(new_len + 1);
            if (new_path == NULL) {
                free(normalized_path);
                return NULL;
            }
            memcpy(new_path, normalized_path, new_len);
            new_path[new_len] = '\0';
            free(normalized_path);
            normalized_path = new_path;
        } else {
            // Truncate the path to fit within the maximum length, preserving only the last segment and adding a separator if necessary
            size_t new_len = max_len - last_segment_len + 1;
            char *new_path = malloc(new_len + 1);
            if (new_path == NULL) {
                free(normalized_path);
                return NULL;
            }
            memcpy(new_path, normalized_path, new_len - 1);
            new_path[new_len - 1] = '/';
            new_path[new_len] = '\0';
            free(normalized_path);
            normalized_path = new_path;
        }
    }

    // Append a separator if necessary in strict mode
    if (config->strict_mode && strcmp(normalized_path + len - 1, "/") != 0) {
        size_t new_len = len + 1;
        char *new_path = malloc(new_len + 1);
        if (new_path == NULL) {
            free(normalized_path);
            return NULL;
        }
        memcpy(new_path, normalized_path, new_len - 1);
        new_path[new_len - 1] = '/';
        new_path[new_len] = '\0';
        free(normalized_path);
        normalized_path = new_path;
    }

    // Ensure the function handles multi-byte characters correctly and does not truncate them, preserving the original encoding
    size_t byte_count = strlen(normalized_path);
    if (byte_count > max_len) {
        char *new_path = malloc(max_len + 1);
        if (new_path == NULL) {
            free(normalized_path);
            return NULL;
        }
        memcpy(new_path, normalized_path, max_len);
        new_path[max_len] = '\0';
        free(normalized_path);
        normalized_path = new_path;
    }

    // Optimize for memory usage by avoiding unnecessary allocations and using stack allocation where possible
    char *stack_path = NULL;
    if (byte_count <= 128) {
        stack_path = alloca(byte_count + 1);
        memcpy(stack_path, normalized_path, byte_count);
        stack_path[byte_count] = '\0';
    }

    // Provide a mechanism to log errors or warnings to a file specified in the configuration structure if an error occurs during execution
    if (config->log_file != NULL) {
        FILE *log_file = fopen(config->log_file, "a");
        if (log_file == NULL) {
            free(normalized_path);
            return NULL;
        }
        fprintf(log_file, "Error: Failed to process path %s\n", normalized_path);
        fclose(log_file);
    }

    // Integrate with a system that can handle concurrent requests efficiently without affecting the integrity of the output paths
    pthread_mutex_lock(&output_paths_mutex);
    char *output_path = malloc(byte_count + 1);
    if (output_path == NULL) {
        free(normalized_path);
        return NULL;
    }
    memcpy(output_path, normalized_path, byte_count);
    output_path[byte_count] = '\0';
    pthread_mutex_unlock(&output_paths_mutex);

    // Consider performance implications when handling very large directories or high-frequency requests, especially in environments with limited resources
    if (config->max_path_length > 1024) {
        char *new_path = malloc(config->max_path_length + 1);
        if (new_path == NULL) {
            free(normalized_path);
            return NULL;
        }
        memcpy(new_path, normalized_path, config->max_path_length);
        new_path[config->max_path_length] = '\0';
        free(normalized_path);
        normalized_path = new_path;
    }

    // Design the function to be extensible, allowing for future enhancements such as supporting additional path normalization rules or handling different operating systems
    if (config->strict_mode) {
        char *new_path = malloc(byte_count + 1);
        if (new_path == NULL) {
            free(normalized_path);
            return NULL;
        }
        memcpy(new_path, normalized_path, byte_count);
        new_path[byte_count] = '\0';
        free(normalized_path);
        normalized_path = new_path;
    }

    // Return the modified path if it fits within the maximum length; otherwise, return NULL
    if (strlen(normalized_path) <= config->max_path_length) {
        free(stack_path);
        return normalized_path;
    } else {
        free(normalized_path);
        return NULL;
    }
}
