#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <limits.h>
#include <stdbool.h>

// Define the maximum path length
#define MAX_PATH_LENGTH 4096

// Define the external configuration structure
struct config {
    bool strict_mode;
    char *log_file;
};

// Define the function to process the directory path string
char* process_path(const char *path, size_t max_length, struct config *config) {
    // Check for null pointers and ensure maximum path length is positive
    if (path == NULL || max_length <= 0) {
        return NULL;
    }

    // Normalize the path by resolving symbolic links and converting to an absolute path
    char *normalized_path = realpath(path, NULL);
    if (normalized_path == NULL) {
        return NULL;
    }

    // Truncate the path if it exceeds the maximum length
    size_t normalized_length = strlen(normalized_path);
    if (normalized_length > max_length) {
        char *truncated_path = malloc(max_length + 1);
        memcpy(truncated_path, normalized_path + normalized_length - max_length, max_length);
        truncated_path[max_length] = '\0';
        free(normalized_path);
        return truncated_path;
    }

    // Append a separator if strict mode is enabled and the remaining path length is less than one-third of the maximum length
    size_t remaining_length = max_length - normalized_length;
    if (config->strict_mode && remaining_length < (max_length / 3)) {
        char *appended_path = malloc(max_length + 1);
        memcpy(appended_path, normalized_path, normalized_length);
        appended_path[normalized_length] = '/';
        appended_path[normalized_length + 1] = '\0';
        free(normalized_path);
        return appended_path;
    }

    // Return the modified path if it fits within the maximum length
    return normalized_path;
}

// Define the function to log errors or warnings to a file specified in the configuration structure
void log_error(const char *message, struct config *config) {
    FILE *log_file = fopen(config->log_file, "a");
    if (log_file == NULL) {
        return;
    }
    fprintf(log_file, "%s\n", message);
    fclose(log_file);
}

// Define the function to handle concurrent requests efficiently without affecting the integrity of the output paths
void process_request(const char *path, size_t max_length, struct config *config) {
    // Process the path and log any errors or warnings
    char *processed_path = process_path(path, max_length, config);
    if (processed_path == NULL) {
        log_error("Error processing path", config);
        return;
    }

    // Use the HTTP client to create a RequestBuilder for the processed path
    struct http_client *http_client = http_client_create();
    if (http_client == NULL) {
        free(processed_path);
        log_error("Error creating HTTP client", config);
        return;
    }
    struct http_request_builder *builder = http_client_get(http_client, processed_path);
    if (builder == NULL) {
        free(processed_path);
        http_client_destroy(http_client);
        log_error("Error creating HTTP request builder", config);
        return;
    }

    // Optionally disable certificate validation and send the request
    if (config->disable_certificate_validation) {
        http_request_builder_set_verify(builder, false);
    }
    struct http_response *response = http_client_send(http_client, builder);
    if (response == NULL) {
        free(processed_path);
        http_client_destroy(http_client);
        log_error("Error sending HTTP request", config);
        return;
    }

    // Free the processed path and response
    free(processed_path);
    http_response_free(response);
    http_client_destroy(http_client);
}
