typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} SYNC;

// Define a function to manage the list of cell status reports and transactions
void manage_list(LIST* list) {
    // Initialize the synchronization primitives for thread safety
    SYNC sync = { .mutex = PTHREAD_MUTEX_INITIALIZER, .cond = PTHREAD_COND_INITIALIZER };

    // Define a variable to hold the current time in milliseconds
    long current_time = 0;

    // Loop until all transactions have been processed
    while (list->num_transactions > 0) {
        // Acquire the lock on the synchronization primitives
        pthread_mutex_lock(&sync.mutex);

        // Check if there are any new cell status reports to process
        if (list->num_cell_status_reports > 0) {
