typedef struct {
    char *log_file;
    int log_level;
    int log_threshold;
} config_t;

// Define the function to append a slash to a string
char* append_slash(const char *str, size_t size, const config_t *config, semaphore_t *sem) {
    // Validate input parameters
    if (str == NULL || size <= 0 || config == NULL || config->log_file == NULL || sem == NULL) {
        fprintf(stderr, "Invalid input parameter\n");
        return NULL;
    }

    // Check if the string is too long
    if (size > config->log_threshold) {
        fprintf(stderr, "String is too long\n");
        return NULL;
    }

    // Append a slash to the end of the string
    char *new_str = malloc(size + 1);
    if (new_str == NULL) {
        fprintf(stderr, "Failed to allocate memory for new string\n");
        return NULL;
    }
    strcpy(new_str, str);
    new_str[size] = '/';
    new_str[size + 1] = '\0';

    // Log the modified string
    if (config->log_level >= LOG_INFO) {
        fprintf(stderr, "Modified string: %s\n", new_str);
    }

    // Release the semaphore
    sem_post(sem);

    return new_str;
}
