        clock_gettime(CLOCK_REALTIME, &current_time);

        // Iterate over the list and purge outdated entries
        for (size_t i = 0; i < list->num_entries; i++) {
            // Check if the entry is outdated
            if (list->entries[i].crc_indication_rel8_tag.crflag == 1 &&
                current_time.tv_sec - list->entries[i].rx_ue_information_tag.timestamp > OUTDATED_ENTRY_THRESHOLD) {
                // Remove the outdated entry from the list
                remove_entry(list, i);
            }
        }
    }

    // Unlock the list for other threads to access
    pthread_mutex_unlock(&list_lock);
}

// Define the function to remove an entry from the list
void remove_entry(LIST_DATA_STRUCTURE *list, size_t index) {
    // Lock the list for thread safety
    pthread_mutex_lock(&list_lock);

    // Shift all entries after the removed entry to fill the gap
    for (size_t i = index; i < list->num_entries - 1; i++) {
        list->entries[i] = list->entries[i + 1];
    }

    // Decrement the number of entries in the list
    list->num_entries--;

    // Unlock the list for other threads to access
    pthread_mutex_unlock(&list_lock);
}

// Define the function to add a new entry to the list
void add_entry(LIST_DATA_STRUCTURE *list, NFAPI_CRC_INDICATION_PDU_T *new_entry) {
    // Lock the list for thread safety
    pthread_mutex_lock(&list_lock);

    // Check if there is enough space in the list to add a new entry
    if (list->num_entries < MAX_LIST_SIZE) {
        // Add the new entry to the end of the list
        list->entries[list->num_entries++] = *new_entry;
    } else {
        // Purge outdated entries from the list if necessary
        purge_outdated_entries(list);

        // Check if there is still enough space in the list to add a new entry
        if (list->num_entries < MAX_LIST_SIZE) {
            // Add the new entry to the end of the list
            list->entries[list->num_entries++] = *new_entry;
        } else {
            // Unlock the list for other threads to access
            pthread_mutex_unlock(&list_lock);

            // Log an error message indicating that the list is full
            printf("List is full\n");
        }
    }

    // Unlock the list for other threads to access
    pthread_mutex_unlock(&list_lock);
}

// Define the function to retrieve a random entry from the list
NFAPI_CRC_INDICATION_PDU_T *get_random_entry(LIST_DATA_STRUCTURE *list) {
    // Lock the list for thread safety
    pthread_mutex_lock(&list_lock);

    // Check if there are any entries in the list
    if (list->num_entries > 0) {
        // Get a random index between 0 and the number of entries in the list
        size_t random_index = rand() % list->num_entries;

        // Return the entry at the random index
        return &list->entries[random_index];
    } else {
        // Unlock the list for other threads to access
        pthread_mutex_unlock(&list_lock);

        // Log an error message indicating that the list is empty
        printf("List is empty\n");

        // Return NULL
        return NULL;
    }
}
