void process_file_paths(char **file_paths, int num_file_paths, config_t *config) {
    // Validate the input list for null pointers and ensure the batch size is a positive integer
    if (file_paths == NULL || num_file_paths <= 0 || config->batch_size <= 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    // Sort the list of file paths alphabetically before processing
    qsort(file_paths, num_file_paths, sizeof(char *), compare_file_paths);

    // Group file paths into batches of no more than the specified size
    int batch_size = config->batch_size;
    char **batch_start = file_paths;
    char **batch_end = file_paths + num_file_paths - 1;
    while (batch_start <= batch_end) {
        // Add all child files to the current batch if it is a directory
        if (is_directory(batch_start)) {
            int num_child_files = get_num_child_files(batch_start);
            for (int i = 0; i < num_child_files; i++) {
                char *child_file_path = get_child_file_path(batch_start, i);
                if (is_accessible(child_file_path)) {
                    batch_end++;
                    *batch_end = child_file_path;
                } else {
                    fprintf(stderr, "Warning: %s is not accessible\n", child_file_path);
                }
            }
        }

        // Flush the current batch if it exceeds the size limit
        int num_files_in_batch = batch_end - batch_start + 1;
        if (num_files_in_batch > batch_size) {
            flush_batch(batch_start, batch_end);
            batch_start = batch_end + 1;
        } else {
            batch_start++;
