        if (!is_accessible(file_path)) {
            fprintf(stderr, "Warning: %s is not accessible\n", file_path);
        } else {
            process_file(file_path);
        }
    }

    // Optimize for memory usage by reusing memory structures where possible and minimizing allocations
    free(file_paths);
}

