    DIR *dir = opendir(directory);
    if (dir == NULL) {
        fprintf(stderr, "Error: %s is not a valid directory\n", directory);
        return -1;
    }
    int num_child_files = 0;
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") && strcmp(entry->d_name, "..")) {
            num_child_files++;
        }
    }
    closedir(dir);
    return num_child_files;
}

// Helper function to get the child file path at a given index in a directory
