    DIR *dir = opendir(directory);
    if (dir == NULL) {
        fprintf(stderr, "Error: %s is not a valid directory\n", directory);
        return NULL;
    }
    struct dirent *entry;
    int i = 0;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") && strcmp(entry->d_name, "..")) {
            if (i == index) {
                closedir(dir);
                return entry->d_name;
            }
            i++;
        }
    }
    closedir(dir);
    fprintf(stderr, "Error: %s does not have a child file at index %d\n", directory, index);
    return NULL;
}

