// Define the list data structure to store the NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    int size;
    int capacity;
    NFAPI_CRC_INDICATION_PDU_T* entries;
} LIST_T;

// Define the synchronization primitives to ensure thread safety
#define LOCK(lock) pthread_mutex_lock(&lock)
#define UNLOCK(lock) pthread_mutex_unlock(&lock)

// Define the function to manage the list of NFAPI_CRC_INDICATION_PDU_T structures
void manage_list(LIST_T* list, int num_threads) {
    // Initialize the list with a default capacity
    if (list->capacity == 0) {
        list->capacity = 16;
        list->entries = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
    }

    // Purge outdated entries from the list periodically
    if (list->size > 0 && list->size % 10 == 0) {
        LOCK(list->lock);
        for (int i = 0; i < list->size; i++) {
            NFAPI_CRC_INDICATION_PDU_T* entry = &list->entries[i];
            if (entry->crc_indication_rel8.crflag == 1) {
                // Remove the outdated entry from the list
                memmove(&list->entries[i], &list->entries[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->size - i));
                list->size--;
            }
        }
        UNLOCK(list->lock);
    }
}

// Define the function to add a new entry to the list
void add_entry(LIST_T* list, NFAPI_CRC_INDICATION_PDU_T* entry) {
    LOCK(list->lock);
    if (list->size == list->capacity) {
        // Increase the capacity of the list by 16 if it is full
        int new_capacity = list->capacity + 16;
        NFAPI_CRC_INDICATION_PDU_T* new_entries = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        memcpy(new_entries, list->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->size);
        free(list->entries);
        list->entries = new_entries;
        list->capacity = new_capacity;
    }
    // Add the new entry to the end of the list
    memcpy(&list->entries[list->size], entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size++;
    UNLOCK(list->lock);
}

// Define the function to retrieve an entry from the list by its index
NFAPI_CRC_INDICATION_PDU_T* get_entry(LIST_T* list, int index) {
    if (index < 0 || index >= list->size) {
        return NULL;
    }
    return &list->entries[index];
}

// Define the function to remove an entry from the list by its index
void remove_entry(LIST_T* list, int index) {
    if (index < 0 || index >= list->size) {
        return;
    }
    LOCK(list->lock);
    // Remove the entry from the list
    memmove(&list->entries[index], &list->entries[index + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->size - index));
    list->size--;
    UNLOCK(list->lock);
}

// Define the function to retrieve the size of the list
int get_size(LIST_T* list) {
    return list->size;
}

// Define the function to retrieve the capacity of the list
int get_capacity(LIST_T* list) {
    return list->capacity;
}
