        num_records = max_num_records;
        mempool_size = max_num_records * sizeof(DATA_RECORD_T);
        mempool = malloc(mempool_size);
    }

    // Add the new NFAPI_CRC_INDICATION_PDU_T structure to the list
    pdu->next = NULL;
    if (head == NULL) {
        head = pdu;
    } else {
        tail->next = pdu;
    }
    tail = pdu;

    // Unlock the mutex after accessing the list
    pthread_mutex_unlock(&mutex);
}

// Define the function to dynamically allocate an array of DATA_RECORD_T structures
DATA_RECORD_T* allocate_records(int num_records) {
    // Lock the mutex before accessing the memory pool
    pthread_mutex_lock(&mutex);

    // Check if there is enough space in the memory pool to allocate the requested number of records
    if (mempool_size - mempool_used < num_records * sizeof(DATA_RECORD_T)) {
        // Reallocate the memory pool with a larger size if necessary
        int new_size = max_num_records + num_records;
        void* new_mempool = realloc(mempool, new_size);
        if (new_mempool == NULL) {
            // Handle the error by logging it to a file and returning NULL
            fprintf(stderr, "Error: Failed to allocate memory for %d records\n", num_records);
            log_error("Failed to allocate memory for %d records", num_records);
            return NULL;
        } else {
            mempool = new_mempool;
            mempool_size = new_size;
        }
    }

    // Allocate the requested number of DATA_RECORD_T structures from the memory pool
    DATA_RECORD_T* records = (DATA_RECORD_T*)mempool + mempool_used;
    mempool_used += num_records * sizeof(DATA_RECORD_T);

    // Unlock the mutex after accessing the memory pool
    pthread_mutex_unlock(&mutex);

    return records;
}

