    // Check if the threshold for purging outdated entries is set and update it if necessary
    if (threshold == 0) {
        char* threshold_str = getenv(ENV_VAR);
        if (threshold_str != NULL) {
            threshold = atoi(threshold_str);
        } else {
            threshold = THRESHOLD_CONFIG;
