    private static final String SUBSTRING_TO_REPLACE = "old"; // substring to replace with "new"
    private static final String SUBSTRING_TO_ADD = "new"; // substring to add to each line

    public static List<String> processFile(String inputFilePath, String targetSubstring) throws IOException {
        if (inputFilePath == null || targetSubstring == null) {
            throw new IllegalArgumentException("Input file path and target substring cannot be null");
        }

        // create a thread pool with a fixed number of threads to manage the processing of lines concurrently
        ExecutorService executor = Executors.newFixedThreadPool(4);

        List<String> transformedContent = new ArrayList<>();

        try (BufferedReader reader = new BufferedReader(new FileReader(inputFilePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                // transform the line to uppercase and replace all occurrences of the target substring with "new"
                String transformedLine = line.toUpperCase().replaceAll(targetSubstring, SUBSTRING_TO_ADD);

                // validate that the resulting string length does not exceed the maximum size for each line
                if (transformedLine.length() > MAX_LINE_LENGTH) {
                    System.err.println("Error: Line " + lineNumber + " is too long");
                    return null;
                }

                // add the transformed line to the list of transformed content
                transformedContent.add(transformedLine);
            }
        } catch (IOException e) {
            System.err.println("Error reading file: " + e.getMessage());
            return null;
        } finally {
            executor.shutdown(); // shut down the thread pool when processing is complete
        }

        return transformedContent;
    }

    public static String combineCertificateAndPrivateKey(OAuthRequest oauthRequest) throws IOException {
        if (oauthRequest == null) {
            throw new IllegalArgumentException("OAuth request cannot be null");
        }

        // fetch the private key and certificate from the specified location in the OAuth request
        String privateKey = fetchPrivateKey(oauthRequest);
        String certificate = fetchCertificate(oauthRequest);

        if (privateKey == null || certificate == null) {
            throw new IOException("Error fetching private key or certificate");
        }

        // combine the private key and certificate into a single PEM file
        return privateKey + "\n" + certificate;
    }

    private static String fetchPrivateKey(OAuthRequest oauthRequest) throws IOException {
        if (oauthRequest == null) {
            throw new IllegalArgumentException("OAuth request cannot be null");
        }

        // validate the OAuth request and handle exceptions appropriately to prevent unauthorized access
        if (!validateOAuthRequest(oauthRequest)) {
            throw new IOException("Invalid OAuth request");
        }

        // fetch the private key from the specified location in the OAuth request
        String privateKey = readPrivateKeyFromFile(oauthRequest.getPrivateKeyPath());

        if (privateKey == null) {
            throw new IOException("Error reading private key file");
        }

        return privateKey;
    }

    private static String fetchCertificate(OAuthRequest oauthRequest) throws IOException {
        if (oauthRequest == null) {
            throw new IllegalArgumentException("OAuth request cannot be null");
        }

        // validate the OAuth request and handle exceptions appropriately to prevent unauthorized access
        if (!validateOAuthRequest(oauthRequest)) {
            throw new IOException("Invalid OAuth request");
        }

        // fetch the certificate from the specified location in the OAuth request
        String certificate = readCertificateFromFile(oauthRequest.getCertificatePath());

        if (certificate == null) {
            throw new IOException("Error reading certificate file");
        }

        return certificate;
    }

    private static boolean validateOAuthRequest(OAuthRequest oauthRequest) {
        // validate the OAuth request and handle exceptions appropriately to prevent unauthorized access
        if (oauthRequest == null) {
            throw new IllegalArgumentException("OAuth request cannot be null");
        }

        // validate that the private key and certificate paths are valid and accessible
        if (!isValidPath(oauthRequest.getPrivateKeyPath()) || !isValidPath(oauthRequest.getCertificatePath())) {
            return false;
        }

        return true;
    }

    private static boolean isValidPath(String path) {
        // validate that the specified path is valid and accessible
        if (path == null || !new File(path).exists()) {
            return false;
        }

        return true;
    }

    private static String readPrivateKeyFromFile(String filePath) throws IOException {
        // read the private key from the specified file path
        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            StringBuilder builder = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                builder.append(line);
            }
            return builder.toString();
        } catch (IOException e) {
            throw new IOException("Error reading private key file");
        }
    }

    private static String readCertificateFromFile(String filePath) throws IOException {
        // read the certificate from the specified file path
        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            StringBuilder builder = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                builder.append(line);
            }
            return builder.toString();
        } catch (IOException e) {
            throw new IOException("Error reading certificate file");
        }
    }
}
