    if (file_paths == NULL || max_batch_size <= 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    // Initialize variables
    int batch_size = 0;
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = NULL;
    char **batch_file_paths = NULL;

    // Iterate over the file paths and process each one
    for (int i = 0; i < max_batch_size; i++) {
        // Check if the current file path is null or empty
        if (file_paths[i] == NULL || strlen(file_paths[i]) == 0) {
            continue;
        }

        // Check if the current file path exists and is accessible
        struct stat sb;
        if (stat(file_paths[i], &sb) != 0) {
            fprintf(stderr, "File %s does not exist or is inaccessible\n", file_paths[i]);
            continue;
        }

        // Check if the current file path is a directory and recursively process its child files
        if (S_ISDIR(sb.st_mode)) {
            DIR *dir = opendir(file_paths[i]);
            struct dirent *entry;
            while ((entry = readdir(dir)) != NULL) {
                // Skip hidden files and directories
                if (strncmp(entry->d_name, ".", 2) == 0 || strncmp(entry->d_name, "..", 3) == 0) {
                    continue;
                }

                // Resolve symbolic links and add the target to the batch
                char *target = realpath(entry->d_name, NULL);
                if (target != NULL) {
                    int index = find_file_index(batch_file_paths, target);
                    if (index == -1) {
                        // Add the file path to the batch
                        batch_file_paths = realloc(batch_file_paths, sizeof(char *) * (batch_size + 1));
                        batch_file_paths[batch_size] = target;
                        batch_size++;
                    } else {
                        // File path already exists in the batch, skip it
                        free(target);
                    }
                }
            }
            closedir(dir);
        } else {
            // Add the file path to the batch
            int index = find_file_index(batch_file_paths, file_paths[i]);
            if (index == -1) {
                batch_file_paths = realloc(batch_file_paths, sizeof(char *) * (batch_size + 1));
                batch_file_paths[batch_size] = strdup(file_paths[i]);
                batch_size++;
            } else {
                // File path already exists in the batch, skip it
            }
        }

        // Check if the batch size exceeds the maximum batch size and flush the current batch
        if (batch_size >= max_batch_size) {
            process_batch(pdu_list, batch_file_paths, batch_size, config);
            free(batch_file_paths);
            batch_file_paths = NULL;
            batch_size = 0;
        }
    }

    // Process the remaining files in the batch
    if (batch_size > 0) {
        process_batch(pdu_list, batch_file_paths, batch_size, config);
        free(batch_file_paths);
    }
}

// Function to find the index of a file path in a list of file paths
int find_file_index(char **file_paths, char *file_path) {
    for (int i = 0; i < batch_size; i++) {
        if (strcmp(file_paths[i], file_path) == 0) {
            return i;
        }
    }
    return -1;
}

// Function to process a batch of file paths, creating and populating a list of NFAPI_CRC_INDICATION_PDU_T structures
void process_batch(NFAPI_CRC_INDICATION_PDU_T *pdu_list, char **file_paths, int batch_size, external_configuration_structure *config) {
    // Initialize variables
    NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;
    int pdu_count = 0;

    // Iterate over the file paths and create a list of NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < batch_size; i++) {
        // Create a new NFAPI_CRC_INDICATION_PDU_T structure
        pdu = realloc(pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (pdu_count + 1));
        memset(&pdu[pdu_count], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Populate the NFAPI_CRC_INDICATION_PDU_T structure with valid data
        pdu[pdu_count].rx_ue_information = config->rx_ue_information;
        pdu[pdu_count].rnti = config->rnti;
        pdu[pdu_count].crc_indication_rel8.crflag = rand() % 2;

        // Increment the PDU count
        pdu_count++;
    }

    // Log the processed batch of file paths and the number of PDUs created
    fprintf(stderr, "Processed batch of %d file paths with %d PDUs\n", batch_size, pdu_count);
}
