char* append_directory_separator(const char* path, int max_depth, bool absolute) {
    // Validate input parameters
    if (max_depth < 0) {
        return NULL;
    }

    // Get the current working directory
    char cwd[PATH_MAX];
    getcwd(cwd, sizeof(cwd));

    // Normalize the path and check its depth
    char* normalized_path = realpath(path, NULL);
    int depth = 0;
    while (normalized_path != NULL && strcmp(normalized_path, cwd) != 0) {
        ++depth;
        normalized_path = dirname(normalized_path);
    }

    // Handle symbolic links and canonical paths
    char* canonical_path = realpath(path, NULL);
    if (canonical_path != NULL && strcmp(canonical_path, path) != 0) {
        normalized_path = canonical_path;
    }

    // Append a directory separator if necessary
    char* new_path = NULL;
    if (depth < max_depth) {
        size_t len = strlen(normalized_path);
        new_path = malloc(len + 2);
        strcpy(new_path, normalized_path);
        new_path[len] = '/';
        new_path[len + 1] = '\0';
    } else {
        new_path = strdup(normalized_path);
    }

    // Clean up and return the result
    free(canonical_path);
    free(normalized_path);
    return new_path;
}
