import threading
import time

class CacheManager:
    def __init__(self):
        self.cache = {}
        self.lock = threading.Lock()
        self.session_ids = set()
        self.memory_usage = 0
        self.max_memory_usage = 100 # in MB
        self.global_pool = []
        self.available_entries = {}
        self.expiration_policies = {
            "lru": self.least_recently_used,
            "lfu": self.least_frequently_used
        }
        self.serialization_formats = {
            "json": self.serialize_to_json,
            "yaml": self.serialize_to_yaml,
            "bson": self.serialize_to_bson
        }

    def get(self, key):
        with self.lock:
            if key in self.cache:
                self.update_lru(key)
                return self.cache[key]
            else:
                return None

    def set(self, key, value, expiration=None, serialization_format="json"):
        with self.lock:
            if key in self.cache:
                self.update_lru(key)
            else:
                self.add_new_entry(key, value, expiration, serialization_format)

    def delete(self, key):
        with self.lock:
            if key in self.cache:
                del self.cache[key]
                self.update_lru(key)

    def update_lru(self, key):
        entry = self.cache[key]
        entry["last_accessed"] = time.time()
        self.available_entries[entry["session_id"]].remove(key)
        self.available_entries[entry["session_id"]].appendleft(key)

    def add_new_entry(self, key, value, expiration=None, serialization_format="json"):
        if expiration is None:
            expiration = 0
        session_id = self.generate_session_id()
        entry = {
            "key": key,
            "value": value,
            "expiration": time.time() + expiration,
            "last_accessed": time.time(),
            "serialization_format": serialization_format,
            "session_id": session_id
        }
        self.cache[key] = entry
        self.available_entries[session_id].append(key)

    def least_recently_used(self):
        with self.lock:
            key = self.available_entries[0][-1]
            del self.available_entries[0][-1]
            return key

    def least_frequently_used(self):
        with self.lock:
            key = self.available_entries[0][0]
            del self.available_entries[0][0]
            return key

    def serialize_to_json(self, entry):
        json_data = json.dumps(entry["value"])
        return json_data.encode("utf-8")

    def serialize_to_yaml(self, entry):
        yaml_data = yaml.dump(entry["value"])
        return yaml_data.encode("utf-8")

    def serialize_to_bson(self, entry):
        bson_data = bson.dumps(entry["value"])
        return bson_data.encode("utf-8")

    def deserialize_from_json(self, data):
        value = json.loads(data)
        return value

    def deserialize_from_yaml(self, data):
        value = yaml.load(data)
        return value

    def deserialize_from_bson(self, data):
        value = bson.loads(data)
        return value

    def generate_session_id(self):
        session_id = str(uuid.uuid4())
        self.session_ids.add(session_id)
        return session_id

    def monitor_memory_usage(self):
        with self.lock:
            if self.memory_usage > self.max_memory_usage:
                print("Memory usage exceeded threshold, triggering alert")
            else:
                print("Memory usage within threshold")

    def resize_global_pool(self, new_size):
        with self.lock:
            if new_size > len(self.available_entries):
                for _ in range(new_size - len(self.available_entries)):
                    self.available_entries.append([])
            else:
                for _ in range(len(self.available_entries) - new_size):
                    del self.available_entries[-1]

    def allocate_entry(self, session_id):
        with self.lock:
            if len(self.available_entries[session_id]) > 0:
                key = self.available_entries[session_id].pop()
                return key
            else:
                return None

    def deallocate_entry(self, session_id, key):
        with self.lock:
            if key in self.cache:
                del self.cache[key]
                self.available_entries[session_id].append(key)

    def serialize_to_file(self, filepath):
        with open(filepath, "wb") as f:
            for key in self.cache:
                entry = self.cache[key]
                serialized_entry = self.serialize_entry(entry)
                f.write(serialized_entry)

    def deserialize_from_file(self, filepath):
        with open(filepath, "rb") as f:
            while True:
                try:
                    serialized_entry = f.read(1024)
                    if not serialized_entry:
                        break
                    entry = self.deserialize_entry(serialized_entry)
                    self.cache[entry["key"]] = entry
                except Exception as e:
                    print("Error deserializing cache entry from file")
                    raise e

    def serialize_entry(self, entry):
        serialized_entry = {
            "key": entry["key"],
            "value": self.serialize_to_json(entry),
            "expiration": entry["expiration"],
            "last_accessed": entry["last_accessed"],
            "serialization_format": entry["serialization_format"]
        }
        return serialized_entry

    def deserialize_entry(self, serialized_entry):
        entry = {
            "key": serialized_entry["key"],
            "value": self.deserialize_from_json(serialized_entry["value"]),
            "expiration": serialized_entry["expiration"],
            "last_accessed": serialized_entry["last_accessed"],
            "serialization_format": serialized_entry["serialization_format"]
        }
        return entry
