    std::lock_guard<std::mutex> lock(_mutex);
    if (validateIPAddress(config.ipAddress)) {
        if (!isUniqueIPAddress(config.ipAddress)) {
            throw std::runtime_error("IP address is not unique");
        }
        _interfaces[config.interfaceID] = config;
        _interfaceStatuses[config.interfaceID].isActive = false;
        _interfaceStatuses[config.interfaceID].isValid = true;
    } else {
        throw std::runtime_error("Invalid IP address");
    }
}

void NetworkManager::removeInterface(const std::string& interfaceID) {
    std::lock_guard<std::mutex> lock(_mutex);
    if (_interfaces.find(interfaceID) != _interfaces.end()) {
        _interfaces.erase(interfaceID);
        _interfaceStatuses.erase(interfaceID);
    } else {
        throw std::runtime_error("Interface not found");
    }
}

