class NetworkInterface {
 public:
  NetworkInterface(const std::string& interfaceID, const std::string& ipAddress, const std::string& subnetMask) :
    interfaceID_(interfaceID), ipAddress_(ipAddress), subnetMask_(subnetMask) {}

  const std::string& getInterfaceID() const { return interfaceID_; }
  const std::string& getIPAddress() const { return ipAddress_; }
  const std::string& getSubnetMask() const { return subnetMask_; }

 private:
  std::string interfaceID_;
  std::string ipAddress_;
  std::string subnetMask_;
};

class NetworkManager {
 public:
  NetworkManager(int numInterfaces) : numInterfaces_(numInterfaces), interfaces_(), cache_() {}

  void addInterface(const std::string& interfaceID, const std::string& ipAddress, const std::string& subnetMask) {
    std::lock_guard<std::mutex> lock(interfacesMutex_);
    interfaces_.push_back(NetworkInterface(interfaceID, ipAddress, subnetMask));
  }

  void removeInterface(const std::string& interfaceID) {
    std::lock_guard<std::mutex> lock(interfacesMutex_);
    for (auto it = interfaces_.begin(); it != interfaces_.end(); ++it) {
      if (it->getInterfaceID() == interfaceID) {
        interfaces_.erase(it);
        break;
      }
    }
  }

  void updateInterface(const std::string& interfaceID, const std::string& ipAddress, const std::string& subnetMask) {
    std::lock_guard<std::mutex> lock(interfacesMutex_);
    for (auto it = interfaces_.begin(); it != interfaces_.end(); ++it) {
      if (it->getInterfaceID() == interfaceID) {
        it->setIPAddress(ipAddress);
        it->setSubnetMask(subnetMask);
        break;
      }
    }
  }

  void setNetworkStatus(const std::string& interfaceID, NetworkStatus status) {
    std::lock_guard<std::mutex> lock(interfacesMutex_);
    for (auto it = interfaces_.begin(); it != interfaces_.end(); ++it) {
      if (it->getInterfaceID() == interfaceID) {
        it->setNetworkStatus(status);
        break;
      }
    }
  }

  NetworkStatus getNetworkStatus(const std::string& interfaceID) const {
    std::lock_guard<std::mutex> lock(interfacesMutex_);
    for (auto it = interfaces_.begin(); it != interfaces_.end(); ++it) {
      if (it->getInterfaceID() == interfaceID) {
        return it->getNetworkStatus();
      }
    }
    return NetworkStatus::INACTIVE;
  }

 private:
  int numInterfaces_;
  std::vector<NetworkInterface> interfaces_;
  std::unordered_map<std::string, NetworkStatus> cache_;
  std::mutex interfacesMutex_;
};
