}

int getFileInfo(char *filePath, FileInfo *fileInfo) {
    struct stat fileStat;
    if (stat(filePath, &fileStat) != 0) {
        return -1;
    }

    // Get the size of the file
    fileInfo->fileSize = fileStat.st_size;

    // Get the last modified time of the file
    struct tm *lastModifiedTime = localtime(&fileStat.st_mtime);
    if (lastModifiedTime == NULL) {
        return -1;
    }

    // Get the last accessed time of the file
    struct tm *lastAccessedTime = localtime(&fileStat.st_atime);
    if (lastAccessedTime == NULL) {
        return -1;
    }

    // Get the creation time of the file
    struct tm *creationTime = localtime(&fileStat.st_ctime);
    if (creationTime == NULL) {
        return -1;
    }

    // Get the permissions of the file
    mode_t permissions = fileStat.st_mode;

    // Get the owner of the file
    uid_t owner = fileStat.st_uid;

    // Get the group of the file
    gid_t group = fileStat.st_gid;

    return 0;
}

void flushCurrentBatch(char **currentBatch, int currentBatchSize) {
    for (int i = 0; i < currentBatchSize; i++) {
        char *filePath = currentBatch[i];
        free(filePath);
    }
}

char *generateNewFileName(char *filePath) {
    // Get the original filename and extension
    char *originalFilename = strrchr(filePath, '/');
    if (originalFilename == NULL) {
        return NULL;
    }
    originalFilename++;
    char *extension = strrchr(originalFilename, '.');
    if (extension == NULL) {
        return NULL;
    }

    // Count the number of vowels in the original filename
    int numVowels = 0;
    for (int i = 0; i < strlen(originalFilename); i++) {
        if (isalpha(originalFilename[i]) && isvowel(originalFilename[i])) {
            numVowels++;
        }
    }

    // Generate a new filename with a random sequence of digits and the original extension
    char *newFileName = malloc(MAX_FILENAME_LENGTH);
    if (newFileName == NULL) {
        return NULL;
    }
    sprintf(newFileName, "%s%0*d%s", originalFilename, MAX_DIGITS_IN_EXTENSION, rand() % 10000, extension);

    // Check if the new filename is unique within the specified directory
    DIR *dir = opendir(filePath);
    if (dir == NULL) {
        return newFileName;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char *childFilePath = entry->d_name;
        if (strlen(childFilePath) == 0 || childFilePath[0] == '.') {
            continue;
        }

        // Check if the file is a symbolic link and resolve it
        struct stat childFileStat;
        if (lstat(childFilePath, &childFileStat) != 0) {
            fprintf(stderr, "Warning: Could not get information about file %s\n", childFilePath);
            continue;
        }

        // Check if the file is a regular file and compare its name with the new filename
        if (S_ISREG(childFileStat.st_mode)) {
            char *childFileName = strrchr(childFilePath, '/');
            if (childFileName == NULL) {
                continue;
            }
            childFileName++;
            if (strcmp(newFileName, childFileName) == 0) {
                free(newFileName);
                newFileName = generateNewFileName(filePath);
                break;
            }
        }
    }

    return newFileName;
}
