    // Check if the length of the input string is less than the size limit
    if (strlen(input_string) >= size_limit) {
        return NULL;
    }

    // If the string length equals the size limit and truncate is set to true, append a '/' to the end of the string
    if (truncate && strlen(input_string) == size_limit) {
        char* modified_string = malloc(size_limit + 1);
        memcpy(modified_string, input_string, size_limit);
        modified_string[size_limit] = '/';
        return modified_string;
    }

    // If the string length is greater than the size limit, return NULL
    if (strlen(input_string) > size_limit) {
        return NULL;
    }

    // If the string length equals the size limit and truncate is false, return the input string unchanged
    if (!truncate && strlen(input_string) == size_limit) {
        char* modified_string = malloc(size_limit + 1);
        memcpy(modified_string, input_string, size_limit);
        return modified_string;
    }

    // If the string length is less than the size limit, return a copy of the input string
    char* modified_string = malloc(size_limit + 1);
    memcpy(modified_string, input_string, strlen(input_string));
    return modified_string;
}
