void manage_dynamic_list(int N, int seed) {
    // Initialize variables for memory usage and number of structures allocated
    int num_structures = 0;
    int num_allocated = 0;

    // Allocate memory for the list of structures
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    if (!list) {
        // Handle memory allocation failure gracefully
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize random number generator with seed value
    srand(seed);

    // Populate list of structures with valid data
    for (int i = 0; i < N; i++) {
        // Set RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG fields randomly
        list[i].rx_ue_information_tag = rand() % 100;
        list[i].rnti = rand() % 1000000000;
        list[i].crc_indication_rel8_tag = rand() % 100;

        // Set PUCCH资源配置 and RACH_CONFIG_DLSCH fields randomly
        list[i].pucch_resource_config = rand() % 100;
        list[i].rach_config_dlsch.rach_flag = rand() % 100;
    }

    // Monitor memory usage and adjust number of structures allocated based on real-time system metrics
    while (num_allocated < N) {
        // Check if there is enough physical RAM available for the current number of structures
        if (get_available_ram() > 0.5 * get_total_ram()) {
            // Allocate additional structures and update variables accordingly
            num_structures += 1;
            num_allocated += 1;
        } else {
            // Deallocate structures if necessary to maintain memory efficiency
            if (num_allocated > 0) {
                num_allocated -= 1;
                free(list[num_structures - 1]);
            }
        }
    }

    // Periodically purge outdated entries from the list to maintain memory efficiency
    while (get_available_ram() < 0.2 * get_total_ram()) {
        // Check if there are any outdated entries in the list
        for (int i = 0; i < num_structures; i++) {
            // If an entry is older than a certain threshold, remove it from the list
            if (list[i].rx_ue_information_tag < get_current_time() - 10) {
                free(list[i]);
                num_allocated -= 1;
                break;
            }
        }
    }

    // Generate new configuration ID based on an existing one, modifying its format with a sequence of random hexadecimal digits and appending a specific identifier type
    char *new_config_id = (char *)malloc(sizeof(char) * 128);
    if (!new_config_id) {
        // Handle memory allocation failure gracefully
        printf("Memory allocation failed\n");
        return;
    }
    sprintf(new_config_id, "%03x%04x%06x", rand() % 1000, rand() % 1000000, rand() % 1000000);
    strcat(new_config_id, "ID");

    // Return new configuration ID and free memory allocated for the list of structures
    return new_config_id;
}
