        return 0;
    }

    // Create a new OAuth2 token structure and populate it with the parsed data
    struct oauth2_token *token = malloc(sizeof(struct oauth2_token));
    token->access_token = strdup(access_token);
    token->expires_in = expires_in;

    // Check if a refresh token is present in the JSON object
    const char *refresh_token = json_object_get_string(json_object_object_get(json, "refresh_token"));
    if (refresh_token != NULL && strlen(refresh_token) > 0) {
        token->refresh_token = strdup(refresh_token);
    } else {
        token->refresh_token = NULL;
    }

    // Verify the OAuth2 access token and return the result
    int valid = verify_oauth2_token(token);
    free(token);
