// Function to initialize and manage the cipher modes
EVP_CIPHER* initCipher(const char* mode) {
    // Check if the specified mode is supported
    if (!strcmp(mode, "ECB")) {
        return EVP_get_cipherbyname("aes-128-ecb");
    } else if (!strcmp(mode, "EDE")) {
        return EVP_get_cipherbyname("aes-192-ede");
    } else if (!strcmp(mode, "EDE3")) {
        return EVP_get_cipherbyname("aes-256-ede3");
    } else if (!strcmp(mode, "CFB")) {
        return EVP_get_cipherbyname("aes-128-cfb");
    } else {
        // Invalid cipher mode specified
        return NULL;
    }
}

// Function to parse and verify a JSON object string representing an OAuth2 access token response
bool parseOAuth2Token(const char* json_str, EVP_CIPHER* cipher) {
    // Parse the JSON object string
    json_object* obj = json_tokener_parse(json_str);
    if (!obj) {
        // Invalid OAuth2 token response format
        return false;
    }

    // Check for required fields in the JSON object
    json_object* access_token = json_object_object_get(obj, "access_token");
    json_object* expires_in = json_object_object_get(obj, "expires_in");
    json_object* token_type = json_object_object_get(obj, "token_type");
    if (!access_token || !expires_in || !token_type) {
        // Missing required field in OAuth2 token response
        return false;
    }

    // Check the value of the token type field
    const char* token_type_str = json_object_get_string(token_type);
    if (strcmp(token_type_str, VALID_TOKEN_TYPES)) {
        // Invalid value for token type field
        return false;
    }

    // Check the expires in field is a positive integer
    long expires_in_val = json_object_get_int(expires_in);
    if (expires_in_val <= 0) {
        // Expires in field is not a positive integer
        return false;
    }

    // Initialize the cipher with the specified mode and key
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        // Failed to initialize the cipher context
        return false;
    }
    int ret = EVP_EncryptInit(ctx, cipher, NULL, NULL);
    if (ret != 1) {
        // Failed to initialize the cipher
        return false;
    }

    // Return true if all checks passed
    return true;
}

// Function to handle encryption and decryption operations
bool encryptDecrypt(const char* mode, const char* json_str, unsigned char* key) {
    // Initialize the cipher with the specified mode and key
    EVP_CIPHER* cipher = initCipher(mode);
    if (!cipher) {
        // Invalid cipher mode specified
        return false;
    }
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        // Failed to initialize the cipher context
        return false;
    }
    int ret = EVP_EncryptInit(ctx, cipher, key, NULL);
    if (ret != 1) {
        // Failed to initialize the cipher
        return false;
    }

    // Parse and verify the OAuth2 access token response
    bool valid = parseOAuth2Token(json_str, cipher);
    if (!valid) {
        // Invalid OAuth2 token response format or missing required fields
        return false;
    }

    // Encrypt/decrypt the JSON object string
    unsigned char* encrypted = NULL;
    int len = 0;
    ret = EVP_EncryptUpdate(ctx, encrypted, &len, json_str, strlen(json_str));
    if (ret != 1) {
        // Failed to encrypt/decrypt the JSON object string
        return false;
    }

    // Return true if all operations succeeded
    return true;
}
