            json_t* transactions = json_object_get(root, "transactions");
            size_t num_transactions = json_array_size(transactions);
            for (size_t i = 0; i < num_transactions; i++) {
                json_t* transaction = json_array_get(transactions, i);
                int age = json_integer_value(json_object_get(transaction, "age"));
                int weighted_sum = json_integer_value(json_object_get(transaction, "weighted_sum"));
                if (age > 3) {
                    continue;
                }
                num_transactions++;
                weighted_sum += weighted_sum;
            }
        }
        metrics.num_transactions = num_transactions;
        metrics.max_weighted_sum = max_weighted_sum;
        transaction_id = json_string_value(json_object_get(root, "transaction_id"));
