import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.regex.Pattern;

public class JSONProcessor {
    private static final int THREAD_POOL_SIZE = 10;
    private static final String LOG_FILE_NAME = "processing.log";

    public List<ObjectModel> processJSONFile(String filePath) throws IOException {
        if (filePath == null || !new File(filePath).exists()) {
            throw new IllegalArgumentException("Invalid input file path");
        }

        ExecutorService executor = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
        List<ObjectModel> objectModels = new ArrayList<>();

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(filePath)))) {
            String line;
            while ((line = reader.readLine()) != null) {
                executor.submit(() -> {
                    ObjectModel objectModel = parseJSONLine(line);
                    if (objectModel != null) {
                        objectModels.add(objectModel);
                    }
                });
            }
        } catch (IOException e) {
            logError("Failed to read input file", e);
        } finally {
            executor.shutdown();
        }

        return objectModels;
    }

    private ObjectModel parseJSONLine(String line) {
        try {
            JSONObject jsonObject = new JSONObject(line);
            ObjectModel objectModel = new ObjectModel();
            objectModel.setId(jsonObject.getString("id"));
            objectModel.setName(jsonObject.getString("name"));
            objectModel.setAge(jsonObject.getInt("age"));
            return objectModel;
        } catch (JSONException e) {
            logError("Failed to parse JSON line", e);
            return null;
        }
    }

    private void logError(String message, Throwable t) {
        System.err.println(message);
        t.printStackTrace();
    }
}
