    logEntry->timestamp = time(NULL);
    logEntry->deviceID = deviceID;
    logEntry->eventCode = eventCode;
    strncpy(logEntry->eventMessage, eventMessage, maxEventMessageLength);
    logEntry->eventMessage[maxEventMessageLength] = '\0';

    // Release the lock on the log pool
    pthread_mutex_unlock(&logPoolMutex);

    return 0;
}

// Define the function to serialize and deserialize the allocated DeviceStatusLog entries to a binary file format
int serializeDeviceStatusLog(const char* filename) {
    // Open the file for writing
