#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <zlib.h>
#include <pthread.h>
#include <errno.h>

#define DEFAULT_DELIMITER "\n"
#define DEFAULT_OUTPUT_FILE "linecount.txt"
#define DEFAULT_LOGGING_LEVEL 1
#define MAX_LINE_LENGTH 4096
#define MIN_THREADS 2
#define MAX_THREADS 8

typedef struct {
    char *filename;
    int fd;
} file_info_t;

typedef struct {
    int line_count;
    long total_char_count;
    double average_line_length;
} file_stats_t;

void print_usage(char *progname) {
    printf("Usage: %s [options] <input files>\n", progname);
    printf("\nOptions:\n");
    printf("  -d, --delimiter=<delim>   Use a custom delimiter for line counting (default: \\n)\n");
    printf("  -o, --output=<file>       Write the final line count to a file instead of stdout\n");
    printf("  -l, --logging=<level>     Set the logging level (1-5, default: 1)\n");
    printf("  -s, --skip=<lines>        Skip every nth line or lines containing specific keywords\n");
    printf("  -c, --compress=<lib>      Select compression library for handling .gz files (default: zlib)\n");
    printf("  -a, --async               Use asynchronous I/O to minimize I/O operations\n");
    printf("  -m, --monitor             Monitor CPU and memory usage during execution\n");
}

void log_message(int level, char *msg) {
    if (level <= DEFAULT_LOGGING_LEVEL) {
        printf("%s\n", msg);
    }
}

void log_error(char *msg) {
    fprintf(stderr, "%s\n", msg);
}

int open_file(char *filename) {
    int fd = -1;
    if (strcmp(filename, "-") == 0) {
        fd = STDIN_FILENO;
    } else {
        fd = open(filename, O_RDONLY);
        if (fd < 0) {
            log_error("Failed to open file");
        }
    }
    return fd;
}

void close_file(int fd) {
    if (fd != STDIN_FILENO) {
        close(fd);
    }
}

char *read_line(int fd, char *delimiter) {
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fd)) != -1) {
        if (strcmp(delimiter, line) == 0) {
            break;
        }
    }
    return line;
}

void process_file(char *filename, int fd, file_stats_t *stats) {
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fd)) != -1) {
        stats->line_count++;
        stats->total_char_count += strlen(line);
        if (stats->average_line_length == 0) {
            stats->average_line_length = strlen(line);
        } else {
            stats->average_line_length = (stats->average_line_length + strlen(line)) / 2;
        }
    }
}

void *process_file_thread(void *arg) {
    file_info_t *file_info = (file_info_t *) arg;
    char *filename = file_info->filename;
    int fd = file_info->fd;
    file_stats_t stats;
    memset(&stats, 0, sizeof(stats));
    process_file(filename, fd, &stats);
    close_file(fd);
    return (void *) &stats;
}

int main(int argc, char *argv[]) {
    int opt;
    char *delimiter = DEFAULT_DELIMITER;
    char *output_file = DEFAULT_OUTPUT_FILE;
    int logging_level = DEFAULT_LOGGING_LEVEL;
    int skip_lines = 0;
    char *compress_lib = "zlib";
    int async = 0;
    int monitor = 0;
    while ((opt = getopt(argc, argv, "d:o:l:s:c:am")) != -1) {
        switch (opt) {
            case 'd':
                delimiter = optarg;
                break;
            case 'o':
                output_file = optarg;
                break;
            case 'l':
                logging_level = atoi(optarg);
                break;
            case 's':
                skip_lines = atoi(optarg);
                break;
            case 'c':
                compress_lib = optarg;
                break;
            case 'a':
                async = 1;
                break;
            case 'm':
                monitor = 1;
                break;
            default:
                print_usage(argv[0]);
                return 1;
        }
    }
    if (optind >= argc) {
        log_message(logging_level, "No input files specified");
        print_usage(argv[0]);
        return 1;
    }
    int num_files = argc - optind;
    file_info_t *file_infos = (file_info_t *) malloc(num_files * sizeof(file_info_t));
    for (int i = 0; i < num_files; i++) {
        char *filename = argv[optind + i];
        int fd = open_file(filename);
        if (fd < 0) {
            log_error("Failed to open file");
            return 1;
        }
        file_infos[i].filename = filename;
        file_infos[i].fd = fd;
    }
    int num_threads = MIN(num_files, MAX_THREADS);
    pthread_t *threads = (pthread_t *) malloc(num_threads * sizeof(pthread_t));
    file_stats_t stats;
    memset(&stats, 0, sizeof(stats));
    for (int i = 0; i < num_files; i++) {
        if (i % num_threads == 0) {
            pthread_create(&threads[i / num_threads], NULL, process_file_thread, &file_infos[i]);
        } else {
            pthread_join(threads[(i - 1) / num_threads], (void **) &stats);
            stats.line_count += file_infos[i].line_count;
            stats.total_char_count += file_infos[i].total_char_count;
        }
    }
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], (void **) &stats);
    }
    if (monitor) {
        log_message(logging_level, "CPU usage: %d%%", get_cpu_usage());
        log_message(logging_level, "Memory usage: %d MB", get_memory_usage());
    }
    if (skip_lines > 0) {
        stats.line_count -= skip_lines;
    }
    char *output = malloc(1024);
    sprintf(output, "%ld\n", stats.line_count);
    if (strcmp(output_file, "-") == 0) {
        printf("%s", output);
    } else {
        FILE *fout = fopen(output_file, "w");
        fprintf(fout, "%s", output);
        fclose(fout);
    }
    free(output);
    return 0;
}
