void process_file(char *filename, char *delimiter) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // initialize variables for tracking line and word counts
    int line_count = 0;
    int word_count = 0;

    // read each line of the file and increment counters as needed
    char *line = NULL;
    size_t len = 0;
    while (getline(&line, &len, file) != -1) {
        if (strcmp(delimiter, "\n") == 0) { // check for newline delimiter
            line_count++;
        } else { // otherwise, count the number of delimiters in the line
            int num_delims = 0;
            char *token = strtok(line, delimiter);
            while (token != NULL) {
                num_delims++;
                token = strtok(NULL, delimiter);
            }
            line_count += num_delims;
        }

        // count the number of words in the line
        char *word = strtok(line, " ");
        while (word != NULL) {
            word_count++;
            word = strtok(NULL, " ");
        }
    }

    // close the file and update the file information struct
    fclose(file);
    file_info_t *info = malloc(sizeof(file_info_t));
    info->filename = filename;
    info->line_count = line_count;
    info->word_count = word_count;
}

// define a function to process multiple files in parallel using threads
void process_files(char **filenames, int num_files, char *delimiter) {
