        infos[i].filename = filenames[i];
        infos[i].line_count = 0;
        infos[i].word_count = 0;
    }

    // create a thread for each file and start the thread
    pthread_t *threads = malloc(sizeof(pthread_t) * num_files);
    for (int i = 0; i < num_files; i++) {
        pthread_create(&threads[i], NULL, process_file, filenames[i]);
    }

    // wait for all threads to finish and update the file information structs
    for (int i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
        infos[i].line_count = line_count;
        infos[i].word_count = word_count;
    }

    // free the memory allocated for the threads and file information structs
    free(threads);
