    file_info_t* info = (file_info_t*)arg;
    FILE* fp = fopen(info->filename, "r");
    if (!fp) {
        perror("fopen");
        return NULL;
    }
    char line[1024];
    while (fgets(line, sizeof(line), fp)) {
        info->line_count++;
    }
    fclose(fp);
    return NULL;
}

// Function to skip commented lines in a file
void* skip_comments(void* arg) {
    file_info_t* info = (file_info_t*)arg;
    FILE* fp = fopen(info->filename, "r");
    if (!fp) {
        perror("fopen");
        return NULL;
    }
    char line[1024];
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, info->comment_delimiter, strlen(info->comment_delimiter))) {
            info->line_count++;
        }
    }
    fclose(fp);
    return NULL;
}

int main(int argc, char* argv[]) {
