#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <zlib.h>
#include <time.h>
#include <errno.h>
#include <stdbool.h>

// Define constants for file types
#define REGULAR_FILE 0
#define GZIPPED_FILE 1
#define DIRECTORY 2

// Define a structure to store information about each input file
typedef struct {
    char *path; // Path to the file
    int type; // Type of the file (regular, gzipped, or directory)
    long size; // Size of the file in bytes
} InputFile;

// Define a structure to store information about each line in a file
typedef struct {
    char *line; // The actual line of text
    int length; // Length of the line in characters
} Line;

// Function to determine the type of a given file
int get_file_type(char *path) {
    struct stat st;
    if (stat(path, &st) == -1) {
        return -1; // Error checking
    }
    if (S_ISREG(st.st_mode)) {
        return REGULAR_FILE;
    } else if (S_ISDIR(st.st_mode)) {
        return DIRECTORY;
    } else if (strstr(path, ".gz") != NULL) {
        return GZIPPED_FILE;
    } else {
        return -1; // Unsupported file type
    }
}

// Function to read a line from a file and store it in a Line structure
Line *read_line(char *path, FILE *file) {
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        if (strlen(line) > 0) { // Ignore empty lines
            break;
        }
    }
    if (read == -1) {
        return NULL; // End of file reached
    }
    Line *result = malloc(sizeof(Line));
    result->line = line;
    result->length = strlen(line);
    return result;
}

// Function to count the number of lines in a file
long count_lines(char *path) {
    int type = get_file_type(path);
    if (type == -1) {
        return -1; // Error checking
    }
    FILE *file = fopen(path, "r");
    if (file == NULL) {
        return -1; // Error checking
    }
    long count = 0;
    Line *line = read_line(path, file);
    while (line != NULL) {
        count++;
        free(line->line);
        line = read_line(path, file);
    }
    fclose(file);
    return count;
}

// Function to sum the number of lines across all files
long sum_lines(int argc, char **argv) {
    long total = 0;
    for (int i = 1; i < argc; i++) {
        InputFile *file = malloc(sizeof(InputFile));
        file->path = argv[i];
        file->type = get_file_type(argv[i]);
        if (file->type == -1) {
            free(file);
            continue; // Error checking
        }
        if (file->type == GZIPPED_FILE) {
            file->size = gz_get_uncompressed_size(argv[i]);
        } else {
            struct stat st;
            if (stat(argv[i], &st) == -1) {
                free(file);
                continue; // Error checking
            }
            file->size = st.st_size;
        }
        total += count_lines(argv[i]);
        free(file);
    }
    return total;
}

// Function to print usage information if no input files are provided
void print_usage() {
    printf("Usage: ./program [input file 1] [input file 2] ...\n");
}

int main(int argc, char **argv) {
    // Check for the correct number of arguments
    if (argc < 2) {
        print_usage();
        return 0;
    }

    // Sum the number of lines across all files
    long total = sum_lines(argc, argv);

    // Print the result to standard output
    printf("Total number of lines: %ld\n", total);

    return 0;
}']

