#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <assert.h>

// Define the maximum size of the array
#define MAX_ARRAY_SIZE 50000

// Define the memory pool size
#define MEMORY_POOL_SIZE (MAX_ARRAY_SIZE * sizeof(struct Transaction))

// Define the structure for a transaction
struct Transaction {
    int id;
    char* merchant;
    char* customerID;
    double amount;
    char* date;
};

// Define the function to process the transactions
void processTransactions(char* inputFile, char* outputFile, char* filterString, char* aggregationType, int verbosityLevel, bool validateTransactions, bool logProcessing) {
    // Initialize the memory pool
    struct MemoryPool* memoryPool = createMemoryPool(MEMORY_POOL_SIZE);

    // Open the input file and output file
    FILE* inputFilePtr = fopen(inputFile, "r");
    FILE* outputFilePtr = fopen(outputFile, "w");

    // Check if the files were opened successfully
    if (inputFilePtr == NULL || outputFilePtr == NULL) {
        printf("Error: Unable to open file\n");
        return;
    }

    // Define the array for storing transactions
    struct Transaction* transactions = malloc(MAX_ARRAY_SIZE * sizeof(struct Transaction));

    // Initialize the number of processed transactions and total processing time
    int numProcessedTransactions = 0;
    double totalProcessingTime = 0.0;

    // Define the start time for measuring processing time
    clock_t startTime = clock();

    // Read the input file line by line
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, inputFilePtr)) != -1) {
        // Check if the line is a comment or empty
        if (line[0] == '#' || line[0] == '\n') {
            continue;
        }

        // Parse the transaction from the line
        struct Transaction* transaction = parseTransaction(line, memoryPool);

        // Check if the transaction is valid
        if (validateTransactions && !isValidTransaction(transaction)) {
            printf("Error: Malformed transaction entry\n");
            continue;
        }

        // Add the transaction to the array
        transactions[numProcessedTransactions++] = *transaction;

        // Check if the array is full
        if (numProcessedTransactions == MAX_ARRAY_SIZE) {
            printf("Warning: Array is full\n");
            break;
        }
    }

    // Close the input file and output file
    fclose(inputFilePtr);
    fclose(outputFilePtr);

    // Define the end time for measuring processing time
    clock_t endTime = clock();

    // Calculate the total processing time
    double totalProcessingTime = (double)(endTime - startTime) / CLOCKS_PER_SEC;

    // Print the number of processed transactions and total processing time
    printf("Number of processed transactions: %d\n", numProcessedTransactions);
    printf("Total processing time: %.2lf seconds\n", totalProcessingTime);

    // Filter and aggregate the transactions based on the filter string and aggregation type
    struct Transaction* filteredTransactions = filterAndAggregate(transactions, numProcessedTransactions, filterString, aggregationType);

    // Write the filtered transactions to the output file
    writeFilteredTransactions(filteredTransactions, numProcessedTransactions, outputFilePtr);

    // Free the memory pool and the array
    freeMemoryPool(memoryPool);
    free(transactions);
}

// Define the function to create a memory pool
struct MemoryPool* createMemoryPool(size_t size) {
    struct MemoryPool* memoryPool = malloc(sizeof(struct MemoryPool));
    memoryPool->size = size;
    memoryPool->used = 0;
    memoryPool->memory = malloc(size);
    return memoryPool;
}

// Define the function to free a memory pool
void freeMemoryPool(struct MemoryPool* memoryPool) {
    free(memoryPool->memory);
    free(memoryPool);
}

// Define the function to parse a transaction from a line
struct Transaction* parseTransaction(char* line, struct MemoryPool* memoryPool) {
    // Allocate memory for the transaction
    struct Transaction* transaction = allocateMemory(sizeof(struct Transaction), memoryPool);

    // Parse the transaction ID
    char* idString = strtok(line, ",");
    transaction->id = atoi(idString);

    // Parse the merchant name
    char* merchantString = strtok(NULL, ",");
    transaction->merchant = allocateMemory(strlen(merchantString) + 1, memoryPool);
    strcpy(transaction->merchant, merchantString);

    // Parse the customer ID
    char* customerIDString = strtok(NULL, ",");
    transaction->customerID = allocateMemory(strlen(customerIDString) + 1, memoryPool);
    strcpy(transaction->customerID, customerIDString);

    // Parse the amount
    char* amountString = strtok(NULL, ",");
    transaction->amount = atof(amountString);

    // Parse the date
    char* dateString = strtok(NULL, "\n");
    transaction->date = allocateMemory(strlen(dateString) + 1, memoryPool);
    strcpy(transaction->date, dateString);

    return transaction;
}

// Define the function to allocate memory from a memory pool
void* allocateMemory(size_t size, struct MemoryPool* memoryPool) {
    // Check if there is enough space in the memory pool
    if (memoryPool->used + size > memoryPool->size) {
        printf("Error: Out of memory\n");
        return NULL;
    }

    // Allocate memory from the memory pool
    void* memory = memoryPool->memory + memoryPool->used;
    memoryPool->used += size;

    return memory;
}

// Define the function to validate a transaction
bool isValidTransaction(struct Transaction* transaction) {
    // Check if the transaction ID is valid
    if (transaction->id < 0) {
        printf("Error: Invalid transaction ID\n");
        return false;
    }

    // Check if the merchant name is valid
    if (strlen(transaction->merchant) == 0) {
        printf("Error: Invalid merchant name\n");
        return false;
    }

    // Check if the customer ID is valid
    if (strlen(transaction->customerID) == 0) {
        printf("Error: Invalid customer ID\n");
        return false;
    }

    // Check if the amount is valid
    if (transaction->amount < 0.0) {
        printf("Error: Invalid transaction amount\n");
        return false;
    }

    // Check if the date is valid
    if (strlen(transaction->date) == 0) {
        printf("Error: Invalid transaction date\n");
        return false;
    }

    return true;
}

// Define the function to filter and aggregate transactions based on a filter string and aggregation type
struct Transaction* filterAndAggregate(struct Transaction* transactions, int numTransactions, char* filterString, char* aggregationType) {
    // Initialize the filtered transactions array
    struct Transaction* filteredTransactions = malloc(numTransactions * sizeof(struct Transaction));

    // Filter and aggregate the transactions based on the filter string and aggregation type
    int numFilteredTransactions = 0;
    for (int i = 0; i < numTransactions; i++) {
        struct Transaction* transaction = &transactions[i];

        // Check if the transaction matches the filter string
        bool match = true;
        char* token = strtok(filterString, " ");
        while (token != NULL) {
            if (strcmp(token, "merchant") == 0 && strcmp(transaction->merchant, token + 1) != 0) {
                match = false;
                break;
            } else if (strcmp(token, "customerID") == 0 && strcmp(transaction->customerID, token + 1) != 0) {
                match = false;
                break;
            } else if (strcmp(token, "amount") == 0 && transaction->amount < atof(token + 1)) {
                match = false;
                break;
            } else if (strcmp(token, "date") == 0 && strcmp(transaction->date, token + 1) != 0) {
                match = false;
                break;
            }
            token = strtok(NULL, " ");
        }

        // Add the transaction to the filtered transactions array if it matches the filter string
        if (match) {
            filteredTransactions[numFilteredTransactions++] = *transaction;
        }
    }

    // Aggregate the filtered transactions based on the aggregation type
    switch (aggregationType[0]) {
        case 'b':
            return aggregateByMerchant(filteredTransactions, numFilteredTransactions);
        case 'c':
            return aggregateByCustomerID(filteredTransactions, numFilteredTransactions);
        case 'd':
            return aggregateByDate(filteredTransactions, numFilteredTransactions);
    }
}

// Define the function to aggregate transactions by merchant
struct Transaction* aggregateByMerchant(struct Transaction* transactions, int numTransactions) {
    // Initialize the aggregated transactions array
    struct Transaction* aggregatedTransactions = malloc(numTransactions * sizeof(struct Transaction));

    // Aggregate the transactions by merchant
    for (int i = 0; i < numTransactions; i++) {
        struct Transaction* transaction = &transactions[i];

        // Check if the transaction is already in the aggregated transactions array
        bool found = false;
        for (int j = 0; j < i; j++) {
            struct Transaction* aggregatedTransaction = &aggregatedTransactions[j];
            if (strcmp(transaction->merchant, aggregatedTransaction->merchant) == 0) {
                found = true;
                break;
            }
        }

        // Add the transaction to the aggregated transactions array if it is not already in it
        if (!found) {
            aggregatedTransactions[i] = *transaction;
        }
    }

    return aggregatedTransactions;
}

// Define the function to aggregate transactions by customer ID
struct Transaction* aggregateByCustomerID(struct Transaction* transactions, int numTransactions) {
    // Initialize the aggregated transactions array
    struct Transaction* aggregatedTransactions = malloc(numTransactions * sizeof(struct Transaction));

    // Aggregate the transactions by customer ID
    for (int i = 0; i < numTransactions; i++) {
        struct Transaction* transaction = &transactions[i];

        // Check if the transaction is already in the aggregated transactions array
        bool found = false;
        for (int j = 0; j < i; j++) {
            struct Transaction* aggregatedTransaction = &aggregatedTransactions[j];
            if (strcmp(transaction->customerID, aggregatedTransaction->customerID) == 0) {
                found = true;
                break;
            }
        }

        // Add the transaction to the aggregated transactions array if it is not already in it
        if (!found) {
            aggregatedTransactions[i] = *transaction;
        }
    }

    return aggregatedTransactions;
}

// Define the function to aggregate transactions by date
struct Transaction* aggregateByDate(struct Transaction* transactions, int numTransactions) {
    // Initialize the aggregated transactions array
    struct Transaction* aggregatedTransactions = malloc(numTransactions * sizeof(struct Transaction));

    // Aggregate the transactions by date
    for (int i = 0; i < numTransactions; i++) {
        struct Transaction* transaction = &transactions[i];

        // Check if the transaction is already in the aggregated transactions array
        bool found = false;
        for (int j = 0; j < i; j++) {
            struct Transaction* aggregatedTransaction = &aggregatedTransactions[j];
            if (strcmp(transaction->date, aggregatedTransaction->date) == 0) {
