}

// Define the function to write filtered transactions to a file
void writeFilteredTransactions(struct Transaction* filteredTransactions, int numFilteredTransactions, FILE* outputFilePtr) {
    // Write the header for the output file
    fprintf(outputFilePtr, "Transaction ID,Merchant,Customer ID,Amount,Date\n");

