void parse_json_file(const char *filename, int data_format) {
    // Open the input file and check for errors
    FILE *input = fopen(filename, "r");
    if (input == NULL) {
        printf("Error: unable to open input file %s\n", filename);
        return;
    }

    // Allocate memory for the transaction array
    int size = 50000;
    Transaction *transactions = malloc(size * sizeof(Transaction));
    if (transactions == NULL) {
        printf("Error: unable to allocate memory for transactions\n");
        fclose(input);
        return;
    }

    // Initialize the transaction array with default values
    for (int i = 0; i < size; i++) {
        transactions[i].id = NULL;
        transactions[i].date = NULL;
        transactions[i].merchant = NULL;
        transactions[i].customer_id = NULL;
        transactions[i].amount = 0.0f;
    }

    // Read the input file and parse each transaction
    int line_number = 1;
    while (fgets(line, sizeof(line), input) != NULL) {
        // Parse the JSON object from the current line
        json_object *json = json_parse(line);
        if (json == NULL) {
            printf("Error: unable to parse JSON object on line %d\n", line_number);
            fclose(input);
            return;
        }

        // Extract the transaction ID, date, merchant, and amount from the JSON object
        char *id = json_get_string(json, "id");
        char *date = json_get_string(json, "date");
        char *merchant = json_get_string(json, "merchant");
        float amount = (float)json_get_number(json, "amount");

        // Check for errors in the extracted data
        if (id == NULL || date == NULL || merchant == NULL || amount < 0.0f) {
            printf("Error: invalid transaction data on line %d\n", line_number);
            json_free(json);
            fclose(input);
            return;
        }

        // Add the transaction to the array
        transactions[line_number - 1].id = id;
        transactions[line_number - 1].date = date;
        transactions[line_number - 1].merchant = merchant;
        transactions[line_number - 1].amount = amount;

        // Free the JSON object and increment the line number
        json_free(json);
        line_number++;
    }

    // Close the input file and return the transaction array
    fclose(input);
    return transactions;
}

