    if (input == NULL) {
        printf("Error: unable to open input file %s\n", filename);
        return;
    }

    // Allocate memory for the transaction array
    int size = 50000;
    Transaction *transactions = malloc(size * sizeof(Transaction));
    if (transactions == NULL) {
        printf("Error: unable to allocate memory for transactions\n");
        fclose(input);
        return;
    }

    // Initialize the transaction array with default values
    for (int i = 0; i < size; i++) {
        transactions[i].id = NULL;
        transactions[i].date = NULL;
        transactions[i].merchant = NULL;
        transactions[i].customer_id = NULL;
        transactions[i].amount = 0.0f;
    }

    // Read the input file and parse each transaction
    int line_number = 1;
    while (fgets(line, sizeof(line), input) != NULL) {
        // Parse the CSV record from the current line
        char *record = strtok(line, ",");
        if (record == NULL) {
            printf("Error: unable to parse CSV record on line %d\n", line_number);
            fclose(input);
            return;
        }

        // Extract the transaction ID, date, merchant, and amount from the CSV record
        char *id = strtok(record, ",");
        char *date = strtok(NULL, ",");
        char *merchant = strtok(NULL, ",");
        float amount = (float)strtod(strtok(NULL, ","), NULL);

        // Check for errors in the extracted data
        if (id == NULL || date == NULL || merchant == NULL || amount < 0.0f) {
            printf("Error: invalid transaction data on line %d\n", line_number);
            fclose(input);
            return;
        }

        // Add the transaction to the array
        transactions[line_number - 1].id = id;
        transactions[line_number - 1].date = date;
        transactions[line_number - 1].merchant = merchant;
        transactions[line_number - 1].amount = amount;

        // Increment the line number and free the record
        line_number++;
        free(record);
    }

    // Close the input file and return the transaction array
    fclose(input);
    return transactions;
}

// Define a function to filter and aggregate transactions based on multiple criteria
void filter_and_aggregate(Transaction *transactions, int num_transactions, char *filter_string, char *aggregation_type, int verbosity_level, int validate_transactions, int log_processing, int data_format) {
    // Check for errors in the input parameters
    if (transactions == NULL || num_transactions <= 0 || filter_string == NULL || aggregation_type == NULL || verbosity_level < 0 || validate_transactions < 0 || log_processing < 0 || data_format < 0) {
        printf("Error: invalid input parameters\n");
        return;
    }

    // Initialize the filter and aggregation criteria
    FilterCriteria *filter = parse_filter_criteria(filter_string);
    AggregationType aggregation = parse_aggregation_type(aggregation_type);

    // Allocate memory for the filtered transactions array
    int num_filtered_transactions = 0;
    Transaction *filtered_transactions = malloc(num_transactions * sizeof(Transaction));
    if (filtered_transactions == NULL) {
        printf("Error: unable to allocate memory for filtered transactions\n");
        return;
    }

    // Iterate over the input transactions and filter them based on the criteria
    for (int i = 0; i < num_transactions; i++) {
        Transaction *transaction = &transactions[i];
        if (filter_transaction(transaction, filter)) {
            filtered_transactions[num_filtered_transactions++] = *transaction;
        }
    }

    // Aggregate the filtered transactions based on the specified criteria
    switch (aggregation) {
        case AGGREGATION_BY_DATE:
            aggregate_by_date(filtered_transactions, num_filtered_transactions);
            break;
        case AGGREGATION_BY_MERCHANT:
            aggregate_by_merchant(filtered_transactions, num_filtered_transactions);
            break;
        case AGGREGATION_BY_CUSTOMER_ID:
            aggregate_by_customer_id(filtered_transactions, num_filtered_transactions);
            break;
    }

    // Generate the report file based on the specified verbosity level
    switch (verbosity_level) {
        case VERBOSITY_LEVEL_BASIC:
            generate_basic_report(filtered_transactions, num_filtered_transactions);
            break;
        case VERBOSITY_LEVEL_DETAILED:
            generate_detailed_report(filtered_transactions, num_filtered_transactions);
            break;
    }

    // Free the memory allocated for the filtered transactions array
    free(filtered_transactions);
}

// Define a function to filter a transaction based on multiple criteria
int filter_transaction(Transaction *transaction, FilterCriteria *filter) {
    // Check for errors in the input parameters
    if (transaction == NULL || filter == NULL) {
        printf("Error: invalid input parameters\n");
        return 0;
    }

    // Apply each filter criterion to the transaction and check if it passes
    for (int i = 0; i < filter->num_criteria; i++) {
        FilterCriterion *criterion = &filter->criteria[i];
        switch (criterion->type) {
            case CRITERION_TYPE_DATE:
                if (!check_date(transaction, criterion)) {
                    return 0;
                }
                break;
            case CRITERION_TYPE_MERCHANT:
                if (!check_merchant(transaction, criterion)) {
                    return 0;
                }
                break;
            case CRITERION_TYPE_CUSTOMER_ID:
                if (!check_customer_id(transaction, criterion)) {
                    return 0;
                }
                break;
        }
    }

    // If all criteria are met, the transaction passes the filter
    return 1;
}

// Define a function to check if a transaction date matches a specified date range
int check_date(Transaction *transaction, FilterCriterion *criterion) {
    // Check for errors in the input parameters
    if (transaction == NULL || criterion == NULL) {
        printf("Error: invalid input parameters\n");
        return 0;
    }

    // Extract the transaction date and compare it to the specified range
    char *date = transaction->date;
    int start_year = criterion->start_year;
    int end_year = criterion->end_year;
    if (start_year > 0 && end_year > 0) {
        int year = atoi(date);
        return year >= start_year && year <= end_year;
    } else if (start_year > 0) {
        int year = atoi(date);
        return year >= start_year;
    } else if (end_year > 0) {
        int year = atoi(date);
        return year <= end_year;
    }

    // If no date range is specified, the transaction passes the filter
    return 1;
}

// Define a function to check if a transaction merchant matches a specified merchant name
int check_merchant(Transaction *transaction, FilterCriterion *criterion) {
    // Check for errors in the input parameters
    if (transaction == NULL || criterion == NULL) {
        printf("Error: invalid input parameters\n");
        return 0;
    }

    // Extract the transaction merchant and compare it to the specified name
    char *merchant = transaction->merchant;
    char *name = criterion->name;
    if (strcmp(merchant, name) == 0) {
        return 1;
    }

    // If no merchant name is specified, the transaction passes the filter
    return 0;
}

// Define a function to check if a transaction customer ID matches a specified customer ID
int check_customer_id(Transaction *transaction, FilterCriterion *criterion) {
    // Check for errors in the input parameters
    if (transaction == NULL || criterion == NULL) {
        printf("Error: invalid input parameters\n");
        return 0;
    }

    // Extract the transaction customer ID and compare it to the specified ID
    char *customer_id = transaction->customer_id;
    char *id = criterion->id;
    if (strcmp(customer_id, id) == 0) {
        return 1;
    }

    // If no customer ID is specified, the transaction passes the filter
    return 0;
}

// Define a function to aggregate transactions by date
void aggregate_by_date(Transaction *transactions, int num_transactions) {
    // Check for errors in the input parameters
    if (transactions == NULL || num_transactions <= 0) {
        printf("Error: invalid input parameters\n");
        return;
    }

    // Initialize the aggregation array with default values
    int size = 50000;
    Aggregate *aggregates = malloc(size * sizeof(Aggregate));
    if (aggregates == NULL) {
        printf("Error: unable to allocate memory for aggregates\n");
        return;
    }

    // Iterate over the input transactions and aggregate them by date
    for (int i = 0; i < num_transactions; i++) {
        Transaction *transaction = &transactions[i];
        char *date = transaction->date;
        int year = atoi(date);
        int month = atoi(date + 5);
        int day = atoi(date + 8);
        Aggregate *aggregate = find_aggregate(year, month, day, aggregates, size);
        if (aggregate == NULL) {
            printf("Error: unable to find aggregate for date %d-%d-%d\n", year, month, day);
            return;
        }
        aggregate->count++;
        aggregate->amount += transaction->amount;
    }

    // Free the memory allocated for the aggregation array
    free(aggregates);
}

// Define a function to find an aggregate by date
Aggregate *find_aggregate(int year, int month, int day, Aggregate *aggregates, int size) {
    // Check for errors in the input parameters
    if (year < 0 || month < 0 || day < 0 || aggregates == NULL || size <= 0) {
        printf("Error: invalid input parameters\n");
        return NULL;
    }

    // Iterate over the aggregation array and find the aggregate for the specified date
    for (int i = 0; i < size; i++) {
        Aggregate *aggregate = &aggregates[i];
        if (aggregate->year == year && aggregate->month == month && aggregate->day == day) {
            return aggregate;
        }
    }

    // If no aggregate is found, create a new one and add it to the array
    Aggregate *new_aggregate = malloc(sizeof(Aggregate));
    if (new_aggregate == NULL) {
        printf("Error: unable to allocate memory for new aggregate\n");
        return NULL;
    }
    new_aggregate->year = year;
    new_aggregate->month = month;
    new_aggregate->day = day;
    new_aggregate->count = 0;
    new_aggregate->amount = 0.0;
    aggregates[size++] = *new_aggregate;
    return new_aggregate;
}

// Define a function to aggregate transactions by merchant
void aggregate_by_merchant(Transaction *transactions, int num_transactions) {
    // Check for errors in the input parameters
    if (transactions == NULL || num_transactions <= 0) {
        printf("Error: invalid input parameters\n");
        return;
    }

    // Initialize the aggregation array with default values
    int size = 50000;
    Aggregate *aggregates = malloc(size * sizeof(Aggregate));
    if (aggregates == NULL) {
        printf("Error: unable to allocate memory for aggregates\n");
        return;
    }

    // Iterate over the input transactions and aggregate them by merchant
    for (int i = 0; i < num_transactions; i++) {
        Transaction *transaction = &transactions[i];
        char *merchant = transaction->merchant;
        Aggregate *aggregate = find_aggregate(merchant, aggregates, size);
        if (aggregate == NULL) {
            printf("Error: unable to find aggregate for merchant %s\n", merchant);
            return;
        }
        aggregate->count++;
        aggregate->amount += transaction->amount;
    }

    // Free the memory allocated for the aggregation array
    free(aggregates);
}']

