    if (!file) {
        printf("Error opening file: %s\n", filename);
        exit(1);
    }

    // Filter lines in file
    char buffer[MAX_LINE_LENGTH];
    while (fgets(buffer, MAX_LINE_LENGTH, file)) {
        if (!filter_lines || !strstr(buffer, "keyword")) {
            printf("%s", buffer);
        }
    }

    // Close file
    fclose(file);
}

void filter_words(char *filename) {
    // Open file for reading
    FILE *file = fopen(filename, "r");
    if (!file) {
        printf("Error opening file: %s\n", filename);
        exit(1);
    }

    // Filter words in file
    char buffer[MAX_LINE_LENGTH];
    while (fgets(buffer, MAX_LINE_LENGTH, file)) {
        char *token = strtok(buffer, delimiter);
        while (token) {
            if (!filter_words || !strstr(token, "keyword")) {
                printf("%s", token);
            }
            token = strtok(NULL, delimiter);
        }
    }

    // Close file
    fclose(file);
}

void sort_words() {
    // Sort words in alphabetical order
    qsort(word_list, num_words, sizeof(word_t), compare_words);
}

int compare_words(const void *a, const void *b) {
    word_t *word1 = (word_t *)a;
    word_t *word2 = (word_t *)b;
    return strcmp(word1->word, word2->word);
}

void write_output() {
    // Open output file for writing
    FILE *file = fopen(output_file, "w");
    if (!file) {
        printf("Error opening output file: %s\n", output_file);
        exit(1);
    }

    // Write sorted words to output file
    for (int i = 0; i < num_words; i++) {
        word_t *word = &word_list[i];
        fprintf(file, "%s\n", word->word);
    }

    // Close output file
    fclose(file);
}

void read_config_file() {
    // Open config file for reading
    FILE *file = fopen(config_file, "r");
    if (!file) {
        printf("Error opening config file: %s\n", config_file);
        exit(1);
    }

    // Read stop words from config file
    char buffer[MAX_LINE_LENGTH];
    while (fgets(buffer, MAX_LINE_LENGTH, file)) {
        char *token = strtok(buffer, delimiter);
        while (token) {
            if (!strstr(token, "keyword")) {
                stop_words.push_back(token);
            }
            token = strtok(NULL, delimiter);
        }
    }

    // Close config file
    fclose(file);
}
