int parse_args(int argc, char **argv) {
  // Initialize variables
  int opt;
  bool input_file = false;
  bool output_file = false;
  bool delimiter = false;
  bool encoding = false;
  bool filter = false;
  bool word_freq = false;
  char *input_filename = NULL;
  char *output_filename = NULL;
  char *delimiter_str = NULL;
  char *encoding_str = NULL;
  char *filter_pattern = NULL;
  int encoding_type = -1;

  // Parse command-line arguments
  while ((opt = getopt(argc, argv, "i:o:d:e:f:w")) != -1) {
    switch (opt) {
      case 'i':
        input_file = true;
        input_filename = optarg;
        break;
      case 'o':
        output_file = true;
        output_filename = optarg;
        break;
      case 'd':
        delimiter = true;
        delimiter_str = optarg;
        break;
      case 'e':
        encoding = true;
        encoding_str = optarg;
        break;
      case 'f':
        filter = true;
        filter_pattern = optarg;
        break;
      case 'w':
        word_freq = true;
        break;
      default:
        printf("Invalid argument\n");
        return -1;
    }
  }

  // Check for required arguments
  if (!input_file || !output_file || !delimiter || !encoding || !filter || !word_freq) {
    printf("Missing required arguments\n");
    return -1;
  }

  // Check for valid encoding type
  if (strcmp(encoding_str, "plain") && strcmp(encoding_str, "gzip")) {
    printf("Invalid encoding type\n");
    return -1;
  }

  // Set encoding type
  if (!strcmp(encoding_str, "plain")) {
    encoding_type = PLAIN;
  } else if (!strcmp(encoding_str, "gzip")) {
    encoding_type = GZIP;
  }

  // Check for valid delimiter
  if (strlen(delimiter_str) != 1 || !isgraph(delimiter_str[0])) {
    printf("Invalid delimiter\n");
    return -1;
  }

  // Set delimiter
  char delimiter = delimiter_str[0];

  // Check for valid filter pattern
  if (regcomp(&filter_pattern, filter_pattern, REG_EXTENDED | REG_NOSUB)) {
    printf("Invalid filter pattern\n");
    return -1;
  }

  // Return parsed arguments
  return input_filename, output_filename, delimiter, encoding_type, filter_pattern;
}

// Function to process a single file
void process_file(char *input_filename, char *output_filename, char delimiter, int encoding_type, regex_t *filter_pattern) {
  // Open input and output files
  FILE *input = fopen(input_filename, "r");
  FILE *output = fopen(output_filename, "w");

  // Check for file opening errors
  if (!input || !output) {
    printf("Error opening file\n");
    return;
  }

  // Initialize variables
  char line[1024];
  int line_count = 0;
  bool filter_match = false;

  // Process each line in the input file
  while (fgets(line, sizeof(line), input)) {
    // Increment line count
    line_count++;

    // Check for filter match
    if (!filter_match) {
      filter_match = regexec(&filter_pattern, line, 0, NULL, 0);
    }

    // Write line to output file
    fprintf(output, "%s", line);
  }

  // Close input and output files
  fclose(input);
  fclose(output);

  // Log processing time and line count
  printf("Processed %d lines in %f seconds\n", line_count, (double)clock() / CLOCKS_PER_SEC);
}

// Function to process multiple files concurrently
void process_files(char **input_filenames, int num_input_files, char *output_filename, char delimiter, int encoding_type, regex_t *filter_pattern) {
  // Initialize variables
  pthread_t threads[num_input_files];
  int thread_ids[num_input_files];
  bool filter_match = false;

  // Create and start threads for each input file
  for (int i = 0; i < num_input_files; i++) {
    thread_ids[i] = i;
    pthread_create(&threads[i], NULL, process_file, (void *)&thread_ids[i]);
  }

  // Join threads and update filter match flag
  for (int i = 0; i < num_input_files; i++) {
    pthread_join(threads[i], NULL);
    if (!filter_match) {
      filter_match = regexec(&filter_pattern, line, 0, NULL, 0);
    }
  }

  // Write output file
  FILE *output = fopen(output_filename, "w");
  for (int i = 0; i < num_input_files; i++) {
    fprintf(output, "%s", line);
  }
  fclose(output);

  // Log processing time and line count
  printf("Processed %d lines in %f seconds\n", line_count, (double)clock() / CLOCKS_PER_SEC);
}

// Main function
int main(int argc, char **argv) {
