#define DEFAULT_DELIMITER "\n"
#define MAX_LINE_LENGTH 1024

typedef struct {
    char *filename;
    int line_count;
} file_info_t;

void usage(char *progname) {
    printf("Usage: %s [options] <input files>\n", progname);
    printf("\nOptions:\n");
    printf("  -d, --delimiter=<delim>   Set the delimiter for line counting (default: \\n)\n");
    printf("  -o, --output=<file>       Write the final line count to a file\n");
    printf("\nExamples:\n");
    printf("  %s file1.txt file2.txt -d ','\n", progname);
    printf("  %s file1.txt file2.txt --delimiter=, --output=result.txt\n", progname);
}

int main(int argc, char **argv) {
    // Parse command line arguments
    if (argc < 2) {
        usage(argv[0]);
        return 1;
    }

    int i = 1;
    while (i < argc && strcmp(argv[i], "-d") != 0 && strcmp(argv[i], "--delimiter") != 0) {
        i++;
    }

    char *delimiter = DEFAULT_DELIMITER;
    if (i < argc && (strcmp(argv[i], "-d") == 0 || strcmp(argv[i], "--delimiter") == 0)) {
        delimiter = argv[i + 1];
        i += 2;
    }

    char *output_file = NULL;
    if (i < argc && strcmp(argv[i], "-o") == 0) {
        output_file = argv[i + 1];
        i += 2;
    } else if (i < argc && strcmp(argv[i], "--output") == 0) {
        output_file = argv[i + 1];
        i += 2;
    }

    // Initialize file information array
    int num_files = argc - i;
    file_info_t *files = malloc(num_files * sizeof(file_info_t));
    for (int j = 0; j < num_files; j++) {
        files[j].filename = argv[i + j];
        files[j].line_count = 0;
    }

    // Open input files and read lines
    for (int j = 0; j < num_files; j++) {
        FILE *file = fopen(files[j].filename, "r");
        if (!file) {
            printf("Error: unable to open file %s\n", files[j].filename);
            continue;
        }

        char line[MAX_LINE_LENGTH];
        while (fgets(line, MAX_LINE_LENGTH, file)) {
            if (strchr(delimiter, line[strlen(line) - 1])) {
                files[j].line_count++;
            } else {
                printf("Warning: ignoring line %d in file %s due to invalid delimiter\n", files[j].line_count + 1, files[j].filename);
            }
        }

        fclose(file);
    }

    // Calculate total number of lines across all files
    int total_lines = 0;
    for (int j = 0; j < num_files; j++) {
        total_lines += files[j].line_count;
    }

    // Write output to file if specified
    if (output_file) {
        FILE *outfile = fopen(output_file, "w");
        if (!outfile) {
            printf("Error: unable to open output file %s\n", output_file);
            return 1;
        }

        fprintf(outfile, "%d\n", total_lines);
        fclose(outfile);
    } else {
        printf("%d\n", total_lines);
    }

    // Clean up
    free(files);

    return 0;
}
