void process_file(file_info_t *file_info);
void aggregate_contents(FILE *output_file, char *format, int options);
void print_stats(int total_lines, int unique_words, double average_word_length);

// Main function
int main(int argc, char **argv) {
    // Check command line arguments
    if (argc < 3) {
        fprintf(stderr, "Usage: %s -%c <directory> -%c <format> [-%c] [-%c] [-%c] [-%c]\n", argv[0], OPTION_DIRECTORY, OPTION_FORMAT, OPTION_OUTPUT, OPTION_STATS, OPTION_IGNORE_CASE);
        return 1;
    }

    // Parse command line options
    int options = 0;
    char *directory = NULL;
    char *format = NULL;
    char *output_file = NULL;
    for (int i = 1; i < argc - 1; i++) {
        if (strcmp(argv[i], "-" OPTION_DIRECTORY) == 0) {
            directory = argv[++i];
        } else if (strcmp(argv[i], "-" OPTION_FORMAT) == 0) {
            format = argv[++i];
        } else if (strcmp(argv[i], "-" OPTION_OUTPUT) == 0) {
            output_file = argv[++i];
        } else if (strcmp(argv[i], "-" OPTION_STATS) == 0) {
            options |= 1 << 0;
        } else if (strcmp(argv[i], "-" OPTION_IGNORE_CASE) == 0) {
            options |= 1 << 1;
        }
    }

    // Check for required command line options
    if (!directory || !format || !output_file) {
        fprintf(stderr, "Missing required command line option\n");
        return 1;
    }

    // Open output file
    FILE *output = fopen(output_file, "w");
    if (!output) {
        perror("fopen");
        return 1;
    }

    // Process directory of text files
    process_directory(directory, options);

    // Close output file
    fclose(output);

    return 0;
}

// Process a directory of text files
void process_directory(char *directory, int options) {
    DIR *dir = opendir(directory);
    if (!dir) {
        perror("opendir");
        return;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip hidden files and directories
        if (entry->d_name[0] == '.') continue;

        // Open file for reading
        char *filename = entry->d_name;
        FILE *file = fopen(filename, "r");
        if (!file) {
            perror("fopen");
            continue;
        }

        // Process file
        process_file(filename, file, options);

        // Close file
        fclose(file);
    }

    closedir(dir);
}

// Process a single text file
void process_file(char *filename, FILE *file, int options) {
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Ignore empty lines and comments
        if (strlen(line) == 0 || line[0] == '#') continue;

        // Aggregate contents of file
        aggregate_contents(filename, line, options);
    }
}

// Aggregate the contents of a single text file
void aggregate_contents(FILE *output_file, char *format, int options) {
    // Check for supported output formats
    if (strcmp(format, FORMAT_PLAIN) != 0 && strcmp(format, FORMAT_CSV) != 0 && strcmp(format, FORMAT_JSON) != 0) {
        fprintf(stderr, "Unsupported output format: %s\n", format);
        return;
    }

    // Initialize variables for aggregation
    int total_lines = 0;
    int unique_words = 0;
    double average_word_length = 0.0;
    char *line = NULL;
    size_t line_len = 0;
    ssize_t read;

    // Read lines from file and aggregate contents
    while ((read = getline(&line, &line_len, output_file)) != -1) {
        // Ignore empty lines and comments
        if (strlen(line) == 0 || line[0] == '#') continue;

        // Increment total lines and unique words
        total_lines++;
        char *word = strtok(line, " ");
        while (word != NULL) {
            unique_words++;
            word = strtok(NULL, " ");
        }

        // Calculate average word length
        int word_length = 0;
        for (int i = 0; i < line_len; i++) {
            if (line[i] != ' ') {
                word_length++;
            } else {
                break;
            }
        }
        average_word_length += word_length / total_lines;
    }

    // Print statistics about aggregated data
    if (options & 1 << 0) {
        print_stats(total_lines, unique_words, average_word_length);
    }
}

// Print statistics about the aggregated data
void print_stats(int total_lines, int unique_words, double average_word_length) {
    printf("Total lines: %d\n", total_lines);
    printf("Unique words: %d\n", unique_words);
    printf("Average word length: %.2f\n", average_word_length);
}
