#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

// Define the structure for DeviceStatusLog entries
typedef struct {
    time_t timestamp;
    int deviceID;
    int eventCode;
    char* eventMessage;
} DeviceStatusLog;

// Define the global pool of available DeviceStatusLog entries
static DeviceStatusLog* logPool = NULL;
static size_t logPoolSize = 0;
static pthread_mutex_t logPoolMutex = PTHREAD_MUTEX_INITIALIZER;

// Define the function to initialize the global pool of available DeviceStatusLog entries
void initLogPool(size_t initialSize) {
    // Allocate memory for the log pool
    logPool = (DeviceStatusLog*)malloc(initialSize * sizeof(DeviceStatusLog));
    if (!logPool) {
        perror("Failed to allocate memory for log pool");
        exit(1);
    }
    // Initialize the log pool size
    logPoolSize = initialSize;
}

// Define the function to resize the global pool of available DeviceStatusLog entries
void resizeLogPool(size_t newSize) {
    // Acquire the lock on the log pool mutex
    pthread_mutex_lock(&logPoolMutex);
    // Reallocate memory for the log pool
    DeviceStatusLog* newLogPool = (DeviceStatusLog*)realloc(logPool, newSize * sizeof(DeviceStatusLog));
    if (!newLogPool) {
        perror("Failed to reallocate memory for log pool");
        exit(1);
    }
    // Update the log pool size and pointer
    logPool = newLogPool;
    logPoolSize = newSize;
    // Release the lock on the log pool mutex
    pthread_mutex_unlock(&logPoolMutex);
}

// Define the function to allocate a DeviceStatusLog entry from the global pool
DeviceStatusLog* allocLogEntry() {
    // Acquire the lock on the log pool mutex
    pthread_mutex_lock(&logPoolMutex);
    // Check if the log pool is full
    if (logPoolSize == 0) {
        // Reallocate memory for the log pool
        resizeLogPool(logPoolSize * 2);
    }
    // Allocate a new DeviceStatusLog entry from the log pool
    DeviceStatusLog* logEntry = &logPool[logPoolSize - 1];
    logPoolSize--;
    // Release the lock on the log pool mutex
    pthread_mutex_unlock(&logPoolMutex);
    return logEntry;
}

// Define the function to free a DeviceStatusLog entry back to the global pool
void freeLogEntry(DeviceStatusLog* logEntry) {
    // Acquire the lock on the log pool mutex
    pthread_mutex_lock(&logPoolMutex);
    // Add the log entry back to the log pool
    logPool[logPoolSize] = *logEntry;
    logPoolSize++;
    // Release the lock on the log pool mutex
    pthread_mutex_unlock(&logPoolMutex);
}

// Define the function to validate a DeviceStatusLog entry
int validateLogEntry(DeviceStatusLog* logEntry) {
    // Check if the device ID is valid
    if (logEntry->deviceID < 0 || logEntry->deviceID > 1000) {
        return -1;
    }
    // Check if the event code is valid
    if (logEntry->eventCode < 0 || logEntry->eventCode > 1000) {
        return -2;
    }
    // Check if the event message is valid
    if (strlen(logEntry->eventMessage) > 100) {
        return -3;
    }
    return 0;
}

// Define the function to add a DeviceStatusLog entry to the global pool
void addLogEntry(DeviceStatusLog* logEntry, int requestID) {
    // Validate the log entry
    if (validateLogEntry(logEntry) != 0) {
        return;
    }
    // Acquire the lock on the log pool mutex
    pthread_mutex_lock(&logPoolMutex);
    // Check if the log pool is full
    if (logPoolSize == 0) {
        // Reallocate memory for the log pool
        resizeLogPool(logPoolSize * 2);
    }
    // Add the log entry to the log pool
    logPool[logPoolSize - 1] = *logEntry;
    logPoolSize--;
    // Release the lock on the log pool mutex
    pthread_mutex_unlock(&logPoolMutex);
}

// Define the function to remove a DeviceStatusLog entry from the global pool
void removeLogEntry(DeviceStatusLog* logEntry, int requestID) {
    // Acquire the lock on the log pool mutex
    pthread_mutex_lock(&logPoolMutex);
    // Check if the log entry is in the log pool
    for (size_t i = 0; i < logPoolSize; i++) {
        if (&logPool[i] == logEntry) {
            // Remove the log entry from the log pool
            logPool[i] = logPool[logPoolSize - 1];
            logPoolSize--;
            break;
        }
    }
    // Release the lock on the log pool mutex
    pthread_mutex_unlock(&logPoolMutex);
}

// Define the function to serialize a DeviceStatusLog entry to a binary file
void serializeLogEntry(DeviceStatusLog* logEntry, FILE* fp) {
    // Write the timestamp to the file
    fwrite(&logEntry->timestamp, sizeof(time_t), 1, fp);
    // Write the device ID to the file
    fwrite(&logEntry->deviceID, sizeof(int), 1, fp);
    // Write the event code to the file
    fwrite(&logEntry->eventCode, sizeof(int), 1, fp);
    // Write the event message to the file
    fwrite(logEntry->eventMessage, strlen(logEntry->eventMessage) + 1, 1, fp);
}

// Define the function to deserialize a DeviceStatusLog entry from a binary file
void deserializeLogEntry(DeviceStatusLog* logEntry, FILE* fp) {
    // Read the timestamp from the file
    fread(&logEntry->timestamp, sizeof(time_t), 1, fp);
    // Read the device ID from the file
    fread(&logEntry->deviceID, sizeof(int), 1, fp);
    // Read the event code from the file
    fread(&logEntry->eventCode, sizeof(int), 1, fp);
    // Read the event message from the file
    char* eventMessage = (char*)malloc(100 * sizeof(char));
    fread(eventMessage, strlen(eventMessage) + 1, 1, fp);
    logEntry->eventMessage = eventMessage;
}

