#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <zlib.h>

// Define constants for default delimiter and maximum directory depth
#define DEFAULT_DELIMITER "\n"
#define MAX_DIRECTORY_DEPTH 10

// Function to normalize a file path and check its depth against the maximum allowed
char* normalizePath(const char* path, int maxDepth) {
    // Allocate memory for the normalized path
    char* normalizedPath = malloc(strlen(path) + 1);
    if (!normalizedPath) {
        return NULL;
    }

    // Copy the original path to the normalized path
    strcpy(normalizedPath, path);

    // Normalize the path by removing any leading or trailing slashes
    char* ptr = normalizedPath;
    while (*ptr == '/') {
        *ptr++ = '\0';
    }
    ptr--;
    while (*ptr == '/') {
        *ptr-- = '\0';
    }

    // Check the depth of the path against the maximum allowed
    int depth = 0;
    char* token = strtok(normalizedPath, "/");
    while (token) {
        if (depth++ > maxDepth) {
            free(normalizedPath);
            return NULL;
        }
        token = strtok(NULL, "/");
    }

    // Return the normalized path
    return normalizedPath;
}

// Function to read a file and calculate its line count
int readFileAndCountLines(const char* filename, const char* delimiter) {
    // Open the file for reading
    FILE* file = fopen(filename, "r");
    if (!file) {
        return -1;
    }

    // Initialize variables to keep track of line count and file size
    int lineCount = 0;
    long fileSize = 0;

    // Read the file line by line and calculate the line count
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        if (strcmp(delimiter, DEFAULT_DELIMITER) == 0 || strstr(line, delimiter) != NULL) {
            lineCount++;
        }
        fileSize += read;
    }

    // Close the file and return the line count
    fclose(file);
    free(line);
    return lineCount;
}

// Function to calculate the total number of lines across multiple files
int countLinesAcrossFiles(char** filenames, int numFiles, const char* delimiter) {
    // Initialize variables to keep track of line count and file size
    int lineCount = 0;
    long fileSize = 0;

    // Loop through each file and calculate the line count
    for (int i = 0; i < numFiles; i++) {
        char* filename = filenames[i];
        if (!filename) {
            continue;
        }
        int linesInFile = readFileAndCountLines(filename, delimiter);
        if (linesInFile == -1) {
            return -1;
        }
        lineCount += linesInFile;
        fileSize += getFileSize(filename);
    }

    // Return the total number of lines and file size
    return lineCount;
}

// Function to write the final line count to an output file
int writeLineCountToOutputFile(const char* filename, int lineCount) {
    // Open the output file for writing
    FILE* file = fopen(filename, "w");
    if (!file) {
        return -1;
    }

    // Write the line count to the output file
    fprintf(file, "%d", lineCount);

    // Close the output file and return success
    fclose(file);
    return 0;
}

// Function to handle errors related to missing files or invalid delimiters
void handleError(const char* message) {
    printf("Error: %s\n", message);
    exit(1);
}

int main(int argc, char** argv) {
    // Check the number of command line arguments
    if (argc < 2) {
        handleError("No input file specified");
    }

    // Normalize the input files and check their depth against the maximum allowed
    int numFiles = argc - 1;
    char** filenames = malloc(numFiles * sizeof(char*));
    for (int i = 0; i < numFiles; i++) {
        char* filename = normalizePath(argv[i + 1], MAX_DIRECTORY_DEPTH);
        if (!filename) {
            handleError("Invalid input file");
        }
        filenames[i] = filename;
    }

    // Check the delimiter and calculate the total number of lines across all files
    const char* delimiter = DEFAULT_DELIMITER;
    if (argc > 2) {
        delimiter = argv[2];
    }
    int lineCount = countLinesAcrossFiles(filenames, numFiles, delimiter);
    if (lineCount == -1) {
        handleError("Invalid delimiter");
    }

    // Check the output file and write the final line count to it
    const char* outputFile = NULL;
    if (argc > 3) {
        outputFile = argv[3];
    }
    int result = writeLineCountToOutputFile(outputFile, lineCount);
    if (result == -1) {
        handleError("Invalid output file");
    }

    // Free memory and return success
    for (int i = 0; i < numFiles; i++) {
        free(filenames[i]);
    }
    free(filenames);
    return 0;
}
