    char *filePath;
    int fileSize;
} FileInfo;

typedef struct {
    char *filePath;
    int fileSize;
    bool isDirectory;
} FileInfoWithType;

typedef struct {
    char *filePath;
    int fileSize;
    bool isDirectory;
    bool isSymbolicLink;
} FileInfoWithTypeAndLink;

typedef struct {
    char *filePath;
    int fileSize;
    bool isDirectory;
    bool isSymbolicLink;
    bool isDuplicate;
} FileInfoWithTypeAndLinkAndDuplicate;

typedef struct {
    char *filePath;
    int fileSize;
    bool isDirectory;
    bool isSymbolicLink;
    bool isDuplicate;
    bool isValid;
} FileInfoWithTypeAndLinkAndDuplicateAndValidity;

void processFile(char *filePath, int batchSize, int maxBatchSize, int maxFileNameLength, int maxDigits, char *fileType, bool strictMode) {
    // Check if file path is null or empty
    if (filePath == NULL || strlen(filePath) == 0) {
        return;
    }

    // Check if batch size is a positive integer
    if (batchSize <= 0) {
        return;
    }

    // Check if file exists and is accessible
    struct stat fileStat;
    if (stat(filePath, &fileStat) != 0) {
        printf("Warning: File %s does not exist or is inaccessible\n", filePath);
        return;
    }

    // Check if file is a directory and recursively process its child files
    if (S_ISDIR(fileStat.st_mode)) {
        DIR *dir = opendir(filePath);
        struct dirent *entry;
        while ((entry = readdir(dir)) != NULL) {
            char *childFilePath = malloc(strlen(filePath) + strlen(entry->d_name) + 1);
            sprintf(childFilePath, "%s/%s", filePath, entry->d_name);
            processFile(childFilePath, batchSize, maxBatchSize, maxFileNameLength, maxDigits, fileType, strictMode);
        }
        closedir(dir);
    } else {
        // Check if file is a symbolic link and resolve it
        char *realFilePath = realpath(filePath, NULL);
        bool isSymbolicLink = (realFilePath != NULL && strcmp(realFilePath, filePath) != 0);
        free(realFilePath);

        // Check if file is a duplicate and retry with a slightly modified extension
        char *newFileName = malloc(maxFileNameLength + 1);
        sprintf(newFileName, "%s%d", filePath, rand() % (int)pow(10, maxDigits));
        strcat(newFileName, FILE_TYPE);
        bool isDuplicate = false;
        for (int i = 0; i < batchSize; i++) {
            if (strcmp(newFileName, fileInfoList[i].filePath) == 0) {
                isDuplicate = true;
                break;
            }
        }
        if (isDuplicate) {
            free(newFileName);
            newFileName = malloc(maxFileNameLength + 1);
            sprintf(newFileName, "%s%d", filePath, rand() % (int)pow(10, maxDigits));
            strcat(newFileName, FILE_TYPE);
        }

        // Check if file is valid and add it to the batch
        bool isValid = true;
        for (int i = 0; i < batchSize; i++) {
            if (strcmp(fileInfoList[i].filePath, newFileName) == 0) {
                isValid = false;
                break;
            }
        }
        if (isValid) {
            FileInfoWithTypeAndLinkAndDuplicateAndValidity fileInfo = {.filePath = newFileName, .fileSize = fileStat.st_size, .isDirectory = S_ISDIR(fileStat.st_mode), .isSymbolicLink = isSymbolicLink, .isDuplicate = isDuplicate, .isValid = true};
            fileInfoList[batchIndex] = fileInfo;
            batchIndex++;
        }
    }
}

void processFileList(char **filePathList, int batchSize, int maxBatchSize, int maxFileNameLength, int maxDigits, char *fileType, bool strictMode) {
    // Initialize file info list and batch index
    FileInfoWithTypeAndLinkAndDuplicateAndValidity *fileInfoList = malloc(maxBatchSize * sizeof(FileInfoWithTypeAndLinkAndDuplicateAndValidity));
    int batchIndex = 0;

    // Process each file in the list
    for (int i = 0; i < batchSize; i++) {
        processFile(filePathList[i], batchSize, maxBatchSize, maxFileNameLength, maxDigits, fileType, strictMode);
    }

    // Sort the file info list alphabetically by file path
    qsort(fileInfoList, batchIndex, sizeof(FileInfoWithTypeAndLinkAndDuplicateAndValidity), compareFilePaths);

    // Flush and start a new batch if necessary
    if (batchIndex >= maxBatchSize) {
        flushBatch();
        batchIndex = 0;
    }
}

int compareFilePaths(const void *a, const void *b) {
    FileInfoWithTypeAndLinkAndDuplicateAndValidity *fileA = (FileInfoWithTypeAndLinkAndDuplicateAndValidity *)a;
    FileInfoWithTypeAndLinkAndDuplicateAndValidity *fileB = (FileInfoWithTypeAndLinkAndDuplicateAndValidity *)b;
    return strcmp(fileA->filePath, fileB->filePath);
}

void flushBatch() {
    // Implement batch flushing logic here
}

int main(int argc, char *argv[]) {
    // Check if input arguments are valid
    if (argc < 4) {
        printf("Usage: %s <file_path_list> <batch_size> <max_batch_size>\n", argv[0]);
        return 1;
    }

    // Initialize file info list and batch index
    FileInfoWithTypeAndLinkAndDuplicateAndValidity *fileInfoList = malloc(MAX_BATCH_SIZE * sizeof(FileInfoWithTypeAndLinkAndDuplicateAndValidity));
    int batchIndex = 0;

    // Process each file in the list
    for (int i = 3; i < argc; i++) {
        processFile(argv[i], atoi(argv[2]), atoi(argv[3]), MAX_FILENAME_LENGTH, MAX_DIGITS, FILE_TYPE, false);
    }

    // Sort the file info list alphabetically by file path
    qsort(fileInfoList, batchIndex, sizeof(FileInfoWithTypeAndLinkAndDuplicateAndValidity), compareFilePaths);

    // Flush and start a new batch if necessary
    if (batchIndex >= atoi(argv[3])) {
        flushBatch();
        batchIndex = 0;
    }

    return 0;
}
