from collections import deque

class SensorDataPacket:
    def __init__(self, timestamp, sensor_id, measurement_value):
        self.timestamp = timestamp
        self.sensor_id = sensor_id
        self.measurement_value = measurement_value
        self.measurement_flag = random.choice([True, False])

class SensorDataManager:
    def __init__(self, max_structures=10000):
        self.max_structures = max_structures
        self.available_structures = deque()
        self.allocated_structures = {}
        self.request_ids = []
        self.memory_usage = 0
        self.total_processing_time = 0
        self.total_requests = 0
        self.total_timeouts = 0
        self.total_excessive_memory_usage = 0
        self.serialization_file = "sensor_data.bin"

    def allocate_structure(self, request_id):
        if len(self.available_structures) > 0:
            structure = self.available_structures.popleft()
            self.allocated_structures[request_id] = structure
            return structure
        else:
            try:
                structure = SensorDataPacket(time.time(), random.randint(1, 10), random.uniform(0, 10))
                self.memory_usage += sys.getsizeof(structure)
                if len(self.allocated_structures) >= self.max_structures:
                    self.total_excessive_memory_usage += 1
            except MemoryError as e:
                print("Memory allocation failed for request {}: {}".format(request_id, e))
                return None
            else:
                self.allocated_structures[request_id] = structure
                return structure

    def deallocate_structure(self, request_id):
        if request_id in self.allocated_structures:
            structure = self.allocated_structures[request_id]
            del self.allocated_structures[request_id]
            self.available_structures.append(structure)
            self.memory_usage -= sys.getsizeof(structure)
        else:
            print("Request {} not found in allocated structures".format(request_id))

    def process_data(self, request_id, data):
        start_time = time.time()
        structure = self.allocate_structure(request_id)
        if structure is None:
            print("Memory allocation failed for request {}: {}".format(request_id, e))
            return False
        else:
            try:
                structure.timestamp = data["timestamp"]
                structure.sensor_id = data["sensor_id"]
                structure.measurement_value = data["measurement_value"]
                self.total_processing_time += time.time() - start_time
                self.total_requests += 1
            except KeyError as e:
                print("Invalid data format for request {}: {}".format(request_id, e))
                return False
            else:
                return True

    def serialize_structures(self):
        with open(self.serialization_file, "wb") as f:
            pickle.dump(self.allocated_structures, f)

    def deserialize_structures(self):
        try:
            with open(self.serialization_file, "rb") as f:
                self.allocated_structures = pickle.load(f)
        except FileNotFoundError:
            print("Serialization file not found")
        else:
            for request_id in self.allocated_structures:
                structure = self.allocated_structures[request_id]
                self.available_structures.append(structure)
                self.memory_usage += sys.getsizeof(structure)

    def monitor_memory_consumption(self):
        if self.memory_usage > 0.8 * os.sysconf("SC_PAGE_SIZE"):
            print("Memory usage exceeded threshold: {}".format(self.memory_usage))
            self.total_excessive_memory_usage += 1

    def monitor_processing_time(self, request_id):
        if time.time() - start_time > 0.5 * os.sysconf("SC_CLK_TCK"):
            print("Processing time exceeded threshold for request {}: {}".format(request_id, time.time() - start_time))
            self.total_timeouts += 1

    def handle_concurrent_requests(self, request_id):
        if request_id in self.allocated_structures:
            structure = self.allocated_structures[request_id]
            self.available_structures.append(structure)
            del self.allocated_structures[request_id]
        else:
            print("Request {} not found in allocated structures".format(request_id))

    def validate_integrity(self):
        for request_id in self.allocated_structures:
            structure = self.allocated_structures[request_id]
            if structure.timestamp is None or structure.sensor_id is None or structure.measurement_value is None:
                print("Invalid data found for request {}: {}".format(request_id, structure))
                return False
        else:
            return True
