    int retries = 0; // Number of retries before failing to acquire necessary locks
    char* errMsg = NULL; // Error message for logging context
    // Define function for acquiring necessary locks and handling potential deadlocks
    void acquireLocks(LTE_PHY_TEST_CONFIG** configs, int numConfigs) {
        pthread_mutex_lock(&mutex);
        if (retries > 0) {
            printf("Warning: Deadlock detected. Retrying...\n");
            retries--;
        } else {
            printf("Error: Failed to acquire necessary locks within specified period.\n");
