            printf("Warning: Hash table/tree is full. Expanding...\n");
            int newSize = hashTable->size * 2;
            LTE_PHY_TEST_CONFIG** newConfigs = realloc(hashTable->configs, sizeof(LTE_PHY_TEST_CONFIG*) * newSize);
            if (newConfigs == NULL) {
                printf("Error: Failed to expand hash table/tree.\n");
                return;
            }
            hashTable->configs = newConfigs;
            hashTable->size = newSize;
        }
        // Check if tree is full and needs to be expanded
        if (tree->size == numConfigs) {
            printf("Warning: Tree is full. Expanding...\n");
            int newSize = tree->size * 2;
            LTE_PHY_TEST_CONFIG** newConfigs = realloc(tree->configs, sizeof(LTE_PHY_TEST_CONFIG*) * newSize);
