            tree->configs = newConfigs;
            tree->size = newSize;
        }
        // Add configuration to the list of configurations and update memory usage
        configs[numConfigs] = config;
        memUsage += sizeof(LTE_PHY_TEST_CONFIG);
        hashTable->configs[numConfigs] = config;
        tree->configs[numConfigs] = config;
        numConfigs++;
        // Update log file with information about the new configuration
        fprintf(logFile, "New configuration added: %d\n", config->phy_test_parameter_id);
        releaseLocks(configs, numConfigs);
