    void removeConfiguration(LTE_PHY_TEST_CONFIG* config) {
        acquireLocks(configs, numConfigs);
        // Find the index of the configuration in the list of configurations
        int idx = -1;
        for (int i = 0; i < numConfigs; i++) {
            if (config == configs[i]) {
                idx = i;
                break;
            }
        }
        // Check if configuration was found in the list of configurations
        if (idx != -1) {
            // Remove configuration from the list of configurations and update memory usage
            for (int i = idx + 1; i < numConfigs; i++) {
                configs[i - 1] = configs[i];
            }
            memUsage -= sizeof(LTE_PHY_TEST_CONFIG);
            numConfigs--;
            // Update log file with information about the removed configuration
            fprintf(logFile, "Configuration removed: %d\n", config->phy_test_parameter_id);
