    void purgeOutdatedEntries() {
        acquireLocks(configs, numConfigs);
        // Check if any outdated entries need to be purged
        time_t currentTime = time(NULL);
        if (currentTime - lastPurgeTime > purgeInterval) {
            for (int i = 0; i < numConfigs; i++) {
                LTE_PHY_TEST_CONFIG* config = configs[i];
