    int newFilenameSize = strlen(filename) + numVowels + 1;
    if (newFilenameSize > 256) {
        printf("Error: New filename exceeds maximum length of 256 characters\n");
        return NULL;
    }

    // Manage file extensions correctly, even when they are missing or incorrectly formatted
    char *extension = strrchr(filename, '.');
    if (extension == NULL) {
        strcat(newFilename, fileType);
    } else {
        int extensionLength = strlen(extension);
        if (strcmp(extension, fileType) != 0) {
            strcat(newFilename, fileType);
        }
    }

    // Validate that the resulting filename is unique within a specified directory by checking against an existing list of filenames
    char *directory = strrchr(filename, '/');
    if (directory == NULL) {
        directory = ".";
    } else {
        directory++;
    }
    DIR *dir = opendir(directory);
    if (dir == NULL) {
        printf("Warning: Failed to open directory %s\n", directory);
        return newFilename;
    }
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(newFilename, entry->d_name) == 0) {
            // If a duplicate is found, retry with a slightly modified extension
            char *modifiedExtension = malloc(strlen(fileType) + 1);
            if (modifiedExtension == NULL) {
                printf("Error: Failed to allocate memory for modified extension\n");
                return NULL;
            }
            sprintf(modifiedExtension, "%s_%d", fileType, rand() % 1000);
            newFilename = generateNewFilename(filename, modifiedExtension);
            free(modifiedExtension);
            break;
        }
    }

    // Clean up memory
    closedir(dir);

    return newFilename;
}
