    }

    // Adjust the capacity of the pool based on the current number of concurrent connections, allowing for seamless integration of additional metadata in future iterations
    int new_capacity = num_concurrent * 2;
    pool->configs = realloc(pool->configs, sizeof(LTE_PHY_TEST_CONFIG*) * new_capacity);
}

// Define the function to handle potential buffer overflows by calculating the necessary buffer size beforehand
void handle_buffer_overflow(char* buffer) {
    // Calculate the necessary buffer size based on the maximum length of the string and the current position in the buffer
    int max_length = 128;
    int current_position = strlen(buffer);
    int new_size = current_position + (max_length - current_position) * sizeof(char);

