// Define the batch processing function
int process_batch(const char **urls, const config_t *config) {
    // Validate input parameters
    if (urls == NULL || config == NULL) {
        return -1;
    }

    // Initialize variables and allocate memory for the processed URLs
    int batch_size = 0;
    char **processed_urls = NULL;
    size_t processed_len = 0;

    // Iterate over the input URLs and process each one
    for (int i = 0; i < config->batch_size; i++) {
        const char *url = urls[i];
        if (url == NULL) {
            continue;
        }

        // Process the URL and handle errors
        int res = process_url(url, config);
        if (res < 0) {
            fprintf(stderr, "Error: %s\n", curl_easy_strerror(res));
            return -2;
        }

        // Add the processed URL to the list of processed URLs
        processed_urls = realloc(processed_urls, (processed_len + 1) * sizeof(char*));
        if (processed_urls == NULL) {
            fprintf(stderr, "Error: %s\n", curl_easy_strerror(res));
            return -3;
        }
        processed_urls[processed_len++] = url;
    }

    // Free resources and return the list of processed URLs
    free(processed_urls);
    return processed_len;
}

// Define the main function
int main(int argc, char **argv) {
    // Validate input parameters
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <list of URLs> <batch size>\n", argv[0]);
        return -1;
    }

    // Initialize variables and allocate memory for the configuration structure
    config_t *config = malloc(sizeof(config_t));
    if (config == NULL) {
        fprintf(stderr, "Error: %s\n", curl_easy_strerror(CURLE_OUT_OF_MEMORY));
        return -2;
    }

    // Parse the configuration structure and handle errors
    int res = parse_config(argv[1], config);
    if (res < 0) {
        fprintf(stderr, "Error: %s\n", curl_easy_strerror(res));
        return -3;
    }

    // Process the list of URLs and handle errors
    int batch_size = atoi(argv[2]);
    if (batch_size <= 0) {
        fprintf(stderr, "Error: invalid batch size\n");
        return -4;
    }
    const char **urls = argv + 3;
    int processed_len = process_batch(urls, config);
    if (processed_len < 0) {
        fprintf(stderr, "Error: %s\n", curl_easy_strerror(processed_len));
        return -5;
    }

    // Free resources and return the list of processed URLs
    free(config);
    return processed_len;
}
