        if (new_element == NULL) {
            num_allocations++;
            return false;
        }
        list[list_size] = *new_element;
        list_size++;
    }
    pthread_mutex_unlock(&lock);
    return true;
}

// Function to handle overflow by clearing the oldest elements and adding new ones
