void process_files_and_directories_recursive_with_limit_and_custom_delimiter_and_output_redirection_and_file_filter(const char* path, int num_elements, struct MemoryPool* pool) {
    // Open the file or directory for reading
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        printf("Error: Failed to open %s\n", path);
        return;
    }

    // Read lines from the file or directory and compute the total line count
    int num_lines = 0;
    char buffer[1024];
    while (read(fd, buffer, sizeof(buffer)) > 0) {
        if (strchr(buffer, '\n')) {
            num_lines++;
        }
    }

    // Close the file or directory
    close(fd);

    // Recursively process files and directories within the current directory
    struct dirent* entry;
    DIR* dir = opendir(path);
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        char* file_path = malloc(strlen(path) + strlen(entry->d_name) + 2);
        if (!file_path) {
            printf("Error: Failed to allocate memory for file path\n");
            return;
        }

        sprintf(file_path, "%s/%s", path, entry->d_name);
        struct stat st;
        if (stat(file_path, &st) == 0 && S_ISDIR(st.st_mode)) {
            process_files_and_directories_recursive_with_limit_and_custom_delimiter_and_output_redirection_and_file_filter(file_path, num_elements, pool);
        } else {
            read_lines(file_path, num_elements, pool);
        }
    }
}

