    // Create the array of NFAPI_STRUCTURES_T structures and initialize it with the allocated arrays
    NFAPI_STRUCTURES_T *nfapi_structures = (NFAPI_STRUCTURES_T *)malloc(sizeof(NFAPI_STRUCTURES_T));
    if (!nfapi_structures) {
