    // Validate the integrity of the allocated structures at allocation and periodically throughout their lifecycle
    validate_integrity(nfapi_structures);

    // Track the number of successfully allocated structures to facilitate efficient memory management under high-load conditions
    track_allocated_structures(nfapi_structures);

