char* sanitize_file_path(const char* file_path, size_t max_dir_len, bool append_slash) {
    // Check if the file path is valid and the directory part does not exceed the maximum length
    if (strlen(file_path) > 0 && strlen(dirname(file_path)) <= max_dir_len) {
        char* new_path = malloc(strlen(file_path) + 1);
        strcpy(new_path, file_path);
        if (append_slash) {
            // Append a slash to the end of the directory part
            char* last_slash = strrchr(new_path, '/');
            if (last_slash != NULL) {
                *(last_slash + 1) = '/';
            } else {
                new_path[strlen(file_path)] = '/';
            }
        }
        return new_path;
    }
    return NULL;
}
