char* sanitizeAndConfigureFilesystemPath(const char* filePath, size_t maxDirectoryLength, bool appendSlash) {
    // Check if the file path is valid and the directory part does not exceed the maximum length
    if (!filePath || strlen(filePath) > maxDirectoryLength) {
        return NULL;
    }

    // Create a new string containing the sanitized file path
    char* sanitizedFilePath = malloc(strlen(filePath) + 1);
    if (!sanitizedFilePath) {
        fprintf(stderr, "Error: Failed to allocate memory for sanitized file path\n");
        return NULL;
    }
    strcpy(sanitizedFilePath, filePath);

    // Append a slash at the end of the directory part if necessary
    size_t lastSlashIndex = strrchr(sanitizedFilePath, '/');
    if (lastSlashIndex != NULL && appendSlash) {
        sanitizedFilePath[lastSlashIndex] = '/';
    }

    // Return the sanitized file path
    return sanitizedFilePath;
}
