#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

typedef struct NetworkInterfaceConfig {
    int InterfaceID;
    char IPAddress[16];
    char SubnetMask[16];
    int NetworkStatus;
} NetworkInterfaceConfig;

void persistNetworkConfigurations(const char* filePath, const NetworkInterfaceConfig* configs, size_t numConfigs) {
    // Check if the input parameters are valid
    if (!filePath || !configs || numConfigs == 0) {
        return;
    }

    // Open the file for writing
    FILE* file = fopen(filePath, "w");
    if (!file) {
        fprintf(stderr, "Error: Failed to open file for writing\n");
        return;
    }

    // Write the network configurations to the file
    for (size_t i = 0; i < numConfigs; i++) {
        NetworkInterfaceConfig* config = &configs[i];
        fprintf(file, "%d %s %s %d\n", config->InterfaceID, config->IPAddress, config->SubnetMask, config->NetworkStatus);
    }

    // Close the file
    fclose(file);
}
