typedef struct NetworkInterfaceConfig {
    int InterfaceID;
    char IPAddress[16];
    char SubnetMask[16];
    int NetworkStatus;
} NetworkInterfaceConfig;

NetworkInterfaceConfig* loadNetworkConfigurations(const char* filePath) {
    // Check if the input parameters are valid
    if (!filePath) {
        return NULL;
    }

    // Open the file for reading
    FILE* file = fopen(filePath, "r");
    if (!file) {
        fprintf(stderr, "Error: Failed to open file for reading\n");
        return NULL;
    }

    // Read the network configurations from the file
    NetworkInterfaceConfig* configs = malloc(sizeof(NetworkInterfaceConfig));
    size_t numConfigs = 0;
    while (fscanf(file, "%d %s %s %d\n", &configs[numConfigs].InterfaceID, configs[numConfigs].IPAddress, configs[numConfigs].SubnetMask, &configs[numConfigs].NetworkStatus) == 4) {
        numConfigs++;
    }

    // Close the file
    fclose(file);

    // Return the network configurations
    return configs;
}
