// Function to manage a dynamic list of TCP connection records
void manage_tcp_connection_records(TCP_CONNECTION_RECORD_T *records, int num_records) {
    // Initialize the random number generator with the seed value
    srand(SEED);

    // Allocate memory for the TCP connection records
    records = (TCP_CONNECTION_RECORD_T *)malloc(num_records * sizeof(TCP_CONNECTION_RECORD_T));
    if (!records) {
        printf("Error: Failed to allocate memory for TCP connection records\n");
