        records[i].tcp_socket_id = rand();
        inet_ntop(AF_INET, &(records[i].source_ip), source_ip, INET6_ADDRSTRLEN);
        inet_ntop(AF_INET, &(records[i].destination_ip), destination_ip, INET6_ADDRSTRLEN);
        records[i].syn_timestamp = time(NULL);
        records[i].syn_seq_number = rand();
        records[i].ack_timestamp = time(NULL);
        records[i].ack_seq_number = rand();
    }

    // Periodically purge outdated entries from the list to maintain memory efficiency
    while (1) {
        sleep(EXTERNAL_DATA_SOURCE_UPDATE_INTERVAL);
        for (int i = 0; i < num_records; i++) {
            if (records[i].ack_timestamp + EXTERNAL_DATA_SOURCE_UPDATE_INTERVAL < time(NULL)) {
                records[i] = records[num_records - 1];
                num_records--;
            }
        }
    }
}

// Function to generate a new connection ID based on an existing one
