    // Initialize the new connection ID with the original connection flags
    char new_conn_id[MAX_NEW_CONN_ID_LEN];
    strcpy(new_conn_id, CONN_TYPE_INDICATOR);

    // Count the number of specific flag bits set in the original connection flags
    int num_specific_flag_bits = 0;
    for (int i = 0; i < MIN_SPECIFIC_FLAG_BITS; i++) {
        if ((record->tcp_socket_id & (1 << i)) != 0) {
            num_specific_flag_bits++;
        }
    }

    // Generate a new connection ID based on the original connection flags
    for (int i = 0; i < num_specific_flag_bits; i++) {
        char random_char = rand() % ('Z' - 'A') + 'A';
        strcat(new_conn_id, &random_char);
    }

    // Return the new connection ID
    return new_conn_id;
