        int status_code = -1;
        long content_length = -1;

        // Verify the accessibility of the URL using HTTP status codes
        CURL* curl = curl_easy_init();
        if (curl) {
            curl_easy_setopt(curl, CURLOPT_URL, url);
            curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
            curl_easy_setopt(curl, CURLOPT_USERAGENT, "Mozilla/5.0 (Windows; U; Windows NT 5.1; en-US; rv:1.8.1.1) Gecko/20071127 Firefox/2.0.0.1");
            curl_easy_setopt(curl, CURLOPT_SSL_VERIFYPEER, 0L);
            curl_easy_setopt(curl, CURLOPT_SSL_VERIFYHOST, 0L);
            CURLcode res = curl_easy_perform(curl);
            if (res == CURLE_OK) {
                status_code = curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &status_code);
                content_length = curl_easy_getinfo(curl, CURLINFO_CONTENT_LENGTH_DOWNLOAD, &content_length);
            }
            curl_easy_cleanup(curl);
        }

        // Handle temporary failures by retrying up to three times with exponential backoff
        int num_retries = 0;
        while (status_code != 200 && num_retries < 3) {
            sleep(pow(2, num_retries));
            curl = curl_easy_init();
            if (curl) {
                curl_easy_setopt(curl, CURLOPT_URL, url);
                curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
                curl_easy_setopt(curl, CURLOPT_USERAGENT, "Mozilla/5.0 (Windows; U; Windows NT 5.1; en-US; rv:1.8.1.1) Gecko/20071127 Firefox/2.0.0.1");
                curl_easy_setopt(curl, CURLOPT_SSL_VERIFYPEER, 0L);
                curl_easy_setopt(curl, CURLOPT_SSL_VERIFYHOST, 0L);
                res = curl_easy_perform(curl);
                if (res == CURLE_OK) {
                    status_code = curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &status_code);
                    content_length = curl_easy_getinfo(curl, CURLINFO_CONTENT_LENGTH_DOWNLOAD, &content_length);
                }
                curl_easy_cleanup(curl);
            }
            num_retries++;
        }

        // Handle HTTPS URLs and certificate validation issues gracefully
        if (strncmp(url, "https://", 7) == 0) {
            SSL_CTX* ctx = SSL_CTX_new(TLSv1_2_client_method());
            SSL* ssl = SSL_new(ctx);
            SSL_set_fd(ssl, curl_easy_getinfo(curl, CURLINFO_SOCKET));
            if (SSL_connect(ssl) == 1) {
                X509* cert = SSL_get_peer_certificate(ssl);
                if (cert != NULL) {
                    // Verify the certificate using the external configuration structure
                    int valid = verify_certificate(cert, config);
                    if (!valid) {
                        status_code = -1;
                        content_length = -1;
                    }
                } else {
                    status_code = -1;
                    content_length = -1;
                }
            } else {
                status_code = -1;
                content_length = -1;
            }
        }

        // Handle malformed content gracefully
        if (status_code == 200 && content_length > 0) {
            char* content = malloc(content_length * sizeof(char));
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
            curl_easy_setopt(curl, CURLOPT_WRITEDATA, content);
            res = curl_easy_perform(curl);
            if (res == CURLE_OK) {
                // Parse the content to extract relevant data fields
                parse_content(content, config);
            } else {
                status_code = -1;
                content_length = -1;
            }
        }

        // Add the network activity log to the list
        pthread_mutex_lock(&mutex);
        logs = realloc(logs, (num_batches + 1) * sizeof(struct NETWORK_ACTIVITY_LOG));
        logs[num_batches].url = url;
        logs[num_batches].status_code = status_code;
        logs[num_batches].content_length = content_length;
        pthread_mutex_unlock(&mutex);
    }

    // Clean up resources
    free(sorted_urls);
    free(batch_sizes);
    curl_global_cleanup();

    return 0;
}

