    if (status_code == 200 && content_length > 0) {
        char* content = malloc(content_length * sizeof(char));
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, content);
        res = curl_easy_perform(curl);
        if (res == CURLE_OK) {
            // Parse the content to extract relevant data fields
            parse_content(content, config);
        } else {
            status_code = -1;
            content_length = -1;
        }
    }

    return 0;
}

// Define the function to verify the accessibility of a URL using HTTP status codes
int verify_certificate(X509* cert, struct CONFIGURATION* config) {
    // Initialize variables
    int valid = 1;

    // Verify the certificate using the external configuration structure
    if (config->verify_certificate) {
        // Check the domain name in the subject field of the certificate
        char* domain = X509_get_subject(cert);
        if (domain != NULL && strcmp(domain, config->domain) == 0) {
            valid = 1;
        } else {
            valid = 0;
        }
    }

    return valid;
}

// Define the function to parse the content of a URL and extract relevant data fields
void parse_content(char* content, struct CONFIGURATION* config) {
    // Initialize variables
    int num_fields = 0;
    char** fields = NULL;

    // Parse the content to extract relevant data fields
    if (config->parse_content) {
        // Tokenize the content using a regular expression
        regex_t* regex = malloc(sizeof(regex_t));
        regcomp(regex, config->token_pattern, REG_EXTENDED);
        int num_matches = 0;
        char** matches = NULL;
        while (num_matches < MAX_MATCHES) {
            if (regnexec(regex, content, MAX_MATCHES - num_matches, &matches[num_matches], 0) == REG_NOERROR) {
                num_matches++;
            } else {
                break;
            }
        }
        regfree(regex);

        // Extract the relevant data fields from the matches
        for (int i = 0; i < num_matches; i++) {
            char* field = malloc(strlen(matches[i]) * sizeof(char));
            strcpy(field, matches[i]);
            fields = realloc(fields, (num_fields + 1) * sizeof(char*));
            fields[num_fields] = field;
            num_fields++;
        }
    }
}

// Define the function to write data to a file
void write_callback(char* ptr, size_t size, size_t nmemb, void* userdata) {
    // Initialize variables
    FILE* fp = NULL;
    char* filename = "output.txt";

    // Open the output file in append mode
    if ((fp = fopen(filename, "a")) == NULL) {
        printf("Error: Unable to open file %s\n", filename);
        return;
    }

    // Write the data to the file
    size_t written = fwrite(ptr, size, nmemb, fp);
    if (written != nmemb) {
        printf("Error: Unable to write to file %s\n", filename);
    }

    // Close the output file
    fclose(fp);
}
