import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class FileProcessor {
  private static final int MAX_LINE_LENGTH = 1024 * 1024; // 1 MB
  private static final String SUBSTRING_TO_REPLACE = "old";
  private static final String REPLACEMENT_SUBSTRING = "new";

  public List<String> processFile(String filePath, String targetSubstring) throws IOException {
    if (filePath == null || targetSubstring == null) {
      throw new IllegalArgumentException("Invalid input parameters");
    }

    // Initialize thread pool with a fixed number of threads
    ExecutorService executor = Executors.newFixedThreadPool(4);

    // Create a list to store the transformed lines
    List<String> transformedLines = new ArrayList<>();

    try (BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(filePath), StandardCharsets.UTF_8))) {
      String line;
      while ((line = reader.readLine()) != null) {
        // Convert the line to uppercase and replace all occurrences of the target substring with the replacement substring
        String transformedLine = line.toUpperCase().replaceAll(Pattern.quote(targetSubstring), REPLACEMENT_SUBSTRING);

        // Validate that the resulting string length does not exceed the maximum size for each line
        if (transformedLine.length() > MAX_LINE_LENGTH) {
          System.err.println("Error: Line " + reader.getLineNumber() + " is too long");
          return null;
        }

        // Add the transformed line to the list
        transformedLines.add(transformedLine);
      }
    } catch (IOException e) {
      System.err.println("Error reading file: " + e.getMessage());
      return null;
    } finally {
      executor.shutdown();
    }

    // Return the transformed lines as a list of strings
    return transformedLines;
  }
}
