import os
import json
import csv
import pandas as pd
from datetime import datetime
from typing import List, Dict

class LogProcessor:
    def __init__(self, directory: str, output_format: str = "json", filters: Dict[str, any] = None):
        self.directory = directory
        self.output_format = output_format
        self.filters = filters or {}

    def process(self) -> List[Dict]:
        # Initialize a list to store the processed data
        processed_data = []

        # Iterate over all files in the directory
        for filename in os.listdir(self.directory):
            filepath = os.path.join(self.directory, filename)

            # Skip any files that do not match the specified filters
            if self._should_skip_file(filename):
                continue

            # Process the file and append the results to the processed data list
            processed_data.extend(self._process_file(filepath))

        # Return the processed data
        return processed_data

    def _should_skip_file(self, filename: str) -> bool:
        """Determine whether a file should be skipped based on the specified filters."""
        for key, value in self.filters.items():
            if not self._filter_matches(filename, key, value):
                return True
        return False

    def _filter_matches(self, filename: str, key: str, value: any) -> bool:
        """Determine whether a filter matches a file based on the specified criteria."""
        if key == "date":
            date = self._get_file_date(filename)
            return date >= value
        elif key == "event_type":
            event_type = self._get_file_event_type(filename)
            return event_type == value
        elif key == "severity":
            severity = self._get_file_severity(filename)
            return severity >= value
        else:
            raise ValueError(f"Invalid filter key: {key}")

    def _process_file(self, filepath: str) -> List[Dict]:
        """Process a single log file and return the processed data."""
        # Read the contents of the file
        with open(filepath, "r") as f:
            contents = f.read()

        # Parse the contents based on the output format
        if self.output_format == "json":
            data = json.loads(contents)
        elif self.output_format == "csv":
            data = csv.DictReader(contents)
        else:
            raise ValueError(f"Invalid output format: {self.output_format}")

        # Filter the data based on any specified filters
        filtered_data = []
        for row in data:
            if self._should_skip_row(row):
                continue
            filtered_data.append(row)

        return filtered_data

    def _should_skip_row(self, row: Dict) -> bool:
        """Determine whether a row should be skipped based on the specified filters."""
        for key, value in self.filters.items():
            if not self._filter_matches(row, key, value):
                return True
        return False

    def _get_file_date(self, filename: str) -> datetime:
        """Get the date of a log file based on its name."""
        # Extract the date from the filename using regular expressions
        pattern = r"(\d{4})-(\d{2})-(\d{2})"
        match = re.search(pattern, filename)
        if not match:
            raise ValueError("Invalid file name")
        year, month, day = map(int, match.groups())
        return datetime(year, month, day)

    def _get_file_event_type(self, filename: str) -> str:
        """Get the event type of a log file based on its name."""
        # Extract the event type from the filename using regular expressions
        pattern = r"(\w+)-(\d{4})-(\d{2})-(\d{2})"
        match = re.search(pattern, filename)
        if not match:
            raise ValueError("Invalid file name")
        return match.group(1)

    def _get_file_severity(self, filename: str) -> int:
        """Get the severity of a log file based on its name."""
        # Extract the severity from the filename using regular expressions
        pattern = r"(\w+)-(\d{4})-(\d{2})-(\d{2})"
        match = re.search(pattern, filename)
        if not match:
            raise ValueError("Invalid file name")
        return int(match.group(3))
