#include <stdlib.h>
#include <string.h>

// Define the LTE_TRANSPORT_CHANNEL_T structure
typedef struct {
    int transportChannelId;
    int bandwidth;
    int schedulingInstanceTag;
} LTE_TRANSPORT_CHANNEL_T;

// Define the LTE_PHY_STATS_T structure
typedef struct {
    float rbUtilization;
} LTE_PHY_STATS_T;

// Define an array of LTE_TRANSPORT_CHANNEL_T structures
LTE_TRANSPORT_CHANNEL_T *transportChannels = NULL;

// Define an array of LTE_PHY_STATS_T structures
LTE_PHY_STATS_T *phyStats = NULL;

// Function to allocate memory for the transport channels and phy stats arrays
void allocateMemory(int numTransportChannels, int numPhyStats) {
    // Allocate memory for the transport channels array
    transportChannels = (LTE_TRANSPORT_CHANNEL_T *)malloc(numTransportChannels * sizeof(LTE_TRANSPORT_CHANNEL_T));
    if (!transportChannels) {
        printf("Error: Failed to allocate memory for the transport channels array\n");
        exit(1);
    }

    // Allocate memory for the phy stats array
    phyStats = (LTE_PHY_STATS_T *)malloc(numPhyStats * sizeof(LTE_PHY_STATS_T));
    if (!phyStats) {
        printf("Error: Failed to allocate memory for the phy stats array\n");
        exit(1);
    }
}

// Function to deallocate memory for the transport channels and phy stats arrays
void deallocateMemory() {
    // Deallocate memory for the transport channels array
    free(transportChannels);
    transportChannels = NULL;

    // Deallocate memory for the phy stats array
    free(phyStats);
    phyStats = NULL;
}

// Function to add a new transport channel and its corresponding phy stats
void addTransportChannel(int transportChannelId, int bandwidth, int schedulingInstanceTag) {
    // Check if the transport channels array is full
    if (numTransportChannels == MAX_TRANSPORT_CHANNELS) {
        printf("Error: The transport channels array is full\n");
        return;
    }

    // Add a new transport channel to the array
    transportChannels[numTransportChannels].transportChannelId = transportChannelId;
    transportChannels[numTransportChannels].bandwidth = bandwidth;
    transportChannels[numTransportChannels].schedulingInstanceTag = schedulingInstanceTag;
    numTransportChannels++;

    // Check if the phy stats array is full
    if (numPhyStats == MAX_PHY_STATS) {
        printf("Error: The phy stats array is full\n");
        return;
    }

    // Add a new phy stats to the array
    phyStats[numPhyStats].rbUtilization = 0.0f;
    numPhyStats++;
}

// Function to update the rb utilization for a given transport channel and scheduling instance tag
void updateRbUtilization(int transportChannelId, int schedulingInstanceTag, float rbUtilization) {
    // Find the index of the transport channel in the array
    int i = 0;
    while (i < numTransportChannels && transportChannels[i].transportChannelId != transportChannelId) {
        i++;
    }

    // Check if the transport channel was found
    if (i == numTransportChannels) {
        printf("Error: The transport channel with ID %d was not found\n", transportChannelId);
        return;
    }

    // Find the index of the phy stats in the array
    int j = 0;
    while (j < numPhyStats && phyStats[j].schedulingInstanceTag != schedulingInstanceTag) {
        j++;
    }

    // Check if the phy stats was found
    if (j == numPhyStats) {
        printf("Error: The phy stats with scheduling instance tag %d were not found\n", schedulingInstanceTag);
        return;
    }

    // Update the rb utilization for the given transport channel and scheduling instance tag
    phyStats[j].rbUtilization = rbUtilization;
}
