// Define the function to create a memory pool
struct MemoryPool* createMemoryPool(size_t size) {
    // Allocate memory for the memory pool
    struct MemoryPool* memoryPool = malloc(sizeof(struct MemoryPool));

    // Check if the allocation was successful
    if (memoryPool == NULL) {
        printf("Error: Unable to allocate memory for memory pool\n");
        return NULL;
    }

    // Initialize the memory pool
    memoryPool->size = size;
    memoryPool->usedMemory = 0;
    memoryPool->freeList = NULL;

    // Return the memory pool
    return memoryPool;
}

// Define the function to free a memory pool
void freeMemoryPool(struct MemoryPool* memoryPool) {
    // Free the memory pool
    free(memoryPool);
}

// Define the function to allocate memory from a memory pool
void* allocateFromMemoryPool(struct MemoryPool* memoryPool, size_t size) {
    // Check if there is enough memory in the memory pool
    if (memoryPool->usedMemory + size > memoryPool->size) {
        return NULL;
    }

    // Allocate memory from the memory pool
    void* memory = malloc(size);

    // Check if the allocation was successful
    if (memory == NULL) {
        printf("Error: Unable to allocate memory from memory pool\n");
        return NULL;
    }

    // Update the used memory in the memory pool
    memoryPool->usedMemory += size;

    // Return the allocated memory
    return memory;
}

// Define the function to free memory from a memory pool
void freeFromMemoryPool(struct MemoryPool* memoryPool, void* memory) {
    // Check if the memory is in the memory pool
    if (memoryPool->freeList == NULL || memoryPool->freeList > memory) {
        return;
    }

    // Free the memory from the memory pool
    free(memory);

    // Update the used memory in the memory pool
    memoryPool->usedMemory -= size;
}
