        }

        for (int i = 0; i < json_object_array_length(cipher_suites); i++) {
            const char *cipher_suite = json_object_get_string(json_object_array_get_idx(cipher_suites, i));
            if (!SSL_set_cipher_list(method, cipher_suite)) {
                return NULL;
            }
        }
    }

    // Set the additional metadata for the SSL method
    if (additional_metadata) {
        json_object *metadata = json_object_get_object(additional_metadata);
        if (!metadata) {
            return NULL;
        }

        const char *key = json_object_get_string(json_object_get_string(metadata, "key"));
        const char *value = json_object_get_string(json_object_get_string(metadata, "value"));
        if (!SSL_set_ex_data(method, key, value)) {
            return NULL;
        }
    }

    // Return the initialized SSL method structure
    return method;
}

// Define the function to handle TLS handshake processes and manage cipher suites
TLS_HANDSHAKE_INFO *handle_tls_handshake(const char *json) {
    // Validate the JSON object string representing a TLS handshake response
    if (!validate_tls_handshake(json)) {
        return NULL;
    }

    // Initialize and manage cipher suites for the TLS handshake process
    SSL_METHOD *method = init_cipher_suites(json);
    if (!method) {
        return NULL;
    }

    // Create a new SSL object with the initialized SSL method structure
    SSL *ssl = SSL_new(method);
    if (!ssl) {
        return NULL;
    }

    // Set the SSL object to use the TLS handshake response JSON object string
    SSL_set_fd(ssl, json);

    // Perform the TLS handshake process and manage the cipher suites
    int ret = SSL_connect(ssl);
    if (ret <= 0) {
        return NULL;
    }

    // Get the selected cipher suite for the TLS handshake process
    const char *cipher_suite = SSL_get_cipher_name(ssl);
    if (!cipher_suite) {
        return NULL;
    }

    // Create a new TLS handshake information structure with the selected cipher suite and validity flag
    TLS_HANDSHAKE_INFO *info = malloc(sizeof(TLS_HANDSHAKE_INFO));
    info->method = method;
    info->valid = true;

    // Return the initialized TLS handshake information structure
    return info;
}
