#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

// Define the structure to hold the event data
typedef struct {
    char *event_type;
    char *source_ip;
    int timestamp;
} Event;

// Define the function to filter and aggregate events
void process_events(Event *events, size_t num_events) {
    // Initialize the output file
    FILE *output = fopen("summary.txt", "w");
    if (!output) {
        perror("fopen");
        return;
    }

    // Filter and aggregate events based on user-provided criteria
    for (size_t i = 0; i < num_events; ++i) {
        Event *event = &events[i];
        if (strcmp(event->event_type, "filter") == 0 && strcmp(event->source_ip, "192.168.1.1") == 0) {
            // Aggregate events by time
            int timestamp = event->timestamp;
            while (i < num_events && events[i].timestamp == timestamp) {
                ++i;
            }
            --i;
        } else if (strcmp(event->event_type, "aggregate") == 0 && strcmp(event->source_ip, "192.168.1.2") == 0) {
            // Aggregate events by source IP
            char *source_ip = event->source_ip;
            while (i < num_events && strcmp(events[i].source_ip, source_ip) == 0) {
                ++i;
            }
            --i;
        } else {
            // Write the filtered and aggregated events to the output file
            fprintf(output, "%s %s %d\n", event->event_type, event->source_ip, event->timestamp);
        }
    }

    // Close the output file
    fclose(output);
}

// Define the function to read and process events from a log file
void *read_events(void *args) {
    // Cast the arguments to the correct types
    char *input_file = (char *)args;
    FILE *input = fopen(input_file, "r");
    if (!input) {
        perror("fopen");
        return NULL;
    }

    // Read and process events from the input file
    Event *events = malloc(sizeof(Event));
    size_t num_events = 0;
    while (fscanf(input, "%s %s %d", events[num_events].event_type, events[num_events].source_ip, &events[num_events].timestamp) == 3) {
        ++num_events;
        events = realloc(events, sizeof(Event) * (num_events + 1));
    }

    // Process the events and write the results to a summary file
    process_events(events, num_events);

    // Close the input file
    fclose(input);

    return NULL;
}

// Define the main function to handle command-line arguments and spawn threads for event processing
int main(int argc, char *argv[]) {
    if (argc != 6) {
        printf("Usage: %s <input_file> <output_file> <filter_string> <aggregation_type> <concurrency_level>\n", argv[0]);
        return 1;
    }

    // Parse the command-line arguments and validate them
    char *input_file = argv[1];
    char *output_file = argv[2];
    char *filter_string = argv[3];
    char *aggregation_type = argv[4];
    int concurrency_level = atoi(argv[5]);
    if (concurrency_level < 1) {
        printf("Invalid concurrency level: %d\n", concurrency_level);
        return 1;
    }

    // Spawn threads for event processing
    pthread_t *threads = malloc(sizeof(pthread_t) * concurrency_level);
    for (int i = 0; i < concurrency_level; ++i) {
        char *input_file_copy = strdup(input_file);
        if (!input_file_copy) {
            perror("strdup");
            return 1;
        }
        int rc = pthread_create(&threads[i], NULL, read_events, input_file_copy);
        if (rc != 0) {
            printf("Error spawning thread: %d\n", rc);
            return 1;
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < concurrency_level; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Free the memory allocated for the threads
    free(threads);

    return 0;
}
