// Define the structure for transport channel information
typedef struct {
    int TRANSPORT_CHANNEL_ID;
    int BANDWIDTH;
    int SCHEDULING_INSTANCE_TAG;
} LTE_TRANSPORT_CHANNEL_T;

// Define the structure for PHY statistics
typedef struct {
    float RB_Utilization;
    float SRS_Utilization;
    float PDCCH_Utilization;
} LTE_PHY_STATS_T;

// Define the array of transport channels and their associated statistics
LTE_TRANSPORT_CHANNEL_T *transport_channels = NULL;
LTE_PHY_STATS_T *phy_stats = NULL;
int num_transport_channels = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new transport channel and its associated statistics
void add_transport_channel(int TRANSPORT_CHANNEL_ID, int BANDWIDTH, int SCHEDULING_INSTANCE_TAG) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the transport channel ID is valid
    if (TRANSPORT_CHANNEL_ID < 0 || TRANSPORT_CHANNEL_ID >= num_transport_channels) {
        printf("Invalid transport channel ID: %d\n", TRANSPORT_CHANNEL_ID);
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Check if the bandwidth is valid
    if (BANDWIDTH <= 0) {
        printf("Invalid bandwidth: %d\n", BANDWIDTH);
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Check if the scheduling instance tag is valid
    if (SCHEDULING_INSTANCE_TAG < 0 || SCHEDULING_INSTANCE_TAG >= num_transport_channels) {
        printf("Invalid scheduling instance tag: %d\n", SCHEDULING_INSTANCE_TAG);
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Allocate memory for the new transport channel and its associated statistics
    LTE_TRANSPORT_CHANNEL_T *new_transport_channel = (LTE_TRANSPORT_CHANNEL_T *)malloc(sizeof(LTE_TRANSPORT_CHANNEL_T));
    LTE_PHY_STATS_T *new_phy_stats = (LTE_PHY_STATS_T *)malloc(sizeof(LTE_PHY_STATS_T));

    // Initialize the new transport channel and its associated statistics
    new_transport_channel->TRANSPORT_CHANNEL_ID = TRANSPORT_CHANNEL_ID;
    new_transport_channel->BANDWIDTH = BANDWIDTH;
    new_transport_channel->SCHEDULING_INSTANCE_TAG = SCHEDULING_INSTANCE_TAG;
    new_phy_stats->RB_Utilization = 0.0f;
    new_phy_stats->SRS_Utilization = 0.0f;
    new_phy_stats->PDCCH_Utilization = 0.0f;

    // Add the new transport channel and its associated statistics to the array
    transport_channels[num_transport_channels] = *new_transport_channel;
    phy_stats[num_transport_channels] = *new_phy_stats;
    num_transport_channels++;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to remove a transport channel and its associated statistics
void remove_transport_channel(int TRANSPORT_CHANNEL_ID) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the transport channel ID is valid
    if (TRANSPORT_CHANNEL_ID < 0 || TRANSPORT_CHANNEL_ID >= num_transport_channels) {
        printf("Invalid transport channel ID: %d\n", TRANSPORT_CHANNEL_ID);
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Remove the transport channel and its associated statistics from the array
    LTE_TRANSPORT_CHANNEL_T *removed_transport_channel = &transport_channels[TRANSPORT_CHANNEL_ID];
    LTE_PHY_STATS_T *removed_phy_stats = &phy_stats[TRANSPORT_CHANNEL_ID];
    transport_channels[TRANSPORT_CHANNEL_ID] = transport_channels[num_transport_channels - 1];
    phy_stats[TRANSPORT_CHANNEL_ID] = phy_stats[num_transport_channels - 1];
    num_transport_channels--;

    // Free the memory for the removed transport channel and its associated statistics
    free(removed_transport_channel);
    free(removed_phy_stats);

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to update the PHY statistics for a transport channel
void update_phy_stats(int TRANSPORT_CHANNEL_ID, float RB_Utilization, float SRS_Utilization, float PDCCH_Utilization) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the transport channel ID is valid
    if (TRANSPORT_CHANNEL_ID < 0 || TRANSPORT_CHANNEL_ID >= num_transport_channels) {
        printf("Invalid transport channel ID: %d\n", TRANSPORT_CHANNEL_ID);
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Check if the RB utilization, SRS utilization, and PDCCH utilization are valid
    if (RB_Utilization < 0.0f || SRS_Utilization < 0.0f || PDCCH_Utilization < 0.0f) {
        printf("Invalid utilization values: %f, %f, %f\n", RB_Utilization, SRS_Utilization, PDCCH_Utilization);
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Update the PHY statistics for the transport channel
    phy_stats[TRANSPORT_CHANNEL_ID].RB_Utilization = RB_Utilization;
    phy_stats[TRANSPORT_CHANNEL_ID].SRS_Utilization = SRS_Utilization;
    phy_stats[TRANSPORT_CHANNEL_ID].PDCCH_Utilization = PDCCH_Utilization;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to generate a summary report for all transport channels and their associated statistics
void generate_summary_report() {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Initialize the average and peak utilization metrics
    float avg_RB_Utilization = 0.0f;
    float peak_RB_Utilization = 0.0f;
    float avg_SRS_Utilization = 0.0f;
    float peak_SRS_Utilization = 0.0f;
    float avg_PDCCH_Utilization = 0.0f;
    float peak_PDCCH_Utilization = 0.0f;

    // Iterate over all transport channels and their associated statistics
    for (int i = 0; i < num_transport_channels; i++) {
        // Calculate the average and peak utilization metrics for each type of utilization metric
        avg_RB_Utilization += phy_stats[i].RB_Utilization;
        if (phy_stats[i].RB_Utilization > peak_RB_Utilization) {
            peak_RB_Utilization = phy_stats[i].RB_Utilization;
        }
        avg_SRS_Utilization += phy_stats[i].SRS_Utilization;
        if (phy_stats[i].SRS_Utilization > peak_SRS_Utilization) {
            peak_SRS_Utilization = phy_stats[i].SRS_Utilization;
        }
        avg_PDCCH_Utilization += phy_stats[i].PDCCH_Utilization;
        if (phy_stats[i].PDCCH_Utilization > peak_PDCCH_Utilization) {
            peak_PDCCH_Utilization = phy_stats[i].PDCCH_Utilization;
        }
    }

    // Print the summary report
    printf("Summary Report:\n");
    printf("Average RB Utilization: %f\n", avg_RB_Utilization / num_transport_channels);
    printf("Peak RB Utilization: %f\n", peak_RB_Utilization);
    printf("Average SRS Utilization: %f\n", avg_SRS_Utilization / num_transport_channels);
    printf("Peak SRS Utilization: %f\n", peak_SRS_Utilization);
    printf("Average PDCCH Utilization: %f\n", avg_PDCCH_Utilization / num_transport_channels);
    printf("Peak PDCCH Utilization: %f\n", peak_PDCCH_Utilization);

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}
