// Define the function to add a new network interface
void addNetworkInterface(int InterfaceID, char* IPAddress, char* SubnetMask) {
    // Acquire the lock on the network interfaces array
    pthread_mutex_lock(&networkInterfacesMutex);

    // Check if the interface ID is already in use
    for (int i = 0; i < numNetworkInterfaces; i++) {
        if (networkInterfaces[i].InterfaceID == InterfaceID) {
            pthread_mutex_unlock(&networkInterfacesMutex);
            return; // Return early if the interface ID is already in use
        }
    }

    // Allocate memory for the new network interface config structure
    NetworkInterfaceConfig* newNetworkInterface = malloc(sizeof(NetworkInterfaceConfig));
    if (newNetworkInterface == NULL) {
        pthread_mutex_unlock(&networkInterfacesMutex);
        return; // Return early if memory allocation failed
    }

    // Initialize the new network interface config structure
    newNetworkInterface->InterfaceID = InterfaceID;
    newNetworkInterface->IPAddress = IPAddress;
    newNetworkInterface->SubnetMask = SubnetMask;
    newNetworkInterface->NetworkStatus = 0; // Set to inactive by default

    // Add the new network interface config structure to the array
    networkInterfaces = realloc(networkInterfaces, (numNetworkInterfaces + 1) * sizeof(NetworkInterfaceConfig));
    if (networkInterfaces == NULL) {
        free(newNetworkInterface);
        pthread_mutex_unlock(&networkInterfacesMutex);
        return; // Return early if memory reallocation failed
    }
    networkInterfaces[numNetworkInterfaces++] = *newNetworkInterface;

    // Release the lock on the network interfaces array
    pthread_mutex_unlock(&networkInterfacesMutex);
}

