// Define the structure for UE simulation sessions
typedef struct {
    char *sim_card_identifier;
    char *imsi;
    char *message_type;
    int message_flag;
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
    int crcflag;
} ue_session_t;

// Define the array of structures for managing UE simulation sessions
#define MAX_UE_SESSIONS 100000
ue_session_t *ue_sessions[MAX_UE_SESSIONS];

// Define the mutex for thread-safe operations
pthread_mutex_t ue_sessions_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the function to read a line from a file and parse it into an UE session structure
int read_ue_session(FILE *file, char *delimiter, ue_session_t *ue_session) {
    // Read a line from the file
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    if ((read = getline(&line, &len, file)) == -1) {
        return -1;
    }

    // Parse the line into an UE session structure
    char *token = strtok(line, delimiter);
    int i = 0;
    while (token != NULL && i < MAX_UE_SESSIONS) {
        switch (i) {
            case 0:
                ue_session->sim_card_identifier = token;
                break;
            case 1:
                ue_session->imsi = token;
                break;
            case 2:
                ue_session->message_type = token;
                break;
            case 3:
                ue_session->message_flag = atoi(token);
                break;
            case 4:
                ue_session->rx_ue_information_tag = atoi(token);
                break;
            case 5:
                ue_session->rnti = atoi(token);
                break;
            case 6:
                ue_session->crc_indication_rel8_tag = atoi(token);
                break;
            case 7:
                ue_session->crcflag = atoi(token);
                break;
        }
        token = strtok(NULL, delimiter);
        i++;
    }

    // Free the memory allocated for the line
    free(line);

    return 0;
}

// Define the function to read multiple input files and count the number of lines using a specified delimiter
int read_input_files(char **file_names, int num_files, char *delimiter) {
    // Initialize the line count variable
    int line_count = 0;

    // Loop through each file and read its contents
    for (int i = 0; i < num_files; i++) {
        FILE *file = fopen(file_names[i], "r");
        if (file == NULL) {
            printf("Error: unable to open input file %s\n", file_names[i]);
            return -1;
        }

        // Read the contents of the file line by line and count the number of lines
        char *line = NULL;
        size_t len = 0;
        ssize_t read;
        while ((read = getline(&line, &len, file)) != -1) {
            // Check if the line is a comment or an empty line
            if (line[0] == '#' || line[0] == '\n') {
                continue;
            }

            // Increment the line count
            line_count++;
        }

        // Free the memory allocated for the line
        free(line);

        // Close the file
        fclose(file);
    }

    return line_count;
}

// Define the function to decompress a compressed file using zlib
int decompress_file(char *file_name, char **decompressed_data) {
    // Open the compressed file for reading
    FILE *file = fopen(file_name, "rb");
    if (file == NULL) {
        printf("Error: unable to open compressed input file %s\n", file_name);
        return -1;
    }

    // Get the size of the compressed data
    fseek(file, 0, SEEK_END);
    long int size = ftell(file);
    rewind(file);

    // Allocate memory for the decompressed data
    *decompressed_data = (char *)malloc(size);
    if (*decompressed_data == NULL) {
        printf("Error: unable to allocate memory for decompressed data\n");
        return -1;
    }

    // Decompress the data using zlib
    int ret = uncompress((unsigned char *)*decompressed_data, size, (const unsigned char *)file);
    if (ret != Z_OK) {
        printf("Error: unable to decompress input file %s\n", file_name);
        return -1;
    }

    // Close the compressed file
    fclose(file);

    return 0;
}

