    if (ue_sessions == NULL) {
        handle_memory_allocation_failure();
        return -1;
    }

    // Initialize the mutex for thread-safe operations
    pthread_mutex_init(&ue_sessions_mutex, NULL);

    // Loop through each input file and read its contents
    for (int i = 1; i < argc - 1; i++) {
        FILE *file = fopen(argv[i], "r");
