#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pthread.h>
#include <zlib.h>

// Define constants for hash table size and delimiter
#define HASH_SIZE 100000
#define DELIMITER ' '

// Define struct for session data
struct Session {
    char* session_id;
    char* user_name;
    int login_status;
    time_t login_time;
    time_t last_access_time;
    char* last_location;
    int session_duration;
    int status_flag;
};

// Define struct for hash table node
struct HashNode {
    struct Session* session;
    struct HashNode* next;
};

// Define struct for hash table
struct HashTable {
    struct HashNode** nodes;
    int size;
};

// Function to initialize hash table
void init_hash_table(struct HashTable* hash_table) {
    // Allocate memory for hash table nodes
    hash_table->nodes = (struct HashNode**)malloc(sizeof(struct HashNode*) * HASH_SIZE);
    if (!hash_table->nodes) {
        printf("Error: unable to allocate memory for hash table\n");
        exit(1);
    }

    // Initialize each node in the hash table
    for (int i = 0; i < HASH_SIZE; i++) {
        hash_table->nodes[i] = NULL;
    }

    // Set size of hash table
    hash_table->size = HASH_SIZE;
}

// Function to insert session data into hash table
void insert_session(struct HashTable* hash_table, struct Session* session) {
    // Calculate hash value for session ID
    int hash_value = calculate_hash(session->session_id);

    // Check if hash value is within bounds of hash table
    if (hash_value < 0 || hash_value >= HASH_SIZE) {
        printf("Error: invalid hash value\n");
        exit(1);
    }

    // Insert session data into hash table node
    struct HashNode* new_node = (struct HashNode*)malloc(sizeof(struct HashNode));
    if (!new_node) {
        printf("Error: unable to allocate memory for hash table node\n");
        exit(1);
    }
    new_node->session = session;
    new_node->next = hash_table->nodes[hash_value];
    hash_table->nodes[hash_value] = new_node;
}

// Function to calculate hash value for a given string
int calculate_hash(char* str) {
    int hash_value = 0;
    for (int i = 0; i < strlen(str); i++) {
        hash_value += str[i];
    }
    return hash_value % HASH_SIZE;
}

// Function to read log file and parse timestamps
void read_log_file(struct HashTable* hash_table, char* filename) {
    // Open log file for reading
    FILE* fp = fopen(filename, "r");
    if (!fp) {
        printf("Error: unable to open log file\n");
        exit(1);
    }

    // Read log file line by line
    char buffer[256];
    while (fgets(buffer, sizeof(buffer), fp)) {
        // Parse timestamp from line
        char* timestamp = strtok(buffer, DELIMITER);
        if (!timestamp) {
            printf("Error: unable to parse timestamp\n");
            exit(1);
        }

        // Convert timestamp to time_t format
        struct tm tm;
        memset(&tm, 0, sizeof(struct tm));
        strptime(timestamp, "%Y-%m-%d %H:%M:%S", &tm);
        time_t login_time = mktime(&tm);

        // Parse session ID from line
        char* session_id = strtok(NULL, DELIMITER);
        if (!session_id) {
            printf("Error: unable to parse session ID\n");
            exit(1);
        }

        // Check if session ID is already in hash table
        int hash_value = calculate_hash(session_id);
        struct HashNode* node = hash_table->nodes[hash_value];
        while (node) {
            if (!strcmp(node->session->session_id, session_id)) {
                // Update last access time and duration for existing session
                node->session->last_access_time = login_time;
                node->session->session_duration += (login_time - node->session->login_time);
                break;
            }
            node = node->next;
        }

        // If session ID is not in hash table, create new session data and insert into hash table
        if (!node) {
            struct Session* new_session = (struct Session*)malloc(sizeof(struct Session));
            if (!new_session) {
                printf("Error: unable to allocate memory for new session\n");
                exit(1);
            }
            strcpy(new_session->session_id, session_id);
            new_session->login_time = login_time;
            new_session->last_access_time = login_time;
            new_session->session_duration = 0;
            insert_session(hash_table, new_session);
        }
    }

    // Close log file
    fclose(fp);
}

// Function to calculate total login attempts and average session duration
void calculate_stats(struct HashTable* hash_table) {
    int total_login_attempts = 0;
    int total_session_duration = 0;
    for (int i = 0; i < HASH_SIZE; i++) {
        struct HashNode* node = hash_table->nodes[i];
        while (node) {
            total_login_attempts++;
            total_session_duration += node->session->session_duration;
            node = node->next;
        }
    }
    printf("Total login attempts: %d\n", total_login_attempts);
    if (total_login_attempts > 0) {
        printf("Average session duration: %.2f minutes\n", (double)total_session_duration / total_login_attempts / 60);
    }
}

// Function to write report to output file
void write_report(struct HashTable* hash_table, char* filename) {
    // Open output file for writing
    FILE* fp = fopen(filename, "w");
    if (!fp) {
        printf("Error: unable to open output file\n");
        exit(1);
    }

    // Write header line to output file
    fprintf(fp, "Session ID,User Name,Login Status,Login Time,Last Access Time,Last Location,Session Duration,Status Flag\n");

    // Iterate through hash table and write each session data to output file
    for (int i = 0; i < HASH_SIZE; i++) {
        struct HashNode* node = hash_table->nodes[i];
        while (node) {
            fprintf(fp, "%s,%s,%d,%ld,%ld,%s,%d,%d\n", node->session->session_id, node->session->user_name, node->session->login_status, node->session->login_time, node->session->last_access_time, node->session->last_location, node->session->session_duration, node->session->status_flag);
            node = node->next;
        }
    }

    // Close output file
    fclose(fp);
}

// Main function to read log files and generate report
int main(int argc, char* argv[]) {
    // Check for correct number of arguments
    if (argc < 3) {
        printf("Usage: %s input_file1 [input_file2 ...]\n", argv[0]);
        return 1;
    }

    // Initialize hash table and read log files
    struct HashTable* hash_table = (struct HashTable*)malloc(sizeof(struct HashTable));
    init_hash_table(hash_table);
    for (int i = 1; i < argc; i++) {
        read_log_file(hash_table, argv[i]);
    }

    // Calculate total login attempts and average session duration
    calculate_stats(hash_table);

    // Write report to output file
    write_report(hash_table, "output.csv");

    // Clean up memory
    for (int i = 0; i < HASH_SIZE; i++) {
        struct HashNode* node = hash_table->nodes[i];
        while (node) {
            struct HashNode* next_node = node->next;
            free(node);
            node = next_node;
        }
    }
    free(hash_table);

    return 0;
}
