                    pthread_mutex_lock(&mutex);
                    file_names[file_index] = *input_file;
                    line_counts[file_index]++;
                    pthread_mutex_unlock(&mutex);
                } else {
                    pthread_mutex_lock(&mutex);
                    line_counts[file_index]++;
                    pthread_mutex_unlock(&mutex);
                }
            }
        }
        fclose(input);
        return NULL;
    }

    // Create threads for processing input files concurrently
    pthread_t *threads = malloc(num_files * sizeof(pthread_t));
    for (int i = 0; i < num_files; i++) {
        pthread_create(&threads[i], NULL, process_input_file, &input_file[i]);
    }

    // Join threads and print line counts for each file
    for (int i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
        if (file_names[i] != NULL) {
            printf("%s\t%ld\n", file_names[i], line_counts[i]);
        }
    }
}

