                    line_counts[file_index]++;
                } else {
                    line_counts[file_index]++;
                }
            }
        }
        fclose(input);
    }

    // Check for memory allocation failures and release all allocated memory
    if (file_names == NULL || line_counts == NULL) {
        printf("Memory allocation failure\n");
        exit(1);
    } else {
        free(file_names);
        free(line_counts);
    }
}

