        fclose(output_file);
    }
}

// Define the function to read a compressed file and decompress it using zlib
void read_compressed_file(char *filename, char **buffer, size_t *size) {
    // Open the compressed file for reading
    FILE *input_file = fopen(filename, "rb");
    if (input_file == NULL) {
        printf("Error: unable to open input file %s\n", filename);
        exit(1);
    }

    // Determine the size of the compressed data
    fseek(input_file, 0, SEEK_END);
    long compressed_size = ftell(input_file);
    rewind(input_file);

    // Allocate memory for the decompressed data
    *buffer = (char *)malloc(compressed_size);
    if (*buffer == NULL) {
        printf("Error: unable to allocate memory for decompression\n");
        exit(1);
    }

    // Decompress the data using zlib
    int result = uncompress(*buffer, compressed_size, input_file);
    if (result != Z_OK) {
        printf("Error: unable to decompress file %s\n", filename);
        exit(1);
    }

    // Close the compressed file and return the size of the decompressed data
    fclose(input_file);
    *size = compressed_size;
}

