#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>

// Define the structure for storing frame information
typedef struct {
    long timestamp;
    int resolution[2];
    bool is_keyframe;
} FRAME_INFO;

// Define the structure for storing a list of frames
typedef struct {
    int num_frames;
    FRAME_INFO *frames;
} MEDIA_FRAME_T;

// Define the function to dynamically allocate memory for a list of frames
int alloc_frame_list(int N, unsigned long seed) {
    // Allocate memory for the list of frames
    MEDIA_FRAME_T *frames = (MEDIA_FRAME_T *)malloc(sizeof(MEDIA_FRAME_T));
    if (!frames) {
        return -1;
    }

    // Initialize the number of frames and allocate memory for the list of frames
    frames->num_frames = N;
    frames->frames = (FRAME_INFO *)malloc(sizeof(FRAME_INFO) * N);
    if (!frames->frames) {
        free(frames);
        return -1;
    }

    // Initialize the seed for the random number generator
    srand(seed);

    // Populate the list of frames with random data
    for (int i = 0; i < N; i++) {
        frames->frames[i].timestamp = rand();
        frames->frames[i].resolution[0] = rand() % 1920 + 640;
        frames->frames[i].resolution[1] = rand() % 1080 + 360;
        frames->frames[i].is_keyframe = (rand() % 2) ? true : false;
    }

    return 0;
}

// Define the function to deallocate memory for a list of frames
void free_frame_list(MEDIA_FRAME_T *frames) {
    if (!frames) {
        return;
    }

    // Deallocate memory for the list of frames
    free(frames->frames);
    free(frames);
}

// Define the function to handle concurrent access from multiple threads safely
void thread_safe_list_operation(MEDIA_FRAME_T *frames, int operation) {
    // Implement a fine-grained lock to ensure that the list operations are thread-safe
    pthread_mutex_lock(&frames->mutex);

    // Perform the requested operation on the list of frames
    switch (operation) {
        case 0: // Add a new frame to the list
            // Allocate memory for the new frame and add it to the end of the list
            MEDIA_FRAME_T *new_frame = (MEDIA_FRAME_T *)malloc(sizeof(MEDIA_FRAME_T));
            if (!new_frame) {
                break;
            }
            new_frame->num_frames = 1;
            new_frame->frames = (FRAME_INFO *)malloc(sizeof(FRAME_INFO));
            if (!new_frame->frames) {
                free(new_frame);
                break;
            }
            frames->num_frames++;
            frames->frames = realloc(frames->frames, sizeof(FRAME_INFO) * frames->num_frames);
            if (!frames->frames) {
                free(new_frame->frames);
                free(new_frame);
                break;
            }
            memcpy(&frames->frames[frames->num_frames - 1], new_frame->frames, sizeof(FRAME_INFO));
            free(new_frame->frames);
            free(new_frame);
            break;
        case 1: // Remove a frame from the list
            // Check if there are any frames in the list
            if (frames->num_frames == 0) {
                break;
            }

            // Remove the last frame from the list and deallocate its memory
            free(frames->frames[frames->num_frames - 1]);
            frames->num_frames--;
            frames->frames = realloc(frames->frames, sizeof(FRAME_INFO) * frames->num_frames);
            if (!frames->frames) {
                break;
            }
            break;
        case 2: // Update a frame in the list
            // Check if there are any frames in the list
            if (frames->num_frames == 0) {
                break;
            }

            // Find the index of the frame to update and update its information
            int index = rand() % frames->num_frames;
            frames->frames[index].timestamp = rand();
            frames->frames[index].resolution[0] = rand() % 1920 + 640;
            frames->frames[index].resolution[1] = rand() % 1080 + 360;
            frames->frames[index].is_keyframe = (rand() % 2) ? true : false;
            break;
    }

    // Unlock the mutex to allow other threads to access the list
    pthread_mutex_unlock(&frames->mutex);
}

