#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void process_log(char* input_file, char* output_file, char* filter_criteria, bool debug) {
    // Open the input log file and read its contents into a buffer
    FILE* fp = fopen(input_file, "r");
    if (fp == NULL) {
        printf("Error: unable to open input log file\n");
        return;
    }
    char* buffer = malloc(sizeof(char) * 1024);
    size_t bytes_read = fread(buffer, sizeof(char), 1024, fp);
    if (bytes_read == 0) {
        printf("Error: unable to read input log file\n");
        return;
    }
    // Close the input log file
    fclose(fp);

    // Parse the buffer and extract relevant information
    char* event = strtok(buffer, "\n");
    while (event != NULL) {
        // Check if the event matches the filter criteria
        if (strstr(event, filter_criteria) != NULL) {
            // Add the event to the output report
            fprintf(output_file, "%s\n", event);
        }
        event = strtok(NULL, "\n");
    }

    // Close the output report file
    fclose(output_file);
}
