    long* offset_array = malloc(1000000 * sizeof(long));
    int* key_array = malloc(1000000 * sizeof(int));
    struct record* record_array = malloc(1000000 * sizeof(struct record));
    struct event* event_array = malloc(1000000 * sizeof(struct event));
    struct audit* audit_array = malloc(1000000 * sizeof(struct audit));

    // Initialize the arrays with random values within a specified range
    for (int i = 0; i < 1000000; i++) {
        offset_array[i] = rand() % 1000000;
        key_array[i] = rand() % 1000000;
        record_array[i].id = rand() % 1000000;
        record_array[i].value1 = rand() % 1000000;
        record_array[i].value2 = rand() % 1000000;
        event_array[i].timestamp = time(NULL);
        event_array[i].message = "Random message";
        audit_array[i].access_count = 0;
        audit_array[i].last_accessed = 0;
