        purge_records(audit_array);
    }

    // Handle concurrent writes to the log file by using a mutex lock
    pthread_mutex_lock(&mutex);

    // Process high-priority events immediately if specified
    if (priority_level > 0) {
        process_high_priority(event_array, priority_level);
    }

    // Write the summarized report to the output file
    write_report(output_file, merged_size, offset_array, key_array, record_array, event_array, audit_array);

    // Release resources properly upon exit
    free(offset_array);
    free(key_array);
    free(record_array);
    free(event_array);
    free(audit_array);
    pthread_mutex_unlock(&mutex);
