// Merge the arrays into a single sorted array based on the 'key' values
int merge(long* offset_array, int* key_array, struct record* record_array, struct event* event_array, struct audit* audit_array) {
    // Initialize the merged array with the same size as the input arrays
    int merged_size = 0;
    for (int i = 0; i < 1000000; i++) {
        merged_size += offset_array[i] + key_array[i] + record_array[i].id + record_array[i].value1 + record_array[i].value2 + event_array[i].timestamp + strlen(event_array[i].message) + audit_array[i].access_count + audit_array[i].last_accessed;
    }

    // Allocate memory for the merged array and initialize it with random values within a specified range
    long* merged_offset_array = malloc(merged_size * sizeof(long));
    int* merged_key_array = malloc(merged_size * sizeof(int));
    struct record* merged_record_array = malloc(merged_size * sizeof(struct record));
    struct event* merged_event_array = malloc(merged_size * sizeof(struct event));
    struct audit* merged_audit_array = malloc(merged_size * sizeof(struct audit));

    // Merge the arrays into a single sorted array based on the 'key' values
    for (int i = 0; i < 1000000; i++) {
        merged_offset_array[i] = offset_array[i];
        merged_key_array[i] = key_array[i];
        merged_record_array[i].id = record_array[i].id;
        merged_record_array[i].value1 = record_array[i].value1;
        merged_record_array[i].value2 = record_array[i].value2;
        merged_event_array[i].timestamp = event_array[i].timestamp;
        merged_event_array[i].message = event_array[i].message;
        merged_audit_array[i].access_count = audit_array[i].access_count;
        merged_audit_array[i].last_accessed = audit_array[i].last_accessed;
    }

