    return merged_size;
}

// Purge less frequently accessed records to maintain performance and resource utilization
void purge_records(struct audit* audit_array) {
    // Initialize a variable to keep track of the number of purged records
    int purged_count = 0;

    // Iterate through the array and check if each record has been accessed less frequently than the purge threshold
    for (int i = 0; i < 1000000; i++) {
