    }

    // Log the number of purged records and return the updated array size
    syslog(LOG_INFO, "Purged %d records to maintain performance and resource utilization.", purged_count);
    return 1000000 - purged_count;
}

// Process high-priority events immediately if specified
void process_high_priority(struct event* event_array, int priority_level) {
    // Iterate through the array and check if each event has a priority level higher than the specified threshold
    for (int i = 0; i < 1000000; i++) {
        if (event_array[i].priority > priority_level) {
            // If an event is found to be high-priority, process it immediately and remove it from the array
            process_event(event_array[i]);
            event_array[i] = event_array[1000000 - 1];
            event_array[1000000 - 1] = NULL;
        }
    }
}

// Write the summarized report to the output file
void write_report(char* output_file, int merged_size, long* offset_array, int* key_array, struct record* record_array, struct event* event_array, struct audit* audit_array) {
    // Open the output file in append mode
    FILE* fp = fopen(output_file, "a");

    // Write the header for the report
    fprintf(fp, "Offset\tKey\tRecord ID\tValue 1\tValue 2\tTimestamp\tMessage\n");

    // Iterate through the merged array and write each record to the output file
    for (int i = 0; i < merged_size; i++) {
        fprintf(fp, "%ld\t%d\t%d\t%d\t%d\t%d\t%s\n", offset_array[i], key_array[i], record_array[i].id, record_array[i].value1, record_array[i].value2, event_array[i].timestamp, event_array[i].message);
    }

    // Close the output file
    fclose(fp);
}
```
This code block defines a function `process_log` that processes a large-scale log file containing structured event data. The function accepts seven command-line arguments: the name of the input log file, the name of the output report file, a string specifying the filter criteria for events, a boolean flag indicating whether to include additional debug information in the report, a numeric threshold for purging less frequently accessed records, a priority level for handling high-priority events separately, and a flag indicating whether the log file should be processed asynchronously.

The function initializes five dynamic arrays: one for storing 'long' offset values, another for 'int' keys, a third for 'record' structures, a fourth for 'event' structures, and a fifth for 'audit' entries. Each 'record' structure contains multiple 'int' fields, and each 'event' structure includes additional metadata and timestamps. The function handles the allocation and resizing of these arrays efficiently to accommodate up to 10 million elements per array, ensuring optimal performance even under high load conditions.

The function merges the 'offset', 'key', 'record', 'event', and 'audit' arrays into a single sorted array based on the 'key' values using the `merge` function. If the merged array size exceeds 750,000 elements, the function triggers a system log warning and initiates a process to purge less frequently accessed records to maintain performance and resource utilization using the `purge_records` function.

The function also handles concurrent writes to the log file by using a mutex lock. If high-priority events are specified, the function processes them immediately using the `process_high_priority` function. Finally, the function writes the summarized report to the output file using the `write_report` function.

