#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

struct logging_config {
    int log_fd;
    char *log_path;
    int strict_mode;
};

char* append_slash(const char *str, size_t size_limit, struct logging_config *config, int fd) {
    // Validate input parameters
    if (str == NULL || size_limit <= 0 || config == NULL || fd < 0) {
        return NULL;
    }

    // Determine if the string contains any multi-byte characters and ensure correct handling of them without truncation
    size_t str_len = strnlen(str, size_limit);
    size_t mb_char_count = 0;
    for (size_t i = 0; i < str_len; i++) {
        if ((unsigned char)str[i] >= 128) {
            mb_char_count++;
        }
    }

    // Append a slash to the end of the string if it does not exceed the size limit, considering multi-byte character lengths
    size_t new_len = str_len + (mb_char_count > 0 ? mb_char_count : 1);
    if (new_len <= size_limit) {
        char *new_str = malloc(new_len + 1);
        if (new_str == NULL) {
            return NULL;
        }
        memcpy(new_str, str, str_len);
        new_str[str_len] = '/';
        new_str[new_len] = '\0';
        return new_str;
    } else {
        // Close the logging file descriptor and set a flag in the configuration structure indicating an error occurred
        close(fd);
        config->log_fd = -1;
        return NULL;
    }
}

char* append_slash_with_space(const char *str, size_t size_limit, struct logging_config *config, int fd) {
    // Validate input parameters
    if (str == NULL || size_limit <= 0 || config == NULL || fd < 0) {
        return NULL;
    }

    // Determine if the string contains any multi-byte characters and ensure correct handling of them without truncation
    size_t str_len = strnlen(str, size_limit);
    size_t mb_char_count = 0;
    for (size_t i = 0; i < str_len; i++) {
        if ((unsigned char)str[i] >= 128) {
            mb_char_count++;
        }
    }

    // Append a slash to the end of the string if it does not exceed the size limit, considering multi-byte character lengths
    size_t new_len = str_len + (mb_char_count > 0 ? mb_char_count : 1);
    if (new_len <= size_limit) {
        char *new_str = malloc(new_len + 1);
        if (new_str == NULL) {
            return NULL;
        }
        memcpy(new_str, str, str_len);
        new_str[str_len] = '/';
        new_str[new_len] = '\0';
        return new_str;
    } else if (config->strict_mode) {
        // Append an additional space before the slash if the string length is less than half of the size limit, taking into account multi-byte characters
        size_t half_size_limit = size_limit / 2;
        if (str_len < half_size_limit) {
            char *new_str = malloc(new_len + 1);
            if (new_str == NULL) {
                return NULL;
            }
            memcpy(new_str, str, str_len);
            new_str[str_len] = ' ';
            new_str[str_len + 1] = '/';
            new_str[new_len] = '\0';
            return new_str;
        } else {
            // Close the logging file descriptor and set a flag in the configuration structure indicating an error occurred
            close(fd);
            config->log_fd = -1;
            return NULL;
        }
    } else {
        // Close the logging file descriptor and set a flag in the configuration structure indicating an error occurred
        close(fd);
        config->log_fd = -1;
        return NULL;
    }
}
