    summary = {}
    for request_id in data:
        summary[request_id] = {
            "count": len(data[request_id]),
            "event_types": set([event["event_type"] for event in data[request_id]]),
            "severity_levels": set([event["severity_level"] for event in data[request_id]])
        }

    return summary
