    int total_weighted_sum;
    int max_age;
    int min_age;
    int max_num_transactions;
    int min_num_transactions;
    float max_weighted_sum;
    float min_weighted_sum;
};

struct compliance_audit {
    int data_protection_compliant;
    char *compliance_report;
};

struct transaction_result {
    struct transaction_data *transaction_data;
    struct oauth2_token_response *oauth2_token_response;
    struct encryption_config *encryption_config;
    struct metrics *metrics;
    struct compliance_audit *compliance_audit;
};

struct transaction_result process_transaction_and_verify_token(struct transaction_data *transaction_data, char *oauth2_token_response, char *encrypted_api_key, struct encryption_config *encryption_config, struct metrics *metrics, int compliance_status) {
    // Initialize the result structure
    struct transaction_result result = {0};

    // Filter transactions based on criteria
    if (transaction_data->age > 5 || transaction_data->num_transactions > 10) {
        return result;
    }

    // Validate OAuth2 access token
    struct oauth2_token_response *token_response = json_parse(oauth2_token_response);
    if (!token_response || !token_response->access_token || !token_response->expires_in || !token_response->token_type) {
        return result;
    }

    // Check token type and expiration time
    int valid_token = 0;
    for (int i = 0; i < encryption_config->num_allowed_modes; i++) {
        if (strcmp(token_response->token_type, encryption_config->allowed_modes[i]) == 0) {
            valid_token = 1;
            break;
        }
    }
    if (!valid_token || token_response->expires_in < 0) {
        return result;
    }

    // Handle encrypted communication securely
    EVP_CIPHER *cipher = NULL;
    int encryption_mode = -1;
    char *decrypted_api_key = NULL;
    if (encrypted_api_key) {
        cipher = EVP_get_cipherbyname(encryption_config->allowed_modes[0]);
        if (!cipher) {
            return result;
        }
        encryption_mode = EVP_CIPHER_CTX_new();
        if (EVP_EncryptInit_ex(encryption_mode, cipher, NULL, NULL, NULL) <= 0) {
            return result;
        }
        decrypted_api_key = malloc(sizeof(char) * EVP_CIPHER_CTX_block_size(encryption_mode));
        if (!decrypted_api_key) {
            return result;
        }
        int len = EVP_DecryptUpdate(encryption_mode, decrypted_api_key, encrypted_api_key);
        if (len <= 0) {
            return result;
        }
    }

    // Ensure compliance with regulatory standards for data protection
    struct compliance_audit *compliance_audit = malloc(sizeof(struct compliance_audit));
    if (!compliance_audit) {
        return result;
    }
    int data_protection_compliant = 0;
    char *compliance_report = NULL;
    // TODO: Implement compliance auditing logic here

    // Update metrics structure and compliance status accordingly
    if (metrics) {
        metrics->total_transactions++;
        metrics->total_weighted_sum += transaction_data->weighted_sum;
        metrics->max_age = max(metrics->max_age, transaction_data->age);
        metrics->min_age = min(metrics->min_age, transaction_data->age);
        metrics->max_num_transactions = max(metrics->max_num_transactions, transaction_data->num_transactions);
        metrics->min_num_transactions = min(metrics->min_num_transactions, transaction_data->num_transactions);
        metrics->max_weighted_sum = max(metrics->max_weighted_sum, transaction_data->weighted_sum);
        metrics->min_weighted_sum = min(metrics->min_weighted_sum, transaction_data->weighted_sum);
    }
    if (compliance_status) {
        compliance_audit->data_protection_compliant = data_protection_compliant;
        compliance_audit->compliance_report = compliance_report;
    }

    // Return result structure with all relevant information
    result.transaction_data = transaction_data;
    result.oauth2_token_response = token_response;
    result.encryption_config = encryption_config;
    result.metrics = metrics;
    result.compliance_audit = compliance_audit;
    return result;
}
