                free(recordArray[i]);
                recordArray[i] = NULL;
                totalRecordsProcessed--;
            }
            for (j = mergedSize - 1; j >= 0 && totalEventsProcessed > purgeThresholdInt; j--) {
                free(eventArray[j]);
                eventArray[j] = NULL;
                totalEventsProcessed--;
            }
            for (k = mergedSize - 1; k >= 0 && totalAuditsProcessed > purgeThresholdInt; k--) {
                free(auditArray[k]);
                auditArray[k] = NULL;
                totalAuditsProcessed--;
            }
            pthread_mutex_unlock(&semaphore);
        }
    }

