    records->records[records->size++] = record;
}

// Define the function to merge the 'offset', 'key', 'record', and 'event' arrays into a single sorted array
void merge_arrays(log_entry_t* entries, record_t* records, event_t* events) {
    // Initialize the merged array
    int size = 0;
    log_entry_t* merged_entries = malloc(10 * sizeof(log_entry_t));
    if (merged_entries == NULL) {
        perror("Error allocating memory for merged entries");
        return;
    }

    // Merge the arrays into a single sorted array
    int i = 0, j = 0, k = 0;
    while (i < records->size && j < events->size) {
        if (records->records[i].key <= events->events[j].key) {
            merged_entries[k++] = log_entry_t{records->records[i].offset, records->records[i].key, records->records[i], NULL};
            i++;
        } else {
            merged_entries[k++] = log_entry_t{events->events[j].offset, events->events[j].key, NULL, events->events[j]};
            j++;
        }
    }
    while (i < records->size) {
        merged_entries[k++] = log_entry_t{records->records[i].offset, records->records[i].key, records->records[i], NULL};
        i++;
    }
    while (j < events->size) {
        merged_entries[k++] = log_entry_t{events->events[j].offset, events->events[j].key, NULL, events->events[j]};
        j++;
    }

    // Sort the merged array
    qsort(merged_entries, size, sizeof(log_entry_t), compare_entries);

    // Write the merged array to the output file
    write_array(output_filename, merged_entries, size);

    // Release resources
    free(merged_entries);
}

// Define the function to purge less frequently accessed records if necessary
void purge_records(record_array_t* records, int purge_threshold) {
    // Check if the threshold is exceeded
    if (records->size > purge_threshold) {
        // Purge the least frequently accessed records
        qsort(records->records, records->size, sizeof(record_t), compare_records);
        int i = 0;
        while (i < records->size && records->records[i].access_count <= purge_threshold) {
            i++;
        }
        if (i > 0) {
            // Remove the least frequently accessed records from the array
            memmove(records->records, records->records + i, (records->size - i) * sizeof(record_t));
            records->size -= i;
        }
    }
}

// Define the function to write the report to the output file
void write_report(const char* output_filename, log_file_t log_file, record_array_t records, event_array_t events) {
