    write(fd, "Log File Report\n", strlen("Log File Report\n"));
    write(fd, "-----------------\n", strlen("-----------------\n"));
    write(fd, "Total number of events: ", strlen("Total number of events: "));
    write(fd, &log_file.size, sizeof(int));
    write(fd, "\n", 1);
    write(fd, "Total number of records: ", strlen("Total number of records: "));
    write(fd, &records.size, sizeof(int));
    write(fd, "\n", 1);
    write(fd, "Total number of events with priority level >=", strlen("Total number of events with priority level >="));
    write(fd, &priority_level, sizeof(int));
    write(fd, ": ", strlen(": "));
    write(fd, &events.size, sizeof(int));
    write(fd, "\n", 1);

    // Close the output file
    close(fd);
}

// Define the function to resize an array if necessary
void resize_array(array_t* array) {
    // Check if the array is full
    if (array->size == array->capacity) {
        // Double the capacity of the array
        int new_capacity = array->capacity * 2;
        void* new_data = realloc(array->data, new_capacity);
        if (new_data == NULL) {
            perror("Error resizing array");
            return;
        }

        // Update the array's capacity and data pointer
        array->capacity = new_capacity;
        array->data = new_data;
    }
}

// Define the function to compare two log entries by key
int compare_entries(const void* a, const void* b) {
    return ((log_entry_t*)a)->key - ((log_entry_t*)b)->key;
}

// Define the function to compare two records by access count
int compare_records(const void* a, const void* b) {
    return ((record_t*)a)->access_count - ((record_t*)b)->access_count;
}
