        perror("Error opening output file");
        fclose(input);
        exit(EXIT_FAILURE);
    }

    // Initialize the event data structure and filter criteria
    struct Event *event = malloc(sizeof(struct Event));
    if (event == NULL) {
        perror("Error allocating memory for event data");
        fclose(input);
        fclose(output);
        exit(EXIT_FAILURE);
    }
    char *filter = strdup(filter_criteria);

    // Read the input log file and extract relevant information
    while (fscanf(input, "%s %d %lf", event->event_name, &event->event_id, &event->timestamp) == 3) {
        // Check if the event matches the filter criteria
        bool match = true;
        for (int i = 0; i < strlen(filter); i++) {
            if (toupper(filter[i]) != toupper(event->event_name[i])) {
                match = false;
                break;
            }
        }
        // If the event matches, add it to the report
        if (match) {
            fprintf(output, "%s %d %.2f\n", event->event_name, event->event_id, event->timestamp);
        }
    }

    // Close the input and output files
    fclose(input);
    fclose(output);

    // Free memory allocated for the event data structure and filter criteria
    free(event);
    free(filter);
}

// Define the main function to handle command-line arguments and call the process_log function
int main(int argc, char *argv[]) {
    if (argc != 6) {
        printf("Usage: %s <input log file> <output report file> <filter criteria> <threshold value> <debug flag>\n", argv[0]);
        return EXIT_FAILURE;
    }

    // Call the process_log function with the command-line arguments
    process_log(argv[1], argv[2], argv[3], atoi(argv[4]), strcmp(argv[5], "true") == 0);

    return EXIT_SUCCESS;
}
