    char* metadata;
} MESSAGE_HEADER;

// Define the structure for storing message validation results
typedef struct {
    int validation_result;
    char* error_message;
} MESSAGE_VALIDATION;

// Define the structure for storing message protocol preferences
typedef struct {
    int amqp_preference;
    int mqtt_preference;
    int http2_preference;
    int websocket_preference;
} PROTOCOL_PREFERENCES;

