    memset(header_cache, 0, sizeof(MESSAGE_HEADER));

    // Initialize the message validation results cache
    MESSAGE_VALIDATION* validation_cache = (MESSAGE_VALIDATION*) malloc(sizeof(MESSAGE_VALIDATION));
