    }

    // Initialize the message queue and validate the message headers and metadata
    MESSAGE_QUEUE* message_queue = init_message_queue(config.preferences);
    for (int i = 0; i < config.preferences.amqp_preference; i++) {
        if (!validate_header(message_queue->headers[i], header_cache)) {
            printf("Invalid message header: %s\n", message_queue->headers[i]);
        } else {
            validation_cache[i].validation_result = 1;
        }
    }

    // Initialize the message transmission and receipt threads
    pthread_t* transmission_threads = (pthread_t*) malloc(sizeof(pthread_t) * config.preferences.amqp_preference);
    for (int i = 0; i < config.preferences.amqp_preference; i++) {
        pthread_create(&transmission_threads[i], NULL, transmit_message, message_queue->messages[i]);
    }
    pthread_t* reception_threads = (pthread_t*) malloc(sizeof(pthread_t) * config.preferences.amqp_preference);
    for (int i = 0; i < config.preferences.amqp_preference; i++) {
        pthread_create(&reception_threads[i], NULL, receive_message, message_queue->messages[i]);
    }

    // Wait for the transmission and reception threads to complete
    for (int i = 0; i < config.preferences.amqp_preference; i++) {
        pthread_join(transmission_threads[i], NULL);
        pthread_join(reception_threads[i], NULL);
    }

    // Clean up the message queue and validation results cache
    cleanup_message_queue(message_queue);
    free(validation_cache);
}

