    memset(message_queue->validation_cache, 0, sizeof(MESSAGE_VALIDATION) * preferences.amqp_preference);

    // Initialize the message transmission and receipt threads
    message_queue->transmission_threads = (pthread_t*) malloc(sizeof(pthread_t) * preferences.amqp_preference);
    memset(message_queue->transmission_threads, 0, sizeof(pthread_t) * preferences.amqp_preference);
    message_queue->reception_threads = (pthread_t*) malloc(sizeof(pthread_t) * preferences.amqp_preference);
    memset(message_queue->reception_threads, 0, sizeof(pthread_t) * preferences.amqp_preference);

    // Initialize the message data structures
    for (int i = 0; i < preferences.amqp_preference; i++) {
        message_queue->messages[i] = (MESSAGE_DATA*) malloc(sizeof(MESSAGE_DATA));
        memset(message_queue->messages[i], 0, sizeof(MESSAGE_DATA));
    }

    return message_queue;
}

// Define the function to clean up a message queue
void cleanup_message_queue(MESSAGE_QUEUE* message_queue) {
    // Clean up the message headers and metadata cache
    free(message_queue->header_cache);

    // Clean up the message validation results cache
    free(message_queue->validation_cache);

    // Clean up the message transmission and receipt threads
    free(message_queue->transmission_threads);
    free(message_queue->reception_threads);

    // Clean up the message data structures
    for (int i = 0; i < message_queue->preferences.amqp_preference; i++) {
        free(message_queue->messages[i]);
    }
}
