#include <openssl/evp.h>
#include <openssl/err.h>
#include <openssl/des.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define the supported cipher modes
typedef enum {
    ECB, EDE, EDE3, CFB
} CipherMode;

// Define the supported key lengths
typedef enum {
    KEY_LEN_64 = 64,
    KEY_LEN_128 = 128,
    KEY_LEN_192 = 192,
    KEY_LEN_256 = 256
} KeyLength;

// Define the cipher context structure
typedef struct {
    EVP_CIPHER_CTX *ctx;
    int key_len;
    CipherMode mode;
} CipherContext;

// Initialize a new cipher context
static void init_cipher(CipherContext *context, KeyLength key_len, CipherMode mode) {
    // Allocate memory for the cipher context
    context->ctx = EVP_CIPHER_CTX_new();

    // Set the key length and mode
    context->key_len = key_len;
    context->mode = mode;
}

// Load and initialize a new cipher based on input parameters
static void load_cipher(CipherContext *context, KeyLength key_len, CipherMode mode) {
    // Initialize the cipher context
    init_cipher(context, key_len, mode);

    // Load the appropriate cipher algorithm and initialize it
    switch (mode) {
        case ECB:
            EVP_EncryptInit_ex(context->ctx, EVP_des_ecb(), NULL, NULL, NULL);
            break;
        case EDE:
            EVP_EncryptInit_ex(context->ctx, EVP_des_ede(), NULL, NULL, NULL);
            break;
        case EDE3:
            EVP_EncryptInit_ex(context->ctx, EVP_des_ede3(), NULL, NULL, NULL);
            break;
        case CFB:
            EVP_EncryptInit_ex(context->ctx, EVP_des_cfb(), NULL, NULL, NULL);
            break;
    }
}

// Select and configure a cryptographic cipher based on runtime configuration settings
static EVP_CIPHER *select_cipher(KeyLength key_len, CipherMode mode) {
    // Initialize the cipher context
    CipherContext context;
    init_cipher(&context, key_len, mode);

    // Load and initialize the appropriate cipher algorithm
    load_cipher(&context, key_len, mode);

    // Return a pointer to the selected cipher
    return EVP_CIPHER_CTX_get_cipher(context.ctx);
}

// Encrypt data using the selected cipher
static int encrypt(const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
    // Initialize the cipher context
    CipherContext context;
    init_cipher(&context, KEY_LEN_128, ECB);

    // Load and initialize the appropriate cipher algorithm
    load_cipher(&context, KEY_LEN_128, ECB);

    // Set the encryption key
    EVP_CIPHER_CTX_set_key_length(context.ctx, 16);
    EVP_EncryptInit_ex(context.ctx, NULL, NULL, "0123456789abcdef", NULL);

    // Encrypt the data
    int ciphertext_len = 0;
    EVP_EncryptUpdate(context.ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len);

    // Clean up the cipher context
    EVP_CIPHER_CTX_free(context.ctx);

    return ciphertext_len;
}

// Decrypt data using the selected cipher
static int decrypt(const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext) {
    // Initialize the cipher context
    CipherContext context;
    init_cipher(&context, KEY_LEN_128, ECB);

    // Load and initialize the appropriate cipher algorithm
    load_cipher(&context, KEY_LEN_128, ECB);

    // Set the decryption key
    EVP_CIPHER_CTX_set_key_length(context.ctx, 16);
    EVP_DecryptInit_ex(context.ctx, NULL, NULL, "0123456789abcdef", NULL);

    // Decrypt the data
    int plaintext_len = 0;
    EVP_DecryptUpdate(context.ctx, plaintext, &plaintext_len, ciphertext, ciphertext_len);

    // Clean up the cipher context
    EVP_CIPHER_CTX_free(context.ctx);

    return plaintext_len;
}

// Main function for testing and debugging purposes
int main() {
    // Define the input data
    unsigned char plaintext[] = "Hello, World!";
    size_t plaintext_len = strlen((char *)plaintext);

    // Encrypt the input data
    unsigned char ciphertext[16];
    int ciphertext_len = encrypt(plaintext, plaintext_len, ciphertext);

    // Decrypt the encrypted data
    unsigned char decrypted_data[16];
    int decrypted_data_len = decrypt(ciphertext, ciphertext_len, decrypted_data);

    // Print the results
    printf("Plaintext: %s\n", plaintext);
    printf("Ciphertext: ");
    for (int i = 0; i < ciphertext_len; i++) {
        printf("%02x ", ciphertext[i]);
    }
    printf("\n");
    printf("Decrypted data: %s\n", decrypted_data);

    return 0;
}
```
This code defines a modular function `select_cipher` that selects and configures a cryptographic cipher using the DES algorithm (ECB, EDE, EDE3, and CFB modes) based on runtime configuration settings. The function dynamically loads and initializes the cipher based on input parameters, ensuring efficient memory usage and minimizing initialization overhead.

The `select_cipher` function takes two arguments: `key_len` (the length of the encryption key), and `mode` (the cipher mode). It returns a pointer to an `EVP_CIPHER` structure representing the selected cipher.

The `init_cipher` function initializes a new cipher context, allocating memory for the cipher context and setting the key length and mode.

The `load_cipher` function loads and initializes the appropriate cipher algorithm based on the input parameters. It sets the encryption or decryption key and initializes the cipher context using the `EVP_EncryptInit_ex` or `EVP_DecryptInit_ex` functions, depending on the mode.

The `encrypt` function encrypts data using the selected cipher. It takes three arguments: `plaintext` (the input plaintext data), `plaintext_len` (the length of the input plaintext data), and `ciphertext` (the output ciphertext). The function returns the length of the encrypted data.

The `decrypt` function decrypts data using the selected cipher. It takes three arguments: `ciphertext` (the input ciphertext data), `ciphertext_len` (the length of the input ciphertext data), and `plaintext` (the output plaintext). The function returns the length of the decrypted data.

The `main` function is used for testing and debugging purposes, demonstrating how to use the `select_cipher`, `encrypt`, and `decrypt` functions. It defines a sample input plaintext, encrypts it using the selected cipher, and then decrypts the encrypted data to obtain the original plaintext.']

