import argparse
import json
import logging
import os
import yaml
from typing import Dict, List, Optional

logger = logging.getLogger(__name__)

class Configuration:
    def __init__(self, data: Dict[str, str]) -> None:
        self.data = data

    @staticmethod
    def from_file(path: str) -> "Configuration":
        if path.endswith(".json"):
            with open(path, "r") as f:
                return Configuration(json.load(f))
        elif path.endswith(".yaml"):
            with open(path, "r") as f:
                return Configuration(yaml.safe_load(f))
        else:
            raise ValueError("Unsupported file format")

    def get(self, key: str) -> Optional[str]:
        return self.data.get(key)

def validate_configuration(config: Dict[str, str], schema: Dict[str, str]) -> bool:
    for k, v in config.items():
        if k not in schema or v != schema[k]:
            logger.error("Invalid configuration value for key %s", k)
            return False
    return True

def load_configuration(path: Optional[str] = None) -> Configuration:
    if path is None:
        # Generate a sample configuration file with default settings
        config = {
            "key1": "value1",
            "key2": "value2",
            "key3": "value3"
        }
        return Configuration(config)

    if not os.path.exists(path):
        logger.error("Configuration file %s does not exist", path)
        raise FileNotFoundError

    # Load the configuration from the specified file
    config = Configuration.from_file(path)

    # Validate the configuration against a predefined schema
    if validate_configuration(config.data, {
            "key1": "value1",
            "key2": "value2",
            "key3": "value3"
        }):
        logger.info("Configuration file %s is valid", path)
    else:
        logger.error("Invalid configuration file %s", path)
        raise ValueError

    return config

def export_configuration(config: Configuration, format: str = "json") -> None:
    if format == "json":
        with open("output.json", "w") as f:
            json.dump(config.data, f)
    elif format == "yaml":
        with open("output.yaml", "w") as f:
            yaml.safe_dump(config.data, f)
    else:
        raise ValueError("Unsupported export format")

def merge_configuration(config1: Configuration, config2: Configuration) -> Configuration:
    merged = {}
    for k, v in config1.data.items():
        if k not in config2.data or v != config2.data[k]:
            merged[k] = v
    for k, v in config2.data.items():
        if k not in merged:
            merged[k] = v
    return Configuration(merged)

def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--config", help="Path to the configuration file")
    parser.add_argument("--format", choices=["json", "yaml"], default="json", help="Format of the configuration file")
    parser.add_argument("--export", help="Export the loaded configuration to a different format")
    parser.add_argument("--merge", nargs=2, metavar=("CONFIG1", "CONFIG2"), help="Merge two configurations together")
    args = parser.parse_args()

    if args.config is not None:
        config = load_configuration(args.config)
    else:
        config = load_configuration()

    if args.export is not None:
        export_configuration(config, args.format)

    if args.merge is not None:
        config1 = load_configuration(args.merge[0])
        config2 = load_configuration(args.merge[1])
        merged = merge_configuration(config1, config2)
        print(merged.data)

if __name__ == "__main__":
    main()
