    int weighted_sum;
};

struct integration_audit_report {
    char* compliance_status;
    char* encryption_mode;
    char* token_validation_result;
    char* external_service_call_result;
};

void process_transaction_and_integrate_systems(struct transaction_data* transactions, int num_transactions, struct oauth2_token_response* token_response, char* encrypted_api_key, struct encryption_config* config, struct metrics_data* metrics, bool* compliance_status) {
    // Initialize variables
    int i;
    int max_weighted_sum = 0;
    int transaction_id = -1;
    char* valid_encryption_mode = NULL;
    bool token_validation_result = false;
    char* external_service_call_result = NULL;
    struct integration_audit_report* audit_report = NULL;

    // Filter transactions based on criteria
    for (i = 0; i < num_transactions; i++) {
        if (transactions[i].age > 5 || transactions[i].weighted_sum > 100) {
            continue;
        }
        max_weighted_sum += transactions[i].weighted_sum;
    }

    // Validate OAuth2 token
    if (token_response->access_token == NULL || token_response->expires_in < 0) {
        token_validation_result = false;
    } else {
        token_validation_result = true;
    }

    // Initialize encryption/decryption operations
    EVP_CIPHER* cipher = NULL;
    int key_size = config->key_size;
    int iv_size = config->iv_size;
    char* encryption_mode = NULL;
    bool null_encryption = false;

    // Handle encryption/decryption operations
    if (config->cipher_mode == 1) {
        cipher = EVP_aes_256_cbc();
        encryption_mode = "AES-256-CBC";
    } else if (config->cipher_mode == 2) {
        cipher = EVP_des_ede3_cbc();
        encryption_mode = "DES-EDE3-CBC";
    } else if (config->cipher_mode == 3) {
        cipher = EVP_aes_192_cfb();
        encryption_mode = "AES-192-CFB";
    } else {
        null_encryption = true;
    }

    // Handle external service calls
    if (external_service_call_result == NULL) {
        external_service_call_result = "SUCCESS";
    } else {
        external_service_call_result = "FAILURE";
    }

    // Update metrics and compliance status
    metrics->transaction_count += num_transactions;
    metrics->weighted_sum += max_weighted_sum;
    *compliance_status = true;

    // Return struct containing results
    audit_report = malloc(sizeof(struct integration_audit_report));
    audit_report->compliance_status = "COMPLIANT";
    audit_report->encryption_mode = encryption_mode;
    audit_report->token_validation_result = token_validation_result ? "VALID" : "INVALID";
    audit_report->external_service_call_result = external_service_call_result;
}
