// Define the function for generating a new filename based on an existing one, modifying its extension with a sequence of random digits and appending a specific file type
char *generate_new_filename(const char *filename, const char *filetype) {
    // Get the length of the original filename
    int len = strlen(filename);

    // Allocate memory for the new filename
    char *new_filename = (char *)malloc(sizeof(char) * (len + 10));
    if (!new_filename) {
        fprintf(stderr, "Error: Failed to allocate memory for the new filename\n");
        exit(1);
    }

    // Copy the original filename to the new one
    strcpy(new_filename, filename);

    // Get the position of the extension in the original filename
    int pos = len - 1;
    while (pos >= 0 && new_filename[pos] != '.') {
        pos--;
    }

    // If the extension is not found, return an error
    if (pos < 0) {
        fprintf(stderr, "Error: Failed to find the position of the extension in the original filename\n");
        exit(1);
    }

    // Get the number of vowels in the original filename
    int num_vowels = 0;
    for (int i = pos + 1; i < len; i++) {
        if (new_filename[i] == 'a' || new_filename[i] == 'e' || new_filename[i] == 'i' || new_filename[i] == 'o' || new_filename[i] == 'u') {
            num_vowels++;
        }
    }

    // Generate a sequence of random digits for the extension
    char *random_digits = (char *)malloc(sizeof(char) * (num_vowels + 1));
    if (!random_digits) {
        fprintf(stderr, "Error: Failed to allocate memory for the random digits\n");
        exit(1);
    }
    srand(seed);
    for (int i = 0; i < num_vowels; i++) {
        random_digits[i] = '0' + rand() % 10;
    }
    random_digits[num_vowels] = '\0';

    // Concatenate the sequence of random digits with the filetype and return the new filename
    strcat(new_filename, random_digits);
    strcat(new_filename, filetype);
    free(random_digits);
    return new_filename;
}

// Define the function for calculating the average line length in a file
int calculate_average_line_length(const char *filename) {
    // Open the file for reading
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error: Failed to open the file %s\n", filename);
        exit(1);
    }

    // Initialize the variables for calculating the average line length
    int num_lines = 0;
    long total_length = 0;

    // Read each line from the file and calculate the average line length
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        num_lines++;
        total_length += strlen(line);
    }

    // Close the file and return the average line length
    fclose(file);
    free(line);
    if (num_lines == 0) {
        return -1;
    } else {
        return total_length / num_lines;
    }
}

