            int rxUeInformationTag = atoi(token);
            token = strtok(NULL, " ");
            int rnti = atoi(token);

            // Check if the CRC indication is within the threshold value
            if (rxUeInformationTag > thresholdValue) {
                continue;
            }

            // Add the CRC indication to the list of CRC indications
            NFAPI_CRC_INDICATION_PDU_T* crcIndication = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (crcIndication == NULL) {
                printf("Error: unable to allocate memory for CRC indication\n");
                return;
            }
            crcIndication->RX_UE_INFORMATION_TAG = rxUeInformationTag;
            crcIndication->RNTI = rnti;
            crcIndications[numCrcIndications++] = crcIndication;
        } else {
            // Check if the event is a system information block
            if (strcmp(token, "SYSTEM_INFORMATION_BLOCK") == 0) {
                // Parse the RRU_ID and SEQUENCE_NUMBER
                token = strtok(NULL, " ");
                int rruId = atoi(token);
                token = strtok(NULL, " ");
                int sequenceNumber = atoi(token);

                // Check if the system information block is within the threshold value
                if (sequenceNumber > thresholdValue) {
                    continue;
