    FILE *logfile = fopen("log.txt", "w");
    if (logfile == NULL) {
        perror("fopen");
        return -1;
    }

    // Process each video file specified via command line arguments
    for (int i = 1; i < argc; i++) {
        char *filepath = argv[i];
        char *metadata = NULL;
        char *transcoded = NULL;

        // Handle the file type appropriately based on its extension
        if (strcmp(filepath, ".mp4") == 0 || strcmp(filepath, ".mkv") == 0) {
            // Parse the video container and extract frames
            int ret = parse_video_container(filepath);
            if (ret != 0) {
                fprintf(stderr, "Error parsing video container: %s\n", filepath);
                continue;
            }
        } else if (strcmp(filepath, ".avi") == 0 || strcmp(filepath, ".mov") == 0) {
            // Parse the standard video file and extract frames
            int ret = parse_standard_video(filepath);
            if (ret != 0) {
                fprintf(stderr, "Error parsing standard video: %s\n", filepath);
                continue;
            }
        } else {
            // Handle unknown file types by skipping them
            fprintf(stderr, "Unknown file type: %s\n", filepath);
            continue;
        }

        // Retrieve metadata from the third-party service if necessary
        if (metadata == NULL) {
            int ret = retrieve_metadata(filepath, &metadata);
            if (ret != 0) {
                fprintf(stderr, "Error retrieving metadata: %s\n", filepath);
                continue;
            }
        }

        // Transcode the video using a third-party service if necessary
        if (transcoded == NULL) {
            int ret = transcode_service(filepath, &transcoded);
            if (ret != 0) {
                fprintf(stderr, "Error transcoding: %s\n", filepath);
                continue;
            }
        }

        // Log the processing results
        fprintf(logfile, "%s: %d frames, %dx%d resolution, %.2f fps, %.2f seconds duration\n", filepath, frames->num_frames, frames->resolution[0], frames->resolution[1], frames->frame_rate, frames->duration);
    }

    // Deallocate memory for the list of frames and close the logging system
    free_frame_list(frames);
    fclose(logfile);

    return 0;
}
