// Function to read a JSON configuration string and extract filter criteria
void get_filter_criteria(const char *config, struct filter_criteria *criteria) {
    json_object *root = json_tokener_parse(config);
    if (!root) {
        fprintf(stderr, "Error parsing JSON configuration\n");
        return;
    }

    // Extract date range criteria
    json_object *date_range = json_object_object_get(root, "date_range");
    if (date_range) {
        criteria->start_date = json_object_get_int(json_object_object_get(date_range, "start"));
        criteria->end_date = json_object_get_int(json_object_object_get(date_range, "end"));
    }

    // Extract transaction type criteria
    json_object *transaction_type = json_object_object_get(root, "transaction_type");
    if (transaction_type) {
        criteria->transaction_type = json_object_get_string(transaction_type);
    }

    // Extract detailed breakdowns flag
    json_object *include_breakdowns = json_object_object_get(root, "include_breakdowns");
    if (include_breakdowns) {
        criteria->include_breakdowns = json_object_get_boolean(include_breakdowns);
    }

    // Extract maximum number of transactions to process
    json_object *max_transactions = json_object_object_get(root, "max_transactions");
    if (max_transactions) {
        criteria->max_transactions = json_object_get_int(max_transactions);
    }
}

