// Function to parse a single transaction from an input file
struct transaction_data *parse_transaction(const char *line) {
    struct transaction_data *transaction = malloc(sizeof(struct transaction_data));
    if (!transaction) {
        return NULL;
    }

    // Parse date and type from input line
    char *date = strtok(line, ",");
    char *type = strtok(NULL, ",");
    if (!date || !type) {
        free(transaction);
        return NULL;
    }

    // Convert date to integer format
    transaction->date = atoi(date);

    // Copy type string
    transaction->type = malloc(strlen(type) + 1);
    if (!transaction->type) {
        free(transaction);
        return NULL;
    }
    strcpy(transaction->type, type);

    // Parse remaining data from input line
    char *data = strtok(NULL, "\n");
    if (!data) {
        free(transaction->type);
        free(transaction);
        return NULL;
    }

    // Copy data string
    transaction->data = malloc(strlen(data) + 1);
    if (!transaction->data) {
        free(transaction->type);
        free(transaction);
        return NULL;
    }
    strcpy(transaction->data, data);

    return transaction;
}

