    }

    // Check for required command line options
    if (directory == NULL || format == NULL) {
        printf("Error: Missing required command line option\n");
        return 1;
    }

    // Process directory and generate output file
    FILE *output = NULL;
    if (output_file != NULL) {
        output = fopen(output_file, "wb");
        if (output == NULL) {
            log_error("Error opening output file");
            return 1;
        }
    }
    process_directory(directory, format, output);

    // Clean up and exit
    if (output != NULL) {
        fclose(output);
    }
    return 0;
}

void process_directory(char *directory, char *format, FILE *output) {
    DIR *dir = opendir(directory);
    if (dir == NULL) {
        log_error("Error opening directory");
        return;
    }

    // Iterate over files in the directory and process them
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char *filename = entry->d_name;
        if (strcmp(filename, ".") == 0 || strcmp(filename, "..") == 0) {
            continue;
        }

        // Open file and process it
        FILE *file = fopen(filename, "rb");
        if (file == NULL) {
            log_error("Error opening file");
            continue;
        }
        process_file(filename, format, output);
        fclose(file);
    }

    // Close directory and return
    closedir(dir);
}

void process_file(char *filename, char *format, FILE *output) {
    // Open file and read contents
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        log_error("Error opening file");
        return;
    }
    char buffer[1024];
    while (fgets(buffer, 1024, file)) {
        // Aggregate data and write to output file
        aggregate_data(file, output, format);
    }
    fclose(file);
}

void aggregate_data(FILE *input_file, FILE *output_file, char *format) {
    // Initialize statistics structure
    stats_t stats = {0};

    // Read input file and write to output file
    char buffer[1024];
    while (fgets(buffer, 1024, input_file)) {
        // Increment line count and unique word count
        stats.total_lines++;
        int num_words = 0;
        char *token = strtok(buffer, " ");
        while (token != NULL) {
            if (!ignore_case) {
                num_words++;
            } else {
                num_words += tolower(token[0]) == token[0];
            }
            token = strtok(NULL, " ");
        }
        stats.unique_words += num_words;

        // Write output file
        if (output_file != NULL) {
            fprintf(output_file, "%s", buffer);
        }
    }

    // Calculate average word length and write statistics to output file
    stats.average_word_length = (float)stats.total_lines / stats.unique_words;
    if (output_file != NULL && stats.total_lines > 0) {
        fprintf(output_file, "\nTotal lines: %d\nUnique words: %d\nAverage word length: %.2f\n", stats.total_lines, stats.unique_words, stats.average_word_length);
    }
}

void compress_output(FILE *input_file, FILE *output_file, char *compression_algorithm) {
    // Initialize compression structure
    z_stream stream;
    memset(&stream, 0, sizeof(z_stream));

    // Set compression algorithm and level
    int compression_level = Z_DEFAULT_COMPRESSION;
    if (!strcmp(compression_algorithm, COMPRESSION_GZIP)) {
        stream.zalloc = Z_NULL;
        stream.zfree = Z_NULL;
        stream.opaque = Z_NULL;
        stream.next_in = (Bytef *)input_file;
        stream.avail_in = 0;
        stream.next_out = (Bytef *)output_file;
        stream.avail_out = 0;
        deflateInit(&stream, compression_level);
    } else if (!strcmp(compression_algorithm, COMPRESSION_BZIP2)) {
        stream.bzalloc = Z_NULL;
        stream.bzfree = Z_NULL;
        stream.opaque = Z_NULL;
        stream.next_in = (Bytef *)input_file;
        stream.avail_in = 0;
        stream.next_out = (Bytef *)output_file;
        stream.avail_out = 0;
        BZ2_bzCompressInit(&stream, compression_level, 0, 0);
    } else {
        log_error("Invalid compression algorithm");
        return;
    }

    // Compress input file and write to output file
    while (deflate(&stream, Z_FINISH) == Z_OK) {}
    deflateEnd(&stream);
}

void log_error(char *message) {
    char *log_file = "error.log";
    FILE *log = fopen(log_file, "a");
    if (log != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(log, "%d-%02d-%02d %02d:%02d:%02d: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fclose(log);
    }
}
