// Define the supported cipher modes
#define CIPHER_MODE_GCM 1
#define CIPHER_MODE_CTR 2
#define CIPHER_MODE_CBC 3
#define CIPHER_MODE_NULL 4

// Define the required claims in the JWT payload
#define ISSUER "iss"
#define SUBJECT "sub"
#define EXPIRATION "exp"
#define NOT_BEFORE "nbf"

bool validateJWT(const char* jwt, const char* key) {
    // Initialize the EVP_CIPHER_CTX structure for the chosen cipher mode
    EVP_CIPHER_CTX *ctx = NULL;
    int mode = CIPHER_MODE_GCM;

    // Parse and validate the JWT payload
    json_object* jwt_payload = json_tokener_parse(jwt);
    if (!jwt_payload) {
        return false;
    }

    // Check for required claims in the JWT payload
    json_object* issuer = json_object_object_get(jwt_payload, ISSUER);
    json_object* subject = json_object_object_get(jwt_payload, SUBJECT);
    json_object* expiration = json_object_object_get(jwt_payload, EXPIRATION);
    json_object* not_before = json_object_object_get(jwt_payload, NOT_BEFORE);

    if (!issuer || !subject || !expiration || !not_before) {
        return false;
    }

    // Check that the expiration time is in the future
    long exp = json_object_get_int64(expiration);
    if (exp <= 0) {
        return false;
    }

    // Check that the not before time is in the past
    long nbf = json_object_get_int64(not_before);
    if (nbf > 0) {
        return false;
    }

    // Initialize the AES cipher for encryption/decryption
    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return false;
    }

    // Set the key and mode for the AES cipher
    int ret = EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, (const unsigned char*)key, NULL);
    if (!ret) {
        return false;
    }

    // Encrypt/decrypt the data using the chosen cipher mode
    int len = json_object_get_string_len(jwt_payload);
    unsigned char* data = (unsigned char*)malloc(len + 1);
    memcpy(data, json_object_get_string(jwt_payload), len);
    data[len] = '\0';

    int out_len;
    ret = EVP_EncryptUpdate(ctx, data, &out_len, data, len);
    if (!ret) {
        return false;
    }

    // Free the AES cipher context and return the result of the JWT validation
    EVP_CIPHER_CTX_free(ctx);
    free(data);
    return true;
}
