    for (int i = 0; i < sizeof(REQUIRED_CLAIMS)/sizeof(char*); i++) {
        const char* claim = REQUIRED_CLAIMS[i];
        if (!json_object_get_exists(jwt, claim)) {
            printf("Error: Missing required claim '%s' in JWT payload\n", claim);
            return NULL;
        }
    }

    // Validate that the expiration time is a future timestamp
    json_t* expClaim = json_object_get(jwt, "exp");
    if (expClaim == NULL) {
        printf("Error: Missing required claim 'exp' in JWT payload\n");
        return NULL;
    }
    int64_t expTime = json_integer_value(expClaim);
    if (expTime <= time(NULL)) {
        printf("Error: Expiration time is not a future timestamp\n");
        return NULL;
    }

    // Validate that the not before time is a past timestamp
    json_t* nbfClaim = json_object_get(jwt, "nbf");
    if (nbfClaim == NULL) {
        printf("Error: Missing required claim 'nbf' in JWT payload\n");
        return NULL;
    }
    int64_t nbfTime = json_integer_value(nbfClaim);
    if (nbfTime >= time(NULL)) {
        printf("Error: Not before time is not a past timestamp\n");
        return NULL;
    }

    // Validate that the issued at time is within the last 30 minutes
    json_t* iatClaim = json_object_get(jwt, "iat");
    if (iatClaim == NULL) {
        printf("Error: Missing required claim 'iat' in JWT payload\n");
        return NULL;
    }
    int64_t iatTime = json_integer_value(iatClaim);
    if (iatTime < time(NULL) - 30 * 60) {
        printf("Error: Issued at time is not within the last 30 minutes\n");
        return NULL;
    }

    // Validate custom claims against predefined rules specified by the user
    for (int i = 0; i < sizeof(CUSTOM_CLAIMS)/sizeof(char*); i++) {
        const char* claim = CUSTOM_CLAIMS[i];
        json_t* value = json_object_get(jwt, claim);
        if (value == NULL) {
