    }

    // Initialize the AES cipher mode and handle encryption/decryption operations efficiently
    switch (cipherMode) {
        case AES_256_GCM:
            if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, NULL, NULL)) {
                printf("Error: Failed to initialize AES-256-GCM cipher mode\n");
                return NULL;
            }
            break;
        case CTR:
            if (!EVP_EncryptInit_ex(ctx, EVP_aes_128_ctr(), NULL, NULL, NULL)) {
                printf("Error: Failed to initialize AES-128-CTR cipher mode\n");
                return NULL;
            }
            break;
        case CBC:
            if (!EVP_EncryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, NULL, NULL)) {
                printf("Error: Failed to initialize AES-128-CBC cipher mode\n");
                return NULL;
            }
            break;
        default:
            printf("Error: Unsupported cipher mode\n");
            return NULL;
    }

    // Handle encryption/decryption operations efficiently for high-throughput applications
    if (!EVP_EncryptUpdate(ctx, NULL, &len, jwtPayload, strlen(jwtPayload))) {
        printf("Error: Failed to encrypt JWT payload\n");
        return NULL;
