#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/des.h>
#include <openssl/modes.h>
#include <openssl/rand.h>
#include <openssl/err.h>

struct transaction_data {
    int age;
    int weighted_sum;
};

struct oauth2_token_response {
    char *access_token;
    int expires_in;
    char *token_type;
    char *refresh_token;
};

struct encryption_config {
    int cipher_mode;
    int key_size;
    int block_size;
    int iv_size;
};

struct metrics_data {
    int transaction_count;
    int weighted_sum;
};

struct integration_audit_report {
    char *compliance_status;
    char *error_message;
};

struct transaction_result {
    struct transaction_data *transaction_data;
    struct oauth2_token_response *oauth2_token_response;
    struct encryption_config *encryption_config;
    struct metrics_data *metrics_data;
    struct integration_audit_report *integration_audit_report;
};

struct transaction_result process_transaction_and_integrate_systems(struct transaction_data *transaction_data, char *oauth2_token_response, char *encrypted_api_key, struct encryption_config *encryption_config, struct metrics_data *metrics_data, int compliance_status) {
    // Initialize the result structure
    struct transaction_result result = {0};

    // Validate the OAuth2 token response
    if (!validate_oauth2_token_response(oauth2_token_response)) {
        result.integration_audit_report->compliance_status = "INVALID";
        result.integration_audit_report->error_message = "Invalid OAuth2 token response";
        return result;
    }

    // Decrypt the encrypted API key using the chosen cipher mode
    EVP_CIPHER *cipher = NULL;
    int valid_encryption_mode = 0;
    if (!decrypt_api_key(encrypted_api_key, &cipher, &valid_encryption_mode)) {
        result.integration_audit_report->compliance_status = "INVALID";
        result.integration_audit_report->error_message = "Invalid encryption mode or decryption failed";
        return result;
    }

    // Filter the transaction data based on the specified criteria
    struct transaction_data *filtered_transaction_data = filter_transactions(transaction_data);

    // Update the metrics structure with the filtered transaction data
    update_metrics(filtered_transaction_data, metrics_data);

    // Integrate with external systems using the chosen cipher mode and encryption key
    if (!integrate_with_external_systems(filtered_transaction_data, cipher, valid_encryption_mode)) {
        result.integration_audit_report->compliance_status = "INVALID";
        result.integration_audit_report->error_message = "External system integration failed";
        return result;
    }

    // Update the compliance status based on the audit report
    if (result.integration_audit_report->compliance_status == "INVALID") {
        compliance_status = 0;
    }

    // Return the result structure with the processed transaction data, OAuth2 token response, encryption config, metrics data, and integration audit report
    return result;
}

int validate_oauth2_token_response(char *oauth2_token_response) {
    struct oauth2_token_response *token_response = NULL;
    if (!json_to_struct(oauth2_token_response, &token_response)) {
        return 0;
    }

    // Check if the token response contains the required fields
    if (token_response->access_token == NULL || token_response->expires_in <= 0 || token_response->token_type == NULL) {
        return 0;
    }

    // Ensure that the token type is allowed and the expires_in field is a positive integer
    if (!is_allowed_token_type(token_response->token_type)) {
        return 0;
    }

    // Decrypt the encrypted API key using the valid encryption mode specified in the token response
    EVP_CIPHER *cipher = NULL;
    int valid_encryption_mode = 0;
    if (!decrypt_api_key(token_response->access_token, &cipher, &valid_encryption_mode)) {
        return 0;
    }

    // Free the memory allocated for the token response struct
    free(token_response);

    return 1;
}

int is_allowed_token_type(char *token_type) {
    // Check if the token type is allowed in the configuration
    if (strcmp(token_type, "Bearer") == 0 || strcmp(token_type, "Mac") == 0) {
        return 1;
    }

    return 0;
}

int decrypt_api_key(char *encrypted_api_key, EVP_CIPHER **cipher, int *valid_encryption_mode) {
    // Initialize the cipher structure and set the valid encryption mode to false
    *cipher = NULL;
    *valid_encryption_mode = 0;

    // Check if the encrypted API key is null or empty
    if (encrypted_api_key == NULL || strlen(encrypted_api_key) == 0) {
        return 0;
    }

    // Determine the encryption mode based on the length of the encrypted API key
    int encryption_mode = get_encryption_mode(strlen(encrypted_api_key));

    // Set the valid encryption mode to true if the encryption mode is supported
    *valid_encryption_mode = (encryption_mode == DES_ECB || encryption_mode == DES_EDE || encryption_mode == DES_EDE3 || encryption_mode == AES_CBC || encryption_mode == AES_GCM);

    // Initialize the cipher structure based on the chosen encryption mode
    *cipher = EVP_get_cipherbyname(encryption_mode);

    return 1;
}

int get_encryption_mode(int key_length) {
    if (key_length == 8) {
        return DES_ECB;
    } else if (key_length == 24) {
        return DES_EDE;
    } else if (key_length == 32) {
        return DES_EDE3;
    } else if (key_length >= 16 && key_length <= 32) {
        return AES_CBC;
    } else if (key_length > 32) {
        return AES_GCM;
    }

    return -1;
}

struct transaction_data *filter_transactions(struct transaction_data *transaction_data) {
    // Initialize the filtered transaction data structure
    struct transaction_data *filtered_transaction_data = NULL;

    // Filter the transaction data based on the specified criteria
    for (int i = 0; i < transaction_data->length; i++) {
        if (transaction_data[i].age > 5 || transaction_data[i].weighted_sum > 100) {
            filtered_transaction_data = realloc(filtered_transaction_data, sizeof(struct transaction_data) * (filtered_transaction_data->length + 1));
            filtered_transaction_data[filtered_transaction_data->length].age = transaction_data[i].age;
            filtered_transaction_data[filtered_transaction_data->length].weighted_sum = transaction_data[i].weighted_sum;
        }
    }

    return filtered_transaction_data;
}

void update_metrics(struct transaction_data *filtered_transaction_data, struct metrics_data *metrics_data) {
    // Update the metrics structure with the filtered transaction data
    for (int i = 0; i < filtered_transaction_data->length; i++) {
        metrics_data->transaction_count++;
        metrics_data->weighted_sum += filtered_transaction_data[i].weighted_sum;
    }
}

int integrate_with_external_systems(struct transaction_data *filtered_transaction_data, EVP_CIPHER *cipher, int valid_encryption_mode) {
    // Initialize the external service endpoint and payload structures
    struct external_service_endpoint *endpoints = NULL;
    struct external_service_payload *payloads = NULL;

    // Create the external service endpoints and payloads based on the filtered transaction data
    for (int i = 0; i < filtered_transaction_data->length; i++) {
        endpoints = realloc(endpoints, sizeof(struct external_service_endpoint) * (endpoints->length + 1));
        endpoints[endpoints->length].url = "https://example.com/api";
        endpoints[endpoints->length].method = "POST";

        payloads = realloc(payloads, sizeof(struct external_service_payload) * (payloads->length + 1));
        payloads[payloads->length].data = filtered_transaction_data[i];
    }

    // Call the external service endpoints and handle potential failures
    for (int i = 0; i < endpoints->length; i++) {
        if (!call_external_service(endpoints[i], payloads[i])) {
            return 0;
        }
    }

    // Free the memory allocated for the external service endpoint and payload structures
    free(endpoints);
    free(payloads);

    return 1;
}

int call_external_service(struct external_service_endpoint *endpoint, struct external_service_payload *payload) {
    // Initialize the HTTP client and request structures
    CURL *curl = NULL;
    CURLcode res = CURLE_OK;
    struct curl_slist *headers = NULL;

    // Set the URL, method, and headers for the external service call
    curl_easy_setopt(curl, CURLOPT_URL, endpoint->url);
    curl_easy_setopt(curl, CURLOPT_CUSTOMREQUEST, endpoint->method);
    headers = curl_slist_append(headers, "Content-Type: application/json");
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

    // Set the payload for the external service call
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, payload->data);

    // Perform the external service call and handle potential failures
    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to call external service: %s\n", curl_easy_strerror(res));
        return 0;
    }

    // Free the memory allocated for the HTTP client and request structures
    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);

    return 1;
}
