// Define the structure for LTE_PHY_TEST_CONFIG
typedef struct {
    int N; // Number of structures to allocate
    int seed; // Seed for random number generator
} LTE_PHY_TEST_CONFIG;

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG; // Tag for RX UE information
    int RNTI; // Random Network Transmission Identifier
    int CRC_INDICATION_REL8_TAG; // Tag for CRC indication
    int CRCFLAG; // Flag for CRC calculation
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to dynamically manage and initialize a configurable number of LTE_PHY_TEST_CONFIG structures within a resource-limited environment
void init_LTE_PHY_TEST_CONFIG(int N, int seed) {
    // Allocate memory for the list of LTE_PHY_TEST_CONFIG structures
    LTE_PHY_TEST_CONFIG *configs = (LTE_PHY_TEST_CONFIG *)malloc(N * sizeof(LTE_PHY_TEST_CONFIG));
    if (!configs) {
        fprintf(stderr, "Error: Failed to allocate memory for LTE_PHY_TEST_CONFIG structures\n");
        exit(1);
    }

    // Initialize the list of LTE_PHY_TEST_CONFIG structures with the given seed
    for (int i = 0; i < N; i++) {
        configs[i].N = N;
        configs[i].seed = seed;
    }

    // Allocate memory for a list of NFAPI_CRC_INDICATION_PDU_T structures, each containing a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
    NFAPI_CRC_INDICATION_PDU_T *crcs = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crcs) {
        fprintf(stderr, "Error: Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T structures\n");
        exit(1);
    }

    // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures with the given seed
    for (int i = 0; i < N; i++) {
        crcs[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        crcs[i].RNTI = rand() % 1000;
        crcs[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        crcs[i].CRCFLAG = rand() % 2;
    }

    // Free the memory for the list of LTE_PHY_TEST_CONFIG structures and the list of NFAPI_CRC_INDICATION_PDU_T structures
    free(configs);
    free(crcs);
}

// Define the function to generate a new filename based on an existing one, modifying its extension with a sequence of random digits and appending a specific file type
char *generate_filename(const char *filename, const char *filetype) {
    // Get the length of the original filename
    int len = strlen(filename);

    // Allocate memory for the new filename
    char *new_filename = (char *)malloc((len + 10) * sizeof(char));
    if (!new_filename) {
        fprintf(stderr, "Error: Failed to allocate memory for new filename\n");
        exit(1);
    }

    // Copy the original filename into the new filename
    strcpy(new_filename, filename);

    // Get the number of vowels in the original filename (excluding [aeiouAEIOU])
    int num_vowels = 0;
    for (int i = 0; i < len; i++) {
        if (!(filename[i] == 'a' || filename[i] == 'e' || filename[i] == 'i' || filename[i] == 'o' || filename[i] == 'u' || filename[i] == 'A' || filename[i] == 'E' || filename[i] == 'I' || filename[i] == 'O' || filename[i] == 'U')) {
            num_vowels++;
        }
    }

    // Generate a sequence of random digits for the new extension
    char *random_digits = (char *)malloc((num_vowels + 1) * sizeof(char));
    if (!random_digits) {
        fprintf(stderr, "Error: Failed to allocate memory for random digits\n");
        exit(1);
    }
    srand(time(NULL));
    for (int i = 0; i < num_vowels; i++) {
        random_digits[i] = '0' + rand() % 10;
    }
    random_digits[num_vowels] = '\0';

    // Append the new extension to the original filename
    strcat(new_filename, random_digits);
    strcat(new_filename, filetype);

    // Free the memory for the sequence of random digits and return the new filename
    free(random_digits);
    return new_filename;
}

// Define the function to calculate metrics like average line length and total character count
void calculate_metrics(const char *filename) {
    // Open the file for reading
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error: Failed to open file %s\n", filename);
        exit(1);
    }

    // Initialize variables for calculating metrics
    int num_lines = 0;
    long total_chars = 0;

    // Read the file line by line and calculate metrics
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        num_lines++;
        total_chars += strlen(line);
    }

    // Print the calculated metrics to stdout
    printf("Average line length: %f\n", (double)total_chars / num_lines);
    printf("Total character count: %ld\n", total_chars);

    // Free the memory for the line buffer and close the file
    free(line);
    fclose(file);
}

// Define the function to support multi-threaded processing with mutexes to protect shared resources against race conditions
void *process_file(void *args) {
    // Cast the arguments to a struct containing the filename and the number of threads
    struct args_t *arguments = (struct args_t *)args;

    // Open the file for reading
    FILE *file = fopen(arguments->filename, "r");
    if (!file) {
        fprintf(stderr, "Error: Failed to open file %s\n", arguments->filename);
        exit(1);
    }

    // Initialize variables for processing the file
    int num_lines = 0;
    long total_chars = 0;

    // Read the file line by line and process it concurrently with other threads
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        num_lines++;
        total_chars += strlen(line);
    }

    // Print the processed metrics to stdout
    printf("Processed %d lines with %ld characters\n", num_lines, total_chars);

    // Free the memory for the line buffer and close the file
    free(line);
    fclose(file);

    return NULL;
}

int main(int argc, char *argv[]) {
    // Define default values for command-line arguments
    const char *input_filename = "stdin";
    const char *output_filename = "stdout";
    int num_threads = 1;
    int seed = time(NULL);

    // Parse the command-line arguments
    if (argc > 1) {
        for (int i = 1; i < argc; i++) {
            if (!strcmp(argv[i], "-i") || !strcmp(argv[i], "--input")) {
                input_filename = argv[++i];
            } else if (!strcmp(argv[i], "-o") || !strcmp(argv[i], "--output")) {
                output_filename = argv[++i];
            } else if (!strcmp(argv[i], "-t") || !strcmp(argv[i], "--threads")) {
                num_threads = atoi(argv[++i]);
            } else if (!strcmp(argv[i], "-s") || !strcmp(argv[i], "--seed")) {
                seed = atoi(argv[++i]);
            }
        }
    }

    // Initialize the LTE_PHY_TEST_CONFIG structures with the given seed
    init_LTE_PHY_TEST_CONFIG(num_threads, seed);

    // Generate a new filename based on the input filename and append a specific file type
    char *new_filename = generate_filename(input_filename, ".txt");

    // Open the output file for writing
    FILE *output_file = fopen(output_filename, "w");
    if (!output_file) {
        fprintf(stderr, "Error: Failed to open output file %s\n", output_filename);
        exit(1);
    }

    // Calculate metrics like average line length and total character count for the input file
    calculate_metrics(input_filename);

    // Process the input file concurrently with other threads using mutexes to protect shared resources against race conditions
    pthread_t *threads = (pthread_t *)malloc(num_threads * sizeof(pthread_t));
    if (!threads) {
        fprintf(stderr, "Error: Failed to allocate memory for thread handles\n");
        exit(1);
    }
    struct args_t arguments;
    arguments.filename = input_filename;
    arguments.num_threads = num_threads;
    for (int i = 0; i < num_threads; i++) {
        if (pthread_create(&threads[i], NULL, process_file, &arguments) != 0) {
            fprintf(stderr, "Error: Failed to create thread %d\n", i);
            exit(1);
        }
    }
    for (int i = 0; i < num_threads; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            fprintf(stderr, "Error: Failed to join thread %d\n", i);
            exit(1);
        }
    }

    // Close the output file and free the memory for the thread handles
    fclose(output_file);
    free(threads);

    return 0;
}
