    int max_value;
} ValidationRule;

// Define a structure to represent the log file data
typedef struct {
    char *log_file_name;
    char *output_report_file_name;
    char *validation_rules;
    char *jwt_token;
} LogFileData;

// Define a function to validate the metrics in the log file
int validate_metrics(LogFileData *log_data) {
    // Parse the validation rules from the input string
    ValidationRule *validation_rules = parse_validation_rules(log_data->validation_rules);

    // Open the log file for reading
    FILE *log_file = fopen(log_data->log_file_name, "r");
    if (log_file == NULL) {
        printf("Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    // Read the log file line by line and validate each metric
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, log_file)) != -1) {
        // Parse the current line as a JSON object
        json_object *json_obj = json_tokener_parse(line);
        if (json_obj == NULL) {
            printf("Error parsing JSON object: %s\n", strerror(errno));
            return -1;
        }

        // Validate each metric in the JSON object against the validation rules
        json_object *metric = NULL;
        json_bool valid = true;
        json_object_object_foreach(json_obj, key, value) {
            if (strcmp(key, "metric") == 0) {
                metric = value;
            } else if (strcmp(key, "value") == 0) {
                int value = json_object_get_int(value);
                ValidationRule *rule = find_validation_rule(validation_rules, key);
                if (rule != NULL && !validate_metric(value, rule->min_value, rule->max_value)) {
                    valid = false;
                    break;
                }
            }
        }

        // If any metric is invalid, print an error message and return -1
        if (!valid) {
            printf("Error: Invalid metric value in log file\n");
            json_object_put(json_obj);
            fclose(log_file);
            free(line);
            return -1;
        }

        // Free the JSON object and continue reading the next line
        json_object_put(json_obj);
    }

    // Close the log file and free any allocated memory
    fclose(log_file);
    free(line);

    return 0;
}

// Define a function to compile the metrics in the log file into a unified reporting format
int compile_metrics(LogFileData *log_data) {
    // Open the output report file for writing
    FILE *output_report = fopen(log_data->output_report_file_name, "w");
    if (output_report == NULL) {
        printf("Error opening output report file: %s\n", strerror(errno));
        return -1;
    }

    // Read the log file line by line and compile each metric into the reporting format
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, log_file)) != -1) {
        // Parse the current line as a JSON object
        json_object *json_obj = json_tokener_parse(line);
        if (json_obj == NULL) {
            printf("Error parsing JSON object: %s\n", strerror(errno));
            return -1;
        }

        // Compile each metric in the JSON object into the reporting format
        json_object *metric = NULL;
        json_bool valid = true;
        json_object_object_foreach(json_obj, key, value) {
            if (strcmp(key, "metric") == 0) {
                metric = value;
            } else if (strcmp(key, "value") == 0) {
                int value = json_object_get_int(value);
                ValidationRule *rule = find_validation_rule(validation_rules, key);
                if (rule != NULL && !validate_metric(value, rule->min_value, rule->max_value)) {
                    valid = false;
                    break;
                }
            }
        }

        // If any metric is invalid, print an error message and return -1
        if (!valid) {
            printf("Error: Invalid metric value in log file\n");
            json_object_put(json_obj);
            fclose(output_report);
            free(line);
            return -1;
        }

        // Write the compiled metric to the output report file
        char *compiled_metric = compile_metric(metric, log_data->jwt_token);
        if (fprintf(output_report, "%s\n", compiled_metric) < 0) {
            printf("Error writing to output report file: %s\n", strerror(errno));
            free(compiled_metric);
            fclose(output_report);
            free(line);
            return -1;
        }

        // Free the compiled metric and continue reading the next line
        free(compiled_metric);
        json_object_put(json_obj);
    }

    // Close the output report file and free any allocated memory
    fclose(output_report);
    free(line);

    return 0;
}

