#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a struct to hold the thread-local data
typedef struct {
    char* buffer; // The input string buffer
    size_t len; // The length of the input string
    size_t limit; // The maximum allowed length for the input string
} thread_data_t;

// Define a function to handle memory allocation failures
void* alloc_failure_handler(size_t size) {
    fprintf(stderr, "Memory allocation failed (%zu bytes requested)\n", size);
    return NULL;
}

// Define the thread-local data for each thread
thread_data_t thread_data[NUM_THREADS];

// Define a function to process strings based on a configurable size limit
char* process_string(const char* str, size_t limit) {
    // Check if the input string is null or empty
    if (!str || !limit) {
        return NULL;
    }

    // Allocate memory for the output string
    char* out = malloc(limit + 1);
    if (!out) {
        alloc_failure_handler(limit + 1);
        return NULL;
    }

    // Copy the input string to the output string, up to the specified limit
    size_t len = strnlen(str, limit);
    memcpy(out, str, len);
    out[len] = '\0';

    // Append a slash to the end of the output string if necessary
    if (len < limit) {
        out[len++] = '/';
        out[len] = '\0';
    }

    return out;
}

// Define a function to process strings in parallel using multiple threads
void* process_strings(void* data) {
    // Cast the input data to a thread_data_t struct
    thread_data_t* td = (thread_data_t*)data;

    // Process each string in the input buffer, up to the specified limit
    for (size_t i = 0; i < td->len; i++) {
        char* str = &td->buffer[i];
        size_t len = strnlen(str, td->limit);
        if (len >= td->limit) {
            // If the string exceeds the limit, return NULL
            td->buffer[i] = '\0';
            continue;
        }
        char* out = process_string(str, td->limit);
        if (!out) {
            // If memory allocation fails, handle the error and continue
            alloc_failure_handler(td->limit + 1);
            td->buffer[i] = '\0';
            continue;
        }
        memcpy(&td->buffer[i], out, len + 1);
    }

    return NULL;
}

// Define a function to launch the thread pool and process strings in parallel
void* launch_threads(void* data) {
    // Cast the input data to a thread_data_t struct
    thread_data_t* td = (thread_data_t*)data;

    // Launch a pool of threads to process the input buffer
    pthread_t threads[NUM_THREADS];
    for (size_t i = 0; i < NUM_THREADS; i++) {
        thread_data_t* tdata = malloc(sizeof(thread_data_t));
        memcpy(tdata, td, sizeof(thread_data_t));
        pthread_create(&threads[i], NULL, process_strings, (void*)tdata);
    }

    // Wait for all threads to complete and free the thread data
    for (size_t i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
        free(td->buffer);
    }

    return NULL;
}
