int create_circular_buffer(size_t capacity) {
    // Allocate memory for the circular buffer structure
    circular_buffer_t *cb = malloc(sizeof(circular_buffer_t));
    if (cb == NULL) {
        return -1;
    }

    // Initialize the mutex and semaphore for synchronizing access to the buffer
    pthread_mutex_init(&cb->mutex, NULL);
    semaphore_init(&cb->semaphore, 0, 1);

    // Allocate memory for the buffer
    cb->buffer = malloc(sizeof(telemetry_data_t) * capacity);
    if (cb->buffer == NULL) {
        free(cb);
        return -1;
    }

    // Initialize the head and tail pointers to the beginning of the buffer
    cb->head = 0;
    cb->tail = 0;

    // Set the capacity of the buffer
    cb->capacity = capacity;

    return 0;
}

// Define the function for adding telemetry data to the circular buffer
int add_telemetry_data(circular_buffer_t *cb, int metric_type, long timestamp, double value) {
    // Validate the input parameters
    if (metric_type < 0 || metric_type > 100) {
        return -1;
    }
    if (timestamp < 0) {
        return -1;
    }
    if (value < 0.0) {
        return -1;
    }

    // Acquire the mutex to synchronize access to the buffer
    pthread_mutex_lock(&cb->mutex);

    // Check if the buffer is full
    if ((cb->head + 1) % cb->capacity == cb->tail) {
        // Buffer is full, wait for space to become available
        semaphore_wait(&cb->semaphore);
    }

    // Add the telemetry data to the buffer
    cb->buffer[cb->head].metric_type = metric_type;
    cb->buffer[cb->head].timestamp = timestamp;
    cb->buffer[cb->head].value = value;
    cb->head = (cb->head + 1) % cb->capacity;

    // Release the mutex
    pthread_mutex_unlock(&cb->mutex);

    return 0;
}

// Define the function for retrieving telemetry data from the circular buffer
int get_telemetry_data(circular_buffer_t *cb, int metric_type, long timestamp, double value) {
    // Validate the input parameters
    if (metric_type < 0 || metric_type > 100) {
        return -1;
    }
    if (timestamp < 0) {
        return -1;
    }
    if (value < 0.0) {
        return -1;
    }

    // Acquire the mutex to synchronize access to the buffer
    pthread_mutex_lock(&cb->mutex);

    // Check if the buffer is empty
    if (cb->head == cb->tail) {
        // Buffer is empty, return failure
        pthread_mutex_unlock(&cb->mutex);
        return -1;
    }

    // Find the first element in the buffer with the specified metric type and timestamp
    size_t i = cb->tail;
    while (i != cb->head) {
        if (cb->buffer[i].metric_type == metric_type && cb->buffer[i].timestamp == timestamp) {
            // Found the element, return it
            value = cb->buffer[i].value;
            break;
        }
        i = (i + 1) % cb->capacity;
    }

    // Release the mutex
    pthread_mutex_unlock(&cb->mutex);

    return 0;
}

// Define the function for destroying the circular buffer
int destroy_circular_buffer(circular_buffer_t *cb) {
    // Acquire the mutex to synchronize access to the buffer
    pthread_mutex_lock(&cb->mutex);

    // Free the memory allocated for the buffer
    free(cb->buffer);

    // Destroy the semaphore and mutex
    semaphore_destroy(&cb->semaphore);
    pthread_mutex_destroy(&cb->mutex);

    // Free the memory allocated for the circular buffer structure
    free(cb);

    return 0;
}
