struct transaction_metrics {
    int num_transactions;
    int max_weighted_sum;
    char* transaction_id;
};

struct oauth2_token {
    char* access_token;
    int expires_in;
    char* token_type;
    char* refresh_token;
};

struct cipher_modes {
    EVP_CIPHER* ecb;
    EVP_CIPHER* ede;
    EVP_CIPHER* ede3;
    EVP_CIPHER* cfb;
};

struct transaction_result {
    int max_weighted_sum;
    char* transaction_id;
    bool token_valid;
    bool encryption_successful;
};

void process_transaction_and_verify_token(char* transaction_data, struct oauth2_token* token, struct transaction_metrics* metrics, EVP_CIPHER* cipher) {
    // Filter transactions based on specific criteria
    int age = 0;
    int num_transactions = 0;
    int weighted_sum = 0;

    // Validate OAuth2 access token
    if (!token || !token->access_token || !token->expires_in || !token->token_type) {
        return false;
    }

    if (strcmp(token->token_type, "Bearer") != 0) {
        return false;
    }

    if (token->expires_in <= 0) {
        return false;
    }

    // Encrypt/decrypt sensitive data using specified DES cipher mode
    int encryption_successful = false;
    char* encrypted_data = NULL;
    char* decrypted_data = NULL;

    if (cipher) {
        // Initialize DES cipher modes
        struct cipher_modes cm;
        cm.ecb = EVP_des_ecb();
        cm.ede = EVP_des_ede();
        cm.ede3 = EVP_des_ede3();
        cm.cfb = EVP_des_cfb();

        // Encrypt/decrypt sensitive data using chosen cipher mode
        if (cipher == cm.ecb) {
            encrypted_data = EVP_Encrypt(transaction_data, cm.ecb);
        } else if (cipher == cm.ede) {
            encrypted_data = EVP_Encrypt(transaction_data, cm.ede);
        } else if (cipher == cm.ede3) {
            encrypted_data = EVP_Encrypt(transaction_data, cm.ede3);
        } else if (cipher == cm.cfb) {
            encrypted_data = EVP_Encrypt(transaction_data, cm.cfb);
        }

        // Update metrics structure with encryption/decryption results
        if (encrypted_data) {
            encryption_successful = true;
            metrics->num_transactions++;
            metrics->max_weighted_sum += weighted_sum;
            metrics->transaction_id = transaction_id;
        } else {
            encryption_successful = false;
        }
    } else {
        // Null encryption for testing purposes
        encrypted_data = NULL;
        encryption_successful = true;
    }

    // Return struct containing maximum weighted sum, transaction ID, token validity, and encryption/decryption success
    struct transaction_result result;
    result.max_weighted_sum = max_weighted_sum;
    result.transaction_id = transaction_id;
    result.token_valid = true;
    result.encryption_successful = encryption_successful;
    return result;
}
