Here is a sample C program that dynamically processes multimedia files specified via command line arguments, categorizing each file as one of three types: standard audio file, multimedia file with embedded metadata, or container file (e.g., MP4, MOV) holding multiple streams. The program also parses and summarizes key metadata such as bitrates, sampling rates, and duration, and handles each file type appropriately.
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

// Define the types of multimedia files
typedef enum {
    AUDIO_FILE,
    METADATA_FILE,
    CONTAINER_FILE
} file_type;

// Define the structure to hold metadata for each frame
typedef struct {
    unsigned long timestamp;
    unsigned int sampling_rate;
    bool is_keyframe;
} FRAME_INFO;

// Define the structure to hold a list of FRAME_INFO structures
typedef struct {
    FRAME_INFO *frames;
    size_t num_frames;
} MEDIA_FRAME_T;

// Define the function to dynamically allocate memory for a list of MEDIA_FRAME_T structures
int allocate_media_frame(size_t N, unsigned int seed) {
    // Allocate memory for the list of frames
    MEDIA_FRAME_T *frames = (MEDIA_FRAME_T *)malloc(sizeof(MEDIA_FRAME_T) * N);
    if (!frames) {
        return -1; // Memory allocation failed
    }

    // Initialize the list of frames
    for (size_t i = 0; i < N; i++) {
        frames[i].frames = NULL;
        frames[i].num_frames = 0;
    }

    return 0; // Memory allocation succeeded
}

// Define the function to populate a list of MEDIA_FRAME_T structures with metadata for each frame
int populate_media_frame(MEDIA_FRAME_T *frames, size_t N) {
    // Loop through each frame and extract its metadata
    for (size_t i = 0; i < N; i++) {
        FRAME_INFO *frame = &frames[i];
        // Extract the timestamp from the frame
        unsigned long timestamp = get_timestamp(frame);
        // Extract the sampling rate from the frame
        unsigned int sampling_rate = get_sampling_rate(frame);
        // Determine whether the frame is a keyframe or not
        bool is_keyframe = is_keyframe(frame);

        // Store the metadata in the list of frames
        frame->timestamp = timestamp;
        frame->sampling_rate = sampling_rate;
        frame->is_keyframe = is_keyframe;
    }

    return 0; // Population succeeded
}

// Define the function to deallocate memory for a list of MEDIA_FRAME_T structures
void deallocate_media_frame(MEDIA_FRAME_T *frames, size_t N) {
    // Loop through each frame and free its metadata
    for (size_t i = 0; i < N; i++) {
        FRAME_INFO *frame = &frames[i];
        // Free the memory allocated for the frame's metadata
        free(frame->frames);
    }

    // Free the memory allocated for the list of frames
