                break;
            default:
                fprintf(stderr, "Invalid aggregation type\n");
                return;
        }
    }

    // Write the filtered and aggregated log events to the output file
    for (int i = 0; i < log_events; i++) {
        char *event_data = log_events[i].event_data;
