// Define the struct for storing telemetry data
typedef struct {
    time_t timestamp;
    int metric_type;
    double metric_value;
} telemetry_data_t;

// Define the circular buffer structure
struct circular_buffer {
    // The array of telemetry data elements
    telemetry_data_t* data;
    // The size of the buffer
    int size;
    // The number of elements in the buffer
    int count;
    // The index of the next element to be written
    int write_index;
    // The index of the next element to be read
    int read_index;
    // The mutex for protecting concurrent access
    pthread_mutex_t mutex;
};

// Initialize a circular buffer with a given size
void init_circular_buffer(struct circular_buffer* buf, int size) {
    buf->data = (telemetry_data_t*)malloc(size * sizeof(telemetry_data_t));
    if (!buf->data) {
        // Handle memory allocation failure gracefully
        printf("Error: Failed to allocate memory for circular buffer\n");
        return;
    }
    buf->size = size;
    buf->count = 0;
    buf->write_index = 0;
    buf->read_index = 0;
    pthread_mutex_init(&buf->mutex, NULL);
}

// Add a telemetry data element to the circular buffer
int add_telemetry_data(struct circular_buffer* buf, time_t timestamp, int metric_type, double metric_value) {
    // Acquire the mutex for protecting concurrent access
    pthread_mutex_lock(&buf->mutex);

    // Check if the buffer is full
    if (buf->count == buf->size) {
        // Handle buffer overflow gracefully
        printf("Error: Circular buffer is full\n");
        pthread_mutex_unlock(&buf->mutex);
        return -1;
    }

    // Add the telemetry data element to the buffer
    buf->data[buf->write_index] = (telemetry_data_t){timestamp, metric_type, metric_value};
    buf->count++;
    buf->write_index = (buf->write_index + 1) % buf->size;

    // Release the mutex for protecting concurrent access
    pthread_mutex_unlock(&buf->mutex);

    return 0;
}

// Read a telemetry data element from the circular buffer
int read_telemetry_data(struct circular_buffer* buf, time_t* timestamp, int* metric_type, double* metric_value) {
    // Acquire the mutex for protecting concurrent access
    pthread_mutex_lock(&buf->mutex);

    // Check if the buffer is empty
    if (buf->count == 0) {
        // Handle buffer underflow gracefully
        printf("Error: Circular buffer is empty\n");
        pthread_mutex_unlock(&buf->mutex);
        return -1;
    }

    // Read the telemetry data element from the buffer
    *timestamp = buf->data[buf->read_index].timestamp;
    *metric_type = buf->data[buf->read_index].metric_type;
    *metric_value = buf->data[buf->read_index].metric_value;
    buf->count--;
    buf->read_index = (buf->read_index + 1) % buf->size;

    // Release the mutex for protecting concurrent access
    pthread_mutex_unlock(&buf->mutex);

    return 0;
}

// Destroy a circular buffer
void destroy_circular_buffer(struct circular_buffer* buf) {
    // Acquire the mutex for protecting concurrent access
    pthread_mutex_lock(&buf->mutex);

    // Free the memory allocated to the buffer
    free(buf->data);
    buf->size = 0;
    buf->count = 0;
    buf->write_index = 0;
    buf->read_index = 0;

    // Release the mutex for protecting concurrent access
    pthread_mutex_unlock(&buf->mutex);
}
