// Define constants for command line options
#define OPTION_HELP "--help"
#define OPTION_SOURCE "-s"
#define OPTION_OUTPUT_DIR "-o"
#define OPTION_PRINT "p"

// Define a structure to represent a file processing task
typedef struct {
    char *filepath; // Path of the file to process
    int fd; // File descriptor for reading the file
} file_task_t;

// Define a function to handle command line options and create tasks for each file to process
void create_tasks(int argc, char **argv) {
    // Initialize variables
    int i, j;
    char *option;
    char *source_dir = NULL;
    char *output_dir = NULL;
    int print_flag = 0;
    file_task_t *tasks = NULL;
    size_t num_tasks = 0;

    // Iterate over command line arguments and handle options
    for (i = 1; i < argc; i++) {
        option = argv[i];
        if (!strcmp(option, OPTION_HELP)) {
            // Display help message and exit
            printf("Usage: %s [options]...\n", argv[0]);
            printf("Options:\n");
            printf("  --help      Display this help message and exit\n");
            printf("  -s source   Specify the source directory containing text files to process\n");
            printf("  -o output_dir Redirect output to specified directories, creating them if they do not exist\n");
            printf("  -p          Print processed data directly to standard output in JSON format for easy integration with other systems\n");
            exit(0);
        } else if (!strcmp(option, OPTION_SOURCE)) {
            // Set the source directory and create tasks for each file in the directory
            source_dir = argv[++i];
            struct stat st;
            if (stat(source_dir, &st) == 0 && S_ISDIR(st.st_mode)) {
                DIR *dir = opendir(source_dir);
                if (dir != NULL) {
                    struct dirent *entry;
                    while ((entry = readdir(dir)) != NULL) {
                        char *filepath = entry->d_name;
                        if (!strcmp(filepath, ".") || !strcmp(filepath, "..")) continue;
                        int fd = open(filepath, O_RDONLY);
                        if (fd >= 0) {
                            file_task_t *new_task = malloc(sizeof(file_task_t));
                            new_task->filepath = strdup(filepath);
                            new_task->fd = fd;
                            tasks = realloc(tasks, (num_tasks + 1) * sizeof(file_task_t));
                            tasks[num_tasks++] = *new_task;
                        } else {
                            perror("open");
                        }
                    }
                } else {
                    perror("opendir");
                }
            } else {
                fprintf(stderr, "Error: %s is not a directory\n", source_dir);
            }
        } else if (!strcmp(option, OPTION_OUTPUT_DIR)) {
            // Set the output directory and create tasks for each file in the directory
            output_dir = argv[++i];
            struct stat st;
            if (stat(output_dir, &st) == 0 && S_ISDIR(st.st_mode)) {
                DIR *dir = opendir(output_dir);
                if (dir != NULL) {
                    struct dirent *entry;
                    while ((entry = readdir(dir)) != NULL) {
                        char *filepath = entry->d_name;
                        if (!strcmp(filepath, ".") || !strcmp(filepath, "..")) continue;
                        int fd = open(filepath, O_WRONLY | O_CREAT, 0644);
                        if (fd >= 0) {
                            file_task_t *new_task = malloc(sizeof(file_task_t));
                            new_task->filepath = strdup(filepath);
                            new_task->fd = fd;
                            tasks = realloc(tasks, (num_tasks + 1) * sizeof(file_task_t));
                            tasks[num_tasks++] = *new_task;
                        } else {
                            perror("open");
                        }
                    }
                } else {
                    perror("opendir");
                }
            } else {
                fprintf(stderr, "Error: %s is not a directory\n", output_dir);
            }
        } else if (!strcmp(option, OPTION_PRINT)) {
            // Set the print flag to indicate that processed data should be printed directly to standard output in JSON format
            print_flag = 1;
        }
    }

    // Create a thread pool for processing tasks asynchronously
    pthread_t *threads = malloc(num_tasks * sizeof(pthread_t));
    size_t num_threads = num_tasks < 4 ? num_tasks : 4;
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);
    for (i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], &attr, process_task, tasks + i);
    }
    pthread_attr_destroy(&attr);

    // Wait for all threads to complete and free resources
    void *status;
    for (i = 0; i < num_threads; i++) {
        pthread_join(threads[i], &status);
    }
    free(threads);
    for (i = 0; i < num_tasks; i++) {
        close(tasks[i].fd);
        free(tasks[i].filepath);
    }
    free(tasks);
}

// Define a function to process each file asynchronously using a thread
void *process_task(void *arg) {
    file_task_t *task = (file_task_t *) arg;
    char buffer[4096];
    size_t num_bytes;
