#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <zlib.h>

// Define constants for file types and delimiters
#define FILE_TYPE_TEXT 0
#define FILE_TYPE_BINARY 1
#define DELIMITER_NONE 0
#define DELIMITER_COMMA 1
#define DELIMITER_TAB 2

// Define a struct to hold the file information
typedef struct {
    char *filename;
    int type; // 0 for text, 1 for binary
    int delimiter; // 0 for none, 1 for comma, 2 for tab
} FileInfo;

// Define a function to parse command line arguments
void parseArgs(int argc, char **argv) {
    // Initialize variables
    int i = 1;
    int numFiles = 0;
    int delimiter = DELIMITER_NONE;
    char *outputFile = NULL;

    // Loop through command line arguments
    while (i < argc) {
        if (strcmp(argv[i], "-t") == 0 || strcmp(argv[i], "--text") == 0) {
            // Set file type to text
            numFiles++;
            i++;
        } else if (strcmp(argv[i], "-b") == 0 || strcmp(argv[i], "--binary") == 0) {
            // Set file type to binary
            numFiles++;
            i++;
        } else if (strcmp(argv[i], "-d") == 0 || strcmp(argv[i], "--delimiter") == 0) {
            // Set delimiter
            delimiter = atoi(argv[i + 1]);
            i += 2;
        } else if (strcmp(argv[i], "-o") == 0 || strcmp(argv[i], "--output") == 0) {
            // Set output file
            outputFile = argv[i + 1];
            i += 2;
        } else {
            // Add file to list of files to process
            numFiles++;
            i++;
        }
    }

    // Check if any files were specified
    if (numFiles == 0) {
        printf("No input files specified\n");
        exit(1);
    }

    // Allocate memory for file information array
    FileInfo *files = malloc(sizeof(FileInfo) * numFiles);

    // Loop through command line arguments again and populate the file information array
    i = 1;
    int j = 0;
    while (i < argc) {
        if (strcmp(argv[i], "-t") == 0 || strcmp(argv[i], "--text") == 0) {
            files[j].type = FILE_TYPE_TEXT;
            i++;
        } else if (strcmp(argv[i], "-b") == 0 || strcmp(argv[i], "--binary") == 0) {
            files[j].type = FILE_TYPE_BINARY;
            i++;
        } else if (strcmp(argv[i], "-d") == 0 || strcmp(argv[i], "--delimiter") == 0) {
            files[j].delimiter = delimiter;
            i += 2;
        } else if (strcmp(argv[i], "-o") == 0 || strcmp(argv[i], "--output") == 0) {
            files[j].filename = outputFile;
            i += 2;
        } else {
            // Add file to list of files to process
            files[j].filename = argv[i];
            i++;
        }
        j++;
    }

    // Print the parsed arguments
    printf("Input files: ");
    for (int i = 0; i < numFiles; i++) {
        printf("%s ", files[i].filename);
    }
    printf("\n");
    printf("Output file: %s\n", outputFile);
    printf("Delimiter: %d\n", delimiter);
}

// Define a function to read a file and count the number of lines
int countLines(char *filename, int type, int delimiter) {
    // Open the file
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file %s\n", filename);
        exit(1);
    }

    // Check the file type and set the appropriate buffer size
    int bufferSize;
    if (type == FILE_TYPE_TEXT) {
        bufferSize = 1024;
    } else {
        bufferSize = 1024 * 1024;
    }

    // Allocate memory for the buffer
    char *buffer = malloc(sizeof(char) * bufferSize);

    // Initialize variables
    int numLines = 0;
    int currentLineLength = 0;

    // Loop through the file and count the number of lines
    while (fgets(buffer, bufferSize, file)) {
        if (delimiter == DELIMITER_NONE) {
            // No delimiter specified, so just count the number of newlines
            numLines++;
            currentLineLength = 0;
        } else if (delimiter == DELIMITER_COMMA) {
            // Count the number of commas in the line
            int commaCount = 0;
            for (int i = 0; i < bufferSize; i++) {
                if (buffer[i] == ',') {
                    commaCount++;
                }
            }
            numLines += commaCount;
            currentLineLength = 0;
        } else if (delimiter == DELIMITER_TAB) {
            // Count the number of tabs in the line
            int tabCount = 0;
            for (int i = 0; i < bufferSize; i++) {
                if (buffer[i] == '\t') {
                    tabCount++;
                }
            }
            numLines += tabCount;
            currentLineLength = 0;
        } else {
            // Unsupported delimiter specified, so just count the number of newlines
            numLines++;
            currentLineLength = 0;
        }
    }

    // Close the file
    fclose(file);

    // Return the number of lines
    return numLines;
}

// Define a function to decompress a gzip file
void decompressGzipFile(char *filename) {
    // Open the file
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file %s\n", filename);
        exit(1);
    }

    // Create a new file with the same name but without the .gz extension
    char *newFilename = malloc(sizeof(char) * 256);
    strcpy(newFilename, filename);
    int len = strlen(filename);
    if (len > 3 && strcmp(filename + len - 3, ".gz") == 0) {
        newFilename[len - 3] = '\0';
    } else {
        printf("Error decompressing file %s\n", filename);
        exit(1);
    }

    // Create a new file to write the decompressed data to
    FILE *newFile = fopen(newFilename, "w");
    if (newFile == NULL) {
        printf("Error creating file %s\n", newFilename);
        exit(1);
    }

    // Decompress the gzip file
    int ret;
    z_stream strm;
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;
    strm.avail_in = 0;
    strm.next_in = Z_NULL;
    ret = inflateInit2(&strm, -MAX_WBITS);
    if (ret != Z_OK) {
        printf("Error decompressing file %s\n", filename);
        exit(1);
    }
    do {
        strm.avail_in = fread(buffer, 1, bufferSize, file);
        if (ferror(file)) {
            printf("Error reading from file %s\n", filename);
            exit(1);
        }
        strm.next_in = buffer;
        do {
            strm.avail_out = bufferSize;
            strm.next_out = buffer;
            ret = inflate(&strm, Z_NO_FLUSH);
            if (ret == Z_STREAM_END) break;
            if (ret != Z_OK) {
                printf("Error decompressing file %s\n", filename);
                exit(1);
            }
            fwrite(buffer, 1, bufferSize - strm.avail_out, newFile);
        } while (strm.avail_out == 0);
    } while (strm.avail_in > 0);
    inflateEnd(&strm);

    // Close the files
    fclose(file);
    fclose(newFile);
}

// Define a function to read and count lines in multiple input files
void processFiles(int numFiles, FileInfo *files) {
    // Loop through each file and count the number of lines
    for (int i = 0; i < numFiles; i++) {
        if (strcmp(files[i].filename, "-") == 0) {
            // Read from standard input
            printf("Reading from standard input\n");
            int numLines = countLines(NULL, files[i].type, files[i].delimiter);
            printf("Number of lines: %d\n", numLines);
        } else if (strcmp(files[i].filename + strlen(files[i].filename) - 3, ".gz") == 0) {
            // Decompress the gzip file and read from it
            printf("Decompressing file %s\n", files[i].filename);
            decompressGzipFile(files[i].filename);
            int numLines = countLines(files[i].filename, files[i].type, files[i].delimiter);
            printf("Number of lines: %d\n", numLines);
        } else {
            // Read from the file directly
            printf("Reading from file %s\n", files[i].filename);
            int numLines = countLines(files[i].filename, files[i].type, files[i].delimiter);
            printf("Number of lines: %d\n", numLines);
        }
    }
}

// Define a function to write the results to an output file
void writeResults(int numFiles, FileInfo *files) {
    // Open the output file
    FILE *file = fopen(files[0].filename, "w");
    if (file == NULL) {
        printf("Error opening file %s\n", files[0].filename);
        exit(1);
    }

    // Write the results to the output file
    for (int i = 0; i < numFiles; i++) {
        fprintf(file, "%d\n", files[i].numLines);
    }

    // Close the output file
    fclose(file);
}

// Define a function to append the results to an existing output file
void appendResults(int numFiles, FileInfo *files) {
    // Open the output file
    FILE *file = fopen(files[0].filename, "a");
    if (file == NULL) {
        printf("Error opening file %s\n", files[0].filename);
        exit(1);
    }

    // Write the results to the output file
    for (int i = 0; i < numFiles; i++) {
        fprintf(file, "%d\n", files[i].numLines);
    }

    // Close the output file
    fclose(file);
}

// Define a function to handle errors and exit the program
void handleError(char *message) {
    printf("Error: %s\n", message);
    exit(1);
}

int main(int argc, char **argv) {
    // Parse the command line arguments
    parseArgs(argc, argv);

    // Check if any files were specified
    if (numFiles == 0) {
        handleError("No input files specified");
    }

    // Allocate memory for file information array
    FileInfo *files = malloc(sizeof(FileInfo) * numFiles);

    // Loop through command line arguments again and populate the file information array
    i = 1;
    int j = 0;
    while (i < argc) {
        if (strcmp(argv[i], "-t") == 0 || strcmp(argv[i], "--text") == 0) {
            files[j].type = FILE_TYPE_TEXT;
            i++;
        } else if (strcmp(argv[i], "-b") == 0 || strcmp(argv[i], "--binary") == 0) {
            files[j].type = FILE_TYPE_BINARY;
            i++;
        } else if (strcmp(argv[i], "-d") == 0 || strcmp(argv[i], "--delimiter") == 0) {
            files[j].delimiter = delimiter;
            i += 2;
        } else if (strcmp(argv[i], "-o") == 0 || strcmp(argv[i], "--output") == 0) {
            files[j].filename = outputFile;
            i += 2;
        } else {
            // Add file to list of files to process
            files[j].filename = argv[i];
            i++;
        }
        j++;
    }

    // Process the input files and count the number of lines
    processFiles(numFiles, files);

    // Write the results to an output file or append them to an existing one
    if (strcmp(files[0].filename, "-") == 0) {
        writeResults(numFiles, files);
    } else {
        appendResults(numFiles, files);
    }

    // Free memory for the file information array
    free(files);

