    char *content_type;
    int content_length;
    char *date;
};

// Function to initialize and manage HTTP methods
http_method* init_http_methods(int num_methods) {
    // Allocate memory for the array of HTTP methods
    http_method *methods = malloc(sizeof(http_method) * num_methods);

    // Initialize each method with a default value
    for (int i = 0; i < num_methods; i++) {
        methods[i] = GET;
    }

    return methods;
}

// Function to send an HTTP request and receive the response
struct http_response_header* send_http_request(char *url, char *method) {
    // Create a socket for the connection
    int sock = socket(AF_INET, SOCK_STREAM, 0);

    // Set up the address structure for the server
    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80);
    inet_pton(AF_INET, url, &serv_addr.sin_addr);

    // Connect to the server
    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Connection failed");
        return NULL;
    }

    // Send the HTTP request
    char *request = malloc(sizeof(char) * 1024);
    sprintf(request, "%s %s HTTP/1.1\r\nHost: %s\r\nConnection: close\r\n\r\n", method, url, url);
    send(sock, request, strlen(request), 0);

    // Receive the response
    char *response = malloc(sizeof(char) * 1024);
    int bytes_received = recv(sock, response, 1024, 0);
    if (bytes_received < 0) {
        perror("Error receiving response");
        return NULL;
    }

    // Parse the HTTP response header
    struct http_response_header *header = malloc(sizeof(struct http_response_header));
    char *token = strtok(response, "\r\n");
    while (token != NULL) {
        if (strncmp(token, "Content-Type:", 12) == 0) {
            header->content_type = malloc(sizeof(char) * 128);
            strcpy(header->content_type, token + 12);
        } else if (strncmp(token, "Content-Length:", 14) == 0) {
            header->content_length = atoi(token + 14);
        } else if (strncmp(token, "Date:", 5) == 0) {
            header->date = malloc(sizeof(char) * 32);
            strcpy(header->date, token + 5);
        }
        token = strtok(NULL, "\r\n");
    }

    // Validate the HTTP response header
    if (strcmp(header->content_type, "application/json") != 0 && strcmp(header->content_type, "text/html") != 0) {
        printf("Invalid Content-Type: %s\n", header->content_type);
        return NULL;
    } else if (header->content_length <= 0) {
        printf("Invalid Content-Length: %d\n", header->content_length);
        return NULL;
    }

    // Return the HTTP response header and the JSON data
    char *json = malloc(sizeof(char) * header->content_length + 1);
    strncpy(json, response + bytes_received - header->content_length, header->content_length);
    json[header->content_length] = '\0';
    return header;
}

// Function to parse and validate an HTTP response header
struct http_response_header* parse_http_response_header(char *response) {
    // Allocate memory for the HTTP response header struct
    struct http_response_header *header = malloc(sizeof(struct http_response_header));

    // Initialize the fields to default values
    header->content_type = NULL;
    header->content_length = -1;
    header->date = NULL;

    // Parse the HTTP response header
    char *token = strtok(response, "\r\n");
    while (token != NULL) {
        if (strncmp(token, "Content-Type:", 12) == 0) {
            header->content_type = malloc(sizeof(char) * 128);
            strcpy(header->content_type, token + 12);
        } else if (strncmp(token, "Content-Length:", 14) == 0) {
            header->content_length = atoi(token + 14);
        } else if (strncmp(token, "Date:", 5) == 0) {
            header->date = malloc(sizeof(char) * 32);
            strcpy(header->date, token + 5);
        }
        token = strtok(NULL, "\r\n");
    }

    // Validate the HTTP response header
    if (strcmp(header->content_type, "application/json") != 0 && strcmp(header->content_type, "text/html") != 0) {
        printf("Invalid Content-Type: %s\n", header->content_type);
        return NULL;
    } else if (header->content_length <= 0) {
        printf("Invalid Content-Length: %d\n", header->content_length);
        return NULL;
    }

    // Return the HTTP response header struct
    return header;
}

// Function to handle an HTTP request and receive a JSON response
json_object* handle_http_request(char *url, char *method) {
    // Send the HTTP request and receive the response
    struct http_response_header *header = send_http_request(url, method);
    if (header == NULL) {
        return NULL;
    }

    // Parse the JSON data from the response body
    json_object *json = json_tokener_parse(header->content_length);
    if (json == NULL) {
        printf("Error parsing JSON: %s\n", strerror(errno));
        return NULL;
    }

    // Free the HTTP response header struct and return the JSON data
    free(header);
    return json;
}
