} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to dynamically create and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_array(int n) {
    // Check if the input value is valid
    if (n <= 0) {
        printf("Error: Invalid input value for number of structures\n");
        return NULL;
    }

    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        printf("Error: Memory allocation failed\n");
        return NULL;
    }

    // Initialize the array of NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < n; i++) {
        pdu_array[i].rx_ue_information_tag = i + 1;
        pdu_array[i].rnti = i + 1;
        pdu_array[i].crc_indication_rel8_tag = (uint8_t)rand() % 256;
        pdu_array[i].crcflag = (bool)(pdu_array[i].crc_indication_rel8_tag & 0x1);
    }

    // Return the array of NFAPI_CRC_INDICATION_PDU_T structures
    return pdu_array;
}

// Define the function to validate the password strength and handle error conditions
bool validate_password(const char* password) {
    // Check if the password is null or empty
    if (!password || !strlen(password)) {
        printf("Error: Password cannot be null or empty\n");
        return false;
    }

    // Check if the password meets the predefined complexity criteria
    if (strlen(password) < 8 || strlen(password) > 16) {
        printf("Error: Password must be between 8 and 16 characters\n");
        return false;
    }

    // Check if the password contains at least one uppercase letter, one lowercase letter, and one digit
    bool has_upper = false, has_lower = false, has_digit = false;
    for (int i = 0; i < strlen(password); i++) {
        char c = password[i];
        if (c >= 'A' && c <= 'Z') {
            has_upper = true;
        } else if (c >= 'a' && c <= 'z') {
            has_lower = true;
        } else if (c >= '0' && c <= '9') {
            has_digit = true;
        }
    }
    if (!has_upper || !has_lower || !has_digit) {
        printf("Error: Password must contain at least one uppercase letter, one lowercase letter, and one digit\n");
        return false;
    }

    // Return true if the password meets the predefined complexity criteria
    return true;
}

// Define the function to handle error conditions and deallocate memory
void destroy_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_T* pdu_array) {
    // Check if the input value is valid
    if (!pdu_array) {
        printf("Error: Invalid input value for array of structures\n");
        return;
    }

    // Deallocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    free(pdu_array);
}
