// Define the maximum size of the allocated memory in bytes
#define MAX_ALLOCATED_MEMORY 1024 * 1024 * 10 // 10 MB

// Define the power of two to use for allocating chunks of memory
#define MEMORY_CHUNK_SIZE 1024 * 1024 // 1 MB

// Define the maximum number of structures that can be allocated at once
#define MAX_STRUCTURES 100

// Define the structure to hold the information for each NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to dynamically allocate memory for a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocate_memory(int num_structures) {
    // Check if the number of structures is valid
    if (num_structures <= 0 || num_structures > MAX_STRUCTURES) {
        return NULL;
    }

    // Calculate the total size of memory to allocate
    int total_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_structures;

    // Check if the total size exceeds the maximum allocated memory
    if (total_size > MAX_ALLOCATED_MEMORY) {
        return NULL;
    }

    // Allocate memory for the list of structures
    NFAPI_CRC_INDICATION_PDU_T* structures = malloc(total_size);

    // Check if memory allocation failed
    if (structures == NULL) {
        return NULL;
    }

    // Initialize each structure with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (int i = 0; i < num_structures; i++) {
        structures[i].rx_ue_information_tag = RX_UE_INFORMATION_TAG_CRC_INDICATION;
        structures[i].rnti = rand(); // Generate a random RNTI
        structures[i].crc_indication_rel8_tag.CRCFlag = 1; // Set CRCFlag to 1
    }

    return structures;
}

// Define the function to deallocate memory for a list of NFAPI_CRC_INDICATION_PDU_T structures
void deallocate_memory(NFAPI_CRC_INDICATION_PDU_T* structures) {
    // Check if the input is valid
    if (structures == NULL) {
        return;
    }

    // Deallocate memory for each structure in the list
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        free(structures[i].rx_ue_information_tag);
        free(structures[i].rnti);
        free(structures[i].crc_indication_rel8_tag.CRCFlag);
    }

    // Deallocate memory for the list of structures
    free(structures);
}

