        cinfo.image_height = height;
        cinfo.input_components = 3;
        cinfo.in_color_space = JCS_RGB;
        jpeg_set_defaults(&cinfo);
        jpeg_start_compress(&cinfo, TRUE);
        JSAMPROW row[1];
        while (cinfo.next_scanline < cinfo.image_height) {
            row[0] = malloc(width * 3);
            for (int x = 0; x < width; x++) {
                int x_orig = x * 4;
                int y_orig = cinfo.next_scanline * 4;
                row[0][x * 3] = jpeg_get_byte(png_ptr, info_ptr, metadata->width, y_orig, x_orig);
                row[0][x * 3 + 1] = jpeg_get_byte(png_ptr, info_ptr, metadata->width, y_orig + 1, x_orig);
                row[0][x * 3 + 2] = jpeg_get_byte(png_ptr, info_ptr, metadata->width, y_orig + 2, x_orig);
            }
            jpeg_write_scanlines(&cinfo, row, 1);
        }
        jpeg_finish_compress(&cinfo);
        jpeg_destroy_compress(&cinfo);
    } else {
        logMessage(LOG_LEVEL_ERROR, "Unsupported image format");
        return;
    }

