        sprintf(compressed_file, "%s/thumbnail.png", output_directory);
        FILE *compressed = fopen(compressed_file, "wb");
        if (compressed == NULL) {
            logMessage(LOG_LEVEL_ERROR, "Failed to create file %s: %s", compressed_file, strerror(errno));
            return;
        }
        png_structp png_ptr = png_create_write_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, NULL);
        if (png_ptr == NULL) {
            logMessage(LOG_LEVEL_ERROR, "Failed to create PNG write structure");
            return;
