#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the structure to hold the NFAPI message data
typedef struct {
    int UE_IDENTIFIER;
    int CELL_ID;
    int NETWORK_EVENT_TAG;
    time_t timestamp;
} NFAPI_MESSAGE_T;

// Define the linked list node structure
typedef struct Node {
    NFAPI_MESSAGE_T data;
    struct Node* next;
    struct Node* prev;
} Node;

// Define the doubly-linked list structure
typedef struct List {
    Node* head;
    Node* tail;
} List;

// Function to create a new linked list node
Node* create_node(NFAPI_MESSAGE_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        return NULL;
    }
    node->data = data;
    node->next = NULL;
    node->prev = NULL;
    return node;
}

// Function to insert a new node at the end of the linked list
int insert_node(List* list, NFAPI_MESSAGE_T data) {
    Node* node = create_node(data);
    if (!node) {
        return -1;
    }
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }
    return 0;
}

// Function to delete a node from the linked list
int delete_node(List* list, NFAPI_MESSAGE_T data) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.UE_IDENTIFIER == data.UE_IDENTIFIER &&
            current->data.CELL_ID == data.CELL_ID &&
            current->data.NETWORK_EVENT_TAG == data.NETWORK_EVENT_TAG) {
            if (current == list->head) {
                list->head = current->next;
            }
            if (current == list->tail) {
                list->tail = current->prev;
            }
            free(current);
            return 0;
        }
        current = current->next;
    }
    return -1;
}

// Function to retrieve a node from the linked list based on CELL_ID and NETWORK_EVENT_TAG
Node* get_node(List* list, int CELL_ID, int NETWORK_EVENT_TAG) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.CELL_ID == CELL_ID &&
            current->data.NETWORK_EVENT_TAG == NETWORK_EVENT_TAG) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

// Function to filter and retrieve specific types of network events based on a provided CELL_ID and a specified time range
void filter_events(List* list, int CELL_ID, time_t start_time, time_t end_time) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.CELL_ID == CELL_ID &&
            current->data.timestamp >= start_time &&
            current->data.timestamp <= end_time) {
            printf("Event: UE_IDENTIFIER=%d, CELL_ID=%d, NETWORK_EVENT_TAG=%d, timestamp=%s\n",
                current->data.UE_IDENTIFIER, current->data.CELL_ID, current->data.NETWORK_EVENT_TAG, ctime(&current->data.timestamp));
        }
        current = current->next;
    }
}

// Function to validate the network event tags before processing
int validate_tags(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.NETWORK_EVENT_TAG < 0 || current->data.NETWORK_EVENT_TAG > 10) {
            return -1;
        }
        current = current->next;
    }
    return 0;
}

// Function to handle concurrent access from multiple threads without data corruption or race conditions
int process_events(List* list, int CELL_ID, time_t start_time, time_t end_time) {
    // Validate the network event tags before processing
    if (validate_tags(list) < 0) {
        return -1;
    }
    // Filter and retrieve specific types of network events based on a provided CELL_ID and a specified time range
    filter_events(list, CELL_ID, start_time, end_time);
    return 0;
}

// Main function to demonstrate the use of the doubly-linked list
int main() {
    // Create a new linked list
    List* list = (List*)malloc(sizeof(List));
    if (!list) {
        return -1;
    }
    list->head = NULL;
    list->tail = NULL;

    // Insert some nodes into the linked list
    insert_node(list, (NFAPI_MESSAGE_T){.UE_IDENTIFIER=100, .CELL_ID=1, .NETWORK_EVENT_TAG=1, .timestamp=time(NULL)});
    insert_node(list, (NFAPI_MESSAGE_T){.UE_IDENTIFIER=200, .CELL_ID=2, .NETWORK_EVENT_TAG=2, .timestamp=time(NULL)});
    insert_node(list, (NFAPI_MESSAGE_T){.UE_IDENTIFIER=300, .CELL_ID=1, .NETWORK_EVENT_TAG=3, .timestamp=time(NULL)});
    insert_node(list, (NFAPI_MESSAGE_T){.UE_IDENTIFIER=400, .CELL_ID=2, .NETWORK_EVENT_TAG=4, .timestamp=time(NULL)});

    // Process the network events for a specific CELL_ID and time range
    process_events(list, 1, time(NULL) - 3600, time(NULL));

    // Free the linked list memory
    free(list);

    return 0;
}
```
This code implements a doubly-linked list of `NFAPI_MESSAGE_T` structures to manage network events. The functions `create_node`, `insert_node`, `delete_node`, and `get_node` are used to create, insert, delete, and retrieve nodes from the linked list based on CELL_ID and NETWORK_EVENT_TAG. The function `filter_events` is used to filter and retrieve specific types of network events based on a provided CELL_ID and a specified time range. The function `validate_tags` is used to validate the network event tags before processing, and the function `process_events` is used to handle concurrent access from multiple threads without data corruption or race conditions.

The main function demonstrates the use of the doubly-linked list by creating a new linked list, inserting some nodes into it, and then processing the network events for a specific CELL_ID and time range using the `process_events` function. Finally, the memory is freed using the `free` function.

Note that this code assumes that the `NFAPI_MESSAGE_T` structure has been defined elsewhere in the program. Also, this code uses the `time` function to get the current time and the `ctime` function to convert a timestamp to a string for logging purposes.']

