#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the structure for an NFAPI_MESSAGE_T
typedef struct {
    uint32_t UE_IDENTIFIER;
    uint16_t CELL_ID;
    uint8_t NETWORK_EVENT_TAG;
    time_t timestamp;
} NFAPI_MESSAGE_T;

// Define the structure for a LTEPHY_RACH_CONFIG_DLSCH_T
typedef struct {
    uint8_t num_pucch_resource[10];
    uint8_t num_ra_preambles[10];
} LTEPHY_RACH_CONFIG_DLSCH_T;

// Define the function to manage a doubly-linked list of NFAPI_MESSAGE_T structures
void manage_nfapi_message_list(NFAPI_MESSAGE_T **head, uint16_t cell_id, uint8_t network_event_tag) {
    // Check if the head pointer is NULL
    if (*head == NULL) {
        // If it is, create a new node and set it as the head
        *head = (NFAPI_MESSAGE_T *)malloc(sizeof(NFAPI_MESSAGE_T));
        (*head)->UE_IDENTIFIER = 0;
        (*head)->CELL_ID = cell_id;
        (*head)->NETWORK_EVENT_TAG = network_event_tag;
        (*head)->timestamp = time(NULL);
    } else {
        // If it's not, traverse the list until we find a node with the same CELL_ID and NETWORK_EVENT_TAG
        NFAPI_MESSAGE_T *current = *head;
        while (current != NULL) {
            if (current->CELL_ID == cell_id && current->NETWORK_EVENT_TAG == network_event_tag) {
                break;
            }
            current = current->next;
        }

        // If we found a node with the same CELL_ID and NETWORK_EVENT_TAG, update its timestamp
        if (current != NULL) {
            current->timestamp = time(NULL);
        } else {
            // If we didn't find a node with the same CELL_ID and NETWORK_EVENT_TAG, create a new node and add it to the list
            current = (NFAPI_MESSAGE_T *)malloc(sizeof(NFAPI_MESSAGE_T));
            current->UE_IDENTIFIER = 0;
            current->CELL_ID = cell_id;
            current->NETWORK_EVENT_TAG = network_event_tag;
            current->timestamp = time(NULL);
            current->next = *head;
            *head = current;
        }
    }
}

// Define the function to create a new LTEPHY_RACH_CONFIG_DLSCH_T structure
LTEPHY_RACH_CONFIG_DLSCH_T *create_ltephy_rach_config_dlsch(uint8_t num_pucch_resource, uint8_t num_ra_preambles) {
    // Allocate memory for the structure
    LTEPHY_RACH_CONFIG_DLSCH_T *new_structure = (LTEPHY_RACH_CONFIG_DLSCH_T *)malloc(sizeof(LTEPHY_RACH_CONFIG_DLSCH_T));

    // Validate the input parameters
    if (num_pucch_resource > 10 || num_ra_preambles > 10) {
        return NULL;
    }

    // Populate the structure with the input parameters
    new_structure->num_pucch_resource[0] = num_pucch_resource;
    new_structure->num_ra_preambles[0] = num_ra_preambles;

    return new_structure;
}

// Define the function to manage a doubly-linked list of LTEPHY_RACH_CONFIG_DLSCH_T structures
void manage_ltephy_rach_config_dlsch_list(LTEPHY_RACH_CONFIG_DLSCH_T **head, uint8_t num_pucch_resource, uint8_t num_ra_preambles) {
    // Check if the head pointer is NULL
    if (*head == NULL) {
        // If it is, create a new node and set it as the head
        *head = (LTEPHY_RACH_CONFIG_DLSCH_T *)malloc(sizeof(LTEPHY_RACH_CONFIG_DLSCH_T));
        (*head)->num_pucch_resource[0] = num_pucch_resource;
        (*head)->num_ra_preambles[0] = num_ra_preambles;
    } else {
        // If it's not, traverse the list until we find a node with the same parameters
        LTEPHY_RACH_CONFIG_DLSCH_T *current = *head;
        while (current != NULL) {
            if (current->num_pucch_resource[0] == num_pucch_resource && current->num_ra_preambles[0] == num_ra_preambles) {
                break;
            }
            current = current->next;
        }

        // If we found a node with the same parameters, update its timestamp
        if (current != NULL) {
            current->timestamp = time(NULL);
        } else {
            // If we didn't find a node with the same parameters, create a new node and add it to the list
            current = (LTEPHY_RACH_CONFIG_DLSCH_T *)malloc(sizeof(LTEPHY_RACH_CONFIG_DLSCH_T));
            current->num_pucch_resource[0] = num_pucch_resource;
            current->num_ra_preambles[0] = num_ra_preambles;
