int secure_function(const char* input, const char* mode) {
    // Initialize the EVP_CIPHER structure for the chosen cipher mode
    EVP_CIPHER* cipher = NULL;
    int status = SUCCESS;

    // Validate the JSON object string representing an OAuth2 access token response
    json_object* token = json_tokener_parse(input);
    if (token == NULL) {
        status = INVALID_TOKEN;
        goto cleanup;
    }

    // Verify that the token contains all required fields and no invalid data
    const char* access_token = json_object_get_string(json_object_object_get(token, ACCESS_TOKEN));
    if (access_token == NULL) {
        status = MISSING_FIELD;
        goto cleanup;
    }
    const char* token_type = json_object_get_string(json_object_object_get(token, TOKEN_TYPE));
    if (strcmp(token_type, "Bearer") != 0) {
        status = INVALID_FIELD;
        goto cleanup;
    }
    const char* expires_in = json_object_get_string(json_object_object_get(token, EXPIRES_IN));
    if (expires_in == NULL) {
        status = MISSING_FIELD;
        goto cleanup;
    }
    int expires_in_int = atoi(expires_in);
    if (expires_in_int <= 0) {
        status = INVALID_FIELD;
        goto cleanup;
    }
    const char* refresh_token = json_object_get_string(json_object_object_get(token, REFRESH_TOKEN));
    if (refresh_token != NULL) {
        status = INVALID_FIELD;
        goto cleanup;
    }

    // Initialize the cipher structure for the chosen mode
    int mode_int = DEFAULT_MODE;
    if (mode != NULL) {
        mode_int = atoi(mode);
        if (mode_int < 0 || mode_int > 3) {
            status = INVALID_MODE;
            goto cleanup;
        }
    }
    switch (mode_int) {
        case ECB:
            cipher = EVP_des_ecb();
            break;
        case EDE:
            cipher = EVP_des_ede();
            break;
        case EDE3:
            cipher = EVP_des_ede3();
            break;
        case CFB:
            cipher = EVP_des_cfb();
            break;
    }
    if (cipher == NULL) {
        status = FAILURE;
        goto cleanup;
    }

    // Perform the cryptographic operations using the chosen cipher mode
    int failed_attempts = 0;
    while (failed_attempts < MAX_FAILED_ATTEMPTS) {
        unsigned char* plaintext = NULL;
        size_t plaintext_len = 0;
        if (!EVP_DecryptUpdate(cipher, &plaintext, &plaintext_len, (unsigned char*)access_token, strlen(access_token))) {
            status = FAILURE;
            goto cleanup;
        }
        failed_attempts++;
    }

cleanup:
    // Handle memory allocation and deallocation safely
    if (cipher != NULL) {
        EVP_CIPHER_CTX_free(cipher);
    }
    if (token != NULL) {
        json_object_put(token);
    }

    // Return the status code and any relevant error messages
    return status;
}
