void process_log(char* input_file, char* output_file, char* filter_criteria, char* report_format, int max_events) {
    // Open the input and output files
    FILE* in = fopen(input_file, "r");
    FILE* out = fopen(output_file, "w");

    // Define a linked list to store temporary events
    Event* events = NULL;

    // Read the log file line by line and process each event
