    event->timestamp = strtok(line, " ");
    event->message = strtok(NULL, "\n");
    return event;
}

// Define the function to add an event to a linked list for temporary storage
Event* add_event(Event* events, Event* event) {
    if (events == NULL) {
        events = malloc(sizeof(Event));
        events->next = NULL;
    } else {
        events->next = malloc(sizeof(Event));
        events->next->next = NULL;
    }
    events->timestamp = event->timestamp;
    events->message = event->message;
    return events;
}

// Define the function to count the number of events in a linked list
int count_events(Event* events) {
    int count = 0;
    while (events != NULL) {
        count++;
        events = events->next;
    }
    return count;
}

// Define the function to write the report to an output file
