    while (events != NULL) {
        fprintf(out, "%s %s\n", events->timestamp, events->message);
        events = events->next;
    }
}

// Define the function to handle potential errors gracefully
void error_handler(char* message) {
    printf("Error: %s\n", message);
    exit(1);
}
