// Define the structure for the network event tag
typedef struct {
    uint32_t UE_IDENTIFIER;
    uint16_t CELL_ID;
    uint8_t NETWORK_EVENT_TAG;
    time_t timestamp;
} NFAPI_MESSAGE_T;

// Define the structure for the doubly-linked list of network events
typedef struct {
    NFAPI_MESSAGE_T *head;
    NFAPI_MESSAGE_T *tail;
} NETWORK_EVENTS_LIST;

// Function to create a new network event tag
NFAPI_MESSAGE_T* create_network_event(uint32_t UE_IDENTIFIER, uint16_t CELL_ID, uint8_t NETWORK_EVENT_TAG) {
    NFAPI_MESSAGE_T *new_event = (NFAPI_MESSAGE_T*) malloc(sizeof(NFAPI_MESSAGE_T));
    if (!new_event) {
        return NULL;
    }
    new_event->UE_IDENTIFIER = UE_IDENTIFIER;
    new_event->CELL_ID = CELL_ID;
    new_event->NETWORK_EVENT_TAG = NETWORK_EVENT_TAG;
    new_event->timestamp = time(NULL);
    return new_event;
}

// Function to insert a network event into the list
void insert_network_event(NETWORK_EVENTS_LIST *list, NFAPI_MESSAGE_T *new_event) {
    if (!list || !new_event) {
        return;
    }
    new_event->next = NULL;
    new_event->prev = list->tail;
    if (list->tail) {
        list->tail->next = new_event;
    } else {
        list->head = new_event;
    }
    list->tail = new_event;
}

// Function to delete a network event from the list
void delete_network_event(NETWORK_EVENTS_LIST *list, NFAPI_MESSAGE_T *event) {
    if (!list || !event) {
        return;
    }
    if (event->prev) {
        event->prev->next = event->next;
    } else {
        list->head = event->next;
    }
    if (event->next) {
        event->next->prev = event->prev;
    } else {
        list->tail = event->prev;
    }
}

// Function to retrieve a network event from the list based on CELL_ID and NETWORK_EVENT_TAG
NFAPI_MESSAGE_T* get_network_event(NETWORK_EVENTS_LIST *list, uint16_t CELL_ID, uint8_t NETWORK_EVENT_TAG) {
    if (!list) {
        return NULL;
    }
    NFAPI_MESSAGE_T *event = list->head;
    while (event) {
        if (event->CELL_ID == CELL_ID && event->NETWORK_EVENT_TAG == NETWORK_EVENT_TAG) {
            return event;
        }
        event = event->next;
    }
    return NULL;
}

// Function to filter and retrieve specific types of network events within a specified time range
void filter_network_events(NETWORK_EVENTS_LIST *list, uint16_t CELL_ID, uint8_t NETWORK_EVENT_TAG, time_t start_time, time_t end_time) {
    if (!list) {
        return;
    }
    NFAPI_MESSAGE_T *event = list->head;
    while (event) {
        if (event->CELL_ID == CELL_ID && event->NETWORK_EVENT_TAG == NETWORK_EVENT_TAG && event->timestamp >= start_time && event->timestamp <= end_time) {
            printf("Network event: UE ID = %d, Cell ID = %d, Event Tag = %d, Timestamp = %ld\n", event->UE_IDENTIFIER, event->CELL_ID, event->NETWORK_EVENT_TAG, event->timestamp);
        }
        event = event->next;
    }
}

// Function to handle edge cases such as empty lists and invalid CELL_IDs gracefully
void handle_edge_cases(NETWORK_EVENTS_LIST *list, uint16_t CELL_ID) {
    if (!list || !CELL_ID) {
        return;
    }
    NFAPI_MESSAGE_T *event = list->head;
    while (event) {
        if (event->CELL_ID == CELL_ID) {
            printf("Network event: UE ID = %d, Cell ID = %d, Event Tag = %d, Timestamp = %ld\n", event->UE_IDENTIFIER, event->CELL_ID, event->NETWORK_EVENT_TAG, event->timestamp);
        }
        event = event->next;
    }
}
