    pthread_cond_init(&queue->cond, NULL);

    // Set the size and capacity of the queue to 0
    queue->size = 0;
    queue->capacity = 0;

    // Allocate memory for the data array in the queue
    queue->data = (LOG_RECORD_T*)malloc(sizeof(LOG_RECORD_T) * queue->capacity);
