#define BUFFER_SIZE 4096
#define MAX_LINE_LENGTH 1024
#define MAX_FILENAME_LENGTH 256
#define LOG_FILE "log.txt"
#define LOG_LEVEL_INFO 0
#define LOG_LEVEL_DEBUG 1
#define LOG_LEVEL_ERROR 2

// Struct to store information about a file
struct file {
    char *filename;
    int fd;
};

// Struct to store information about a line in the file
struct line {
    char *line;
    size_t length;
};

// Function to read a line from a file and return it as a string
char *read_line(int fd) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read = read(fd, buffer, BUFFER_SIZE);
    if (bytes_read < 0) {
        perror("Error reading from file");
        exit(1);
    }
    // Trim leading and trailing whitespace
    char *trimmed = trim(buffer);
    return trimmed;
}

// Function to compare two lines case-insensitively and ignore leading and trailing whitespace
bool compare_lines(char *line1, char *line2) {
    // Convert both lines to lowercase
    char *lower1 = strtolower(line1);
    char *lower2 = strtolower(line2);
    // Compare the two lines
    return strcmp(lower1, lower2) == 0;
}

// Function to trim leading and trailing whitespace from a string
char *trim(char *str) {
    size_t len = strlen(str);
    char *start = str;
    while (isspace(*start)) start++;
    if (*start == 0) return start;
    char *end = start + len - 1;
    while (isspace(*end)) end--;
    size_t new_len = end - start + 1;
    char *trimmed = malloc(new_len + 1);
    memcpy(trimmed, start, new_len);
    trimmed[new_len] = '\0';
    return trimmed;
}

// Function to convert a string to lowercase
char *strtolower(char *str) {
    char *lower = malloc(strlen(str) + 1);
    strcpy(lower, str);
    for (int i = 0; i < strlen(lower); i++) {
        if (isupper(lower[i])) lower[i] = tolower(lower[i]);
    }
    return lower;
}

// Function to open a file and return its file descriptor
int open_file(char *filename) {
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        perror("Error opening file");
        exit(1);
    }
    return fd;
}

// Function to close a file and release its file descriptor
void close_file(int fd) {
    int status = close(fd);
    if (status < 0) {
        perror("Error closing file");
        exit(1);
    }
}

// Function to read a line from a file and return it as a string
char *read_line(int fd) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read = read(fd, buffer, BUFFER_SIZE);
    if (bytes_read < 0) {
        perror("Error reading from file");
        exit(1);
    }
    // Trim leading and trailing whitespace
    char *trimmed = trim(buffer);
    return trimmed;
}

// Function to compare two lines case-insensitively and ignore leading and trailing whitespace
bool compare_lines(char *line1, char *line2) {
    // Convert both lines to lowercase
    char *lower1 = strtolower(line1);
    char *lower2 = strtolower(line2);
    // Compare the two lines
    return strcmp(lower1, lower2) == 0;
}

// Function to print usage information and exit
void print_usage() {
    printf("Usage: ./program [options] <input file>\n");
    printf("\nOptions:\n");
    printf("  -h, --help\t\tPrint this help message and exit\n");
    printf("  -m, --manpage\t\tPrint detailed usage information and exit\n");
    printf("  -c <baseline file>\tCompare the input file against a baseline file\n");
    printf("  -o <output file>\tRedirect output to a specified file instead of standard output\n");
    printf("  -v\t\t\tEnable verbose mode for additional debugging information\n");
    printf("  -d <directory>\tProcess multiple text files in a directory, one by one\n");
    printf("  -r <regex>\t\tFilter lines that match a specified regular expression pattern before processing\n");
    printf("  -t\t\t\tEnable multi-threaded execution for faster processing of very large files\n");
    exit(0);
}

