}

// Function to compare the input file against a baseline file and output the number of lines that differ
void compare_baseline(char *input_file, char *baseline_file) {
    // Open the input and baseline files
    int input_fd = open_file(input_file);
    int baseline_fd = open_file(baseline_file);
    // Read lines from both files
    struct line input_line, baseline_line;
    while (true) {
        input_line.line = read_line(input_fd);
        baseline_line.line = read_line(baseline_fd);
        if (strcmp(input_line.line, "") == 0 && strcmp(baseline_line.line, "") == 0) {
            break;
        }
        // Compare the two lines case-insensitively and ignore leading and trailing whitespace
        bool match = compare_lines(input_line.line, baseline_line.line);
        if (!match) {
            printf("Line %d: %s\n", input_line.length, input_line.line);
            printf("Line %d: %s\n", baseline_line.length, baseline_line.line);
        }
    }
    // Close the files
    close_file(input_fd);
    close_file(baseline_fd);
}

// Function to redirect output to a specified file instead of standard output
