#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

// Event structure for the message queue
typedef struct {
    int event_id;
    long timestamp;
    char* event_source;
    void* event_payload;
} event_t;

// Queue data structure
struct queue {
    sem_t mutex; // Mutex for synchronizing access to the queue
    sem_t cond; // Condition variable for signaling when a new event is available
    int size; // Size of the queue
    int head; // Index of the first element in the queue
    int tail; // Index of the last element in the queue
    event_t* events[]; // Array of events in the queue
};

// Function to create a new message queue
struct queue* create_queue(int size) {
    struct queue* q = malloc(sizeof(struct queue));
    if (!q) {
        perror("malloc");
        return NULL;
    }
    q->size = size;
    q->head = 0;
    q->tail = 0;
    q->events = calloc(size, sizeof(event_t));
    if (!q->events) {
        perror("calloc");
        free(q);
        return NULL;
    }
    sem_init(&q->mutex, 0, 1); // Initialize the mutex with a value of 1
    sem_init(&q->cond, 0, 0); // Initialize the condition variable with a value of 0
    return q;
}

// Function to destroy a message queue
void destroy_queue(struct queue* q) {
    if (q) {
        sem_destroy(&q->mutex);
        sem_destroy(&q->cond);
        free(q->events);
        free(q);
    }
}

// Function to enqueue an event in the message queue
int enqueue(struct queue* q, int event_id, long timestamp, char* event_source, void* event_payload) {
    if (!q) {
        return -1;
    }
    sem_wait(&q->mutex); // Acquire the mutex lock
    while (q->size == q->tail - q->head) { // Check for backpressure
        sem_post(&q->cond); // Signal the condition variable to wait until a new event is available
        sem_wait(&q->mutex); // Reacquire the mutex lock
    }
    q->events[q->tail] = (event_t){event_id, timestamp, event_source, event_payload};
    q->tail = (q->tail + 1) % q->size; // Increment the tail index and wrap around if necessary
    sem_post(&q->mutex); // Release the mutex lock
    return 0;
}

// Function to dequeue an event from the message queue
int dequeue(struct queue* q, int* event_id, long* timestamp, char** event_source, void** event_payload) {
    if (!q) {
        return -1;
    }
    sem_wait(&q->mutex); // Acquire the mutex lock
    while (q->head == q->tail) { // Check for empty queue
        sem_post(&q->cond); // Signal the condition variable to wait until a new event is available
        sem_wait(&q->mutex); // Reacquire the mutex lock
    }
    *event_id = q->events[q->head].event_id;
    *timestamp = q->events[q->head].timestamp;
    *event_source = q->events[q->head].event_source;
    *event_payload = q->events[q->head].event_payload;
    q->head = (q->head + 1) % q->size; // Increment the head index and wrap around if necessary
    sem_post(&q->mutex); // Release the mutex lock
    return 0;
}
