int insert_new_connection(TCP_CONNECTION_T *new_connection) {
    // Check if the list is empty
    if (!connections) {
        connections = new_connection;
        return 0;
    }

    // Find the position to insert the new connection
    TCP_CONNECTION_T *current_connection = connections;
    while (current_connection->next && strcmp(new_connection->server_identifier, current_connection->next->server_identifier) < 0) {
        current_connection = current_connection->next;
    }

    // Insert the new connection into the list
    new_connection->next = current_connection->next;
    current_connection->next = new_connection;

    return 0;
}

// Define the function to delete a connection from the list of connections
int delete_connection(char *server_identifier) {
    // Find the position of the connection to delete
    TCP_CONNECTION_T *current_connection = connections;
    while (current_connection && strcmp(server_identifier, current_connection->server_identifier)) {
        current_connection = current_connection->next;
