    // Initialize the AES cipher context
    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return false;
    }

    // Set the key and IV for encryption/decryption
    unsigned char* key_ptr = (unsigned char*)key;
    int key_len = strlen(key);
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key_ptr, iv);

    // Encrypt/decrypt the data using the selected cipher mode
    unsigned char* data_ptr = (unsigned char*)jwt;
    int data_len = strlen(jwt);
    EVP_EncryptUpdate(ctx, NULL, &len, data_ptr, data_len);
    if (!EVP_EncryptFinal_ex(ctx, NULL, &len)) {
        return false;
    }

    // Verify the tag for GCM mode
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    if (!EVP_VerifyFinal(ctx, tag, 16)) {
        return false;
    }

    // Free the AES cipher context
    EVP_CIPHER_CTX_free(ctx);

    // Return true if the JWT is valid
    return true;
}
