                    nfapi_crc_indication_pdu[i].crc_indication_rel8.crcflag = nfapi_crc_indication_pdu->crc_indication_rel8.crcflag;
                    break;
            }
            i++;
        }
        if (i == nfapi_crc_indication_pdu->length) {
            // If the current NFAPI_CRC_INDICATION_PDU_T structure does not exist in the list, add it to the end of the list
            nfapi_crc_indication_pdu[i].rx_ue_information = nfapi_crc_indication_pdu->rx_ue_information;
            nfapi_crc_indication_pdu[i].rnti = nfapi_crc_indication_pdu->rnti;
            nfapi_crc_indication_pdu[i].crc_indication_rel8.crcflag = nfapi_crc_indication_pdu->crc_indication_rel8.crcflag;
            nfapi_crc_indication_pdu->length++;
        }
    }

    // Release the semaphore to allow other threads to access the list of NFAPI_CRC_INDICATION_PDU_T structures
    semaphore_release(semaphore);
}

// Define the function to merge the 'offset', 'key', 'record', 'event', and 'audit' arrays into a single sorted array based on the 'key' values
void merge_arrays(long *offset, int *key, record *record, event *event, audit *audit) {
    // Initialize the merged array with the same size as the input arrays
    long *merged_offset = (long *)malloc(sizeof(long) * offset->length);
    int *merged_key = (int *)malloc(sizeof(int) * key->length);
    record *merged_record = (record *)malloc(sizeof(record) * record->length);
    event *merged_event = (event *)malloc(sizeof(event) * event->length);
    audit *merged_audit = (audit *)malloc(sizeof(audit) * audit->length);

    // Merge the arrays based on the 'key' values
    int i = 0, j = 0;
    while (i < offset->length && j < key->length) {
        if (offset[i] == key[j]) {
            merged_offset[j] = offset[i];
            merged_key[j] = key[j];
            merged_record[j] = record[i];
            merged_event[j] = event[i];
            merged_audit[j] = audit[i];
            j++;
        } else if (offset[i] < key[j]) {
            i++;
        } else {
            j++;
        }
    }

    // Free the input arrays and return the merged arrays
    free(offset);
    free(key);
    free(record);
    free(event);
    free(audit);
    return merged_offset, merged_key, merged_record, merged_event, merged_audit;
}

