void process_log_file(char *input_log_file, char *output_report_file, char *filter_criteria, bool include_debug_info, int purge_threshold, int priority_level, bool async_processing, float max_allowed_memory_usage) {
    // Initialize the semaphore for synchronizing access to the list of NFAPI_CRC_INDICATION_PDU_T structures
    static semaphore_t semaphore = 0;
    if (semaphore == 0) {
