}

char* integrate_string(char* input, size_t limit, const char* prefix) {
    // Check for null inputs
    if (!input || !limit || !prefix) {
        return NULL;
    }

    // Get the length of the input string
    size_t input_len = strlen(input);

    // Check if the input string exceeds the limit
    if (input_len > limit) {
        log_error("Input string exceeds maximum limit");
        return NULL;
    }

    // Get the length of the prefix
    size_t prefix_len = strlen(prefix);

    // Calculate the total size of the output string
    size_t output_size = input_len + prefix_len + 1;

    // Allocate memory for the output string
    char* output = custom_malloc(output_size);

    // If allocation fails, return NULL
    if (!output) {
        log_error("Failed to allocate memory for output string");
        return NULL;
    }

    // Copy the prefix to the output string
    memcpy(output, prefix, prefix_len);

    // Append the specific character to the end of the output string
    output[prefix_len] = APPEND_CHAR;

    // Copy the input string to the output string
    memcpy(output + prefix_len + 1, input, input_len);

    return output;
}

int main() {
