// Define the structure for the circular buffer
typedef struct {
    int capacity; // The maximum number of elements in the buffer
    int size; // The current number of elements in the buffer
    int head; // The index of the first element in the buffer
    int tail; // The index of the next available slot in the buffer
    void** data; // An array of pointers to the elements in the buffer
} circular_buffer_t;

// Define the structure for the metric data
typedef struct {
    long timestamp; // The timestamp of the metric
    double value; // The value of the metric
} metric_data_t;

// Define the function to create a new circular buffer
circular_buffer_t* create_circular_buffer(int capacity) {
    // Allocate memory for the circular buffer structure
    circular_buffer_t* buffer = (circular_buffer_t*)malloc(sizeof(circular_buffer_t));
    if (!buffer) {
        return NULL;
    }

    // Initialize the fields of the circular buffer structure
    buffer->capacity = capacity;
    buffer->size = 0;
    buffer->head = 0;
    buffer->tail = 0;
    buffer->data = (void**)malloc(sizeof(void*) * capacity);
    if (!buffer->data) {
        free(buffer);
        return NULL;
    }

    // Return the pointer to the circular buffer structure
    return buffer;
}

// Define the function to destroy a circular buffer
void destroy_circular_buffer(circular_buffer_t* buffer) {
    if (buffer) {
        free(buffer->data);
        free(buffer);
    }
}

// Define the function to add an element to the circular buffer
bool add_element(circular_buffer_t* buffer, void* data) {
    // Check if the buffer is full
    if (buffer->size == buffer->capacity) {
        return false;
    }

    // Increment the size of the buffer and update the tail index
    buffer->size++;
    buffer->tail = (buffer->tail + 1) % buffer->capacity;

    // Add the element to the buffer
    buffer->data[buffer->tail] = data;

    return true;
}

// Define the function to remove an element from the circular buffer
void* remove_element(circular_buffer_t* buffer) {
    // Check if the buffer is empty
    if (buffer->size == 0) {
        return NULL;
    }

    // Decrement the size of the buffer and update the head index
    buffer->size--;
    buffer->head = (buffer->head + 1) % buffer->capacity;

    // Return the element that was removed from the buffer
    return buffer->data[buffer->head];
}

// Define the function to retrieve an element from the circular buffer
void* get_element(circular_buffer_t* buffer, int index) {
    // Check if the index is valid
    if (index < 0 || index >= buffer->size) {
        return NULL;
    }

    // Calculate the offset from the head index
    int offset = (buffer->head + index) % buffer->capacity;

    // Return the element at the specified index
    return buffer->data[offset];
}

// Define the function to retrieve the size of the circular buffer
int get_size(circular_buffer_t* buffer) {
    return buffer->size;
}

// Define the function to retrieve the capacity of the circular buffer
int get_capacity(circular_buffer_t* buffer) {
    return buffer->capacity;
}

// Define the function to validate a metric value
bool validate_metric(double value, double min, double max) {
    // Check if the value is within the acceptable range
    if (value < min || value > max) {
        return false;
    }

    return true;
}

// Define the function to process a metric data point
void process_metric(circular_buffer_t* buffer, long timestamp, double value) {
    // Validate the metric value before processing
    if (!validate_metric(value, MIN_VALUE, MAX_VALUE)) {
        return;
    }

    // Add the metric data point to the circular buffer
    add_element(buffer, (void*)&timestamp);
    add_element(buffer, (void*)&value);
}

// Define the function to retrieve a specific type of performance metric based on a provided time range or METRIC_TYPE
void* get_metric(circular_buffer_t* buffer, int start_index, int end_index, METRIC_TYPE type) {
    // Check if the start and end indices are valid
    if (start_index < 0 || start_index >= buffer->size || end_index < 0 || end_index >= buffer->size) {
        return NULL;
    }

    // Calculate the offset from the head index
    int offset = (buffer->head + start_index) % buffer->capacity;

    // Initialize the sum of the metric values and the number of elements in the range
    double sum = 0.0;
    int count = 0;

    // Iterate over the elements in the range
    for (int i = start_index; i <= end_index; i++) {
        // Get the element at the current index
        void* data = get_element(buffer, i);

        // Check if the element is a metric data point
        if (data && type == METRIC_TYPE_DATA) {
            // Cast the element to a metric data point and add it to the sum and count
            metric_data_t* metric = (metric_data_t*)data;
            sum += metric->value;
            count++;
        } else if (data && type == METRIC_TYPE_TIMESTAMP) {
            // Cast the element to a timestamp and add it to the sum and count
            long* timestamp = (long*)data;
            sum += *timestamp;
            count++;
        }
    }

    // Return the average of the metric values in the range
    return sum / count;
}

