    MAC_ADDRESS mac_address;
    FRAME_SUCCESS_FLAG success_flag;
} PHY_FRAME_STATS_T;

// Define the data structure for managing the list of PHY frame statistics
typedef struct {
    PHY_FRAME_STATS_T* stats;
    size_t num_stats;
} PHY_FRAME_STATS_LIST_T;

// Define the synchronization primitives for managing concurrent access to the list of PHY frame statistics
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

// Define the function for managing the list of PHY frame statistics
void manage_phy_frame_stats(PTRY_FRAME_STATS_LIST_T* stats_list, size_t num_stats) {
    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&mutex);

    // Iterate over the list of PHY frame statistics and purge frames that have been successfully transmitted beyond the specified timeout period
    for (size_t i = 0; i < num_stats; i++) {
        if (stats_list->stats[i].success_flag && time(NULL) - stats_list->stats[i].tx_frame_tag.timestamp > TIMEOUT_PERIOD) {
            // Purge the frame by setting its success flag to false and updating the number of frames in the list
            stats_list->stats[i].success_flag = false;
            num_stats--;
        }
    }

    // Unlock the mutex to release thread safety
    pthread_mutex_unlock(&mutex);

    // Signal the condition variable to wake up any threads that are waiting for the list of PHY frame statistics to be updated
    pthread_cond_signal(&cond);
}

