// Define the structure for NetworkEvent
typedef struct NetworkEvent {
    int EventID;
    char DeviceSerialNumber[16];
    time_t Timestamp;
    int SensorType;
} NetworkEvent;

// Define the structure for TemperatureSensorConfig
typedef struct TemperatureSensorConfig {
    int ConfigID;
    int M; // Number of structures
    int Seed; // Seed for random number generator
} TemperatureSensorConfig;

// Define the function to manage a singly-linked list of NetworkEvent structures
void ManageNetworkEvents(NetworkEvent *head) {
    // Create a new node with the given EventID, DeviceSerialNumber, Timestamp, and SensorType
    void CreateNode(int EventID, char *DeviceSerialNumber, time_t Timestamp, int SensorType) {
        NetworkEvent *new_node = (NetworkEvent *)malloc(sizeof(NetworkEvent));
        new_node->EventID = EventID;
        strcpy(new_node->DeviceSerialNumber, DeviceSerialNumber);
        new_node->Timestamp = Timestamp;
        new_node->SensorType = SensorType;
        new_node->next = NULL;
    }

    // Insert a node into the list based on DeviceSerialNumber and Timestamp
    void InsertNode(NetworkEvent *head, int EventID, char *DeviceSerialNumber, time_t Timestamp, int SensorType) {
        NetworkEvent *current = head;
        while (current->next != NULL && strcmp(current->DeviceSerialNumber, DeviceSerialNumber) < 0) {
            current = current->next;
        }
        if (strcmp(current->DeviceSerialNumber, DeviceSerialNumber) == 0 && current->Timestamp == Timestamp) {
            return; // Node already exists
        }
        NetworkEvent *new_node = CreateNode(EventID, DeviceSerialNumber, Timestamp, SensorType);
        new_node->next = current->next;
        current->next = new_node;
    }

    // Delete a node from the list based on DeviceSerialNumber and Timestamp
    void DeleteNode(NetworkEvent *head, char *DeviceSerialNumber, time_t Timestamp) {
        NetworkEvent *current = head;
        while (current->next != NULL && strcmp(current->DeviceSerialNumber, DeviceSerialNumber) < 0) {
            current = current->next;
        }
        if (strcmp(current->DeviceSerialNumber, DeviceSerialNumber) == 0 && current->Timestamp == Timestamp) {
            NetworkEvent *temp = current->next;
            current->next = temp->next;
            free(temp);
        }
    }

    // Retrieve a node from the list based on DeviceSerialNumber and Timestamp
    NetworkEvent *RetrieveNode(NetworkEvent *head, char *DeviceSerialNumber, time_t Timestamp) {
        NetworkEvent *current = head;
        while (current->next != NULL && strcmp(current->DeviceSerialNumber, DeviceSerialNumber) < 0) {
            current = current->next;
        }
        if (strcmp(current->DeviceSerialNumber, DeviceSerialNumber) == 0 && current->Timestamp == Timestamp) {
            return current;
        }
        return NULL;
    }
}

// Define the function to manage a list of TemperatureSensorConfig structures
void ManageTemperatureSensors(TemperatureSensorConfig *head) {
    // Create a new node with the given ConfigID, M, and Seed
    void CreateNode(int ConfigID, int M, int Seed) {
        TemperatureSensorConfig *new_node = (TemperatureSensorConfig *)malloc(sizeof(TemperatureSensorConfig));
        new_node->ConfigID = ConfigID;
        new_node->M = M;
        new_node->Seed = Seed;
        new_node->next = NULL;
    }

    // Insert a node into the list based on ConfigID
    void InsertNode(TemperatureSensorConfig *head, int ConfigID) {
        TemperatureSensorConfig *current = head;
        while (current->next != NULL && current->ConfigID < ConfigID) {
            current = current->next;
        }
        if (current->ConfigID == ConfigID) {
            return; // Node already exists
        }
        TemperatureSensorConfig *new_node = CreateNode(ConfigID, M, Seed);
        new_node->next = current->next;
        current->next = new_node;
    }

    // Delete a node from the list based on ConfigID
    void DeleteNode(TemperatureSensorConfig *head, int ConfigID) {
        TemperatureSensorConfig *current = head;
        while (current->next != NULL && current->ConfigID < ConfigID) {
            current = current->next;
        }
        if (current->ConfigID == ConfigID) {
            TemperatureSensorConfig *temp = current->next;
            current->next = temp->next;
            free(temp);
        }
    }

    // Retrieve a node from the list based on ConfigID
    TemperatureSensorConfig *RetrieveNode(TemperatureSensorConfig *head, int ConfigID) {
        TemperatureSensorConfig *current = head;
        while (current->next != NULL && current->ConfigID < ConfigID) {
            current = current->next;
        }
        if (current->ConfigID == ConfigID) {
            return current;
        }
        return NULL;
    }
}

// Define the function to generate a new configuration ID based on an existing one
int GenerateNewConfigurationID(TemperatureSensorConfig *head, int ConfigID) {
    // Check if the given ConfigID is valid
    TemperatureSensorConfig *node = RetrieveNode(head, ConfigID);
    if (node == NULL) {
        return -1; // Invalid configuration ID
    }

    // Generate a new configuration ID based on the existing one
    int new_config_id = 0;
    while (true) {
        new_config_id = rand() % 1000000 + 100000;
        if (RetrieveNode(head, new_config_id) == NULL) {
            break; // New configuration ID is unique
        }
    }
    return new_config_id;
}

