EVP_CIPHER* get_cipher(int mode, int key_len) {
    EVP_CIPHER *cipher = NULL;
    switch (mode) {
        case ECB:
            cipher = EVP_des_ecb();
            break;
        case EDE:
            cipher = EVP_des_ede();
            break;
        case EDE3:
            cipher = EVP_des_ede3();
            break;
        case CFB:
            cipher = EVP_des_cfb();
            break;
        default:
            // handle invalid mode input
            return NULL;
    }

    if (key_len != 8 && key_len != 16 && key_len != 24) {
        // handle invalid key length input
        return NULL;
    }

    // initialize cipher with the given key length and mode
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) <= 0) {
        // handle error initializing cipher
        return NULL;
    }
    if (EVP_CIPHER_CTX_set_key_length(ctx, key_len) <= 0) {
        // handle error setting key length
        return NULL;
    }
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) <= 0) {
        // handle error initializing cipher
        return NULL;
    }

    // integrate with external library for symmetric key derivation from passphrase
    unsigned char *key = NULL;
