    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) <= 0) {
        // handle error initializing cipher state
        return NULL;
    }

    // handle errors gracefully and securely
    ERR_clear_error();

    // return pointer to EVP_CIPHER structure representing chosen cipher
    return cipher;
