// Define the structure to hold the essential details of a network event
typedef struct {
    uint32_t ue_identifier;
    uint32_t cell_id;
    uint32_t network_event_tag;
} nfapi_message_t;

// Define the doubly linked list data structure to hold the network events
typedef struct {
    nfapi_message_t *data;
    struct nfapi_message_list *next;
    struct nfapi_message_list *prev;
} nfapi_message_list_t;

// Define the function to create and manage the doubly linked list of network events
void nfapi_manage_events(nfapi_message_list_t **event_list, uint32_t cell_id, uint32_t ue_identifier, uint32_t network_event_tag) {
    // Check if the event list is empty and create a new node if necessary
    if (*event_list == NULL) {
        *event_list = (nfapi_message_list_t *)malloc(sizeof(nfapi_message_list_t));
        (*event_list)->data = (nfapi_message_t *)malloc(sizeof(nfapi_message_t));
        (*event_list)->next = NULL;
        (*event_list)->prev = NULL;
    }

    // Add the new event to the end of the list
    nfapi_message_list_t *new_node = (nfapi_message_list_t *)malloc(sizeof(nfapi_message_list_t));
    new_node->data = (nfapi_message_t *)malloc(sizeof(nfapi_message_t));
    new_node->next = NULL;
    new_node->prev = *event_list;
    (*event_list)->next = new_node;

    // Set the essential details of the new event
    nfapi_message_t *new_event = new_node->data;
    new_event->ue_identifier = ue_identifier;
    new_event->cell_id = cell_id;
    new_event->network_event_tag = network_event_tag;

    // Log the new event
    char log_message[256];
    sprintf(log_message, "New network event: UE %u, Cell %u, Event %u", ue_identifier, cell_id, network_event_tag);
    printf("%s\n", log_message);
}

// Define the function to handle and log network connectivity events
void nfapi_handle_events(nfapi_message_list_t *event_list) {
    // Iterate through the list of events and handle each one
    for (nfapi_message_list_t *node = event_list; node != NULL; node = node->next) {
        nfapi_message_t *event = node->data;
        uint32_t ue_identifier = event->ue_identifier;
        uint32_t cell_id = event->cell_id;
        uint32_t network_event_tag = event->network_event_tag;

        // Handle the new event based on its type
        if (network_event_tag == NETWORK_EVENT_TAG_ATTACHED) {
            printf("UE %u attached to Cell %u\n", ue_identifier, cell_id);
        } else if (network_event_tag == NETWORK_EVENT_TAG_DETACHED) {
            printf("UE %u detached from Cell %u\n", ue_identifier, cell_id);
        } else if (network_event_tag == NETWORK_EVENT_TAG_HANDOVER) {
            printf("UE %u handover from Cell %u to Cell %u\n", ue_identifier, cell_id, event->new_cell_id);
        } else {
            printf("Unknown network event: UE %u, Cell %u, Event %u\n", ue_identifier, cell_id, network_event_tag);
        }
    }
}

// Define the function to filter and retrieve specific types of network events based on a provided CELL_ID
void nfapi_filter_events(nfapi_message_list_t *event_list, uint32_t cell_id) {
    // Iterate through the list of events and filter each one based on the provided CELL_ID
    for (nfapi_message_list_t *node = event_list; node != NULL; node = node->next) {
        nfapi_message_t *event = node->data;
        uint32_t ue_identifier = event->ue_identifier;
        uint32_t network_event_tag = event->network_event_tag;

        // Filter the event based on the provided CELL_ID
        if (event->cell_id == cell_id) {
            printf("UE %u, Cell %u, Event %u\n", ue_identifier, cell_id, network_event_tag);
        }
    }
}

// Define the function to handle simultaneous access from multiple threads, ensuring thread safety and preventing race conditions
void nfapi_thread_safe(nfapi_message_list_t *event_list) {
    // Use a mutex to protect the list of events from concurrent access
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Handle the list of events in a thread-safe manner
    nfapi_handle_events(event_list);

    // Release the mutex to allow other threads to access the list of events
    pthread_mutex_unlock(&mutex);
}

// Define the function to periodically clear expired events based on a configurable timeout value
void nfapi_clear_expired_events(nfapi_message_list_t *event_list, uint32_t timeout) {
    // Use a mutex to protect the list of events from concurrent access
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Iterate through the list of events and clear each one that has expired based on the provided timeout value
    for (nfapi_message_list_t *node = event_list; node != NULL; node = node->next) {
        nfapi_message_t *event = node->data;
        uint32_t ue_identifier = event->ue_identifier;
        uint32_t cell_id = event->cell_id;
        uint32_t network_event_tag = event->network_event_tag;

        // Check if the event has expired based on the provided timeout value
        time_t current_time = time(NULL);
        if (current_time - event->timestamp > timeout) {
            printf("Expired network event: UE %u, Cell %u, Event %u\n", ue_identifier, cell_id, network_event_tag);

            // Remove the expired event from the list
            nfapi_message_list_t *prev = node->prev;
            prev->next = node->next;
            free(node);
        }
    }

    // Release the mutex to allow other threads to access the list of events
    pthread_mutex_unlock(&mutex);
}

// Define the function to validate that all network event tags are correctly initialized before processing
void nfapi_validate_events(nfapi_message_list_t *event_list) {
    // Iterate through the list of events and validate each one
    for (nfapi_message_list_t *node = event_list; node != NULL; node = node->next) {
        nfapi_message_t *event = node->data;
        uint32_t ue_identifier = event->ue_identifier;
        uint32_t cell_id = event->cell_id;
        uint32_t network_event_tag = event->network_event_tag;

        // Validate that the network event tag is correctly initialized
        if (network_event_tag == 0) {
            printf("Invalid network event: UE %u, Cell %u, Event %u\n", ue_identifier, cell_id, network_event_tag);
        }
    }
}
