#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the structure to hold network events
typedef struct NFAPI_MESSAGE_T {
    UE_IDENTIFIER ue_identifier;
    CELL_ID cell_id;
    NETWORK_EVENT_TAG event_tag;
    time_t timestamp;
} NFAPI_MESSAGE_T;

// Define the list to hold network events
typedef struct NFAPI_LIST {
    NFAPI_MESSAGE_T *head;
    NFAPI_MESSAGE_T *tail;
    size_t count;
} NFAPI_LIST;

// Define the synchronization primitives for thread-safe access to the list
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

// Define the function to initialize the network event list
void init_list(NFAPI_LIST *list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
}

// Define the function to insert a new network event into the list
int insert_event(NFAPI_LIST *list, UE_IDENTIFIER ue_identifier, CELL_ID cell_id, NETWORK_EVENT_TAG event_tag) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&mutex);

    // Create a new node for the network event
    NFAPI_MESSAGE_T *node = malloc(sizeof(NFAPI_MESSAGE_T));
    if (node == NULL) {
        printf("Error: Failed to allocate memory for new network event\n");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Set the fields of the new node
    node->ue_identifier = ue_identifier;
    node->cell_id = cell_id;
    node->event_tag = event_tag;
    node->timestamp = time(NULL);

    // Insert the new node into the list
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }

    // Increment the count of events in the list
    list->count++;

    // Unlock the mutex and return success
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Define the function to delete a network event from the list
int delete_event(NFAPI_LIST *list, UE_IDENTIFIER ue_identifier) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&mutex);

    // Find the node with the matching UE identifier
    NFAPI_MESSAGE_T *node = list->head;
    while (node != NULL && node->ue_identifier != ue_identifier) {
        node = node->next;
    }

    // If the node was found, delete it from the list and free its memory
    if (node != NULL) {
        // Update the head and tail pointers as needed
        if (node == list->head) {
            list->head = node->next;
        }
        if (node == list->tail) {
            list->tail = node->prev;
        }

        // Decrement the count of events in the list
        list->count--;

        // Free the memory of the deleted node
        free(node);
    } else {
        printf("Error: Failed to find network event with UE identifier %d\n", ue_identifier);
    }

    // Unlock the mutex and return success
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Define the function to retrieve a network event from the list
NFAPI_MESSAGE_T *get_event(NFAPI_LIST *list, UE_IDENTIFIER ue_identifier) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&mutex);

    // Find the node with the matching UE identifier
    NFAPI_MESSAGE_T *node = list->head;
    while (node != NULL && node->ue_identifier != ue_identifier) {
        node = node->next;
    }

    // If the node was found, return it
    if (node != NULL) {
        pthread_mutex_unlock(&mutex);
        return node;
    } else {
        printf("Error: Failed to find network event with UE identifier %d\n", ue_identifier);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
}

// Define the function to filter network events based on CELL ID
NFAPI_LIST *filter_events(NFAPI_LIST *list, CELL_ID cell_id) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&mutex);

    // Create a new list to hold the filtered events
    NFAPI_LIST *filtered_list = malloc(sizeof(NFAPI_LIST));
    if (filtered_list == NULL) {
        printf("Error: Failed to allocate memory for filtered network event list\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Initialize the filtered list
    init_list(filtered_list);

    // Iterate over the events in the original list and filter those with matching CELL ID
    NFAPI_MESSAGE_T *node = list->head;
    while (node != NULL) {
        if (node->cell_id == cell_id) {
            // Insert the filtered event into the new list
            insert_event(filtered_list, node->ue_identifier, node->cell_id, node->event_tag);
        }
        node = node->next;
    }

    // Unlock the mutex and return the filtered list
    pthread_mutex_unlock(&mutex);
    return filtered_list;
}

// Define the function to clear expired events from the list based on a timeout threshold
void clear_expired_events(NFAPI_LIST *list, time_t timeout) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&mutex);

    // Iterate over the events in the original list and delete those that are expired
    NFAPI_MESSAGE_T *node = list->head;
    while (node != NULL) {
        if (difftime(time(NULL), node->timestamp) > timeout) {
            // Delete the expired event from the list and free its memory
            delete_event(list, node->ue_identifier);
        } else {
            break;
        }
    }

    // Unlock the mutex and return success
    pthread_mutex_unlock(&mutex);
}

// Define the function to validate the correct initialization of network event tags
int validate_event_tags(NFAPI_LIST *list) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&mutex);

    // Iterate over the events in the original list and validate their event tags
    NFAPI_MESSAGE_T *node = list->head;
    while (node != NULL) {
        if (!validate_event_tag(node->event_tag)) {
            printf("Error: Invalid network event tag %d\n", node->event_tag);
            pthread_mutex_unlock(&mutex);
            return -1;
        }
        node = node->next;
    }

    // Unlock the mutex and return success
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Define the function to send network events for further analysis or processing
void send_events(NFAPI_LIST *list) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&mutex);

    // Iterate over the events in the original list and send them for further analysis or processing
    NFAPI_MESSAGE_T *node = list->head;
    while (node != NULL) {
        // Send the event for further analysis or processing
        printf("Sending network event with UE identifier %d, CELL ID %d, and event tag %d\n", node->ue_identifier, node->cell_id, node->event_tag);
        node = node->next;
    }

    // Unlock the mutex and return success
    pthread_mutex_unlock(&mutex);
}
