#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

// Define the data structures for the lists
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int MAC_HEADER;
    int PAYLOAD;
    int METADATA;
} NFAPI_RRC_MSG_T;

typedef struct {
    int PHY_TEST_PARAMETER_ID;
    int TEST_MODE;
    int PHYSICAL_LAYER_STATUS;
} LTE_PHY_TEST_CONFIG;

// Define the data structure for the list of lists
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu_list;
    NFAPI_RRC_MSG_T *rrc_msg_list;
    LTE_PHY_TEST_CONFIG *phy_test_config_list;
} DATA_STRUCTURES;

// Define the function to manage the lists
void manage_lists(DATA_STRUCTURES *data) {
    // Initialize the semaphore for synchronizing access to the lists
    sem_t sem;
    sem_init(&sem, 0, 1);

    // Initialize the mutex for protecting the list of lists
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    // Define the function to handle errors during list operations
    void error_handler(char *message) {
        printf("Error: %s\n", message);
        exit(1);
    }

    // Define the function to add an element to a list
    void add_element(DATA_STRUCTURES *data, int type, void *element) {
        sem_wait(&sem);
        pthread_mutex_lock(&mutex);
        switch (type) {
            case 1: // CRC indication PDU list
                data->crc_indication_pdu_list = realloc(data->crc_indication_pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (data->num_elements + 1));
                if (!data->crc_indication_pdu_list) {
                    error_handler("Failed to allocate memory for CRC indication PDU list");
                }
                data->crc_indication_pdu_list[data->num_elements] = *(NFAPI_CRC_INDICATION_PDU_T *)element;
                break;
            case 2: // RRC message list
                data->rrc_msg_list = realloc(data->rrc_msg_list, sizeof(NFAPI_RRC_MSG_T) * (data->num_elements + 1));
                if (!data->rrc_msg_list) {
                    error_handler("Failed to allocate memory for RRC message list");
                }
                data->rrc_msg_list[data->num_elements] = *(NFAPI_RRC_MSG_T *)element;
                break;
            case 3: // PHY test configuration list
                data->phy_test_config_list = realloc(data->phy_test_config_list, sizeof(LTE_PHY_TEST_CONFIG) * (data->num_elements + 1));
                if (!data->phy_test_config_list) {
                    error_handler("Failed to allocate memory for PHY test configuration list");
                }
                data->phy_test_config_list[data->num_elements] = *(LTE_PHY_TEST_CONFIG *)element;
                break;
            default:
                error_handler("Invalid type specified for adding element to list");
        }
        data->num_elements++;
        pthread_mutex_unlock(&mutex);
        sem_post(&sem);
    }

    // Define the function to remove an element from a list
    void remove_element(DATA_STRUCTURES *data, int type, int index) {
        sem_wait(&sem);
        pthread_mutex_lock(&mutex);
        switch (type) {
            case 1: // CRC indication PDU list
                if (index >= data->num_elements || index < 0) {
                    error_handler("Invalid index specified for removing element from CRC indication PDU list");
                }
                memmove(&data->crc_indication_pdu_list[index], &data->crc_indication_pdu_list[index + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (data->num_elements - index - 1));
                data->num_elements--;
                break;
            case 2: // RRC message list
                if (index >= data->num_elements || index < 0) {
                    error_handler("Invalid index specified for removing element from RRC message list");
                }
                memmove(&data->rrc_msg_list[index], &data->rrc_msg_list[index + 1], sizeof(NFAPI_RRC_MSG_T) * (data->num_elements - index - 1));
                data->num_elements--;
                break;
            case 3: // PHY test configuration list
                if (index >= data->num_elements || index < 0) {
                    error_handler("Invalid index specified for removing element from PHY test configuration list");
                }
                memmove(&data->phy_test_config_list[index], &data->phy_test_config_list[index + 1], sizeof(LTE_PHY_TEST_CONFIG) * (data->num_elements - index - 1));
                data->num_elements--;
                break;
            default:
                error_handler("Invalid type specified for removing element from list");
        }
        pthread_mutex_unlock(&mutex);
        sem_post(&sem);
    }

    // Define the function to purge outdated elements from a list
    void purge_outdated_elements(DATA_STRUCTURES *data, int type) {
        sem_wait(&sem);
        pthread_mutex_lock(&mutex);
        switch (type) {
            case 1: // CRC indication PDU list
                for (int i = 0; i < data->num_elements; i++) {
                    if (data->crc_indication_pdu_list[i].RX_UE_INFORMATION_TAG == -1) {
                        remove_element(data, type, i);
                        i--;
                    }
                }
                break;
            case 2: // RRC message list
                for (int i = 0; i < data->num_elements; i++) {
                    if (data->rrc_msg_list[i].MAC_HEADER == -1) {
                        remove_element(data, type, i);
                        i--;
                    }
                }
                break;
            case 3: // PHY test configuration list
                for (int i = 0; i < data->num_elements; i++) {
                    if (data->phy_test_config_list[i].PHY_TEST_PARAMETER_ID == -1) {
                        remove_element(data, type, i);
                        i--;
                    }
                }
                break;
            default:
                error_handler("Invalid type specified for purging outdated elements from list");
        }
        pthread_mutex_unlock(&mutex);
        sem_post(&sem);
    }

    // Define the function to log the creation of an element
    void log_creation(DATA_STRUCTURES *data, int type, void *element) {
        char message[1024];
        switch (type) {
            case 1: // CRC indication PDU list
                sprintf(message, "CRC indication PDU with RX_UE_INFORMATION_TAG %d and RNTI %d was added to the list\n", ((NFAPI_CRC_INDICATION_PDU_T *)element)->RX_UE_INFORMATION_TAG, ((NFAPI_CRC_INDICATION_PDU_T *)element)->RNTI);
                break;
            case 2: // RRC message list
                sprintf(message, "RRC message with MAC header %d and payload %d was added to the list\n", ((NFAPI_RRC_MSG_T *)element)->MAC_HEADER, ((NFAPI_RRC_MSG_T *)element)->PAYLOAD);
                break;
            case 3: // PHY test configuration list
                sprintf(message, "PHY test configuration with PHY_TEST_PARAMETER_ID %d and TEST_MODE %d was added to the list\n", ((LTE_PHY_TEST_CONFIG *)element)->PHY_TEST_PARAMETER_ID, ((LTE_PHY_TEST_CONFIG *)element)->TEST_MODE);
                break;
            default:
                error_handler("Invalid type specified for logging creation of element");
        }
        printf("%s", message);
    }

    // Define the function to log an error during list operations
    void log_error(char *message) {
        printf("Error: %s\n", message);
    }

    // Initialize the lists with the specified sizes
    data->crc_indication_pdu_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * crc_indication_pdu_list_size);
    if (!data->crc_indication_pdu_list) {
        error_handler("Failed to allocate memory for CRC indication PDU list");
    }
    data->rrc_msg_list = malloc(sizeof(NFAPI_RRC_MSG_T) * rrc_msg_list_size);
    if (!data->rrc_msg_list) {
        error_handler("Failed to allocate memory for RRC message list");
    }
    data->phy_test_config_list = malloc(sizeof(LTE_PHY_TEST_CONFIG) * phy_test_config_list_size);
    if (!data->phy_test_config_list) {
        error_handler("Failed to allocate memory for PHY test configuration list");
    }
    data->num_elements = 0;

    // Define the function to handle concurrent access to the lists
    void *handle_concurrent_access(void *data) {
        while (1) {
            sem_wait(&sem);
            pthread_mutex_lock(&mutex);
            switch ((intptr_t)data) {
                case 1: // Add element to list
                    add_element(data, type, element);
                    break;
                case 2: // Remove element from list
                    remove_element(data, type, index);
                    break;
                case 3: // Purge outdated elements from list
                    purge_outdated_elements(data, type);
                    break;
                default:
                    error_handler("Invalid data specified for handling concurrent access to lists");
            }
            pthread_mutex_unlock(&mutex);
            sem_post(&sem);
        }
    }

    // Define the function to handle asynchronous operations on the list
    void *handle_asynchronous_operations(void *data) {
        while (1) {
            sem_wait(&sem);
            pthread_mutex_lock(&mutex);
            switch ((intptr_t)data) {
                case 1: // Monitor the list for updates and log messages
                    if (data->num_elements > 0) {
