const char* env_var_log_level = "LOG_LEVEL";
const char* env_var_log_file = "LOG_FILE";

// Vendor autoloader
#include <vendor/autoload.php>

// Configuration file
const char* config_file = "config.json";

// Asymmetric encryption key size in bits
const int KEY_SIZE = 2048;

// RSA cipher modes
const int ENCRYPTION_MODE = RSA_PKCS1_OAEP_PADDING;
const int SIGNATURE_VERIFICATION_MODE = RSA_PKCS1_PSS_PADDING;

// Cache size limits
const int MIN_CACHE_SIZE = 1024;
const int MAX_CACHE_SIZE = 16384;

// Cache TTL in seconds
const int CACHE_TTL = 3600;

// Log levels
const char* LOG_LEVELS[] = {"DEBUG", "INFO", "WARNING", "ERROR"};

// Initialize web application environment
bool initialize_web_application(void) {
    // Load configuration file
    json_t* config = json_load_file(config_file, 0, NULL);
    if (!config) {
        printf("Failed to load configuration file\n");
        return false;
    }

    // Set environment variables
    setenv(env_var_db_host, json_string_value(json_object_get(config, "database.host")), 1);
    setenv(env_var_db_port, json_string_value(json_object_get(config, "database.port")), 1);
    setenv(env_var_db_user, json_string_value(json_object_get(config, "database.username")), 1);
    setenv(env_var_db_pass, json_string_value(json_object_get(config, "database.password")), 1);
    setenv(env_var_cache_size, json_string_value(json_object_get(config, "cache.size")), 1);
    setenv(env_var_cache_ttl, json_string_value(json_object_get(config, "cache.ttl")), 1);
    setenv(env_var_log_level, json_string_value(json_object_get(config, "logging.level")), 1);
    setenv(env_var_log_file, json_string_value(json_object_get(config, "logging.file")), 1);

    // Validate API keys
    json_t* api_keys = json_object_get(config, "api_keys");
    if (!api_keys) {
        printf("No API keys found in configuration file\n");
        return false;
    }
    size_t num_keys = json_array_size(api_keys);
    for (int i = 0; i < num_keys; i++) {
        json_t* key = json_array_get(api_keys, i);
        if (!json_is_object(key)) {
            printf("Invalid API key found in configuration file\n");
            return false;
        }
        const char* api_key = json_string_value(json_object_get(key, "api_key"));
        int expiration_time = json_integer_value(json_object_get(key, "expiration_time"));
        const char* scope = json_string_value(json_object_get(key, "scope"));
        if (!api_key || !expiration_time || !scope) {
            printf("Invalid API key found in configuration file\n");
            return false;
        }
    }

    // Initialize cryptographic operations
    RSA* rsa = RSA_new();
    BIGNUM* bn = BN_new();
    if (!rsa || !bn) {
        printf("Failed to initialize cryptographic operations\n");
        return false;
    }
    int ret = RSA_generate_key_ex(rsa, KEY_SIZE, bn, NULL);
    if (ret != 1) {
        printf("Failed to generate asymmetric encryption key\n");
        return false;
    }
    EVP_PKEY* pkey = EVP_PKEY_new();
    if (!pkey) {
        printf("Failed to initialize cryptographic operations\n");
        return false;
    }
    ret = EVP_PKEY_assign(pkey, RSA_get0_key(rsa), 0);
    if (ret != 1) {
        printf("Failed to assign asymmetric encryption key\n");
        return false;
    }

    // Initialize caching mechanism
    LRUCache* cache = LRUCache_new();
    if (!cache) {
        printf("Failed to initialize caching mechanism\n");
        return false;
    }
    ret = LRUCache_set_capacity(cache, json_integer_value(json_object_get(config, "cache.size")));
    if (ret != 1) {
        printf("Failed to set caching capacity\n");
        return false;
    }
    ret = LRUCache_set_ttl(cache, json_integer_value(json_object_get(config, "cache.ttl")));
    if (ret != 1) {
        printf("Failed to set caching TTL\n");
        return false;
    }

    // Initialize logging mechanism
    Logger* logger = Logger_new();
    if (!logger) {
        printf("Failed to initialize logging mechanism\n");
        return false;
    }
    ret = Logger_set_level(logger, json_string_value(json_object_get(config, "logging.level")));
    if (ret != 1) {
        printf("Failed to set logging level\n");
        return false;
    }
    ret = Logger_set_file(logger, json_string_value(json_object_get(config, "logging.file")));
    if (ret != 1) {
        printf("Failed to set logging file\n");
        return false;
    }

    // Initialize web application
    WebApplication* app = WebApplication_new();
    if (!app) {
        printf("Failed to initialize web application\n");
        return false;
    }
    ret = WebApplication_set_database(app, json_string_value(json_object_get(config, "database.host")), json_integer_value(json_object_get(config, "database.port")), json_string_value(json_object_get(config, "database.username")), json_string_value(json_object_get(config, "database.password")));
    if (ret != 1) {
        printf("Failed to set database configuration\n");
        return false;
    }
    ret = WebApplication_set_cache(app, cache);
    if (ret != 1) {
        printf("Failed to set caching mechanism\n");
        return false;
    }
    ret = WebApplication_set_logger(app, logger);
    if (ret != 1) {
        printf("Failed to set logging mechanism\n");
        return false;
    }
    ret = WebApplication_set_cryptographic_operations(app, pkey, ENCRYPTION_MODE, SIGNATURE_VERIFICATION_MODE);
    if (ret != 1) {
        printf("Failed to set cryptographic operations\n");
        return false;
    }

    // Clean up
    RSA_free(rsa);
    BN_free(bn);
    EVP_PKEY_free(pkey);
    LRUCache_free(cache);
    Logger_free(logger);

    return true;
}
