pthread_mutex_t mutex;

// Define function for managing NFAPI_CRC_INDICATION_PDU_T structures
void manage_nfapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Check if the record is valid and not already in the array
    int found = 0;
    for (int i = 0; i < num_records; i++) {
        if (strcmp(pdu->rx_ue_information.rnti, pdu->rnti) == 0 &&
            strcmp(pdu->crc_indication_rel8.crcflag, "randomly set") == 0) {
            found = 1;
            break;
        }
    }

    // If the record is not already in the array, add it and update the counters
    if (!found) {
