// Define function for merging arrays and purging outdated entries
void merge_arrays() {
    // Merge the 'offset', 'key', 'record', 'event', and 'audit' arrays into a single sorted array based on the 'key' values
    MERGED_ARRAY_STRUCT *merged_array = malloc(sizeof(MERGED_ARRAY_STRUCT) * num_records);
    for (int i = 0; i < num_records; i++) {
