        merged_array[i].record = records[i].record;
    }
    qsort(merged_array, num_records, sizeof(MERGED_ARRAY_STRUCT), compare_keys);

    // Trigger a system log warning and initiate a process to purge less frequently accessed records if the merged array size exceeds 750,000 elements
    if (num_merged_records > max_num_merged_records) {
        printf("Warning: maximum number of merged records exceeded\n");
        // Purge outdated records to maintain performance and resource utilization
        for (int i = 0; i < num_merged_records - max_num_merged_records; i++) {
            free(merged_array[i].record);
            merged_array[i] = merged_array[i + 1];
        }
        num_merged_records -= (num_merged_records - max_num_merged_records);
    }
}

