    // Merge the arrays and purge outdated entries if necessary
    merge_arrays();

    // Process high-priority events immediately to ensure data integrity and consistency during concurrent writes to the log file
    process_high_priority_events();

    // Write the summarized report to a file
    FILE *output = fopen(output_filename, "w");
    for (int i = 0; i < num_merged_records; i++) {
        fprintf(output, "%d\t%s\n", merged_arrays[i].key, merged_arrays[i].record.rx_ue_information.rnti);
    }
    fclose(output);
}
