// Define the supported cipher modes
#define CIPHER_MODES { "ECB", "EDE", "EDE3", "CFB" }

// Define the configuration settings for the function
struct config {
    char *cipher_mode; // The selected cipher mode
    int key_size; // The size of the encryption key (in bits)
    int block_size; // The size of the encryption block (in bytes)
    int iv_size; // The size of the initialization vector (in bytes)
