// Define the structure for a NFAPI_MESSAGE_T
typedef struct {
    UE_IDENTIFIER ue_identifier;
    CELL_ID cell_id;
    NETWORK_EVENT_TAG network_event_tag;
} NFAPI_MESSAGE_T;

// Define the linked list structure for managing the NFAPI_MESSAGE_T structures
typedef struct {
    NFAPI_MESSAGE_T *head;
    NFAPI_MESSAGE_T *tail;
} NFAPI_MESSAGE_LIST_T;

// Define the function to manage the doubly linked list of NFAPI_MESSAGE_T structures
void manage_nfapi_message_list(NFAPI_MESSAGE_LIST_T *list, UE_IDENTIFIER ue_identifier, CELL_ID cell_id, NETWORK_EVENT_TAG network_event_tag) {
    // Create a new NFAPI_MESSAGE_T structure with the given parameters
    NFAPI_MESSAGE_T *new_message = (NFAPI_MESSAGE_T *)malloc(sizeof(NFAPI_MESSAGE_T));
    if (!new_message) {
        // Handle memory allocation failure gracefully by returning a status code indicating failure and logging the issue
        printf("Memory allocation failed for new NFAPI message\n");
        return;
    }
    new_message->ue_identifier = ue_identifier;
    new_message->cell_id = cell_id;
    new_message->network_event_tag = network_event_tag;

    // Lock the list to prevent concurrent access from multiple threads
    pthread_mutex_lock(&list->mutex);

    // Check if the list is empty and initialize it if necessary
    if (!list->head) {
        list->head = new_message;
        list->tail = new_message;
    } else {
        // Add the new message to the end of the list
        list->tail->next = new_message;
        new_message->prev = list->tail;
        list->tail = new_message;
    }

    // Unlock the list and return success
    pthread_mutex_unlock(&list->mutex);
}

// Define the function to filter and retrieve specific network events based on CELL_ID
NETWORK_EVENT_TAG *filter_nfapi_message_list(NFAPI_MESSAGE_LIST_T *list, CELL_ID cell_id) {
    // Create a new NETWORK_EVENT_TAG structure to store the filtered network events
    NETWORK_EVENT_TAG *filtered_events = (NETWORK_EVENT_TAG *)malloc(sizeof(NETWORK_EVENT_TAG));
    if (!filtered_events) {
        // Handle memory allocation failure gracefully by returning a status code indicating failure and logging the issue
        printf("Memory allocation failed for filtered NFAPI message list\n");
        return NULL;
    }

    // Lock the list to prevent concurrent access from multiple threads
    pthread_mutex_lock(&list->mutex);

    // Iterate through the list and filter out network events with the given CELL_ID
    NFAPI_MESSAGE_T *current = list->head;
    while (current) {
        if (current->cell_id == cell_id) {
            filtered_events->network_event_tag = current->network_event_tag;
            break;
        }
        current = current->next;
    }

    // Unlock the list and return the filtered network events
    pthread_mutex_unlock(&list->mutex);
    return filtered_events;
}

// Define the function to retrieve a specific network event based on UE_IDENTIFIER and CELL_ID
NETWORK_EVENT_TAG *retrieve_nfapi_message(NFAPI_MESSAGE_LIST_T *list, UE_IDENTIFIER ue_identifier, CELL_ID cell_id) {
    // Create a new NETWORK_EVENT_TAG structure to store the retrieved network event
    NETWORK_EVENT_TAG *retrieved_event = (NETWORK_EVENT_TAG *)malloc(sizeof(NETWORK_EVENT_TAG));
    if (!retrieved_event) {
        // Handle memory allocation failure gracefully by returning a status code indicating failure and logging the issue
        printf("Memory allocation failed for retrieved NFAPI message\n");
        return NULL;
    }

    // Lock the list to prevent concurrent access from multiple threads
    pthread_mutex_lock(&list->mutex);

    // Iterate through the list and retrieve the network event with the given UE_IDENTIFIER and CELL_ID
    NFAPI_MESSAGE_T *current = list->head;
    while (current) {
        if (current->ue_identifier == ue_identifier && current->cell_id == cell_id) {
            retrieved_event->network_event_tag = current->network_event_tag;
            break;
        }
        current = current->next;
    }

    // Unlock the list and return the retrieved network event
    pthread_mutex_unlock(&list->mutex);
    return retrieved_event;
}
