#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

bool validate_oauth2_token(const char *json) {
    json_object *root = json_tokener_parse(json);
    if (!root) {
        return false;
    }

    // Check for mandatory fields
    json_object *access_token = json_object_object_get(root, "access_token");
    json_object *expires_in = json_object_object_get(root, "expires_in");
    json_object *token_type = json_object_object_get(root, "token_type");
    if (!access_token || !expires_in || !token_type) {
        return false;
    }

    // Check for null string in access token
    const char *access_token_str = json_object_get_string(access_token);
    if (access_token_str == NULL) {
        return false;
    }

    // Check for positive integer in expires in
    int64_t expires_in_int = json_object_get_int64(expires_in);
    if (expires_in_int <= 0) {
        return false;
    }

    // Check for exactly 'Bearer' in token type
    const char *token_type_str = json_object_get_string(token_type);
    if (strcmp(token_type_str, "Bearer") != 0) {
        return false;
    }

    // Check for refresh token length
    json_object *refresh_token = json_object_object_get(root, "refresh_token");
    if (refresh_token) {
        const char *refresh_token_str = json_object_get_string(refresh_token);
        if (strlen(refresh_token_str) > 1024) {
            return false;
        }
    }

    // Check for scopes field
    json_object *scopes = json_object_object_get(root, "scopes");
    if (scopes) {
        size_t scope_count = json_object_array_length(scopes);
        for (size_t i = 0; i < scope_count; ++i) {
            json_object *scope = json_object_array_get_idx(scopes, i);
            if (!json_object_is_type(scope, json_type_string)) {
                return false;
            }
            const char *scope_str = json_object_get_string(scope);
            if (strlen(scope_str) > 255) {
                return false;
            }
        }
    }

    // Check for expires in value not exceeding 86400 seconds
    if (expires_in_int > 86400) {
        return false;
    }

    json_object_put(root);
    return true;
}
```
