    new_event->prev = list->tail;
    if (list->tail) {
        list->tail->next = new_event;
    } else {
        list->head = new_event;
    }
    list->tail = new_event;
}

// Function to delete a network event from the list
void delete_network_event(NETWORK_EVENTS_LIST *list, NFAPI_MESSAGE_T *event) {
    if (!list || !event) {
        return;
    }
    if (event->prev) {
        event->prev->next = event->next;
    } else {
        list->head = event->next;
    }
    if (event->next) {
        event->next->prev = event->prev;
    } else {
        list->tail = event->prev;
    }
}

// Function to retrieve a network event from the list based on CELL_ID and NETWORK_EVENT_TAG
NFAPI_MESSAGE_T* get_network_event(NETWORK_EVENTS_LIST *list, uint16_t CELL_ID, uint8_t NETWORK_EVENT_TAG) {
    if (!list) {
        return NULL;
    }
    NFAPI_MESSAGE_T *event = list->head;
    while (event) {
        if (event->CELL_ID == CELL_ID && event->NETWORK_EVENT_TAG == NETWORK_EVENT_TAG) {
            return event;
        }
        event = event->next;
    }
    return NULL;
}

// Function to filter and retrieve specific types of network events within a specified time range
void filter_network_events(NETWORK_EVENTS_LIST *list, uint16_t CELL_ID, uint8_t NETWORK_EVENT_TAG, time_t start_time, time_t end_time) {
    if (!list) {
        return;
    }
    NFAPI_MESSAGE_T *event = list->head;
    while (event) {
        if (event->CELL_ID == CELL_ID && event->NETWORK_EVENT_TAG == NETWORK_EVENT_TAG && event->timestamp >= start_time && event->timestamp <= end_time) {
            printf("Network event: UE ID = %d, Cell ID = %d, Event Tag = %d, Timestamp = %ld\n", event->UE_IDENTIFIER, event->CELL_ID, event->NETWORK_EVENT_TAG, event->timestamp);
        }
        event = event->next;
    }
}

// Function to handle memory management for the doubly-linked list of network events
void manage_network_events(NETWORK_EVENTS_LIST *list) {
    if (!list) {
        return;
    }
    NFAPI_MESSAGE_T *event = list->head;
    while (event) {
        // Handle memory management for each event in the list
        free(event);
        event = event->next;
    }
}
