    // Allocate memory for the merged array and initialize it to zero
    struct long_offset *merged_array = (struct long_offset *)calloc(1000000, sizeof(struct long_offset));

    // Loop through each element in the offset array and add its value to the merged array
    for (int i = 0; i < num_elements; i++) {
        struct long_offset *element = &offset[i];
        merged_array[num_records++] = *element;
