#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <pthread.h>

#define MAX_NODES 1000
#define MAX_THREADS 8
#define THRESHOLD_LOW 75
#define THRESHOLD_HIGH 90
#define UPDATE_INTERVAL 60 // seconds
#define LOGGING_INTERVAL 300 // seconds
#define MAX_LOG_ENTRIES 1000

typedef struct {
    int node_id;
    float cpu_usage;
    float memory_usage;
} NodeStatus;

NodeStatus nodes[MAX_NODES];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
int num_nodes = 0;
int num_threads = 0;
int thread_id[MAX_THREADS];
int thread_status[MAX_THREADS];
int log_index = 0;
NodeStatus log_entries[MAX_LOG_ENTRIES];

void init_nodes() {
    for (int i = 0; i < MAX_NODES; i++) {
        nodes[i].node_id = -1;
        nodes[i].cpu_usage = -1.0f;
        nodes[i].memory_usage = -1.0f;
    }
}

void init_threads() {
    for (int i = 0; i < MAX_THREADS; i++) {
        thread_id[i] = -1;
        thread_status[i] = -1;
    }
}

void update_node(int node_id, float cpu_usage, float memory_usage) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_nodes; i++) {
        if (nodes[i].node_id == node_id) {
            nodes[i].cpu_usage = cpu_usage;
            nodes[i].memory_usage = memory_usage;
            break;
        }
    }
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&mutex);
}

void* thread_func(void* arg) {
    int thread_id = (int)arg;
    while (1) {
        pthread_mutex_lock(&mutex);
        while (num_nodes == 0 || thread_status[thread_id] != -1) {
            pthread_cond_wait(&cond, &mutex);
        }
        thread_status[thread_id] = 1;
        int node_index = thread_id % num_nodes;
        NodeStatus* node = &nodes[node_index];
        float cpu_usage = node->cpu_usage;
        float memory_usage = node->memory_usage;
        pthread_mutex_unlock(&mutex);

        // Check if CPU usage is below threshold
        if (cpu_usage < THRESHOLD_LOW) {
            printf("Node %d: CPU usage is low (%f%%)\n", node->node_id, cpu_usage);
            // Initiate recovery process
            // ...
        }

        // Check if memory usage is below threshold
        if (memory_usage < THRESHOLD_LOW) {
            printf("Node %d: Memory usage is low (%f%%)\n", node->node_id, memory_usage);
            // Initiate recovery process
            // ...
        }

        pthread_mutex_lock(&mutex);
        thread_status[thread_id] = 0;
        pthread_cond_signal(&cond);
        pthread_mutex_unlock(&mutex);
    }
}

int main() {
    init_nodes();
    init_threads();

    // Create threads for each node
    for (int i = 0; i < num_nodes; i++) {
        pthread_create(&thread_id[i], NULL, thread_func, (void*)i);
    }

    // Update nodes with real-time metrics
    while (1) {
        // Get telemetry data from third-party APIs
        // ...

        // Update node statuses
        for (int i = 0; i < num_nodes; i++) {
            update_node(i, cpu_usage, memory_usage);
        }

        // Sleep for UPDATE_INTERVAL seconds
        sleep(UPDATE_INTERVAL);
    }

    return 0;
}
```
