public class SessionManager {
    private static final int MAX_SESSIONS = 1000000; // maximum number of sessions to store in memory
    private static final int MIN_PURGE_THRESHOLD = 750000; // minimum threshold for purging inactive sessions
    private static final int MAX_PURGE_THRESHOLD = 1000000; // maximum threshold for purging inactive sessions

    private Map<String, Session> sessions; // map of session IDs to session structures
    private List<String> sessionIDs; // list of session IDs in chronological order
    private List<String> userIPAddresses; // list of user IP addresses in chronological order
    private List<Long> loginTimestamps; // list of login timestamps in chronological order
    private List<Integer> sessionDurations; // list of session durations in seconds
    private List<Boolean> statusFlags; // list of status flags indicating whether sessions are active or inactive

    public SessionManager() {
        this.sessions = new HashMap<>();
        this.sessionIDs = new ArrayList<>();
        this.userIPAddresses = new ArrayList<>();
        this.loginTimestamps = new ArrayList<>();
        this.sessionDurations = new ArrayList<>();
        this.statusFlags = new ArrayList<>();
    }

    public void processLogFile(String inputLogFile, String outputReportFile, String filterCriteria, boolean includeSessionLogs, int purgeThreshold) {
        // read log file and extract relevant information
        List<String> lines = FileUtils.readLines(inputLogFile);
        for (String line : lines) {
            processLine(line);
        }

        // generate summarized report
        generateReport(outputReportFile, filterCriteria, includeSessionLogs, purgeThreshold);
    }

    public void processLine(String line) {
        // extract relevant information from the log line
        String[] tokens = line.split(" ");
        String sessionID = tokens[0];
        String userIPAddress = tokens[1];
        long loginTimestamp = Long.parseLong(tokens[2]);
        long logoutTimestamp = Long.parseLong(tokens[3]);
        int duration = (int) (logoutTimestamp - loginTimestamp);
        boolean statusFlag = Boolean.parseBoolean(tokens[4]);

        // update session structure in memory
        Session session = sessions.get(sessionID);
        if (session == null) {
            session = new Session();
            sessions.put(sessionID, session);
            sessionIDs.add(sessionID);
            userIPAddresses.add(userIPAddress);
            loginTimestamps.add(loginTimestamp);
            sessionDurations.add(duration);
            statusFlags.add(statusFlag);
        } else {
            session.update(userIPAddress, logoutTimestamp, duration, statusFlag);
        }
    }

    public void generateReport(String outputReportFile, String filterCriteria, boolean includeSessionLogs, int purgeThreshold) {
        // filter sessions based on the filter criteria
        List<Session> filteredSessions = new ArrayList<>();
        for (Session session : sessions.values()) {
            if (filterCriteria == null || filterCriteria.isEmpty() || session.matches(filterCriteria)) {
                filteredSessions.add(session);
            }
        }

        // generate report
        StringBuilder sb = new StringBuilder();
        for (Session session : filteredSessions) {
            sb.append("Session ID: ").append(session.getID()).append("\n");
            sb.append("User IP Address: ").append(session.getUserIPAddress()).append("\n");
            sb.append("Login Timestamp: ").append(session.getLoginTimestamp()).append("\n");
            sb.append("Logout Timestamp: ").append(session.getLogoutTimestamp()).append("\n");
            sb.append("Duration (seconds): ").append(session.getDuration()).append("\n");
            sb.append("Status Flag: ").append(session.isActive() ? "active" : "inactive").append("\n");
            if (includeSessionLogs) {
                sb.append("Session Logs:\n");
                for (String logLine : session.getLogLines()) {
                    sb.append(logLine).append("\n");
                }
            }
        }
        FileUtils.writeStringToFile(outputReportFile, sb.toString());

        // purge inactive sessions if necessary
        int numInactiveSessions = 0;
        for (Session session : sessions.values()) {
            if (!session.isActive()) {
                numInactiveSessions++;
            }
        }
        if (numInactiveSessions > purgeThreshold) {
            log.warn("Purging " + numInactiveSessions + " inactive sessions");
            for (Session session : sessions.values()) {
                if (!session.isActive()) {
                    sessions.remove(session.getID());
                    sessionIDs.remove(session.getID());
                    userIPAddresses.remove(session.getUserIPAddress());
                    loginTimestamps.remove(session.getLoginTimestamp());
                    sessionDurations.remove(session.getDuration());
                    statusFlags.remove(session.isActive());
                }
            }
        }
    }

    public void updateSession(String sessionID, String userIPAddress, long logoutTimestamp, int duration, boolean statusFlag) {
        Session session = sessions.get(sessionID);
        if (session == null) {
            throw new IllegalArgumentException("Invalid session ID");
        }
        session.update(userIPAddress, logoutTimestamp, duration, statusFlag);
    }

    public void purgeInactiveSessions() {
        int numInactiveSessions = 0;
        for (Session session : sessions.values()) {
            if (!session.isActive()) {
                numInactiveSessions++;
            }
        }
        if (numInactiveSessions > MIN_PURGE_THRESHOLD) {
            log.warn("Purging " + numInactiveSessions + " inactive sessions");
            for (Session session : sessions.values()) {
                if (!session.isActive()) {
                    sessions.remove(session.getID());
                    sessionIDs.remove(session.getID());
                    userIPAddresses.remove(session.getUserIPAddress());
                    loginTimestamps.remove(session.getLoginTimestamp());
                    sessionDurations.remove(session.getDuration());
                    statusFlags.remove(session.isActive());
                }
            }
        }
    }
}

class Session {
    private String id;
    private String userIPAddress;
    private long loginTimestamp;
    private long logoutTimestamp;
    private int duration;
    private boolean active;
    private List<String> logLines; // list of session logs

    public Session(String id, String userIPAddress, long loginTimestamp, long logoutTimestamp, int duration, boolean active) {
