#define MAX_MESSAGE_SIZE 1024
#define MAX_QUEUE_CAPACITY 10000
#define MIN_QUEUE_CAPACITY 100
#define DEFAULT_QUEUE_CAPACITY 500
#define MESSAGE_TIMEOUT 30 // seconds
#define MAX_THREADS 10

typedef struct {
    char* payload;
    size_t payload_size;
    long timestamp;
} message_t;

typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int head, tail;
    int capacity;
    message_t* messages[MAX_QUEUE_CAPACITY];
} queue_t;

void init_queue(queue_t* q) {
    q->head = 0;
    q->tail = 0;
    q->capacity = DEFAULT_QUEUE_CAPACITY;
    for (int i = 0; i < MAX_QUEUE_CAPACITY; i++) {
        q->messages[i] = NULL;
    }
}

void destroy_queue(queue_t* q) {
    for (int i = 0; i < q->capacity; i++) {
        free(q->messages[i]->payload);
        free(q->messages[i]);
    }
    pthread_mutex_destroy(&q->mutex);
    pthread_cond_destroy(&q->cond);
}

int enqueue(queue_t* q, message_t* m) {
    int ret = 0;
    pthread_mutex_lock(&q->mutex);
    while (q->head == (q->tail + 1) % q->capacity) {
        if (ret >= MESSAGE_TIMEOUT) {
            break;
        }
        ret++;
        pthread_cond_wait(&q->cond, &q->mutex);
    }
    if (q->head == (q->tail + 1) % q->capacity) {
        ret = -1; // queue is full
    } else {
        q->messages[q->tail] = m;
        q->tail = (q->tail + 1) % q->capacity;
    }
    pthread_mutex_unlock(&q->mutex);
    return ret;
}

int dequeue(queue_t* q, message_t** m) {
    int ret = 0;
    pthread_mutex_lock(&q->mutex);
    while (q->head == q->tail) {
        if (ret >= MESSAGE_TIMEOUT) {
            break;
        }
        ret++;
        pthread_cond_wait(&q->cond, &q->mutex);
    }
    if (q->head == q->tail) {
        ret = -1; // queue is empty
    } else {
        *m = q->messages[q->head];
        q->head = (q->head + 1) % q->capacity;
    }
    pthread_mutex_unlock(&q->mutex);
    return ret;
}

int peek(queue_t* q, message_t** m) {
