// Define the structure for the UDP header
typedef struct {
    uint32_t SRC_IP;
    uint32_t DEST_IP;
    uint16_t SRC_PORT;
    uint16_t DEST_PORT;
    uint32_t SEQ_NUMBER;
    bool ACK_FLAG;
} UDP_HEADER_T;

// Define the structure for the record
typedef struct {
    long offset;
    int key;
    int value;
} RECORD_T;

// Define the function to dynamically allocate and initialize an array of records
RECORD_T* allocate_records(int num_records, int key_size, int value_size) {
    // Allocate memory for the array of records
    RECORD_T* records = (RECORD_T*)malloc(num_records * sizeof(RECORD_T));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for the array of records\n");
        return NULL;
    }

    // Initialize each record with a random value within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % key_size;
        records[i].value = rand() % value_size;
    }

    return records;
}

// Define the function to dynamically allocate and initialize an array of UDP headers
UDP_HEADER_T* allocate_udp_headers(int num_headers, int src_ip_size, int dest_ip_size, int src_port_size, int dest_port_size) {
    // Allocate memory for the array of UDP headers
    UDP_HEADER_T* udp_headers = (UDP_HEADER_T*)malloc(num_headers * sizeof(UDP_HEADER_T));
    if (!udp_headers) {
        fprintf(stderr, "Failed to allocate memory for the array of UDP headers\n");
        return NULL;
    }

    // Initialize each header with a random value within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_headers; i++) {
        udp_headers[i].SRC_IP = rand() % src_ip_size;
        udp_headers[i].DEST_IP = rand() % dest_ip_size;
        udp_headers[i].SRC_PORT = rand() % src_port_size;
        udp_headers[i].DEST_PORT = rand() % dest_port_size;
        udp_headers[i].SEQ_NUMBER = rand();
        udp_headers[i].ACK_FLAG = (rand() % 2) ? true : false;
    }

    return udp_headers;
}

// Define the function to handle memory allocation failures gracefully
void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Failed to allocate memory\n");
        return NULL;
    }
    return ptr;
}

// Define the function to handle memory deallocation gracefully
void safe_free(void* ptr) {
    if (ptr) {
        free(ptr);
    }
}

// Define the function to validate a JSON object string representing an OAuth2 access token response
bool validate_oauth2_token(const char* json_string, const char* secret_key) {
    // Parse the JSON object string into a JSON object
    json_object* json = json_tokener_parse(json_string);
    if (!json) {
        fprintf(stderr, "Failed to parse the JSON object\n");
        return false;
    }

    // Check if the access token field is present and valid
    const char* access_token = json_object_get_string(json_object_object_get(json, "access_token"));
    if (!access_token) {
        fprintf(stderr, "The access token field is missing or invalid\n");
        return false;
    }

    // Check if the expires_in field is present and valid
    const char* expires_in = json_object_get_string(json_object_object_get(json, "expires_in"));
    if (!expires_in) {
        fprintf(stderr, "The expires_in field is missing or invalid\n");
        return false;
    }

    // Check if the token type field is present and valid
    const char* token_type = json_object_get_string(json_object_object_get(json, "token_type"));
    if (!token_type) {
        fprintf(stderr, "The token_type field is missing or invalid\n");
        return false;
    }

    // Calculate the HMAC SHA-256 hash of the access token and secret key
    unsigned char* hmac = HMAC(EVP_sha256(), (const void*)secret_key, strlen(secret_key), (const void*)access_token, strlen(access_token), NULL, NULL);
    if (!hmac) {
        fprintf(stderr, "Failed to calculate the HMAC SHA-256 hash\n");
        return false;
    }

    // Compare the calculated HMAC with the one in the JSON object
    const char* hmac_str = json_object_get_string(json_object_object_get(json, "hmac"));
    if (!hmac_str) {
        fprintf(stderr, "The hmac field is missing or invalid\n");
        return false;
    }
    if (strcmp(hmac_str, (const char*)hmac) != 0) {
        fprintf(stderr, "The HMAC SHA-256 hash does not match the one in the JSON object\n");
        return false;
    }

    // Free the memory allocated for the HMAC
    OPENSSL_free(hmac);

    // Return true if all checks passed successfully
    return true;
}

// Define the function to encrypt a string using AES-GCM with a random IV
int encrypt_string(const char* plaintext, const char* key, const char* iv, char** ciphertext) {
    // Allocate memory for the ciphertext
    *ciphertext = (char*)malloc(strlen(plaintext));
    if (!*ciphertext) {
        fprintf(stderr, "Failed to allocate memory for the ciphertext\n");
        return -1;
    }

    // Initialize the AES-GCM context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to initialize the AES-GCM context\n");
        return -1;
    }

    // Set the encryption key and IV
    int ret = EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, (const unsigned char*)key, (const unsigned char*)iv);
    if (!ret) {
        fprintf(stderr, "Failed to set the encryption key and IV\n");
        return -1;
    }

    // Encrypt the plaintext
    int len = strlen(plaintext);
    ret = EVP_EncryptUpdate(ctx, (unsigned char*)*ciphertext, &len, (const unsigned char*)plaintext, len);
    if (!ret) {
        fprintf(stderr, "Failed to encrypt the plaintext\n");
        return -1;
    }

    // Finalize the encryption
    ret = EVP_EncryptFinal_ex(ctx, (unsigned char*)*ciphertext + len, &len);
    if (!ret) {
        fprintf(stderr, "Failed to finalize the encryption\n");
        return -1;
    }

    // Get the length of the ciphertext
    *ciphertext = (char*)realloc(*ciphertext, len + 1);
    if (!*ciphertext) {
        fprintf(stderr, "Failed to reallocate memory for the ciphertext\n");
        return -1;
    }
    (*ciphertext)[len] = '\0';

    // Clean up the AES-GCM context
    EVP_CIPHER_CTX_free(ctx);

    return len;
}

// Define the function to decrypt a string using AES-GCM with a random IV
int decrypt_string(const char* ciphertext, const char* key, const char* iv, char** plaintext) {
    // Allocate memory for the plaintext
    *plaintext = (char*)malloc(strlen(ciphertext));
    if (!*plaintext) {
        fprintf(stderr, "Failed to allocate memory for the plaintext\n");
        return -1;
    }

    // Initialize the AES-GCM context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to initialize the AES-GCM context\n");
        return -1;
    }

    // Set the decryption key and IV
    int ret = EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, (const unsigned char*)key, (const unsigned char*)iv);
    if (!ret) {
        fprintf(stderr, "Failed to set the decryption key and IV\n");
        return -1;
    }

    // Decrypt the ciphertext
    int len = strlen(ciphertext);
    ret = EVP_DecryptUpdate(ctx, (unsigned char*)*plaintext, &len, (const unsigned char*)ciphertext, len);
    if (!ret) {
        fprintf(stderr, "Failed to decrypt the ciphertext\n");
        return -1;
    }

    // Finalize the decryption
    ret = EVP_DecryptFinal_ex(ctx, (unsigned char*)*plaintext + len, &len);
    if (!ret) {
        fprintf(stderr, "Failed to finalize the decryption\n");
        return -1;
    }

    // Get the length of the plaintext
    *plaintext = (char*)realloc(*plaintext, len + 1);
    if (!*plaintext) {
        fprintf(stderr, "Failed to reallocate memory for the plaintext\n");
        return -1;
    }
    (*plaintext)[len] = '\0';

    // Clean up the AES-GCM context
    EVP_CIPHER_CTX_free(ctx);

    return len;
}

