    if (level < 0 || level > 5) {
        fprintf(stderr, "Invalid logging level\n");
        return;
    }

    // Log the message based on the specified logging level
    switch (level) {
        case 1:
            printf("[DEBUG] %s\n", message);
            break;
        case 2:
            printf("[INFO] %s\n", message);
            break;
        case 3:
            printf("[WARNING] %s\n", message);
            break;
        case 4:
            printf("[ERROR] %s\n", message);
            break;
        case 5:
            printf("[FATAL] %s\n", message);
            break;
    }
}

