struct EVP_CIPHER *select_cipher(const char *mode) {
    struct EVP_CIPHER *cipher = NULL;

    if (strcmp(mode, "ECB") == 0) {
        cipher = EVP_des_ecb();
    } else if (strcmp(mode, "EDE") == 0) {
        cipher = EVP_des_ede();
    } else if (strcmp(mode, "EDE3") == 0) {
        cipher = EVP_des_ede3();
    } else if (strcmp(mode, "CFB") == 0) {
        cipher = EVP_des_cfb();
    } else if (strcmp(mode, "NULL") == 0) {
        // Null encryption for testing purposes only
        cipher = NULL;
    }

    return cipher;
}

bool validate_oauth2_token(const char *json_string) {
    json_object *root = json_tokener_parse(json_string);
    if (!root) {
        // JSON parsing failed, invalid token
        return false;
    }

    const char *access_token = json_object_get_string(json_object_object_get(root, "access_token"));
    if (!access_token) {
        // Missing access token field
        json_object_put(root);
        return false;
    }

    const char *token_type = json_object_get_string(json_object_object_get(root, "token_type"));
    if (!token_type || strcmp(token_type, "Bearer") != 0) {
        // Invalid token type field or missing field
        json_object_put(root);
        return false;
    }

    const char *expires_in = json_object_get_string(json_object_object_get(root, "expires_in"));
    if (!expires_in) {
        // Missing expires_in field
        json_object_put(root);
        return false;
    }

    int expires_in_int = atoi(expires_in);
    if (expires_in_int <= 0) {
        // Invalid expires_in value
        json_object_put(root);
        return false;
    }

    json_object_put(root);
    return true;
}

bool encrypt_decrypt(const char *mode, const unsigned char *plaintext, size_t plaintext_len, unsigned char **ciphertext, size_t *ciphertext_len) {
    struct EVP_CIPHER *cipher = select_cipher(mode);
    if (!cipher) {
        // Invalid cipher mode
        return false;
    }

    int key_len = EVP_CIPHER_key_length(cipher);
    unsigned char key[key_len];
    memset(key, 0, key_len);

    int iv_len = EVP_CIPHER_iv_length(cipher);
    unsigned char iv[iv_len];
    memset(iv, 0, iv_len);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        // Failed to create cipher context
        return false;
    }

    int ret = EVP_EncryptInit(ctx, cipher, key, iv);
    if (ret != 1) {
        // Encryption initialization failed
        EVP_CIPHER_CTX_free(ctx);
        return false;
    }

    ret = EVP_EncryptUpdate(ctx, *ciphertext, ciphertext_len, plaintext, plaintext_len);
    if (ret != 1) {
        // Encryption update failed
        EVP_CIPHER_CTX_free(ctx);
        return false;
    }

    ret = EVP_EncryptFinal(ctx, *ciphertext + *ciphertext_len, ciphertext_len);
    if (ret != 1) {
        // Encryption finalization failed
        EVP_CIPHER_CTX_free(ctx);
        return false;
    }

    EVP_CIPHER_CTX_free(ctx);
    return true;
}

bool decrypt_encrypt(const char *mode, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char **plaintext, size_t *plaintext_len) {
    struct EVP_CIPHER *cipher = select_cipher(mode);
    if (!cipher) {
        // Invalid cipher mode
        return false;
    }

    int key_len = EVP_CIPHER_key_length(cipher);
    unsigned char key[key_len];
    memset(key, 0, key_len);

    int iv_len = EVP_CIPHER_iv_length(cipher);
    unsigned char iv[iv_len];
    memset(iv, 0, iv_len);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        // Failed to create cipher context
        return false;
    }

    int ret = EVP_DecryptInit(ctx, cipher, key, iv);
    if (ret != 1) {
        // Decryption initialization failed
        EVP_CIPHER_CTX_free(ctx);
        return false;
    }

    ret = EVP_DecryptUpdate(ctx, *plaintext, plaintext_len, ciphertext, ciphertext_len);
    if (ret != 1) {
        // Decryption update failed
        EVP_CIPHER_CTX_free(ctx);
        return false;
    }

    ret = EVP_DecryptFinal(ctx, *plaintext + *plaintext_len, plaintext_len);
    if (ret != 1) {
        // Decryption finalization failed
        EVP_CIPHER_CTX_free(ctx);
        return false;
    }

    EVP_CIPHER_CTX_free(ctx);
    return true;
}
