Ptr<Filter> selectAndApplyFilter(const string& imagePath, FilterMode mode) {
    // Load the image from file
    Mat img = imread(imagePath);

    // Check if the image is valid
    if (img.empty()) {
        cout << "Invalid image" << endl;
        return nullptr;
    }

    // Select and apply the filter based on the mode
    Ptr<Filter> filter = nullptr;
    switch (mode) {
        case GaussianBlur:
            filter = createGaussianBlur(img, 5, 0);
            break;
        case MedianFilter:
            filter = createMedianFilter(img, 5);
            break;
        case EdgeDetection:
            filter = createEdgeDetector(img, CV_8U);
            break;
        case ContrastAdjustment:
            filter = createContrastAdjuster(img, 1.2);
            break;
        case NullProcessing:
            // Do nothing
            break;
    }

    // Apply the filter to the image
    if (filter != nullptr) {
        filter->apply(img);
    }

    return filter;
}

// Function to validate a JSON object string representing metadata
bool validateMetadata(const string& jsonString) {
    // Parse the JSON object
    Json::Value root;
    Json::Reader reader;
    if (!reader.parse(jsonString, root)) {
        cout << "Invalid JSON" << endl;
        return false;
    }

    // Check if all required fields are present
    if (!root["content_type"].isString() || !root["size"].isInt() || !root["last_modified"].isString() || !root["etag"].isString()) {
        cout << "Missing required field" << endl;
        return false;
    }

    // Check if the content type is valid
    string contentType = root["content_type"].asString();
    if (contentType != "image/jpeg" && contentType != "image/png" && contentType != "application/pdf") {
        cout << "Invalid content type" << endl;
        return false;
    }

    // Check if the size is a positive integer
    int size = root["size"].asInt();
    if (size <= 0) {
        cout << "Invalid size" << endl;
        return false;
    }

    // Check if the last modified timestamp is in ISO 8601 format
    string lastModified = root["last_modified"].asString();
    struct tm tm;
    char* result = strptime(lastModified.c_str(), "%Y-%m-%dT%H:%M:%SZ", &tm);
    if (result == nullptr) {
        cout << "Invalid last modified timestamp" << endl;
        return false;
    }

    // Check if the etag is a string
    string etag = root["etag"].asString();
    if (!etag.is_string()) {
        cout << "Invalid etag" << endl;
        return false;
    }

    return true;
}

int main() {
    // Test the selectAndApplyFilter function
    string imagePath = "/path/to/image.jpg";
    FilterMode mode = GaussianBlur;
    Ptr<Filter> filter = selectAndApplyFilter(imagePath, mode);
    if (filter != nullptr) {
        cout << "Selected and applied filter: " << filter->getDefaultName() << endl;
    } else {
        cout << "Failed to select and apply filter" << endl;
    }

    // Test the validateMetadata function
    string jsonString = "{\"content_type\": \"image/jpeg\", \"size\": 1024, \"last_modified\": \"2023-02-27T15:30:00Z\", \"etag\": \"abcdefg\"}";
    bool valid = validateMetadata(jsonString);
    if (valid) {
        cout << "Valid metadata" << endl;
    } else {
        cout << "Invalid metadata" << endl;
    }

    return 0;
}
```
This code defines a `selectAndApplyFilter` function that takes an image path and a filter mode as input, loads the image from file using OpenCV's `imread` function, selects and applies the appropriate filter based on the mode, and returns a pointer to the selected filter. It also defines a `validateMetadata` function that takes a JSON object string representing metadata as input, parses the JSON object using the JsonCpp library, checks if all required fields are present and have valid values, and returns a boolean indicating whether the metadata is valid or not.

The code also includes a main function that tests the `selectAndApplyFilter` and `validateMetadata` functions by applying Gaussian blur to an image and validating a JSON object string representing metadata. The output of the program should indicate whether the filter was successfully applied and the metadata is valid or not.']

