// C function to develop and maintain a modular, thread-safe message queue system for handling asynchronous event-driven applications
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <stdbool.h>

// Define the structure for an event in the queue
typedef struct {
    int EVENT_ID;
    time_t TIMESTAMP;
    char* EVENT_SOURCE;
    char* EVENT_PAYLOAD;
} Event;

// Define the structure for a message in the queue
typedef struct {
    Event event;
    bool processed;
} Message;

// Define the structure for the queue itself
typedef struct {
    int size;
    int capacity;
    Message* messages;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} Queue;

// Function to initialize a new queue
Queue* initQueue(int capacity) {
    Queue* queue = (Queue*) malloc(sizeof(Queue));
    queue->size = 0;
    queue->capacity = capacity;
    queue->messages = (Message*) malloc(sizeof(Message) * capacity);
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond, NULL);
    return queue;
}

// Function to add a new event to the queue
void enqueueEvent(Queue* queue, Event event) {
    // Acquire lock on mutex
    pthread_mutex_lock(&queue->mutex);

    // Check if the queue is full
    if (queue->size == queue->capacity) {
        // If the queue is full, wait for a message to be processed before adding a new one
        while (queue->size == queue->capacity) {
            pthread_cond_wait(&queue->cond, &queue->mutex);
        }
    }

    // Add the event to the end of the queue
    queue->messages[queue->size].event = event;
    queue->messages[queue->size].processed = false;
    queue->size++;

    // Signal that a new message has been added
    pthread_cond_signal(&queue->cond);

    // Release lock on mutex
    pthread_mutex_unlock(&queue->mutex);
}

// Function to remove an event from the queue
Event dequeueEvent(Queue* queue) {
    // Acquire lock on mutex
    pthread_mutex_lock(&queue->mutex);

    // Check if the queue is empty
    if (queue->size == 0) {
        // If the queue is empty, wait for a message to be added before removing one
        while (queue->size == 0) {
            pthread_cond_wait(&queue->cond, &queue->mutex);
        }
    }

    // Remove the first event from the queue
    Event event = queue->messages[0].event;
    queue->messages[0].processed = true;
    queue->size--;

    // If there are any messages after the one we removed, move them to the front of the queue
    if (queue->size > 0) {
        for (int i = 1; i < queue->size + 1; i++) {
            queue->messages[i - 1] = queue->messages[i];
        }
    }

    // Signal that a message has been processed
    pthread_cond_signal(&queue->cond);

    // Release lock on mutex
    pthread_mutex_unlock(&queue->mutex);

    return event;
}

// Function to destroy the queue and free its resources
void destroyQueue(Queue* queue) {
    // Acquire lock on mutex
    pthread_mutex_lock(&queue->mutex);

    // Free the memory used by the queue
    free(queue->messages);
    free(queue);

    // Release lock on mutex
    pthread_mutex_unlock(&queue->mutex);
}
