// PHP function to generate a random string of a specified length using a given character set, and then hashes a given password using a default hash function
function generateRandomString($length, $charset) {
    $randomString = '';
    for ($i = 0; $i < $length; $i++) {
        $randomString .= $charset[rand(0, strlen($charset) - 1)];
    }
    return $randomString;
}

function hashPassword($password) {
    // Use a default hash function such as bcrypt or argon2i to hash the password
    return password_hash($password, PASSWORD_DEFAULT);
