#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

// Define the struct for log entries
typedef struct {
    char *ip_address;
    int port_number;
    time_t timestamp;
} LogEntry;

// Define the array of log entries
LogEntry *log_array = NULL;
size_t log_array_size = 0;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new log entry
int add_log(const char *ip_address, int port_number, time_t timestamp) {
    // Validate input parameters
    if (ip_address == NULL || port_number < 0 || timestamp < 0) {
        return -1;
    }

    // Acquire the mutex lock to ensure thread safety
    pthread_mutex_lock(&log_mutex);

    // Check if the array needs to be resized
    if (log_array_size == 0 || log_array_size <= log_array_used) {
        size_t new_size = log_array_size * 2;
        LogEntry *new_array = realloc(log_array, new_size * sizeof(LogEntry));
        if (new_array == NULL) {
            pthread_mutex_unlock(&log_mutex);
            return -1;
        }
        log_array = new_array;
        log_array_size = new_size;
    }

    // Add the new log entry to the array
    LogEntry *new_entry = &log_array[log_array_used++];
    new_entry->ip_address = strdup(ip_address);
    new_entry->port_number = port_number;
    new_entry->timestamp = timestamp;

    // Release the mutex lock
    pthread_mutex_unlock(&log_mutex);

    return 0;
}

// Function to retrieve a log entry based on IP address and timestamp
int get_log(const char *ip_address, time_t timestamp) {
    // Validate input parameters
    if (ip_address == NULL || timestamp < 0) {
        return -1;
    }

    // Acquire the mutex lock to ensure thread safety
    pthread_mutex_lock(&log_mutex);

    // Search for the log entry in the array
    size_t i = 0;
    while (i < log_array_used) {
        LogEntry *entry = &log_array[i];
        if (strcmp(entry->ip_address, ip_address) == 0 && entry->timestamp == timestamp) {
            // Release the mutex lock and return the log entry
            pthread_mutex_unlock(&log_mutex);
            return i;
        }
        i++;
    }

    // Release the mutex lock and return failure if the log entry is not found
    pthread_mutex_unlock(&log_mutex);
    return -1;
}

// Function to filter log entries based on IP address and timestamp
int filter_logs(const char *ip_address, time_t timestamp) {
    // Validate input parameters
    if (ip_address == NULL || timestamp < 0) {
        return -1;
    }

    // Acquire the mutex lock to ensure thread safety
    pthread_mutex_lock(&log_mutex);

    // Search for the log entry in the array
    size_t i = 0;
    while (i < log_array_used) {
        LogEntry *entry = &log_array[i];
        if (strcmp(entry->ip_address, ip_address) == 0 && entry->timestamp >= timestamp) {
            // Release the mutex lock and return the log entry
            pthread_mutex_unlock(&log_mutex);
            return i;
        }
        i++;
    }

    // Release the mutex lock and return failure if the log entry is not found
    pthread_mutex_unlock(&log_mutex);
    return -1;
}

// Function to retrieve all log entries
int get_all_logs() {
    // Acquire the mutex lock to ensure thread safety
    pthread_mutex_lock(&log_mutex);

    // Return a copy of the log array
    LogEntry *copy = malloc(log_array_used * sizeof(LogEntry));
    if (copy == NULL) {
        pthread_mutex_unlock(&log_mutex);
        return -1;
    }
    memcpy(copy, log_array, log_array_used * sizeof(LogEntry));

    // Release the mutex lock and return the copy of the log array
    pthread_mutex_unlock(&log_mutex);
    return 0;
}

// Function to clear all log entries
int clear_logs() {
    // Acquire the mutex lock to ensure thread safety
    pthread_mutex_lock(&log_mutex);

    // Free the memory allocated for the log array
    free(log_array);
    log_array = NULL;
    log_array_size = 0;
    log_array_used = 0;

    // Release the mutex lock and return success
    pthread_mutex_unlock(&log_mutex);
    return 0;
}
```
