#include <errno.h>
#include <pthread.h>

#define MAX_STRUCTS 1000000
#define MIN_CRCFLAG_PROBABILITY 0.5
#define CRCFLAG_RANDOM_SEED 42

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* allocateStructs(int numStructs) {
    // Allocate an array of structs
    NFAPI_CRC_INDICATION_PDU_T* structArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numStructs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structArray) {
        printf("Error: Failed to allocate memory for %d structures\n", numStructs);
        return NULL;
    }

    // Initialize the structs with default values
    for (int i = 0; i < numStructs; i++) {
        structArray[i].RX_UE_INFORMATION_TAG = -1;
        structArray[i].RNTI = -1;
        structArray[i].CRC_INDICATION_REL8_TAG = -1;
    }

    // Set the CRCFLAG randomly based on a configurable probability
    for (int i = 0; i < numStructs; i++) {
        if (rand() / (double)RAND_MAX < MIN_CRCFLAG_PROBABILITY) {
            structArray[i].CRCFLAG = 1;
        } else {
            structArray[i].CRCFLAG = 0;
        }
    }

    return structArray;
}

void deallocateStructs(NFAPI_CRC_INDICATION_PDU_T* structArray) {
    // Free the memory allocated for the struct array
    free(structArray);
}

int processLogFile(char* logFilePath, char* outputSummaryFileName, int filterStringLength, char* filterString, int aggregationTypeStringLength, char* aggregationTypeString) {
    // Open the log file and read its contents
    FILE* logFile = fopen(logFilePath, "r");
    if (!logFile) {
        printf("Error: Failed to open log file %s\n", logFilePath);
        return -1;
    }

    // Allocate an array of structs for the log data
    int numStructs = 0;
    NFAPI_CRC_INDICATION_PDU_T* structArray = allocateStructs(numStructs);
    if (!structArray) {
        printf("Error: Failed to allocate memory for %d structures\n", numStructs);
        return -1;
    }

    // Read the log data and populate the struct array
    while (fscanf(logFile, "%d,%d,%d", &structArray[numStructs].RX_UE_INFORMATION_TAG, &structArray[numStructs].RNTI, &structArray[numStructs].CRC_INDICATION_REL8_TAG) == 3) {
        numStructs++;
    }

    // Close the log file
    fclose(logFile);

    // Filter and aggregate the data based on user-defined criteria
    int filteredNumStructs = 0;
    for (int i = 0; i < numStructs; i++) {
        if (filterStringLength > 0 && strncmp(filterString, structArray[i].RX_UE_INFORMATION_TAG, filterStringLength) != 0) {
            continue;
        }
        if (aggregationTypeStringLength > 0 && strncmp(aggregationTypeString, structArray[i].RNTI, aggregationTypeStringLength) != 0) {
            continue;
        }
        filteredNumStructs++;
    }

    // Write the processed data to a summary file
    FILE* outputSummaryFile = fopen(outputSummaryFileName, "w");
    if (!outputSummaryFile) {
        printf("Error: Failed to open output summary file %s\n", outputSummaryFileName);
        return -1;
    }
    for (int i = 0; i < filteredNumStructs; i++) {
        fprintf(outputSummaryFile, "%d,%d,%d\n", structArray[i].RX_UE_INFORMATION_TAG, structArray[i].RNTI, structArray[i].CRC_INDICATION_REL8_TAG);
    }
    fclose(outputSummaryFile);

    // Deallocate the memory allocated for the struct array
    deallocateStructs(structArray);

    return 0;
}

int main(int argc, char* argv[]) {
    if (argc < 5) {
        printf("Usage: %s <input directory path> <output summary file name> <filter string> <aggregation type string>\n", argv[0]);
        return -1;
    }

    char* inputDirectoryPath = argv[1];
    char* outputSummaryFileName = argv[2];
    int filterStringLength = strlen(argv[3]);
    char* filterString = argv[3];
    int aggregationTypeStringLength = strlen(argv[4]);
    char* aggregationTypeString = argv[4];

    // Process each log file in the input directory
    DIR* dir;
    struct dirent* entry;
    if ((dir = opendir(inputDirectoryPath)) != NULL) {
        while ((entry = readdir(dir)) != NULL) {
            char* logFilePath = (char*)malloc(strlen(inputDirectoryPath) + strlen(entry->d_name) + 1);
            sprintf(logFilePath, "%s/%s", inputDirectoryPath, entry->d_name);
            processLogFile(logFilePath, outputSummaryFileName, filterStringLength, filterString, aggregationTypeStringLength, aggregationTypeString);
            free(logFilePath);
        }
        closedir(dir);
    } else {
        printf("Error: Failed to open input directory %s\n", inputDirectoryPath);
        return -1;
    }

    return 0;
}
