// Define the function to validate the password
bool validatePassword(const char* password) {
    // Check if the password is long enough
    if (strlen(password) < 8) {
        return false;
    }

    // Check if the password includes special characters
    for (int i = 0; i < strlen(password); i++) {
        if (!isalnum(password[i]) && !isspace(password[i])) {
            return true;
        }
    }

    // Check if the password includes numbers and uppercase/lowercase letters
    for (int i = 0; i < strlen(password); i++) {
        if (isdigit(password[i]) || isupper(password[i]) || islower(password[i])) {
            return true;
        }
    }

    // If none of the above conditions are met, return false
    return false;
}

// Define the function to populate the NFAPI_CRC_INDICATION_PDU_T linked list with validation
bool populateNFAPIListWithValidation(const char* password) {
    // Validate the password concurrently using a separate worker thread
    pthread_t validatePasswordThread;
    if (pthread_create(&validatePasswordThread, NULL, validatePassword, password)) {
        printf("Error creating validation thread\n");
        return false;
    }

    // Wait for the validation thread to complete
    void* result = NULL;
    pthread_join(validatePasswordThread, &result);

    // Check if the password is valid
    bool isValid = (bool)result;
    if (!isValid) {
        printf("Invalid password\n");
        return false;
    }

    // Create a new linked list node for each RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    NFAPI_CRC_INDICATION_PDU_T* currentNode = NULL;
    while (currentNode != NULL) {
        // Allocate memory for the new node
        currentNode = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (currentNode == NULL) {
            printf("Error allocating memory for linked list\n");
            return false;
        }

        // Initialize the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG in the new node
        currentNode->rxUeInformation = RX_UE_INFORMATION_TAG();
        currentNode->rnti = RNTI();
        currentNode->crcIndicationRel8.crCFlag = (uint16_t)rand() % 2;

        // Add the new node to the linked list
        if (head == NULL) {
            head = currentNode;
        } else {
            tail->next = currentNode;
        }
        tail = currentNode;
    }

    return true;
}
