    struct Node *next;
    struct Node *prev;
};

// Define a function to create and initialize a doubly-linked list of NFAPI_MESSAGE_T structures
int createList(struct Node **head) {
    // Allocate memory for the head node
    *head = (struct Node *)malloc(sizeof(struct Node));
    if (*head == NULL) {
        return -1;
    }

    // Initialize the head node
    (*head)->data = NULL;
    (*head)->next = NULL;
    (*head)->prev = NULL;

    return 0;
}

// Define a function to insert a new NFAPI_MESSAGE_T structure into the doubly-linked list
int insertNode(struct Node **head, struct NFAPI_MESSAGE_T *data) {
    // Allocate memory for the new node
    struct Node *newNode = (struct Node *)malloc(sizeof(struct Node));
    if (newNode == NULL) {
        return -1;
    }

    // Initialize the new node
    newNode->data = data;
    newNode->next = NULL;
    newNode->prev = NULL;

    // Insert the new node into the list
    struct Node *current = *head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = newNode;
    newNode->prev = current;

    return 0;
}

// Define a function to delete a NFAPI_MESSAGE_T structure from the doubly-linked list
int deleteNode(struct Node **head, struct NFAPI_MESSAGE_T *data) {
    // Find the node containing the specified data
    struct Node *current = *head;
    while (current != NULL && current->data != data) {
        current = current->next;
    }

    // If the node is found, delete it from the list
    if (current != NULL) {
        struct Node *temp = current;
        current = current->prev;
        current->next = temp->next;
        free(temp);
        return 0;
    } else {
        // If the node is not found, return an error code
        return -1;
    }
}

