bool populateSensorList(SensorData *data, int size) {
    // Initialize variables
    bool success = true;
    int i;
    double movingAverage[3];
    double threshold = 10.0;

    // Validate incoming sensor data
    for (i = 0; i < size; i++) {
        if (!validateSensorData(data[i])) {
            success = false;
            printf("Invalid sensor data detected at index %d\n", i);
        }
