    for (i = 0; i < size - 2; i++) {
        movingAverage[0] = data[i].temperature;
        movingAverage[1] = data[i + 1].temperature;
        movingAverage[2] = data[i + 2].temperature;
        if (fabs(movingAverage[0] - movingAverage[1]) > threshold || fabs(movingAverage[1] - movingAverage[2]) > threshold) {
            success = false;
            printf("Anomaly detected in temperature data at index %d\n", i);
        }
    }

    // Log warnings and return status indicator
    if (!success) {
        printf("Warnings detected during sensor data population\n");
    }
    return success;
}

// Define function to validate incoming sensor data
bool validateSensorData(SensorData data) {
    bool valid = true;
    // Validate temperature range
    if (data.temperature < 0 || data.temperature > 100) {
        valid = false;
    }
    // Validate humidity range
    if (data.humidity < 0 || data.humidity > 100) {
        valid = false;
    }
    // Validate pressure change
    if (fabs(data.pressure - data.pressure) > 5) {
        valid = false;
    }
    return valid;
}

// Define function to export sensor data to file for long-term storage and analysis
void exportSensorDataToFile(SensorData *data, int size) {
    FILE *file = fopen("sensor_data.txt", "w");
    if (file == NULL) {
        printf("Error opening file\n");
        return;
    }
    for (int i = 0; i < size; i++) {
        fprintf(file, "%f,%f,%f\n", data[i].temperature, data[i].humidity, data[i].pressure);
    }
    fclose(file);
}
