    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a linked list to store the NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
} NFAPI_CRC_INDICATION_LIST;

// Define a function to dynamically allocate and populate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_LIST* create_crc_indication_list(int num_elements) {
    // Allocate memory for the linked list
    NFAPI_CRC_INDICATION_LIST *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST));
    if (!list) {
        printf("Error: Failed to allocate memory for CRC indication list\n");
        return NULL;
    }

    // Initialize the linked list
    list->head = NULL;
    list->tail = NULL;

    // Populate the linked list with NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < num_elements; i++) {
        // Allocate memory for the current element
        NFAPI_CRC_INDICATION_PDU_T *element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!element) {
            printf("Error: Failed to allocate memory for CRC indication element\n");
            return NULL;
        }

        // Set the RX_UE_INFORMATION_TAG and RNTI for the current element
        element->rx_ue_information.tag = RX_UE_INFORMATION_TAG;
        element->rnti = i + 1;

        // Set a randomly set CRCFLAG for the current element
        element->crc_indication_rel8.crcflag = rand() % 2;

        // Add the current element to the linked list
        if (list->head == NULL) {
            list->head = element;
            list->tail = element;
        } else {
            list->tail->next = element;
            list->tail = element;
        }
    }

    return list;
}

// Define a function to iterate over the linked list and print each element's details
void print_crc_indication_list(NFAPI_CRC_INDICATION_LIST *list) {
    // Iterate over the linked list and print each element's details
    for (NFAPI_CRC_INDICATION_PDU_T *element = list->head; element != NULL; element = element->next) {
        printf("RX_UE_INFORMATION_TAG: %d\n", element->rx_ue_information.tag);
        printf("RNTI: %d\n", element->rnti);
        printf("CRCFLAG: %d\n", element->crc_indication_rel8.crcflag);
    }
}

// Define a function to resize the linked list if it exceeds a predefined size limit
void resize_crc_indication_list(NFAPI_CRC_INDICATION_LIST *list, int new_size) {
    // Allocate memory for the new linked list
    NFAPI_CRC_INDICATION_LIST *new_list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST));
    if (!new_list) {
        printf("Error: Failed to allocate memory for resized CRC indication list\n");
        return;
    }

    // Initialize the new linked list
    new_list->head = NULL;
    new_list->tail = NULL;

    // Copy over the existing elements from the old linked list to the new one
    for (NFAPI_CRC_INDICATION_PDU_T *element = list->head; element != NULL; element = element->next) {
        // Allocate memory for the current element in the new linked list
        NFAPI_CRC_INDICATION_PDU_T *new_element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_element) {
            printf("Error: Failed to allocate memory for resized CRC indication element\n");
            return;
        }

        // Copy over the details from the current element in the old linked list to the new one
        memcpy(new_element, element, sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Add the current element to the new linked list
        if (new_list->head == NULL) {
            new_list->head = new_element;
            new_list->tail = new_element;
        } else {
            new_list->tail->next = new_element;
            new_list->tail = new_element;
        }
    }

    // Free the memory for the old linked list
    free(list);

    // Update the pointer to the resized linked list
    list = new_list;
}
