// Define the structure to hold the NFAPI_CRC_INDICATION_PDU_T data
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list structure to hold the NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next;
} LinkedList;

// Function to dynamically manage the linked list of NFAPI_CRC_INDICATION_PDU_T structures
void manageLinkedList(LinkedList **list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, bool CRCFLAG) {
    // Check if the list is empty
    if (*list == NULL) {
        // Allocate memory for the first node in the list
        *list = (LinkedList *)malloc(sizeof(LinkedList));
        if (*list == NULL) {
            printf("Memory allocation failed\n");
            return;
        }
        (*list)->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if ((*list)->data == NULL) {
            printf("Memory allocation failed\n");
            return;
        }
        (*list)->data->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        (*list)->data->RNTI = RNTI;
        (*list)->data->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        (*list)->data->CRCFLAG = CRCFLAG;
        (*list)->next = NULL;
    } else {
        // Iterate through the list until a node with the same RNTI is found
        LinkedList *currentNode = *list;
        while (currentNode != NULL) {
            if (currentNode->data->RNTI == RNTI) {
                break;
            }
            currentNode = currentNode->next;
        }
        // If a node with the same RNTI is found, update its data
        if (currentNode != NULL) {
            currentNode->data->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
            currentNode->data->RNTI = RNTI;
            currentNode->data->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
            currentNode->data->CRCFLAG = CRCFLAG;
        } else {
            // If a node with the same RNTI is not found, create a new node and add it to the list
            LinkedList *newNode = (LinkedList *)malloc(sizeof(LinkedList));
            if (newNode == NULL) {
                printf("Memory allocation failed\n");
                return;
            }
            newNode->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (newNode->data == NULL) {
                printf("Memory allocation failed\n");
                return;
            }
            newNode->data->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
            newNode->data->RNTI = RNTI;
            newNode->data->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
            newNode->data->CRCFLAG = CRCFLAG;
            newNode->next = NULL;
            // Add the new node to the end of the list
            LinkedList *currentNode = *list;
            while (currentNode->next != NULL) {
                currentNode = currentNode->next;
            }
            currentNode->next = newNode;
        }
    }
}

// Function to insert a new element at the beginning of the list
void insertAtBeginning(LinkedList **list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, bool CRCFLAG) {
    // Create a new node with the given data
    LinkedList *newNode = (LinkedList *)malloc(sizeof(LinkedList));
    if (newNode == NULL) {
        printf("Memory allocation failed\n");
        return;
    }
    newNode->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newNode->data == NULL) {
        printf("Memory allocation failed\n");
        return;
    }
    newNode->data->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->data->RNTI = RNTI;
    newNode->data->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    newNode->data->CRCFLAG = CRCFLAG;
    // Insert the new node at the beginning of the list
    newNode->next = *list;
    *list = newNode;
}

// Function to delete an element from the list based on its RNTI
void deleteByRNTI(LinkedList **list, int RNTI) {
    // Iterate through the list until a node with the given RNTI is found
    LinkedList *currentNode = *list;
    while (currentNode != NULL) {
        if (currentNode->data->RNTI == RNTI) {
            break;
        }
        currentNode = currentNode->next;
    }
    // If a node with the given RNTI is found, delete it from the list
    if (currentNode != NULL) {
        LinkedList *previousNode = NULL;
        while (currentNode != NULL && currentNode->data->RNTI == RNTI) {
            previousNode = currentNode;
            currentNode = currentNode->next;
        }
        // If the node to be deleted is not the first node in the list, update its previous node's next pointer
        if (previousNode != NULL) {
            previousNode->next = currentNode;
        } else {
            *list = currentNode;
        }
    }
}

// Function to update an element in the list based on its RNTI
void updateByRNTI(LinkedList **list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, bool CRCFLAG) {
    // Iterate through the list until a node with the given RNTI is found
    LinkedList *currentNode = *list;
    while (currentNode != NULL) {
        if (currentNode->data->RNTI == RNTI) {
            break;
        }
        currentNode = currentNode->next;
    }
    // If a node with the given RNTI is found, update its data
    if (currentNode != NULL) {
        currentNode->data->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        currentNode->data->RNTI = RNTI;
        currentNode->data->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        currentNode->data->CRCFLAG = CRCFLAG;
    }
}

// Function to resize the list when it exceeds a predefined size limit by reallocating memory and copying over the existing elements
void resizeList(LinkedList **list, int newSize) {
    // Check if the list is empty or has reached its maximum size
    if (*list == NULL || (*list)->next == NULL) {
        return;
    }
    // Calculate the number of elements to be copied over
    int numElements = 0;
    LinkedList *currentNode = *list;
    while (currentNode != NULL) {
        numElements++;
        currentNode = currentNode->next;
    }
    // Reallocate memory for the new list and copy over the existing elements
    LinkedList *newList = (LinkedList *)malloc(sizeof(LinkedList) * newSize);
    if (newList == NULL) {
        printf("Memory allocation failed\n");
        return;
    }
    currentNode = *list;
    for (int i = 0; i < numElements && currentNode != NULL; i++) {
        newList[i].data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (newList[i].data == NULL) {
            printf("Memory allocation failed\n");
            return;
        }
        memcpy(newList[i].data, currentNode->data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        newList[i].next = &newList[i + 1];
        currentNode = currentNode->next;
    }
    // Free the old list and set the new list as the current list
    free(*list);
    *list = newList;
}
