#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>

// Define the event structure
typedef struct {
    int EVENT_ID;
    time_t TIMESTAMP;
    char* EVENT_SOURCE;
    void* EVENT_PAYLOAD;
} Event;

// Define the queue structure
typedef struct {
    Event* events;
    int size;
    int capacity;
    pthread_mutex_t mutex;
    semaphore_t semaphore;
} Queue;

// Initialize the queue
void initQueue(Queue* queue) {
    queue->events = malloc(sizeof(Event*) * 10);
    queue->size = 0;
    queue->capacity = 10;
    pthread_mutex_init(&queue->mutex, NULL);
    semaphore_init(&queue->semaphore, 0, 0);
}

// Enqueue an event
void enqueue(Queue* queue, Event* event) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->size == queue->capacity) {
        // Dynamically expand the queue
        queue->events = realloc(queue->events, sizeof(Event*) * (queue->capacity + 10));
        queue->capacity += 10;
    }
    queue->events[queue->size++] = event;
    semaphore_post(&queue->semaphore);
    pthread_mutex_unlock(&queue->mutex);
}

// Dequeue an event
Event* dequeue(Queue* queue) {
    Event* event = NULL;
    pthread_mutex_lock(&queue->mutex);
    if (queue->size > 0) {
        event = queue->events[0];
        memmove(queue->events, queue->events + 1, sizeof(Event*) * (queue->size - 1));
        queue->size--;
    }
    semaphore_wait(&queue->semaphore);
    pthread_mutex_unlock(&queue->mutex);
    return event;
}

// Destroy the queue
void destroyQueue(Queue* queue) {
    free(queue->events);
    pthread_mutex_destroy(&queue->mutex);
    semaphore_destroy(&queue->semaphore);
}
