// Define the structure for the LTE_PHY_TEST_CONFIG
typedef struct {
    int N; // Number of structures to allocate
    int seed; // Seed for the random number generator
} LTE_PHY_TEST_CONFIG;

// Define the structure for the RX_UE_INFORMATION_TAG
typedef struct {
    int RX_UE_INFORMATION_TAG; // Tag for the RX UE information
    int RNTI; // RNTI value
    int CRC_INDICATION_REL8_TAG; // Tag for the CRC indication
} RX_UE_INFORMATION_TAG;

// Define the structure for the NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    RX_UE_INFORMATION_TAG *rx_ue_information_tag; // Pointer to the RX UE information tag
    int CRC_INDICATION_REL8_TAG; // Tag for the CRC indication
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to dynamically manage and initialize a configurable number of LTE_PHY_TEST_CONFIG structures within a resource-limited environment
void init_lte_phy_test_config(LTE_PHY_TEST_CONFIG *config, int N) {
    // Allocate memory for the list of RX_UE_INFORMATION_TAG structures
    config->rx_ue_information_tag = (RX_UE_INFORMATION_TAG *)malloc(N * sizeof(RX_UE_INFORMATION_TAG));
    if (!config->rx_ue_information_tag) {
        fprintf(stderr, "Error: Failed to allocate memory for the list of RX UE information tags\n");
        exit(1);
    }

    // Initialize the random number generator with a seed value
    srand(config->seed);

    // Populate the list of RX_UE_INFORMATION_TAG structures with randomly set values
    for (int i = 0; i < N; i++) {
        config->rx_ue_information_tag[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        config->rx_ue_information_tag[i].RNTI = rand() % 1000;
        config->rx_ue_information_tag[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
    }
}

// Define the function to dynamically manage and initialize a configurable number of NFAPI_CRC_INDICATION_PDU_T structures within a resource-limited environment
void init_nfapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, int N) {
    // Allocate memory for the list of RX_UE_INFORMATION_TAG structures
    pdu->rx_ue_information_tag = (RX_UE_INFORMATION_TAG *)malloc(N * sizeof(RX_UE_INFORMATION_TAG));
    if (!pdu->rx_ue_information_tag) {
        fprintf(stderr, "Error: Failed to allocate memory for the list of RX UE information tags\n");
        exit(1);
    }

    // Initialize the random number generator with a seed value
    srand(pdu->seed);

