    for (int i = 0; i < N; i++) {
        pdu->rx_ue_information_tag[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu->rx_ue_information_tag[i].RNTI = rand() % 1000;
        pdu->rx_ue_information_tag[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
    }
}

// Define the function to generate a new filename based on an existing one, modifying its extension with a sequence of random digits and appending a specific file type
char *generate_new_filename(const char *filename, const char *filetype) {
    // Get the length of the original filename
    int len = strlen(filename);

    // Allocate memory for the new filename
    char *new_filename = (char *)malloc((len + 10) * sizeof(char));
    if (!new_filename) {
        fprintf(stderr, "Error: Failed to allocate memory for the new filename\n");
        exit(1);
    }

    // Copy the original filename into the new one
    strcpy(new_filename, filename);

    // Get the position of the extension in the original filename
    int ext_pos = len - 4;

    // Replace the extension with a sequence of random digits and append the specific file type
    for (int i = 0; i < 10; i++) {
        new_filename[ext_pos + i] = '0' + rand() % 10;
    }
    strcat(new_filename, filetype);

    return new_filename;
}

// Define the function to calculate metrics like average line length and total character count for a given input file
void calculate_metrics(const char *filename) {
    // Open the input file in read-only mode
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error: Failed to open the input file %s\n", filename);
        exit(1);
    }

    // Initialize variables for calculating metrics
    int line_count = 0;
    long char_count = 0;

    // Read each line of the input file and calculate metrics
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        line_count++;
        char_count += strlen(line);
    }

    // Print the calculated metrics to the console
    printf("Average line length: %ld\n", char_count / line_count);
    printf("Total character count: %ld\n", char_count);

    // Close the input file
    fclose(file);
}

// Define the function to export metrics results to a separate log file
void export_metrics(const char *filename) {
    // Open the output file in write-only mode
    FILE *file = fopen(filename, "w");
    if (!file) {
        fprintf(stderr, "Error: Failed to open the output file %s\n", filename);
        exit(1);
    }

    // Print the calculated metrics to the output file
    calculate_metrics(filename);

    // Close the output file
    fclose(file);
}

// Define the function to handle errors during processing
void error_handler(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
    exit(1);
}

int main(int argc, char **argv) {
    // Initialize variables for command-line arguments and configuration parameters
    const char *input_file = NULL;
    const char *output_file = NULL;
    int processing_parameters = 0;
    int delimiter = '\n';
    int verbosity_level = 1;

    // Parse the command-line arguments and configuration parameters
    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-i") || !strcmp(argv[i], "--input")) {
            input_file = argv[++i];
        } else if (!strcmp(argv[i], "-o") || !strcmp(argv[i], "--output")) {
            output_file = argv[++i];
        } else if (!strcmp(argv[i], "-p") || !strcmp(argv[i], "--processing-parameters")) {
            processing_parameters = atoi(argv[++i]);
        } else if (!strcmp(argv[i], "-d") || !strcmp(argv[i], "--delimiter")) {
            delimiter = argv[++i][0];
        } else if (!strcmp(argv[i], "-v") || !strcmp(argv[i], "--verbosity-level")) {
            verbosity_level = atoi(argv[++i]);
        } else {
            error_handler("Invalid command-line argument");
        }
    }

    // Validate the input and output files
    if (!input_file || !output_file) {
        error_handler("Input and output files must be specified");
    }

    // Initialize the logging framework with the verbosity level
    init_logging(verbosity_level);

    // Open the input file in read-only mode
    FILE *input = fopen(input_file, "r");
    if (!input) {
        error_handler("Failed to open the input file");
    }

    // Open the output file in write-only mode
    FILE *output = fopen(output_file, "w");
    if (!output) {
        error_handler("Failed to open the output file");
    }

    // Initialize a configurable number of LTE_PHY_TEST_CONFIG structures within a resource-limited environment
    LTE_PHY_TEST_CONFIG config;
    init_lte_phy_test_config(&config, processing_parameters);

    // Initialize a configurable number of NFAPI_CRC_INDICATION_PDU_T structures within a resource-limited environment
    NFAPI_CRC_INDICATION_PDU_T pdu;
    init_nfapi_crc_indication_pdu(&pdu, processing_parameters);

    // Define the delimiter mechanism for line counting
    char *delimiter_str = (char *)malloc(2 * sizeof(char));
    delimiter_str[0] = delimiter;
    delimiter_str[1] = '\0';

    // Read each line of the input file and process it accordingly
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, input)) != -1) {
        // Count the number of lines in the input file
        int line_count = 1;
        char *token = strtok(line, delimiter_str);
        while (token) {
            token = strtok(NULL, delimiter_str);
            line_count++;
        }

        // Print the number of lines in the input file to the console
        printf("Number of lines: %d\n", line_count);

        // Calculate metrics like average line length and total character count for the input file
        calculate_metrics(input_file);

        // Export metrics results to a separate log file
        export_metrics("metrics.log");
    }

    // Close the input and output files
    fclose(input);
    fclose(output);

    return 0;
}
