    for (int i = 0; i < num_structures; i++) {
        // Generate a random RX UE information tag
        char *rx_ue_information_tag = malloc(sizeof(char) * 1024);
        sprintf(rx_ue_information_tag, "RX UE information %d", i);
        nfapi_crc_indication_pdu[i]->rx_ue_information_tag = rx_ue_information_tag;
        // Generate a random RNTI
        char *rnti = malloc(sizeof(char) * 1024);
        sprintf(rnti, "RNTI %d", i);
        nfapi_crc_indication_pdu[i]->rnti = rnti;
        // Generate a random CRC indication tag with a randomly set CRCFLAG
        char *crc_indication_rel8_tag = malloc(sizeof(char) * 1024);
        sprintf(crc_indication_rel8_tag, "CRC indication %d", i);
        nfapi_crc_indication_pdu[i]->crc_indication_rel8_tag = crc_indication_rel8_tag;
    }

    // Apply the transformation rules to process and generate an output file
    FILE *output = fopen(output_file, "w");
    if (output == NULL) {
        printf("Error: unable to open output file %s\n", output_file);
        return;
    }
    // Write the network parameters and transformation rules to the output file
    fwrite(network_parameters, sizeof(char), 1024, output);
    fwrite(transformation_rule, sizeof(char), 1024, output);
    // Close the output file
    fclose(output);

    // Free memory allocated for the dynamic arrays of LTE_RRCNAS_TransportChannel and NFAPI_CRC_INDICATION_PDU structures
    for (int i = 0; i < num_structures; i++) {
        free(lte_rrcnas_transport_channel[i]->nas_message);
        free(lte_rrcnas_transport_channel[i]->transport_channel_id);
        free(nfapi_crc_indication_pdu[i]->rx_ue_information_tag);
        free(nfapi_crc_indication_pdu[i]->rnti);
        free(nfapi_crc_indication_pdu[i]->crc_indication_rel8_tag);
    }
    free(lte_rrcnas_transport_channel);
    free(nfapi_crc_indication_pdu);
}
