// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t pdu_length;
    uint8_t pdu_type;
    uint8_t pdu_subtype;
    uint32_t pdu_data[];
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to manage a list of NFAPI_CRC_INDICATION_PDU_T structures
void manage_nfapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu_list, int num_pdus) {
    // Check if the list is NULL or empty
    if (pdu_list == NULL || num_pdus <= 0) {
        return;
