// Function to initialize and manage compression algorithms
void* initCompression(int algorithm) {
    void* ctx = NULL;
    switch (algorithm) {
        case DEFLATE:
            ctx = deflateInit();
            break;
        case GZIP:
            ctx = gzip_init();
            break;
        case LZ4:
            ctx = lz4_init();
            break;
    }
    return ctx;
}

// Function to compress data using the selected compression algorithm
void* compressData(void* ctx, const char* data) {
    switch (ctx) {
        case DEFLATE:
            return deflate(data);
        case GZIP:
            return gzip_compress(data);
        case LZ4:
            return lz4_compress(data);
    }
}

// Function to decompress data using the selected compression algorithm
void* decompressData(void* ctx, const char* data) {
    switch (ctx) {
        case DEFLATE:
            return deflate(data);
        case GZIP:
            return gzip_decompress(data);
        case LZ4:
            return lz4_decompress(data);
    }
}

