    if (!content_type || strcmp(content_type, APPLICATION_JSON) && strcmp(content_type, TEXT_HTML)) {
        return false;
    }

    // Free the JSON object string and return true if all required fields are valid
    json_object_put(obj);
    return true;
}

// Function to handle compression and decompression operations seamlessly
void* handleCompression(const char* data, int algorithm) {
    void* ctx = initCompression(algorithm);
    if (!ctx) {
        return NULL;
    }

    // Compress the data using the selected compression algorithm
    const char* compressed_data = compressData(ctx, data);
    if (!compressed_data) {
        free(ctx);
        return NULL;
    }

    // Decompress the compressed data using the selected compression algorithm
    const char* decompressed_data = decompressData(ctx, compressed_data);
    if (!decompressed_data) {
        free(ctx);
        return NULL;
    }

    // Free the compression context and return the decompressed data
    free(ctx);
    return decompressed_data;
}

