// Define the structure for a network event
typedef struct {
    uint32_t UE_IDENTIFIER;
    uint16_t CELL_ID;
    uint8_t NETWORK_EVENT_TAG;
    time_t timestamp;
} NFAPI_MESSAGE_T;

// Define the structure for a doubly-linked list of network events
typedef struct {
    NFAPI_MESSAGE_T *head;
    NFAPI_MESSAGE_T *tail;
} NETWORK_EVENTS_LIST_T;

// Define the function to create a new doubly-linked list of network events
NETWORK_EVENTS_LIST_T* create_network_events_list() {
    NETWORK_EVENTS_LIST_T *list = (NETWORK_EVENTS_LIST_T*)malloc(sizeof(NETWORK_EVENTS_LIST_T));
    if (!list) {
        printf("Error: unable to allocate memory for network events list\n");
        return NULL;
    }
    list->head = NULL;
    list->tail = NULL;
    return list;
}

// Define the function to insert a new node into the doubly-linked list of network events
void insert_network_event(NETWORK_EVENTS_LIST_T *list, uint32_t UE_IDENTIFIER, uint16_t CELL_ID, uint8_t NETWORK_EVENT_TAG) {
    // Create a new node for the network event
    NFAPI_MESSAGE_T *node = (NFAPI_MESSAGE_T*)malloc(sizeof(NFAPI_MESSAGE_T));
    if (!node) {
        printf("Error: unable to allocate memory for network event\n");
        return;
    }
    node->UE_IDENTIFIER = UE_IDENTIFIER;
    node->CELL_ID = CELL_ID;
    node->NETWORK_EVENT_TAG = NETWORK_EVENT_TAG;
    node->timestamp = time(NULL);

    // Insert the new node into the doubly-linked list
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }
}

// Define the function to delete a node from the doubly-linked list of network events
void delete_network_event(NETWORK_EVENTS_LIST_T *list, uint32_t UE_IDENTIFIER, uint16_t CELL_ID, uint8_t NETWORK_EVENT_TAG) {
    // Find the node to be deleted in the doubly-linked list
    NFAPI_MESSAGE_T *node = list->head;
    while (node != NULL && (node->UE_IDENTIFIER != UE_IDENTIFIER || node->CELL_ID != CELL_ID || node->NETWORK_EVENT_TAG != NETWORK_EVENT_TAG)) {
        node = node->next;
    }

    // If the node is found, delete it from the doubly-linked list
    if (node != NULL) {
        if (node == list->head) {
            list->head = node->next;
        } else {
            node->prev->next = node->next;
        }
        if (node == list->tail) {
            list->tail = node->prev;
        } else {
            node->next->prev = node->prev;
        }
        free(node);
    }
}

// Define the function to retrieve a node from the doubly-linked list of network events based on CELL_ID and NETWORK_EVENT_TAG
NFAPI_MESSAGE_T* get_network_event(NETWORK_EVENTS_LIST_T *list, uint16_t CELL_ID, uint8_t NETWORK_EVENT_TAG) {
    // Find the node in the doubly-linked list based on CELL_ID and NETWORK_EVENT_TAG
    NFAPI_MESSAGE_T *node = list->head;
    while (node != NULL && (node->CELL_ID != CELL_ID || node->NETWORK_EVENT_TAG != NETWORK_EVENT_TAG)) {
        node = node->next;
    }

    // Return the found node or NULL if not found
    return node;
}

// Define the function to filter and retrieve specific types of network events within a specified time range
void filter_network_events(NETWORK_EVENTS_LIST_T *list, uint16_t CELL_ID, uint8_t NETWORK_EVENT_TAG, time_t start_time, time_t end_time) {
    // Find the first node in the doubly-linked list that meets the specified criteria
    NFAPI_MESSAGE_T *node = list->head;
    while (node != NULL && (node->CELL_ID != CELL_ID || node->NETWORK_EVENT_TAG != NETWORK_EVENT_TAG)) {
        node = node->next;
    }

    // If the first node is found, iterate through the list and filter out nodes that are not within the specified time range
    if (node != NULL) {
        while (node != NULL && node->timestamp < end_time) {
            if (node->timestamp >= start_time) {
                // If the node meets the specified criteria, add it to a filtered list
                NFAPI_MESSAGE_T *filtered_node = (NFAPI_MESSAGE_T*)malloc(sizeof(NFAPI_MESSAGE_T));
                if (!filtered_node) {
                    printf("Error: unable to allocate memory for filtered network event\n");
                    return;
                }
                memcpy(filtered_node, node, sizeof(NFAPI_MESSAGE_T));
                filtered_node->next = NULL;
                if (list->head == NULL) {
                    list->head = filtered_node;
                } else {
                    list->tail->next = filtered_node;
                }
                list->tail = filtered_node;
            }
            node = node->next;
        }
    }
}

// Define the function to retrieve all nodes from the doubly-linked list of network events
void get_all_network_events(NETWORK_EVENTS_LIST_T *list, NFAPI_MESSAGE_T **nodes) {
    // Iterate through the doubly-linked list and add all nodes to an array
    NFAPI_MESSAGE_T *node = list->head;
    while (node != NULL) {
        nodes[*nodes] = node;
        (*nodes)++;
        node = node->next;
    }
}
