// Linked list node structure for UE contexts
typedef struct ue_context {
    char *ue_id;
    int qos_class;
    int slice_selection;
    struct ue_context *next;
} ue_context_t;

// Global linked list head pointer
static ue_context_t *head = NULL;

// Environment variable for batch size
#define BATCH_SIZE 5000

// Function to initialize and populate the linked list with data from a CSV file
void init_ue_list(char *filepath) {
    // Open the CSV file
    FILE *fp = fopen(filepath, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filepath);
        return;
    }

    // Read the data from the CSV file and populate the linked list
    char line[1024];
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Parse the line into UE identifier, QoS class, and slice selection
        char *token = strtok(line, ",");
        char *ue_id = token;
        int qos_class = atoi(strtok(NULL, ","));
        int slice_selection = atoi(strtok(NULL, "\n"));

        // Check if the UE identifier is valid and the QoS class is within range
        if (ue_id == NULL || qos_class < 0 || qos_class > 4) {
            printf("Error: invalid data in file %s\n", filepath);
            fclose(fp);
            return;
        }

        // Create a new node for the UE context and add it to the linked list
        ue_context_t *node = malloc(sizeof(ue_context_t));
        node->ue_id = strdup(ue_id);
        node->qos_class = qos_class;
        node->slice_selection = slice_selection;
        node->next = NULL;

        if (head == NULL) {
            head = node;
        } else {
            ue_context_t *current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = node;
        }
    }

    // Close the CSV file
    fclose(fp);
}

// Function to perform an integrity check on the linked list
void check_ue_list() {
    ue_context_t *current = head;
    while (current != NULL) {
        if (current->next == NULL) {
            break;
        }
        current = current->next;
    }
}

// Function to serialize the linked list into a JSON format for persistence
void serialize_ue_list(char *filepath) {
    // Open the output file
    FILE *fp = fopen(filepath, "w");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filepath);
        return;
    }

    // Serialize the linked list into JSON format
    json_object *root = json_object_new();
    json_object *ue_list = json_object_new();
    ue_context_t *current = head;
    while (current != NULL) {
        json_object *node = json_object_new();
        json_object_set_string(node, "ue_id", current->ue_id);
        json_object_set_int(node, "qos_class", current->qos_class);
        json_object_set_int(node, "slice_selection", current->slice_selection);
        json_array_add(ue_list, node);
        current = current->next;
    }
    json_object_set_value(root, "ue_list", ue_list);

    // Write the JSON data to the output file
    char *json_string = json_object_to_json_string(root);
    fprintf(fp, "%s\n", json_string);

    // Close the output file
    fclose(fp);
}

// Function to deserialize the linked list back into memory
void deserialize_ue_list(char *filepath) {
    // Open the input file
    FILE *fp = fopen(filepath, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filepath);
        return;
    }

    // Read the JSON data from the input file
    char line[1024];
    while (fgets(line, sizeof(line), fp) != NULL) {
        json_object *root = json_tokener_parse(line);
        json_object *ue_list = json_object_get_object(root, "ue_list");
        int size = json_object_array_length(ue_list);

        // Deserialize the JSON data into a linked list
        for (int i = 0; i < size; i++) {
            json_object *node = json_object_array_get_idx(ue_list, i);
            char *ue_id = json_object_get_string(json_object_object_get(node, "ue_id"));
            int qos_class = json_object_get_int(json_object_object_get(node, "qos_class"));
            int slice_selection = json_object_get_int(json_object_object_get(node, "slice_selection"));

            // Create a new node for the UE context and add it to the linked list
            ue_context_t *current = malloc(sizeof(ue_context_t));
            current->ue_id = strdup(ue_id);
            current->qos_class = qos_class;
            current->slice_selection = slice_selection;
            current->next = NULL;

            if (head == NULL) {
                head = current;
            } else {
                ue_context_t *current = head;
                while (current->next != NULL) {
                    current = current->next;
                }
                current->next = node;
            }
        }
    }

    // Close the input file
    fclose(fp);
}

// Function to handle race conditions and ensure thread safety when modifying or accessing the linked list
void lock_ue_list() {
    pthread_mutex_lock(&mutex);
}

void unlock_ue_list() {
    pthread_mutex_unlock(&mutex);
}

// Function to track the function's performance and identify any anomalies in data integrity checks
void log_ue_list(char *message) {
    printf("%s\n", message);
}

// Main function for testing the linked list functionality
int main() {
    // Initialize the linked list with data from a CSV file
    init_ue_list("ue_context.csv");

    // Perform an integrity check on the linked list
    check_ue_list();

    // Serialize the linked list into a JSON format for persistence
    serialize_ue_list("ue_context.json");

    // Deserialize the linked list back into memory
    deserialize_ue_list("ue_context.json");

    return 0;
}
