// Define a structure to represent a record in the CSV file
typedef struct {
    char *name;
    int age;
} Record;

// Define a function to read and filter records from a CSV file
void filter_records(char *input_file, char *output_file, char *filter_criteria, int max_records, bool sort_by_column, int max_structures) {
    // Open the input file for reading
    FILE *input = fopen(input_file, "r");
    if (input == NULL) {
        printf("Error: unable to open input file\n");
        return;
    }

    // Open the output file for writing
    FILE *output = fopen(output_file, "w");
    if (output == NULL) {
        printf("Error: unable to open output file\n");
        fclose(input);
        return;
    }

    // Dynamically allocate memory for the filtering criteria string
    char *filter_criteria_copy = malloc(strlen(filter_criteria) + 1);
    if (filter_criteria_copy == NULL) {
        printf("Error: unable to allocate memory for filter criteria\n");
        fclose(input);
        fclose(output);
        return;
    }
    strcpy(filter_criteria_copy, filter_criteria);

    // Dynamically allocate memory for the list of filtered records
    Record **filtered_records = malloc(max_structures * sizeof(Record));
    if (filtered_records == NULL) {
        printf("Error: unable to allocate memory for filtered records\n");
        free(filter_criteria_copy);
        fclose(input);
        fclose(output);
        return;
    }

    // Read the input file and filter the records based on the criteria
    int record_count = 0;
    while (fscanf(input, "%s %d", &filtered_records[record_count]->name, &filtered_records[record_count]->age) == 2 && record_count < max_structures) {
        // Check if the current record matches the filtering criteria
        bool match = true;
        for (int i = 0; i < strlen(filter_criteria); i++) {
            if (filtered_records[record_count]->name[i] != filter_criteria[i]) {
                match = false;
                break;
            }
        }

        // If the current record matches the filtering criteria, add it to the list of filtered records
        if (match) {
            record_count++;
        }
    }

    // Sort the list of filtered records by a specific column
    if (sort_by_column) {
        qsort(filtered_records, record_count, sizeof(Record), compare_records);
    }

    // Write the filtered records to the output file
    for (int i = 0; i < record_count; i++) {
        fprintf(output, "%s %d\n", filtered_records[i]->name, filtered_records[i]->age);
    }

    // Clean up memory
    free(filtered_records);
    free(filter_criteria_copy);
    fclose(input);
    fclose(output);
}

// Define a function to compare two records based on a specific column
int compare_records(const void *a, const void *b) {
    Record *record1 = (Record *)a;
    Record *record2 = (Record *)b;
    return strcmp(record1->name, record2->name);
}
