    int offset;
    int eof;
} FileReader;

typedef struct {
    char* resource_file;
    LanguageBundle** language_bundles;
    int num_languages;
    int current_language;
    int fallback_language;
} ResourceManager;

void manage_resource_and_hash(ResourceManager* manager) {
    // Initialize the hash function
    EVP_MD_CTX* mdctx = EVP_MD_CTX_new();
    if (mdctx == NULL) {
        fprintf(stderr, "Failed to initialize hash function\n");
        return;
    }

    // Open the resource file and read it in chunks
    FileReader* reader = open_file(manager->resource_file);
    if (reader == NULL) {
        fprintf(stderr, "Failed to open resource file\n");
        EVP_MD_CTX_free(mdctx);
        return;
    }

    // Read the file in chunks and compute the hash
    while (!reader->eof) {
        char* buffer = read_file(reader, manager->buffer_size);
        if (buffer == NULL) {
            fprintf(stderr, "Failed to read from resource file\n");
            close_file(reader);
            EVP_MD_CTX_free(mdctx);
            return;
        }

        // Update the hash with the current chunk of data
        if (!EVP_DigestUpdate(mdctx, buffer, reader->buffer_size)) {
            fprintf(stderr, "Failed to update hash\n");
            close_file(reader);
            EVP_MD_CTX_free(mdctx);
            return;
        }
    }

    // Get the final hash value and convert it to a hex string
    unsigned char digest[EVP_MAX_MD_SIZE];
    unsigned int digest_len = 0;
    if (!EVP_DigestFinal(mdctx, digest, &digest_len)) {
        fprintf(stderr, "Failed to finalize hash\n");
        close_file(reader);
        EVP_MD_CTX_free(mdctx);
        return;
    }

    char* hexdigest = malloc(2 * digest_len + 1);
    if (hexdigest == NULL) {
        fprintf(stderr, "Failed to allocate memory for hash\n");
        close_file(reader);
        EVP_MD_CTX_free(mdctx);
        return;
    }

    for (int i = 0; i < digest_len; ++i) {
        sprintf(&hexdigest[2 * i], "%02x", digest[i]);
    }

    // Clean up and return the hash value
    close_file(reader);
    EVP_MD_CTX_free(mdctx);
    return hexdigest;
}

FileReader* open_file(const char* file_path) {
    FileReader* reader = malloc(sizeof(FileReader));
    if (reader == NULL) {
        fprintf(stderr, "Failed to allocate memory for file reader\n");
        return NULL;
    }

    // Open the file and check its size
    int fd = open(file_path, O_RDONLY);
    if (fd == -1) {
        fprintf(stderr, "Failed to open resource file\n");
        free(reader);
        return NULL;
    }

    struct stat st;
    if (fstat(fd, &st) == -1) {
        fprintf(stderr, "Failed to get file size\n");
        close(fd);
        free(reader);
        return NULL;
    }

    reader->file_path = file_path;
    reader->buffer_size = MAX_BUFFER_SIZE;
    reader->file_size = st.st_size;
    reader->offset = 0;
    reader->eof = 0;
    return reader;
}

char* read_file(FileReader* reader, int buffer_size) {
    if (reader == NULL || buffer_size <= 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    // Read the file in chunks and update the offset
    char* buffer = malloc(buffer_size);
    if (buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for file buffer\n");
        return NULL;
    }

    int bytes_read = read(reader->fd, buffer, buffer_size);
    if (bytes_read < 0) {
        fprintf(stderr, "Failed to read from resource file\n");
        free(buffer);
        return NULL;
    }

    reader->offset += bytes_read;
    reader->eof = reader->offset >= reader->file_size;
    return buffer;
}

void close_file(FileReader* reader) {
    if (reader == NULL) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    close(reader->fd);
    free(reader);
}
