    parseFrameData(data, dataSize, frameStats);

    // Add the new node to the linked list
    if (frameStatsHead == NULL) {
        frameStatsHead = newNode;
    } else {
        FrameStatsNode *currentNode = frameStatsHead;
        while (currentNode->next != NULL) {
            currentNode = currentNode->next;
        }
        currentNode->next = newNode;
