    if (new_node == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for new node");
        return NULL;
    }
    new_node->record = record;
    new_node->next = NULL;
    return new_node;
}

// Define a function to add a new record to the linked list
void add_record(Node **head, Record *new_record) {
    Node *new_node = create_node(new_record);
    if (new_node == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for new node");
        return;
    }
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Define a function to filter records based on user-defined criteria
void filter_records(Node **head, char *filter_criteria, int max_records, int sort_by_column, int max_structures) {
    // Initialize variables for filtering and sorting
    int num_records = 0;
    int num_structures = 0;
    Record *current_record = NULL;
    Node *current_node = *head;

    // Iterate through the linked list and filter records based on user-defined criteria
    while (current_node != NULL) {
        current_record = current_node->record;
        if (strcmp(filter_criteria, "age") == 0 && current_record->age >= max_records) {
            add_record(head, current_record);
            num_records++;
            num_structures++;
            if (num_structures == max_structures) {
                break;
            }
        } else if (strcmp(filter_criteria, "name") == 0 && strlen(current_record->name) >= max_records) {
            add_record(head, current_record);
            num_records++;
            num_structures++;
            if (num_structures == max_structures) {
                break;
            }
        }
        current_node = current_node->next;
    }

    // Sort the filtered records by a specific column
    if (sort_by_column != 0) {
        Node *current_node = *head;
        while (current_node != NULL) {
            Record *current_record = current_node->record;
            if (strcmp(filter_criteria, "age") == 0 && current_record->age >= max_records) {
                add_record(head, current_record);
                num_records++;
                num_structures++;
                if (num_structures == max_structures) {
                    break;
                }
            } else if (strcmp(filter_criteria, "name") == 0 && strlen(current_record->name) >= max_records) {
                add_record(head, current_record);
                num_records++;
                num_structures++;
                if (num_structures == max_structures) {
                    break;
                }
            }
            current_node = current_node->next;
        }
    }
}

// Define a function to process a large CSV file, potentially compressed in GZIP format, and filter records based on user-defined criteria
void process_csv(char *input_file, char *output_file, char *filter_criteria, int max_records, int sort_by_column, int max_structures, int priority_level, int timeout_threshold) {
    // Initialize variables for processing and filtering
    Node *head = NULL;
    Record *current_record = NULL;
    FILE *input_file_ptr = fopen(input_file, "r");
    if (input_file_ptr == NULL) {
        syslog(LOG_ERR, "Failed to open input file for reading");
        return;
    }
    FILE *output_file_ptr = fopen(output_file, "w");
    if (output_file_ptr == NULL) {
        syslog(LOG_ERR, "Failed to open output file for writing");
        fclose(input_file_ptr);
        return;
    }

    // Process the input file and filter records based on user-defined criteria
    while (fscanf(input_file_ptr, "%s %d", current_record->name, &current_record->age) != EOF) {
        add_record(&head, current_record);
        num_records++;
        if (num_records == max_records) {
            break;
        }
    }
    filter_records(&head, filter_criteria, max_records, sort_by_column, max_structures);

    // Write the filtered records to the output file
    Node *current_node = head;
    while (current_node != NULL) {
        Record *current_record = current_node->record;
        fprintf(output_file_ptr, "%s %d\n", current_record->name, current_record->age);
        current_node = current_node->next;
    }

    // Close the input and output files
    fclose(input_file_ptr);
    fclose(output_file_ptr);
}

