    int rnti;
    int crc_indication_rel8_tag;
    bool crcflag;
} AUDIO_PROCESSING_PDU_T;

// Define the data structure for holding the media stream configuration
typedef struct {
    int duration;
    int bitrate;
    int sample_rate;
} MEDIA_STREAM_CONFIG;

// Define the function to process the multimedia stream with CRC management
void* process_multimedia_stream_with_crc_management(const char* file_path, int duration_limit, bool clip, void* audio_output_buffer, int buffer_size, int stream_count, MEDIA_STREAM_CONFIG* media_stream_configs, int N) {
    // Validate the input parameters
    if (audio_output_buffer == NULL || buffer_size <= 0) {
        return NULL;
    }

    // Check if the file exists and can be opened for reading
    FILE* file = fopen(file_path, "r");
    if (file == NULL) {
        return NULL;
    }

    // Determine the total duration of all streams specified by the media stream config array
    int total_duration = 0;
    for (int i = 0; i < N; i++) {
        total_duration += media_stream_configs[i].duration;
    }

    // If the total duration exceeds the duration limit, return NULL
    if (total_duration > duration_limit) {
        fclose(file);
        return NULL;
    }

    // Create a semaphore to synchronize access to the audio output buffer
    sem_t* sem = sem_open("audio_output_buffer", O_CREAT, 0644, 1);
    if (sem == SEM_FAILED) {
        fclose(file);
        return NULL;
    }

    // Create a mutex to synchronize access to the media stream config array
    pthread_mutex_t* mutex = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
    if (mutex == NULL) {
        fclose(file);
        sem_close(sem);
        return NULL;
    }
    pthread_mutex_init(mutex, NULL);

    // Create a thread to periodically purge outdated entries from the list
    pthread_t purge_thread;
    if (pthread_create(&purge_thread, NULL, purge_outdated_entries, (void*)sem) != 0) {
        fclose(file);
        sem_close(sem);
        free(mutex);
        return NULL;
    }

    // Create a thread to process the multimedia stream with CRC management
    pthread_t processing_thread;
    if (pthread_create(&processing_thread, NULL, process_multimedia_stream, (void*)file) != 0) {
        fclose(file);
        sem_close(sem);
        free(mutex);
        return NULL;
    }

    // Join the processing thread to ensure that it has completed before returning
    pthread_join(processing_thread, NULL);

    // Close the file and semaphore
    fclose(file);
    sem_close(sem);

    // Free the mutex
    free(mutex);

    return audio_output_buffer;
}

// Define the function to periodically purge outdated entries from the list
void* purge_outdated_entries(void* arg) {
    sem_t* sem = (sem_t*)arg;

    // Loop indefinitely, purging outdated entries from the list
    while (1) {
        // Acquire the semaphore to ensure that only one thread can access the list at a time
        if (sem_wait(sem) == -1) {
            perror("Error waiting for semaphore");
            return NULL;
        }

        // Purge outdated entries from the list
        for (int i = 0; i < N; i++) {
            if (media_stream_configs[i].duration <= 0) {
                media_stream_configs[i] = media_stream_configs[N - 1];
                N--;
            }
        }

        // Release the semaphore to allow other threads to access the list
        if (sem_post(sem) == -1) {
            perror("Error posting semaphore");
            return NULL;
        }
    }
}

// Define the function to process the multimedia stream with CRC management
void* process_multimedia_stream(void* arg) {
    FILE* file = (FILE*)arg;

    // Loop indefinitely, processing the multimedia stream with CRC management
    while (1) {
        // Acquire the semaphore to ensure that only one thread can access the audio output buffer at a time
        if (sem_wait(sem) == -1) {
            perror("Error waiting for semaphore");
            return NULL;
        }

        // Read the next audio frame from the file
        int bytes_read = fread(audio_output_buffer, 1, buffer_size, file);
        if (bytes_read <= 0) {
            break;
        }

        // Release the semaphore to allow other threads to access the audio output buffer
        if (sem_post(sem) == -1) {
            perror("Error posting semaphore");
            return NULL;
        }
    }

    // Close the file
    fclose(file);

    return NULL;
}
