#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the structure for NFAPI_MESSAGE_T
typedef struct {
    UE_IDENTIFIER ue_identifier;
    CELL_ID cell_id;
    NETWORK_EVENT_TAG event_tag;
} NFAPI_MESSAGE_T;

// Define the linked list structure for managing events
typedef struct {
    NFAPI_MESSAGE_T *events;
    size_t num_events;
    pthread_mutex_t mutex;
} EVENT_LIST_T;

// Function to insert an event into the linked list
void insert_event(EVENT_LIST_T *list, NFAPI_MESSAGE_T *event) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&list->mutex);

    // Allocate memory for the new event
    NFAPI_MESSAGE_T *new_event = malloc(sizeof(NFAPI_MESSAGE_T));
    if (new_event == NULL) {
        // Release the lock on the mutex and return failure
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Copy the event data into the new event structure
    memcpy(new_event, event, sizeof(NFAPI_MESSAGE_T));

    // Add the new event to the end of the linked list
    if (list->events == NULL) {
        list->events = new_event;
    } else {
        NFAPI_MESSAGE_T *last_event = list->events;
        while (last_event->next != NULL) {
            last_event = last_event->next;
        }
        last_event->next = new_event;
    }

    // Increment the number of events in the linked list
    list->num_events++;

    // Release the lock on the mutex and return success
    pthread_mutex_unlock(&list->mutex);
}

// Function to delete an event from the linked list
void delete_event(EVENT_LIST_T *list, UE_IDENTIFIER ue_identifier) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&list->mutex);

    // Find the event to be deleted in the linked list
    NFAPI_MESSAGE_T *event = list->events;
    while (event != NULL && event->ue_identifier != ue_identifier) {
        event = event->next;
    }

    // If the event is found, remove it from the linked list
    if (event != NULL) {
        NFAPI_MESSAGE_T *prev_event = event->prev;
        NFAPI_MESSAGE_T *next_event = event->next;
        if (prev_event == NULL) {
            list->events = next_event;
        } else {
            prev_event->next = next_event;
        }
        if (next_event != NULL) {
            next_event->prev = prev_event;
        }
        free(event);
        list->num_events--;
    }

    // Release the lock on the mutex and return success
    pthread_mutex_unlock(&list->mutex);
}

// Function to retrieve an event from the linked list
NFAPI_MESSAGE_T *retrieve_event(EVENT_LIST_T *list, UE_IDENTIFIER ue_identifier) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&list->mutex);

    // Find the event in the linked list
    NFAPI_MESSAGE_T *event = list->events;
    while (event != NULL && event->ue_identifier != ue_identifier) {
        event = event->next;
    }

    // If the event is found, return it
    if (event != NULL) {
        pthread_mutex_unlock(&list->mutex);
        return event;
    }

    // Release the lock on the mutex and return failure
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

// Function to filter events based on CELL_ID
NFAPI_MESSAGE_T *filter_events(EVENT_LIST_T *list, CELL_ID cell_id) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&list->mutex);

    // Find the first event with the specified CELL_ID in the linked list
    NFAPI_MESSAGE_T *event = list->events;
    while (event != NULL && event->cell_id != cell_id) {
        event = event->next;
    }

    // If an event with the specified CELL_ID is found, return it
    if (event != NULL) {
        pthread_mutex_unlock(&list->mutex);
        return event;
    }

    // Release the lock on the mutex and return failure
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

// Function to retrieve all events from the linked list
NFAPI_MESSAGE_T *retrieve_all_events(EVENT_LIST_T *list) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&list->mutex);

    // Create a new array to store all events in the linked list
    NFAPI_MESSAGE_T **events = malloc(sizeof(NFAPI_MESSAGE_T *) * list->num_events);
    if (events == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }

    // Copy all events from the linked list into the array
    size_t i = 0;
    NFAPI_MESSAGE_T *event = list->events;
    while (event != NULL) {
        events[i++] = event;
        event = event->next;
    }

    // Release the lock on the mutex and return the array of events
    pthread_mutex_unlock(&list->mutex);
    return events;
}

// Function to free all memory allocated for the linked list
void free_event_list(EVENT_LIST_T *list) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&list->mutex);

    // Free all events in the linked list
    NFAPI_MESSAGE_T *event = list->events;
    while (event != NULL) {
        NFAPI_MESSAGE_T *next_event = event->next;
        free(event);
        event = next_event;
    }

    // Release the lock on the mutex and return success
    pthread_mutex_unlock(&list->mutex);
}
