    if (list->head == node) {
        list->head = node->next;
    } else {
        NFAPI_MESSAGE_T *curr = list->head;
        while (curr != NULL && curr->next != node) {
            curr = curr->next;
        }
        if (curr == NULL) {
            pthread_mutex_unlock(&list->lock);
            return -1;
