from collections import deque

class PacketManager:
    def __init__(self):
        self.packets = []
        self.sequence_numbers = {}
        self.timestamps = {}

    def add_packet(self, packet):
        self.packets.append(packet)
        self.sequence_numbers[packet.sequence] = packet
        self.timestamps[packet.timestamp] = packet

    def get_packet(self, sequence):
        return self.sequence_numbers[sequence]

    def get_packets(self, timestamp):
        return [p for p in self.timestamps if p.timestamp <= timestamp]

    def purge_records(self, threshold):
        for record in self.sequence_numbers:
            if record.frequency < threshold:
                del self.sequence_numbers[record]
                del self.timestamps[record]

class TCPPacketManager:
    def __init__(self):
        self.packets = deque()
        self.sequence_numbers = {}
        self.timestamps = {}

    def add_packet(self, packet):
        self.packets.append(packet)
        self.sequence_numbers[packet.sequence] = packet
        self.timestamps[packet.timestamp] = packet

    def get_packet(self, sequence):
        return self.sequence_numbers[sequence]

    def get_packets(self, timestamp):
        return [p for p in self.timestamps if p.timestamp <= timestamp]

    def purge_records(self, threshold):
        for record in self.sequence_numbers:
            if record.frequency < threshold:
                del self.sequence_numbers[record]
                del self.timestamps[record]

